app = Flask(__name__)
# X-1 (2026-06-03): accept trailing slashes on every route so Google
# Search Console + Bing Webmaster Tools verification on URL-prefix
# properties (e.g. /georgia/) doesn't 404. Single switch, applies to
# every route -- no per-route change needed.
app.url_map.strict_slashes = False
# SECRET_KEY rotated 2026-07-02 after a cross-user session leak — bumping the
# default invalidates every previously-issued cookie so any leaked/shared
# session stops working and everyone re-logs in cleanly. Set SECRET_KEY in the
# environment to override.
app.secret_key = os.environ.get('SECRET_KEY', 'goocampus-session-2026-07-02-rot1')
app.config['DEBUG'] = False

# ─── Session persistence (safe) ───────────────────────────────────────
# Keep the team logged in for 30 days WITHOUT re-issuing the cookie on every
# response. The earlier version set SESSION_REFRESH_EACH_REQUEST=True and
# marked the session modified on every request, so EVERY response carried a
# Set-Cookie. A shared cache/proxy could then hand one user's session cookie
# to another (users landing in each other's portals). Fix: the cookie is set
# ONCE at login (session.permanent=True in the login handlers) with a 30-day
# absolute lifetime; it is NOT refreshed per request, so authenticated
# responses no longer carry Set-Cookie.
app.config['PERMANENT_SESSION_LIFETIME'] = timedelta(days=30)
app.config['SESSION_REFRESH_EACH_REQUEST'] = False
# Session-cookie hardening (defence in depth). Render serves over HTTPS, so
# Secure is safe. HttpOnly keeps JS from reading the cookie; SameSite=Lax
# stops it being sent on cross-site requests.
app.config['SESSION_COOKIE_SECURE'] = True
app.config['SESSION_COOKIE_HTTPONLY'] = True
app.config['SESSION_COOKIE_SAMESITE'] = 'Lax'


@app.after_request
def _no_store_authenticated(resp):
    """Never let a shared cache store a logged-in response (defence in depth
    against session bleed): mark authenticated pages private + no-store.
    Static assets (not user-specific) keep normal caching."""
    try:
        if request.endpoint == 'static':
            return resp
        if session.get('user_id') or session.get('is_client') or session.get('is_partner'):
            resp.headers['Cache-Control'] = 'private, no-store, no-cache, must-revalidate, max-age=0'
            resp.headers['Pragma'] = 'no-cache'
    except Exception:
        pass
    return resp


# ─── Global Jinja2 date filter: DD-Mon-YYYY (e.g. 15-Apr-2026) ───
@app.template_filter('format_date')
def format_date_filter(value):
    """Convert a date string or date object to DD-Mon-YYYY format."""
    if not value:
        return '—'
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return '—'
        for fmt in ('%Y-%m-%d', '%Y-%m-%dT%H:%M:%S', '%Y-%m-%d %H:%M:%S',
                    '%d-%b-%Y', '%d/%m/%Y', '%d-%m-%Y'):
            try:
                value = datetime.strptime(value, fmt)
                break
            except ValueError:
                continue
        else:
            return value  # return as-is if no format matched
    try:
        return value.strftime('%d-%b-%Y')
    except (AttributeError, ValueError):
        return value

@app.template_filter('format_datetime')
def format_datetime_filter(value):
    """A stored UTC timestamp → 'DD-Mon-YYYY, hh:mm AM/PM IST'."""
    if not value:
        return '—'
    dt = value
    if isinstance(dt, str):
        dt = dt.strip()
        if not dt:
            return '—'
        base = dt.split('.')[0].replace('T', ' ')
        for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d %H:%M', '%Y-%m-%d'):
            try:
                dt = datetime.strptime(base, fmt)
                break
            except ValueError:
                continue
        else:
            return value
    try:
        from datetime import timedelta as _td
        ist = dt + _td(hours=5, minutes=30)   # stored UTC → IST
        return ist.strftime('%d-%b-%Y, %I:%M %p') + ' IST'
    except (AttributeError, ValueError):
        return value


@app.template_filter('format_reg')
def format_reg_filter(value):
    """Normalize registration numbers to a single canonical display:
        GCUKIP/YY-YY/NNN    (PLAB)
        GCAUSIP/YY-YY/NNN   (AMC)
        GCCSS/YY-YY/NNN     (Standard Consulting -- S-3)
    Handles both source formats and pads the trailing number to at
    least 3 digits.

      GCUKIP/2022/42      ->  GCUKIP/22-23/042
      GCUKIP/24-25/06     ->  GCUKIP/24-25/006
      GCAUSIP/2023/9      ->  GCAUSIP/23-24/009
      GCAUSIP/26-27/04    ->  GCAUSIP/26-27/004
      GCAUSIP/25-26/039   ->  GCAUSIP/25-26/039   (unchanged)
      GCCSS/24-25/06      ->  GCCSS/24-25/006
    Unknown shapes are returned as-is. Empty / None becomes '—'.
    """
    if not value or not isinstance(value, str):
        return value or '—'
    value = value.strip()
    if not value:
        return '—'
    import re as _re

    def _pad(n):
        try:
            return f"{int(n):03d}"
        except (ValueError, TypeError):
            return n

    # Match either prefix with either middle form.
    # Group 1 prefix; group 2 either YYYY or YY-YY; group 3 trailing number.
    m = _re.match(r'^(GCUKIP|GCAUSIP|GCCSS)/(\d{2,4}(?:-\d{2,4})?)/(\d+)$',
                  value, _re.IGNORECASE)
    if not m:
        return value
    prefix = m.group(1).upper()
    middle = m.group(2)
    num    = _pad(m.group(3))

    if _re.match(r'^\d{4}$', middle):
        # 4-digit year -> convert to YY-(YY+1)
        year = int(middle)
        yy = year % 100
        next_yy = (yy + 1) % 100
        middle = f"{yy:02d}-{next_yy:02d}"
    elif _re.match(r'^\d{2}-\d{2}$', middle):
        pass  # already canonical
    elif _re.match(r'^\d{2,4}-\d{2,4}$', middle):
        # Mixed widths -- coerce both halves to 2 digits if 4-digit years.
        a, b = middle.split('-')
        try:
            a2 = int(a) % 100
            b2 = int(b) % 100
            middle = f"{a2:02d}-{b2:02d}"
        except ValueError:
            pass
    return f"{prefix}/{middle}/{num}"


