def get_monthly_alloc(month_num):
    """Get monthly leave allocation for a given month number (1-12).
    April (month 4) gets 3 days, all other months get 2 days. Base total = 25/year."""
    return 3 if month_num == 4 else 2


# Per-type annual leave allocation (days/year). Sums to the 25/year pool;
# carry_forward is added to the Annual bucket. Edit here to change the split.
LEAVE_TYPE_ALLOC = {'annual': 13, 'sick': 6, 'casual': 6}


def leave_type_balances(employee_id, year):
    """Per-type leave balances for the FY starting April `year`.

    Each type's balance = its yearly allocation − PAID leaves taken of that
    type. Whether a day is paid is decided by the monthly accrual (3 in April,
    2 otherwise, plus carry_forward), consumed chronologically within each
    month; days taken beyond the available balance are unpaid (LOP) and do NOT
    reduce the type balance. Carry_forward adds to both the available pool and
    the Annual allocation. The three type balances sum to the total leave
    balance (entitlement − total paid taken), and total_deduction here matches
    the salary-deduction report.

    Returns a dict with per-type alloc/taken/paid/balance plus totals.
    """
    conn = get_db()
    emp = conn.execute('SELECT carry_forward FROM employees WHERE id = ?', (employee_id,)).fetchone()
    cf = float(emp['carry_forward'] or 0) if emp else 0.0
    paid = {'annual': 0.0, 'sick': 0.0, 'casual': 0.0}
    taken = {'annual': 0.0, 'sick': 0.0, 'casual': 0.0}
    total_deduction = 0.0
    carried = cf
    for offset in range(12):
        rm = ((offset + 3) % 12) + 1
        ry = year if rm >= 4 else year + 1
        available = carried + get_monthly_alloc(rm)
        rows = conn.execute('''
            SELECT leave_type, days FROM leave_records
            WHERE employee_id = ? AND status = 'approved'
            AND strftime('%Y', leave_date) = ? AND strftime('%m', leave_date) = ?
            ORDER BY leave_date, id
        ''', (employee_id, str(ry), str(rm).zfill(2))).fetchall()
        for r in rows:
            lt = (r['leave_type'] or '').lower()
            if lt not in taken:
                lt = 'casual'  # fallback bucket for any stray type
            d = float(r['days'] or 0)
            taken[lt] += d
            paid_portion = min(d, available) if available > 0 else 0.0
            paid[lt] += paid_portion
            available -= paid_portion
            total_deduction += (d - paid_portion)
        carried = available  # always >= 0
    conn.close()
    alloc = {'annual': LEAVE_TYPE_ALLOC['annual'] + cf,
             'sick': LEAVE_TYPE_ALLOC['sick'],
             'casual': LEAVE_TYPE_ALLOC['casual']}
    bal = {k: alloc[k] - paid[k] for k in alloc}
    # A type can read negative if its PAID usage exceeded its own share while
    # the overall monthly pool still had capacity. Borrow the overdraft from a
    # surplus type (Annual first) so every card shows >= 0 and the three still
    # sum to the total leave balance.
    for k in ('casual', 'sick', 'annual'):
        if bal[k] < -1e-9:
            deficit = -bal[k]
            bal[k] = 0.0
            for src in ('annual', 'sick', 'casual'):
                if src == k or deficit <= 1e-9:
                    continue
                take = min(deficit, max(0.0, bal[src]))
                bal[src] -= take
                deficit -= take
    bal = {k: round(v, 2) for k, v in bal.items()}
    return {
        'alloc': {k: round(v, 2) for k, v in alloc.items()},
        'taken': {k: round(v, 2) for k, v in taken.items()},
        'paid': {k: round(v, 2) for k, v in paid.items()},
        'balance': bal,
        'total_alloc': round(sum(alloc.values()), 2),
        'total_taken': round(sum(taken.values()), 2),
        'total_paid': round(sum(paid.values()), 2),
        'total_deduction': round(total_deduction, 2),
        'total_balance': round(sum(bal.values()), 2),
        'carried': round(carried, 2),
    }

@app.context_processor
def inject_manager_status():
    """Make is_manager, pending_team_count, has_sales_access, and
    has_operations_access + operations_landing_url available in all
    templates.

    Operations access is granted to any user with view permission on
    at least one pathway dashboard OR any operations_shared sub-area.
    The landing URL is the first pathway dashboard they have access
    to (PLAB > Australia > Consulting), so a Consulting-only user
    lands on /operations/consulting instead of 403'ing on
    /operations/uk-pathway.
    """
    if 'user_id' in session:
        user_id = session['user_id']
        user = get_user()
        mgr = is_manager(user_id)
        pending_team = get_pending_team_count(user_id) if mgr else 0
        sales_access = has_section_permission(user, 'sales', 'meetings', 'view') if user else False

        # has_operations_access — any of the 3 pathway dashboards, or
        # any operations_shared sub-area (reports / field_manager /
        # vendors_providers). Admins always see Operations.
        plab_ok = has_section_permission(user, 'plab_pathway', 'dashboard', 'view') if user else False
        aus_ok  = has_section_permission(user, 'australia_pathway', 'dashboard', 'view') if user else False
        cons_ok = has_section_permission(user, 'consulting_pathway', 'dashboard', 'view') if user else False
        port_ok = has_section_permission(user, 'portfolio_pathway', 'dashboard', 'view') if user else False
        trn_ok  = has_section_permission(user, 'training_pathway', 'dashboard', 'view') if user else False
        shared_ok = any(has_section_permission(user, 'operations_shared', s, 'view')
                        for s in ('reports', 'field_manager', 'vendors_providers')) if user else False
        ops_access = plab_ok or aus_ok or cons_ok or port_ok or trn_ok or shared_ok

        # Smart landing URL — unified Operations dashboard when the user
        # has any pathway dashboard; otherwise fall back to Reports.
        if plab_ok or aus_ok or cons_ok or port_ok or trn_ok:
            ops_landing = '/operations/dashboard'
        else:
            # operations_shared only -> Reports is the safest default
            ops_landing = '/operations/reports'

        # Can this user REQUEST an internal transfer (request-only; approval
        # stays admin)? Admins always can; otherwise needs the Access Master
        # grant Clients -> Internal Transfers -> Add. Drives the "Request
        # Internal Transfer" button on the Operations client profiles.
        can_xfer = bool(session.get('is_admin') or
                        (user and has_section_permission(user, 'clients', 'internal_transfers', 'add')))
        # Ops verifier: admin, or Clients > Internal Transfers > Edit. Drives the
        # "Ops Team Verification" queue link.
        can_verify_xfer = bool(session.get('is_admin') or
                        (user and has_section_permission(user, 'clients', 'internal_transfers', 'edit')))

        # has_clients_access — any Clients sub-section grant. The top-level
        # "Clients" menu only existed for admins, so a team member granted
        # (say) just Client Feedback saw no way in. Land them on the FIRST
        # Clients page they actually have, not /admin/clients (which needs
        # the 'registrations' grant and would 403 a feedback-only user).
        _clients_subs = [
            ('registrations',       '/admin/clients'),
            ('invitations',         '/admin/client-invitations'),
            ('form_config',         '/admin/client-form-config'),
            ('welcome_kit',         '/admin/welcome-kit'),
            ('payments_hub',        '/admin/payments'),
            ('refunds',             '/admin/refunds'),
            ('internal_transfers',  '/admin/internal-transfers'),
            ('feedback',            '/admin/feedback'),
        ]
        clients_access = False
        clients_landing = '/admin/clients'
        if user:
            for _sub, _url in _clients_subs:
                if has_section_permission(user, 'clients', _sub, 'view'):
                    if not clients_access:
                        clients_landing = _url
                    clients_access = True

        # has_college_access — the College section (College directory, Medical
        # Predictor, NEET PG PDF library) was admin-only: no top-level menu for a
        # granted team member. Land them on the FIRST College page they hold a
        # grant for. (founder 2026-07-21)
        _college_subs = [
            ('college_portal',  '/colleges'),
            ('mbbs_predictor',  '/medical-predictor'),
            ('fees',            '/admin/neetpg-pdfs'),
        ]
        college_access = False
        college_landing = '/colleges'
        if user:
            for _sub, _url in _college_subs:
                if has_section_permission(user, 'colleges', _sub, 'view'):
                    if not college_access:
                        college_landing = _url
                    college_access = True

        # has_partners_access — Partners is its own top-level group now (founder
        # 2026-07-22). Any of its sub-sections shows the Partners menu, landing on
        # the first page the member holds.
        _partner_subs = [
            ('dashboard',   '/partners/dashboard'),
            ('directory',   '/partners'),
            ('leads',       '/partners/leads'),
            ('invitations', '/partners/invitations'),
        ]
        partners_access = False
        partners_landing = '/partners'
        if user:
            for _sub, _url in _partner_subs:
                if has_section_permission(user, 'partners', _sub, 'view'):
                    if not partners_access:
                        partners_landing = _url
                    partners_access = True
        return {
            'is_manager': mgr,
            'pending_team_count': pending_team,
            'has_sales_access': sales_access,
            'has_operations_access': ops_access,
            'operations_landing_url': ops_landing,
            'has_clients_access': clients_access,
            'clients_landing_url': clients_landing,
            'has_college_access': college_access,
            'colleges_landing_url': college_landing,
            'has_partners_access': partners_access,
            'partners_landing_url': partners_landing,
            'current_user_name': (user['name'] if user else ''),
            'can_request_transfer': can_xfer,
            'can_verify_transfer': can_verify_xfer,
        }
    return {
        'is_manager': False, 'pending_team_count': 0, 'has_sales_access': False,
        'has_operations_access': False, 'operations_landing_url': '/operations/uk-pathway',
        'has_clients_access': False, 'clients_landing_url': '/admin/clients',
        'has_college_access': False, 'colleges_landing_url': '/colleges',
        'has_partners_access': False, 'partners_landing_url': '/partners',
        'current_user_name': '', 'can_request_transfer': False, 'can_verify_transfer': False,
    }

def calculate_monthly_balance(employee_id, year, month):
    """Calculate running balance for a given month"""
    conn = get_db()

    # Get carry forward
    emp = conn.execute('SELECT carry_forward FROM employees WHERE id = ?', (employee_id,)).fetchone()
    carry_forward = emp['carry_forward'] if emp else 0

    # Total annual allocation = 25 + carry_forward
    total_allocation = 25 + carry_forward

    # Calculate balance up to and including the given month
    # Carry forward is added as starting balance; monthly alloc: April=3, others=2
    balance = carry_forward
    for m in range(4, month + 1):  # FY starts April (month 4)
        balance += get_monthly_alloc(m)
        # Subtract approved leaves in this month
        leaves = conn.execute('''
            SELECT SUM(days) as total_days FROM leave_records
            WHERE employee_id = ? AND status = 'approved'
            AND strftime('%Y', leave_date) = ? AND strftime('%m', leave_date) = ?
        ''', (employee_id, str(year if m >= 4 else year - 1), str(m).zfill(2))).fetchone()

        if leaves['total_days']:
            balance -= leaves['total_days']

    conn.close()
    return max(0, balance)

def get_available_balance(employee_id, year, month):
    """Get available balance at the start of a month"""
    conn = get_db()

    emp = conn.execute('SELECT carry_forward FROM employees WHERE id = ?', (employee_id,)).fetchone()
    carry_forward = emp['carry_forward'] if emp else 0

    total_allocation = 25 + carry_forward

    # Get balance from start of FY to end of previous month
    # Carry forward added as starting balance; monthly alloc: April=3, others=2
    balance = carry_forward
    for m in range(4, month):
        balance += get_monthly_alloc(m)
        leaves = conn.execute('''
            SELECT SUM(days) as total_days FROM leave_records
            WHERE employee_id = ? AND status = 'approved'
            AND strftime('%Y', leave_date) = ? AND strftime('%m', leave_date) = ?
        ''', (employee_id, str(year if m >= 4 else year - 1), str(m).zfill(2))).fetchone()

        if leaves['total_days']:
            balance -= leaves['total_days']

    conn.close()
    return max(0, balance)


def leave_month_figures(employee_id, year, month):
    """Leave figures for a single (year, month) under the GooCampus rule:

      available = (unused leaves accumulated from prior months, >= 0)
                  + this month's allocation (April = 3, others = 2)
                  + old transferred leaves (carry_forward, seeded once at the
                    FY start in April)
      deduction = max(0, days_taken - available)        # excess is LOP
      carried_to_next_month = max(0, available - days_taken)

    A DEFICIT does NOT carry — if an employee over-uses leave in a month, the
    next month simply starts with its regular allocation (plus any genuine
    positive surplus). Surplus (unused) leaves DO accumulate forward.

    Walks the fiscal year from April so accumulation/clamping is applied month
    by month. Returns a dict: balance_start (carried in, >= 0), monthly_alloc,
    balance_available, days_taken, deduction, balance_end (carried out).
    """
    conn = get_db()
    emp = conn.execute('SELECT carry_forward FROM employees WHERE id = ?', (employee_id,)).fetchone()
    carried = float(emp['carry_forward'] or 0) if emp else 0.0
    fy_start_year = year if month >= 4 else year - 1
    cy, cm = fy_start_year, 4
    result = None
    while True:
        leaves = conn.execute('''
            SELECT SUM(days) as total_days FROM leave_records
            WHERE employee_id = ? AND status = 'approved'
            AND strftime('%Y', leave_date) = ? AND strftime('%m', leave_date) = ?
        ''', (employee_id, str(cy), str(cm).zfill(2))).fetchone()
        taken_m = float(leaves['total_days'] or 0)
        alloc_m = get_monthly_alloc(cm)
        carried_in = carried
        available = carried_in + alloc_m
        deduction = max(0.0, taken_m - available)
        carried = max(0.0, available - taken_m)  # deficit floored — never carries
        if cy == year and cm == month:
            result = {
                'balance_start': carried_in,
                'monthly_alloc': alloc_m,
                'balance_available': available,
                'days_taken': taken_m,
                'deduction': deduction,
                'balance_end': carried,
            }
            break
        cm += 1
        if cm == 13:
            cm = 1
            cy += 1
        if (cy, cm) > (year, month):  # safety stop
            break
    conn.close()
    if result is None:
        alloc_m = get_monthly_alloc(month)
        result = {'balance_start': 0.0, 'monthly_alloc': alloc_m,
                  'balance_available': alloc_m, 'days_taken': 0.0,
                  'deduction': 0.0, 'balance_end': alloc_m}
    return result

def get_leaves_for_month(employee_id, year, month):
    """Get all approved leaves for a specific month"""
    conn = get_db()
    leaves = conn.execute('''
        SELECT * FROM leave_records
        WHERE employee_id = ? AND status = 'approved'
        AND strftime('%Y', leave_date) = ? AND strftime('%m', leave_date) = ?
        ORDER BY leave_date
    ''', (employee_id, str(year), str(month).zfill(2))).fetchall()
    conn.close()
    return leaves

def get_all_holidays():
    """Get all holidays"""
    conn = get_db()
    holidays = conn.execute('SELECT * FROM holidays ORDER BY holiday_date').fetchall()
    conn.close()
    return {row['holiday_date']: row for row in holidays}

@app.route('/')
@login_required
def index():
    return redirect(url_for('dashboard'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        emp_code = request.form.get('emp_code', '').strip()
        password = request.form.get('password', '').strip()

        if not emp_code or not password:
            flash('Employee code and password required', 'error')
            return render_template('login.html')

        conn = get_db()
        user = conn.execute('SELECT * FROM employees WHERE emp_code = ? AND is_active = 1', (emp_code,)).fetchone()
        conn.close()

        if user and user['password'] == hash_password(password):
            session.clear()  # fresh session on login (prevents fixation/leftover keys)
            session.permanent = True  # 30-day login; cookie set once, here
            session['user_id'] = user['id']
            session['is_admin'] = user['is_admin']
            session['emp_code'] = user['emp_code']
            # Check if password is still the default (first name lowercase)
            default_pw = user['name'].split()[0].lower()
            if password == default_pw:
                session['show_welcome'] = True
            flash('Login successful', 'success')
            return redirect(url_for('index'))
        else:
            flash('Invalid credentials or account inactive', 'error')

    return render_template('login.html')

