@app.route('/client/login', methods=['GET', 'POST'])
def client_login_page():
    if session.get('is_client'):
        return redirect(url_for('client_dashboard'))
    if request.method == 'POST':
        mobile = request.form.get('mobile', '').strip()
        password = request.form.get('password', '').strip()
        if not mobile or not password:
            flash('Mobile and password are required', 'error')
            return render_template('client_login.html')
        # Normalize mobile: strip +91 or leading 91 for 10-digit
        clean = mobile.lstrip('+').lstrip('0')
        if clean.startswith('91') and len(clean) == 12:
            clean = clean[2:]
        conn = get_db()
        acct = conn.execute("SELECT * FROM client_accounts WHERE mobile = ? AND is_active = 1", (clean,)).fetchone()
        conn.close()
        if acct and acct['password_hash'] == hash_password(password):
            session.permanent = True
            session['user_id'] = acct['id']
            session['is_client'] = True
            session['client_name'] = (acct['first_name'] or '') + ' ' + (acct['last_name'] or '')
            session['client_mobile'] = acct['mobile']
            # First-ever login → greet with "Welcome"; returning → "Welcome back".
            # acct was read before the last_login bump below, so a NULL here means
            # they've never logged in.
            session['first_login'] = (acct['last_login'] is None)
            # Update last_login
            conn2 = get_db()
            conn2.execute("UPDATE client_accounts SET last_login = CURRENT_TIMESTAMP WHERE id = ?", (acct['id'],))
            conn2.commit()
            conn2.close()
            return redirect(url_for('client_dashboard'))
        else:
            flash('Invalid mobile number or password', 'error')
            return render_template('client_login.html')
    return render_template('client_login.html')


@app.route('/client/register/<token>', methods=['GET', 'POST'])
def client_register(token):
    conn = get_db()
    inv = conn.execute("SELECT * FROM client_invitations WHERE token = ? AND status = 'pending'", (token,)).fetchone()
    if not inv:
        conn.close()
        flash('This invitation link is invalid or has already been used.', 'error')
        return render_template('client_login.html')

    product = conn.execute("SELECT id, name FROM products_services WHERE id = ?", (inv['product_id'],)).fetchone()

    if request.method == 'POST':
        mobile = request.form.get('mobile', '').strip()
        password = request.form.get('password', '').strip()
        confirm = request.form.get('confirm_password', '').strip()
        first_name = request.form.get('first_name', '').strip()
        last_name = request.form.get('last_name', '').strip()

        # Normalize mobile
        clean = mobile.lstrip('+').lstrip('0')
        if clean.startswith('91') and len(clean) == 12:
            clean = clean[2:]

        if not clean or len(clean) != 10:
            flash('Please enter a valid 10-digit mobile number', 'error')
            conn.close()
            return render_template('client_register.html', invitation=inv, product=product)

        if not password or len(password) < 4:
            flash('Password must be at least 4 characters', 'error')
            conn.close()
            return render_template('client_register.html', invitation=inv, product=product)

        if password != confirm:
            flash('Passwords do not match', 'error')
            conn.close()
            return render_template('client_register.html', invitation=inv, product=product)

        # Check if mobile already exists (mobile is the login id and is UNIQUE).
        existing = conn.execute("SELECT id, email FROM client_accounts WHERE mobile = ?", (clean,)).fetchone()
        if existing:
            _inv_email = (inv['client_email'] or '').strip().lower()
            _acct_email = (existing['email'] or '').strip().lower()
            if _acct_email and _inv_email and _acct_email != _inv_email:
                # Someone else already owns this mobile — never let an invitation
                # overwrite another client's password.
                conn.close()
                flash('This mobile number is already registered to a different email address. '
                      'Please log in with your existing password, or contact us.', 'error')
                return render_template('client_register.html', invitation=inv, product=product)
            # Same client registering again (e.g. a second pathway, or after a purge
            # that left the account behind). Honour the password + name they just
            # typed — silently keeping the old ones locked them out of their account.
            conn.execute(
                "UPDATE client_accounts SET password_hash = ?, first_name = ?, last_name = ?, "
                "is_active = 1, email = COALESCE(NULLIF(email, ''), ?) WHERE id = ?",
                (hash_password(password), first_name, last_name, inv['client_email'] or '', existing['id']))
            conn.commit()
            acct_id = existing['id']
        else:
            conn.execute(
                "INSERT INTO client_accounts (mobile, email, password_hash, first_name, last_name) VALUES (?, ?, ?, ?, ?)",
                (clean, inv['client_email'] or '', hash_password(password), first_name, last_name)
            )
            conn.commit()
            acct_id = conn.execute("SELECT id FROM client_accounts WHERE mobile = ?", (clean,)).fetchone()['id']

        # Generate registration number using per-pathway format.
        # PLAB / UK   -> GCUKIP/<FY>/<NNN>
        # Australia   -> GCAUSIP/<FY>/<NNN>
        # UAE         -> GCUAEIP/<FY>/<NNN>
        # Consulting  -> GCCONS/<FY>/<NNN>
        from core.registration import next_registration_number
        reg_num = next_registration_number(conn, product['name'] if product else None)

        # 2026-06-02: counsellor auto-assign -- the sales rep who raised
        # the invitation IS the counsellor.
        counsellor_id = inv['invited_by']
        counsellor_name = ''
        if counsellor_id:
            emp_row = conn.execute(
                "SELECT name FROM employees WHERE id = ?",
                (counsellor_id,),
            ).fetchone()
            if emp_row:
                counsellor_name = emp_row['name'] or ''

        # Item C: parse the sales closure metadata stashed on the
        # invitation, so the registration row is born with plan +
        # package + installments already filled in. Sales can still
        # tweak any of these later via /admin/clients/<id>.
        import json as _json
        try:
            closure_meta = _json.loads(inv['closure_metadata']) \
                           if inv['closure_metadata'] else {}
        except Exception:
            closure_meta = {}
        plan_type        = closure_meta.get('plan_type', '') or ''
        package_amount   = float(closure_meta.get('package_amount',   0) or 0)
        discount_allowed = float(closure_meta.get('discount_allowed', 0) or 0)
        final_package    = float(closure_meta.get('final_package',    0) or 0)
        addl_pack_notes  = closure_meta.get('additional_package_notes', '') or ''
        lead_source      = closure_meta.get('lead_source', '') or ''
        addl_notes       = closure_meta.get('additional_notes', '') or ''
        ops_notes_val    = closure_meta.get('ops_notes', '') or ''
        inst_amts = [float(closure_meta.get(f'inst{i}_amount', 0) or 0) for i in (1,2,3,4)]
        inst_dts  = [closure_meta.get(f'inst{i}_date', '') or '' for i in (1,2,3,4)]
        inst_nts  = [closure_meta.get(f'inst{i}_note', '') or '' for i in (1,2,3,4)]
        inst_mts  = [closure_meta.get(f'inst{i}_method', '') or '' for i in (1,2,3,4)]
        inst_sts  = [closure_meta.get(f'inst{i}_status', '') or '' for i in (1,2,3,4)]

        conn.execute('''INSERT INTO client_registrations
            (account_id, invitation_id, product_id, registration_number,
             first_name, last_name, mobile, email,
             counsellor_id, counsellor_name,
             plan_type, package_amount, discount_allowed, final_package,
             inst1_amount, inst1_date, inst1_note, inst1_method, inst1_status,
             inst2_amount, inst2_date, inst2_note, inst2_method, inst2_status,
             inst3_amount, inst3_date, inst3_note, inst3_method, inst3_status,
             inst4_amount, inst4_date, inst4_note, inst4_method, inst4_status,
             lead_source, additional_notes, ops_notes,
             contract_path, onboarding_gated,
             form_status, current_step)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                    ?, ?, ?, ?, ?,
                    ?, ?, ?, ?, ?,
                    ?, ?, ?, ?, ?,
                    ?, ?, ?, ?, ?,
                    ?, ?, ?, ?, 1, 'draft', 1)''',
            (acct_id, inv['id'], inv['product_id'], reg_num,
             first_name, last_name, clean, inv['client_email'] or '',
             counsellor_id, counsellor_name,
             plan_type, package_amount, discount_allowed, final_package,
             inst_amts[0], inst_dts[0], inst_nts[0], inst_mts[0], inst_sts[0],
             inst_amts[1], inst_dts[1], inst_nts[1], inst_mts[1], inst_sts[1],
             inst_amts[2], inst_dts[2], inst_nts[2], inst_mts[2], inst_sts[2],
             inst_amts[3], inst_dts[3], inst_nts[3], inst_mts[3], inst_sts[3],
             lead_source, addl_notes, ops_notes_val,
             inv['contract_path']))
        conn.execute("UPDATE client_invitations SET status = 'registered', registered_at = CURRENT_TIMESTAMP WHERE id = ?", (inv['id'],))

        # The sales close date becomes the registration date (founder 2026-07-22).
        _close_date = (closure_meta.get('close_date') or '').strip()
        if _close_date:
            conn.execute("UPDATE client_registrations SET sales_close_date = ? WHERE registration_number = ?",
                         (_close_date, reg_num))

        # Auto-close the originating sales lead(s) → 'Closed Won' when the client
        # onboards, matched by phone. Robust across every creation path so a lead
        # never lingers "open" after the client is in the system. (founder 2026-07-22)
        try:
            _won = conn.execute("SELECT id FROM sales_lead_stages WHERE is_won = 1 "
                                "ORDER BY is_active DESC, id LIMIT 1").fetchone()
            if _won and clean:
                conn.execute(
                    "UPDATE sales_leads SET stage_id = ?, updated_at = CURRENT_TIMESTAMP "
                    "WHERE RIGHT(regexp_replace(COALESCE(phone,''),'[^0-9]','','g'), 10) = ? "
                    "  AND COALESCE(stage_id, 0) <> ?",
                    (_won['id'], clean, _won['id']))
                conn.commit()
        except Exception as _le:
            logging.warning(f"auto-close lead on register {reg_num}: {_le}")
            try: conn.rollback()
            except Exception: pass

        # ── Welcome-call handling chosen by Sales at closure (founder 2026-07-22) ──
        _wc_mode = (closure_meta.get('wc_mode') or 'standard').strip().lower()
        if _wc_mode == 'hold':
            # Hold the welcome call until Sales releases it (payment pending). The
            # client dashboard hides the welcome-call section while held; the reason
            # note surfaces to ops in verification + the welcome-call timeline.
            conn.execute("UPDATE client_registrations SET welcome_call_hold = 1, wc_hold_note = ? "
                         "WHERE registration_number = ?",
                         (closure_meta.get('wc_hold_note', '') or '', reg_num))
        elif _wc_mode == 'completed':
            # Welcome call already done BEFORE onboarding — record it as confirmed with
            # the past date/time so the client sees it done (no scheduler).
            conn.execute("UPDATE client_registrations SET wc_confirmed = 1, wc_status = 'confirmed', "
                         "wc_scheduled_date = ?, wc_scheduled_time = ?, wc_by = ?, wc_hold_note = ?, "
                         "wc_confirmed_at = CURRENT_TIMESTAMP WHERE registration_number = ?",
                         (closure_meta.get('wc_completed_date', '') or '',
                          closure_meta.get('wc_completed_time', '') or '',
                          closure_meta.get('wc_completed_by', '') or '',
                          closure_meta.get('wc_completed_notes', '') or '', reg_num))
        conn.commit()

        # AMC Consulting + AMC 1 combined signup: if the closure opted the client
        # into Training too, create a SECOND registration in the Training pathway
        # (product 'AMC MCQ', plan 'AMC 1', its own GCTRN reg number + its own
        # installments) sharing the same client account. Sales already entered the
        # training split, so it's sales-complete -> lands in the Ops verify queue.
        if closure_meta.get('include_training'):
            try:
                tprod = conn.execute("SELECT id FROM products_services WHERE name = 'AMC MCQ' LIMIT 1").fetchone()
                if tprod:
                    from core.registration import next_registration_number as _nrn
                    t_reg = _nrn(conn, 'AMC MCQ')
                    t_pkg = float(closure_meta.get('training_package', 0) or 0)
                    t_disc = float(closure_meta.get('training_discount', 0) or 0)
                    t_final = float(closure_meta.get('training_final', 0) or (t_pkg - t_disc))
                    trow = {
                        'account_id': acct_id, 'invitation_id': inv['id'], 'product_id': tprod['id'],
                        'registration_number': t_reg, 'first_name': first_name, 'last_name': last_name,
                        'mobile': clean, 'email': inv['client_email'] or '',
                        'counsellor_id': counsellor_id, 'counsellor_name': counsellor_name,
                        'plan_type': 'AMC 1', 'package_amount': t_pkg, 'discount_allowed': t_disc,
                        'final_package': t_final, 'lead_source': lead_source,
                        'additional_notes': addl_notes, 'ops_notes': ops_notes_val,
                        'form_status': 'submitted', 'current_step': 1, 'sales_completed': 1,
                    }
                    for i in (1, 2, 3, 4):
                        trow[f'inst{i}_amount'] = float(closure_meta.get(f'training_inst{i}_amount', 0) or 0)
                        trow[f'inst{i}_date']   = closure_meta.get(f'training_inst{i}_date', '') or ''
                        trow[f'inst{i}_note']   = ''
                        trow[f'inst{i}_method'] = closure_meta.get(f'training_inst{i}_method', '') or ''
                        trow[f'inst{i}_status'] = closure_meta.get(f'training_inst{i}_status', '') or ''
                    tcols = list(trow.keys())
                    conn.execute(
                        f"INSERT INTO client_registrations ({', '.join(tcols)}) "
                        f"VALUES ({', '.join(['?'] * len(tcols))})",
                        [trow[k] for k in tcols])
                    conn.execute("UPDATE client_registrations SET sales_completed_at = CURRENT_TIMESTAMP "
                                 "WHERE registration_number = ?", (t_reg,))
                    conn.commit()
            except Exception as _te:
                logging.warning(f"combined AMC 1 training registration failed: {_te}")
                try: conn.rollback()
                except Exception: pass

        conn.close()

        # Auto-login the client
        session.permanent = True
        session['user_id'] = acct_id
        session['is_client'] = True
        session['client_name'] = f"{first_name} {last_name}"
        session['client_mobile'] = clean
        session['first_login'] = True  # account just created → greet with "Welcome"
        flash('Account created successfully! Please complete your registration form.', 'success')
        return redirect(url_for('client_dashboard'))

    conn.close()
    return render_template('client_register.html', invitation=inv, product=product)


