@app.route('/admin/policies/refund/save', methods=['POST'])
@login_required
def admin_refund_policy_save():
    title = (request.form.get('title') or 'Refund Policy').strip()
    body = request.form.get('body_html') or ''
    bump = request.form.get('bump_version')
    conn = get_db()
    cur = _get_refund_policy(conn)
    # Bumping the version re-requires every client to re-agree (use when the
    # policy materially changes); otherwise edits keep the same version.
    new_ver = (cur['version'] or 1) + 1 if bump else (cur['version'] or 1)
    conn.execute("UPDATE policy_documents SET title = ?, body_html = ?, version = ?, "
                 "updated_at = CURRENT_TIMESTAMP WHERE doc_key = 'refund_policy'",
                 (title, body, new_ver))
    conn.commit()
    conn.close()
    flash('Refund Policy saved.' + (' Version bumped — clients will be asked to re-agree.' if bump else ''), 'success')
    return redirect(url_for('admin_refund_policy_edit'))


# ── Packages & Services: central definition of what each plan's package
#    includes (services delivered over time). Surfaces later in Sales, the
#    client portal, and Operations. ──

@app.route('/admin/packages')
@admin_required
def admin_packages():
    user = get_user()
    conn = get_db()
    products = conn.execute(
        "SELECT id, name, COALESCE(pathway,'') AS pathway FROM products_services "
        "WHERE status = 'active' ORDER BY name").fetchall()
    catalogue = conn.execute(
        "SELECT * FROM service_catalogue WHERE is_active = 1 ORDER BY sort_order, name").fetchall()
    product_id = request.args.get('product_id', type=int)
    selected = None
    plans = []
    stage_options = []
    if product_id:
        selected = conn.execute(
            "SELECT id, name, COALESCE(pathway,'') AS pathway, sale_price "
            "FROM products_services WHERE id = ?", (product_id,)).fetchone()
        if selected:
            # Delivery-stage options = the pathway's client stages (current_stage),
            # so package delivery maps to the same stages Ops tracks. The
            # product's own pathway label may NOT match how current_stage rows
            # are tagged (e.g. product 'standard_consulting' vs stages tagged
            # 'consulting'), so resolve to a pathway that actually HAS stages:
            # try the product pathway first, then the plan type's pathway,
            # then fall back to every distinct stage.
            def _stages_for(pw):
                if not pw:
                    return []
                return [r['value'] for r in conn.execute(
                    "SELECT value FROM lookup_options WHERE category = 'current_stage' AND is_active = TRUE "
                    "AND COALESCE(pathway,'plab') = ? ORDER BY sort_order, value", (pw,)).fetchall()]
            pw_row = conn.execute(
                "SELECT pathway FROM lookup_options WHERE category = 'plan_type' AND product_name = ? "
                "AND pathway IS NOT NULL AND pathway <> '' ORDER BY id LIMIT 1", (selected['name'],)).fetchone()
            plan_pathway = (pw_row['pathway'] if pw_row else '') or ''
            stage_options = _stages_for(selected['pathway'] or '') or _stages_for(plan_pathway)
            if not stage_options:
                stage_options = [r['value'] for r in conn.execute(
                    "SELECT DISTINCT value FROM lookup_options WHERE category = 'current_stage' "
                    "AND is_active = TRUE ORDER BY value").fetchall()]
            ptypes = conn.execute(
                "SELECT DISTINCT value FROM lookup_options WHERE category = 'plan_type' "
                "AND is_active = TRUE AND product_name = ? ORDER BY value", (selected['name'],)).fetchall()
            for pt in ptypes:
                pkg = conn.execute(
                    "SELECT * FROM plan_packages WHERE product_id = ? AND plan_type = ?",
                    (product_id, pt['value'])).fetchone()
                services = []
                if pkg:
                    services = conn.execute(
                        "SELECT * FROM package_services WHERE plan_package_id = ? ORDER BY sort_order, id",
                        (pkg['id'],)).fetchall()
                plans.append({
                    'plan_type': pt['value'],
                    'pkg': dict(pkg) if pkg else None,
                    'services': [dict(s) for s in services],
                })
    # Standard services that apply to EVERY plan of this product (the contract
    # inclusions). Stored as a plan_packages row with the sentinel plan_type.
    standard_services = []
    if selected:
        std_pkg = conn.execute(
            "SELECT id FROM plan_packages WHERE product_id = ? AND plan_type = '__standard__'",
            (product_id,)).fetchone()
        if std_pkg:
            standard_services = [dict(s) for s in conn.execute(
                "SELECT * FROM package_services WHERE plan_package_id = ? ORDER BY sort_order, id",
                (std_pkg['id'],)).fetchall()]
    # Foreign-currency plans: live INR preview per plan type (INR plans omitted).
    # Keyed by plan_type; the template shows "amount CUR × rate +markup% = ₹INR" and
    # the fixed sales revenue. Generalized from the old AMC/AUD-only map.
    amc_aud = {}
    try:
        for _pl in plans:
            _q = amc_aud_quote(_pl['plan_type'], conn=conn, product_id=product_id)
            if _q:
                amc_aud[_pl['plan_type']] = {
                    'currency': _q['currency'], 'aud': _q['amount'], 'amount': _q['amount'],
                    'fixed_sales_revenue': _q['fixed_sales_revenue'], 'markup_pct': _q['markup_pct'],
                    'inr': _q['inr'], 'effective_rate': _q['effective_rate'],
                    'live_rate': _q['live_rate'], 'rate_stale': _q['rate_stale'],
                }
    except Exception:
        amc_aud = {}
    conn.close()
    return render_template('admin_packages.html', user=user, products=products,
                           selected=selected, plans=plans, catalogue=catalogue,
                           standard_services=standard_services, amc_aud=amc_aud,
                           currencies=SUPPORTED_CURRENCIES,
                           stage_options=stage_options, active_section='company')


