@app.route('/admin/packages/plan-type/add', methods=['POST'])
@admin_required
def admin_packages_plan_type_add():
    """Add a plan type from the Products & Services editor. Writes to the SAME
    lookup_options table the Ops Field Manager uses (with product_name + pathway
    set), so plan types stay synced across Field Manager, the sales cascade, and
    here — you can add from either place."""
    product_id = request.form.get('product_id', type=int)
    plan_name = (request.form.get('plan_type') or '').strip()
    conn = get_db()
    prod = conn.execute("SELECT name, COALESCE(pathway,'') AS pathway FROM products_services WHERE id = ?",
                        (product_id,)).fetchone()
    if not prod or not plan_name:
        conn.close()
        flash('Plan type name is required.', 'error')
        return redirect(url_for('admin_packages', product_id=product_id))
    existing = conn.execute(
        "SELECT id FROM lookup_options WHERE category = 'plan_type' AND LOWER(value) = LOWER(?) "
        "AND COALESCE(product_name, '') = ?", (plan_name, prod['name'])).fetchone()
    if existing:
        conn.close()
        flash('That plan type already exists for this product.', 'info')
        return redirect(url_for('admin_packages', product_id=product_id))
    mx = conn.execute("SELECT COALESCE(MAX(sort_order), 0) AS m FROM lookup_options "
                      "WHERE category = 'plan_type'").fetchone()['m']
    conn.execute(
        "INSERT INTO lookup_options (category, label, value, product_name, pathway, is_active, sort_order) "
        "VALUES ('plan_type', ?, ?, ?, ?, TRUE, ?)",
        (plan_name, plan_name, prod['name'], (prod['pathway'] or None), mx + 1))
    conn.commit()
    conn.close()
    flash(f'Plan type "{plan_name}" added to {prod["name"]} (also shows in Field Manager).', 'success')
    return redirect(url_for('admin_packages', product_id=product_id))


@app.route('/client/dashboard')
@client_required
def client_dashboard():
    acct_id = session.get('user_id')
    conn = get_db()
    account = conn.execute("SELECT * FROM client_accounts WHERE id = ?", (acct_id,)).fetchone()
    # Post-submit onboarding gate: lock the dashboard until the client has
    # digitally agreed to their Contract (if one is on file) and the Refund
    # Policy. Redirect to whichever step is still pending.
    _greg, _gate_step, onboarding_stages = _client_gate_status(conn, acct_id)
    if _gate_step == 'contract':
        conn.close()
        return redirect(url_for('client_contract'))
    if _gate_step == 'refund':
        conn.close()
        return redirect(url_for('client_refund_policy'))
    if _gate_step == 'welcome_call':
        # Mandatory welcome-call scheduling (standard flow) — keep the client on the
        # schedule page until they request a slot. (founder 2026-07-22)
        conn.close()
        return redirect(url_for('client_welcome_call_page'))
    # Item C-2: fetch counsellor contact for "Your counsellor" card.
    registrations_raw = conn.execute('''
        SELECT cr.*, ps.name as product_name,
               e.name as counsellor_full_name,
               e.email as counsellor_email_addr,
               e.phone as counsellor_phone_no
        FROM client_registrations cr
        LEFT JOIN products_services ps ON ps.id = cr.product_id
        LEFT JOIN employees e ON e.id = cr.counsellor_id
        WHERE cr.account_id = ?
        ORDER BY cr.created_at DESC
    ''', (acct_id,)).fetchall()
    # Item F: load the admin-managed holidays once per dashboard load
    # so the working-day projection for the 30-day Check-in step
    # honours weekends + holidays. Cheap query, single fetch.
    try:
        from working_days import load_holidays_set
        holidays_set = load_holidays_set(conn)
    except Exception:
        holidays_set = set()

    # Item D: pre-fetch onboarding milestones for every registration
    # number, joined via plab_clients (which holds the ops-side record
    # both PLAB and AMC flows write into). Keyed by registration_number
    # so we can attach per-reg below without a per-row query.
    reg_nums = [r['registration_number'] for r in registrations_raw if r['registration_number']]
    onboarding_by_reg = {}
    if reg_nums:
        placeholders = ','.join(['?' for _ in reg_nums])
        try:
            onb_rows = conn.execute(f"""
                SELECT pc.registration_number,
                       co.welcome_email_sent, co.welcome_email_sent_at,
                       co.welcome_call_confirmed, co.welcome_call_date,
                       co.kit_delivered_date, co.welcome_kit_sent_date,
                       co.onboarding_status, co.updated_at as onb_updated_at
                FROM plab_clients pc
                LEFT JOIN client_onboarding co ON co.client_id = pc.id
                WHERE pc.registration_number IN ({placeholders})
            """, reg_nums).fetchall()
            for row in onb_rows:
                reg_num = row['registration_number']
                if reg_num and reg_num not in onboarding_by_reg:
                    onboarding_by_reg[reg_num] = dict(row)
        except Exception:
            # Defensive: if join fails for any reason just show empty
            # timelines rather than 500 the dashboard.
            onboarding_by_reg = {}

    # Convert to dicts so the template can attach a pre-computed
    # installments list without complicating the SELECT.
    from datetime import date as _date, datetime as _dt
    _today = _date.today()
    def _parse_inst_date(v):
        if not v:
            return None
        if isinstance(v, _dt):
            return v.date()
        if isinstance(v, _date):
            return v
        try:
            return _dt.strptime(str(v)[:10], '%Y-%m-%d').date()
        except Exception:
            return None
    _ORD = {1: '1st', 2: '2nd', 3: '3rd', 4: '4th'}
    registrations = []
    for r in registrations_raw:
        d = dict(r)
        # Combined signup: the add-on (e.g. AMC 1 / Training) registration is
        # auto-created from the client's ONE form — it's 'submitted' but the
        # client never submitted it themselves (client_submitted_at is NULL). It
        # must NOT be independently editable/fillable by the client; its details
        # come from the main registration. (A genuine in-progress form is 'draft'.)
        d['is_combined_addon'] = ((d.get('form_status') == 'submitted') and not d.get('client_submitted_at'))
        insts = []
        for i in (1, 2, 3, 4):
            base = float(d.get(f'inst{i}_amount') or 0)
            draw = d.get(f'inst{i}_date') or ''
            dparsed = _parse_inst_date(draw)
            status = (d.get(f'inst{i}_status') or '').strip()
            # Received ONLY when explicitly marked so. The date is a due date — a
            # past due date does not mean the money arrived, and inferring "received"
            # from it showed clients unpaid installments as paid (founder 2026-07-18).
            received = (status.lower() == 'received')
            # Amounts are stored as the BASE; 18% GST is added on top so the
            # client sees Amount + GST = Total (the total is what was received).
            gst = round(base * 0.18)
            total = round(base + gst)
            insts.append({
                'n': i, 'ordinal': _ORD[i],
                'amount': base, 'gst': gst, 'total': total,
                'date': draw, 'date_obj': dparsed,
                'note': d.get(f'inst{i}_note') or '',
                'method': d.get(f'inst{i}_method') or '',
                'status': status or ('Received' if received else 'Pending'),
                'received': received,
            })
        # Only keep installments that have an amount or date set so we
        # don't render four empty rows for a single-installment plan.
        insts = [it for it in insts if it['amount'] or it['date']]
        d['installments'] = insts
        d['pay_received_total'] = sum(it['total'] for it in insts if it['received'])
        d['pay_due_total']      = sum(it['total'] for it in insts if not it['received'])
        d['gst_received_total'] = sum(it['gst'] for it in insts if it['received'])
        d['gst_total']          = sum(it['gst'] for it in insts)
        d['grand_total']        = sum(it['total'] for it in insts)

        # Item D + F: build the 5-step client-facing onboarding
        # timeline. holidays_set lets the helper project the 30-day
        # Check-in date forward using working_days. onb is None for
        # clients without a client_onboarding row yet; helper handles
        # that by returning all steps as 'upcoming'.
        d['timeline'] = _build_client_timeline(
            onboarding_by_reg.get(d.get('registration_number')),
            holidays_set=holidays_set, reg=d)
        # What's included in the client's package (standard + plan-specific).
        # Names + descriptions only for the client — NEVER budget/cost.
        d['package_services'] = get_package_services(conn, d.get('product_id'), d.get('plan_type'))
        registrations.append(d)

    # Get doc requests for all registrations
    reg_ids = [r['id'] for r in registrations]
    doc_requests = []
    if reg_ids:
        placeholders = ','.join(['?' for _ in reg_ids])
        doc_requests = conn.execute(f"""
            SELECT * FROM client_doc_requests
            WHERE registration_id IN ({placeholders}) AND status = 'pending'
            ORDER BY requested_at DESC
        """, reg_ids).fetchall()

    # Get PLAB documents for this client (via registration_number → plab_clients).
    # Resolve DISTINCT plab_client ids first: the client can have several
    # registrations pointing at the same master (same registration_number), and
    # fetching per-registration listed every document twice or thrice — the
    # "double / triple" the founder saw (2026-07-17). Then de-dupe the rows
    # themselves by (doc_type, file_name) as a belt so a stray duplicate row in the
    # table can't surface either.
    plab_documents = []
    _seen_pc, _seen_doc = set(), set()
    for reg in registrations:
        if not reg.get('registration_number'):
            continue
        plab_client = conn.execute("SELECT id FROM plab_clients WHERE registration_number = ?", (reg['registration_number'],)).fetchone()
        if not plab_client or plab_client['id'] in _seen_pc:
            continue
        _seen_pc.add(plab_client['id'])
        for d in conn.execute("SELECT * FROM plab_client_documents WHERE client_id = ? ORDER BY doc_category, doc_type, id DESC", (plab_client['id'],)).fetchall():
            key = ((d['doc_type'] or ''), (d['file_name'] or ''))
            if key in _seen_doc:
                continue
            _seen_doc.add(key)
            plab_documents.append(d)

    # Photograph: detect an already-uploaded photo across BOTH the post-verify
    # (plab_client_documents) and pre-verify (client_documents) stores, so the
    # dashboard can show the photo + a done tick and block re-uploading.
    # Serve through the owning route — the stored value is an R2 object key, and
    # prepending '/' to it just produced a 404 (or a protocol-relative URL for the
    # legacy '/static/...' rows, which the browser tried to resolve as a hostname).
    photo_doc = None
    for d in plab_documents:
        if (d.get('doc_type') or '') == 'Photograph':
            photo_doc = {'url': url_for('client_serve_plab_doc', doc_id=d['id'])}
            break
    if not photo_doc and reg_ids:
        _php = ','.join(['?' for _ in reg_ids])
        _prow = conn.execute(
            f"SELECT id FROM client_documents WHERE registration_id IN ({_php}) "
            "AND doc_type = 'Photograph' ORDER BY id DESC LIMIT 1", reg_ids).fetchone()
        if _prow:
            photo_doc = {'url': url_for('client_serve_reg_doc', doc_id=_prow['id'])}

    conn.close()
    return render_template('client_dashboard.html',
        account=account, registrations=registrations, doc_requests=doc_requests,
        plab_documents=plab_documents, plab_doc_types=PLAB_DOC_TYPES,
        photo_doc=photo_doc,
        onboarding_stages=onboarding_stages,
        first_login=session.get('first_login', False))


_FORM_STEP_NAMES = {1: 'Personal Details', 2: 'Academic Details',
                    3: 'Documents', 4: 'Review & Submit'}


def _parent_guardian_error(d):
    """Validate the Parent/Guardian block. Returns an error message, or None if OK.
    Parents: at least ONE parent's name, phone AND email. Guardian: name + phone.
    `d` may be the posted form dict or a client_registrations row."""
    def v(k):
        return ((d.get(k) if hasattr(d, 'get') else None) or '').strip()
    gtype = v('guardian_type')
    if gtype == 'guardian':
        if not v('guardian_first_name'):
            return "Please enter the guardian's first name."
        if not v('guardian_phone'):
            return "Please enter the guardian's phone number."
    elif gtype == 'parents':
        if not (v('father_first_name') or v('mother_first_name')):
            return "Please enter at least one parent's name."
        if not (v('father_phone') or v('mother_phone')):
            return "Please enter at least one parent's phone number."
        if not (v('father_email') or v('mother_email')):
            return "Please enter at least one parent's email address."
    return None


# Columns the dynamic client form may write to, per step. The public form is
# rendered + saved from client_form_configs (role='client', is_visible=1); we
# whitelist to real columns so an admin toggling fields can't write arbitrary keys.
_CR_FORM_COLS = {'prefix', 'first_name', 'last_name', 'dob', 'mobile', 'whatsapp',
                 'whatsapp2', 'email', 'address', 'city', 'state', 'country',
                 'father_name', 'father_phone', 'mother_name', 'mother_phone',
                 'parents_email', 'instagram', 'facebook', 'linkedin'}
_CA_FORM_COLS = {'img_fmg', 'img_medical_college', 'fmg_medical_college', 'country',
                 'mbbs_status', 'mbbs_start_date', 'mbbs_end_date', 'speciality_interest_1',
                 'speciality_interest_2', 'internship_status', 'internship_hospital',
                 'internship_location', 'internship_hospital_2', 'internship_location_2',
                 'internship_start_date', 'internship_end_date', 'internship_gap',
                 'gap_in_months', 'gap_reason', 'working_status', 'working_hospital_name',
                 'additional_info'}


@app.route('/client/form/<int:reg_id>', methods=['GET', 'POST'])
@client_required
def client_form(reg_id):
    acct_id = session.get('user_id')
    conn = get_db()
    reg = conn.execute('''
        SELECT cr.*, ps.name as product_name
        FROM client_registrations cr
        LEFT JOIN products_services ps ON ps.id = cr.product_id
        WHERE cr.id = ? AND cr.account_id = ?
    ''', (reg_id, acct_id)).fetchone()
    if not reg:
        conn.close()
        flash('Registration not found', 'error')
        return redirect(url_for('client_dashboard'))

    # Combined-enrolment add-on (e.g. AMC 1 / Training): auto-created from the
    # client's ONE main registration ('submitted' but client_submitted_at NULL).
    # The client must not fill/edit it separately — its details come from the main
    # registration. Bounce any direct access back to the dashboard.
    if (reg['form_status'] == 'submitted') and not reg['client_submitted_at']:
        conn.close()
        flash('This programme is part of your combined enrolment — its details come from your main registration, so there is no separate form to fill.', 'info')
        return redirect(url_for('client_dashboard'))

    # Load academics
    academics = conn.execute("SELECT * FROM client_academics WHERE registration_id = ?", (reg_id,)).fetchone()
    # Load documents
    documents = conn.execute("SELECT * FROM client_documents WHERE registration_id = ? ORDER BY uploaded_at", (reg_id,)).fetchall()
    # Load form config for this product
    form_config = conn.execute('''
        SELECT * FROM client_form_configs
        WHERE product_id = ? AND role = 'client' AND is_visible = 1
        ORDER BY step_number, display_order
    ''', (reg['product_id'],)).fetchall()
    # Get doc requests
    doc_requests = conn.execute(
        "SELECT * FROM client_doc_requests WHERE registration_id = ? AND status = 'pending' ORDER BY requested_at DESC",
        (reg_id,)
    ).fetchall()
    # States for dropdown
    states = conn.execute("SELECT DISTINCT name AS state_name FROM states ORDER BY name").fetchall()

    # Photo-first gate (founder 2026-07-13): the client must upload their
    # photograph (from the dashboard) BEFORE the registration form opens, so it is
    # never skipped. Only enforced while the form is still a draft.
    if (reg['form_status'] or 'draft') == 'draft':
        has_photo = conn.execute(
            "SELECT 1 FROM client_documents cd "
            "JOIN client_registrations cr2 ON cr2.id = cd.registration_id "
            "WHERE cr2.account_id = ? AND cd.doc_type = 'Photograph' LIMIT 1",
            (acct_id,)).fetchone()
        if not has_photo:
            conn.close()
            flash('Please upload your photograph first — then continue your registration.', 'error')
            return redirect(url_for('client_dashboard'))

    if request.method == 'POST':
        # Editing is allowed after submit, but locks once operations has verified
        # (the master record is created then). Guard server-side too.
        if (reg['ops_status'] or '') == 'verified':
            conn.close()
            flash('Your details have been verified and can no longer be edited. Contact your counsellor for changes.', 'error')
            return redirect(url_for('client_dashboard'))
        step = int(request.form.get('step', 1))
        action = request.form.get('action', 'save')  # save, continue or submit
        # "Save Progress" must save WITHOUT moving the client on — current_step is
        # the furthest step reached, so advancing it on a draft save silently ticked
        # the step done and made the two buttons behave identically.
        _advance = (action == 'continue')

        if step == 1:
            # Personal info — config-driven (only the visible client fields).
            s1 = [f for f in form_config if (f['step_number'] or 1) == 1 and f['field_name'] in _CR_FORM_COLS]
            data = {f['field_name']: request.form.get(f['field_name'], '') for f in s1}

            # Parent / Guardian block (custom, NOT config-driven). Save the granular
            # fields + guardian_type, and compose the legacy father_name/mother_name/
            # parents_email so existing displays + the master sync keep working.
            gtype = (request.form.get('guardian_type', '') or '').strip()
            for c in ('guardian_type',
                      'father_first_name', 'father_last_name', 'father_email', 'father_phone',
                      'mother_first_name', 'mother_last_name', 'mother_email', 'mother_phone',
                      'guardian_first_name', 'guardian_last_name', 'guardian_email', 'guardian_phone'):
                data[c] = (request.form.get(c, '') or '').strip()

            def _full(a, b):
                return (a + ' ' + b).strip() if (a or b) else ''
            if gtype == 'guardian':
                # one guardian only — clear the parent legacy fields
                data['father_name'] = ''
                data['mother_name'] = ''
                data['parents_email'] = data.get('guardian_email') or ''
            else:  # parents (or unset) — compose the legacy names, but never blank
                # an existing value with an empty compose (protects older records
                # that had only the flat father_name/mother_name/parents_email).
                _fn = _full(data['father_first_name'], data['father_last_name'])
                _mn = _full(data['mother_first_name'], data['mother_last_name'])
                _pe = data.get('father_email') or data.get('mother_email') or ''
                if _fn:
                    data['father_name'] = _fn
                if _mn:
                    data['mother_name'] = _mn
                if _pe:
                    data['parents_email'] = _pe

            # A contactable parent/guardian is mandatory to move on. The form's JS
            # mirrors this; re-check here so it can't be bypassed. Draft saves are
            # never blocked, and the typed values are always kept either way.
            _pg_err = _parent_guardian_error(data) if action == 'continue' else None

            if data:
                sets = ', '.join(f"{k} = ?" for k in data)
                _adv = ', current_step = GREATEST(current_step, 2)' if (_advance and not _pg_err) else ''
                conn.execute(
                    f"UPDATE client_registrations SET {sets}{_adv}, "
                    f"updated_at = CURRENT_TIMESTAMP WHERE id = ?", list(data.values()) + [reg_id])
            elif _advance and not _pg_err:
                conn.execute("UPDATE client_registrations SET current_step = GREATEST(current_step, 2), "
                             "updated_at = CURRENT_TIMESTAMP WHERE id = ?", (reg_id,))
            if _pg_err:
                conn.commit()
                conn.close()
                flash(_pg_err, 'error')
                return redirect(url_for('client_form', reg_id=reg_id))

        elif step == 2:
            # Academic details — config-driven.
            s2 = [f for f in form_config if (f['step_number'] or 2) == 2 and f['field_name'] in _CA_FORM_COLS]
            acad_fields = {f['field_name']: request.form.get(f['field_name'], '') for f in s2}
            if academics:
                if acad_fields:
                    set_clause = ', '.join(f"{k} = ?" for k in acad_fields)
                    conn.execute(f"UPDATE client_academics SET {set_clause} WHERE registration_id = ?",
                                 list(acad_fields.values()) + [reg_id])
            elif acad_fields:
                cols = ', '.join(acad_fields.keys())
                placeholders = ', '.join(['?'] * (len(acad_fields) + 1))
                conn.execute(f"INSERT INTO client_academics (registration_id, {cols}) VALUES ({placeholders})",
                             [reg_id] + list(acad_fields.values()))
            if _advance:
                conn.execute("UPDATE client_registrations SET current_step = GREATEST(current_step, 3), updated_at = CURRENT_TIMESTAMP WHERE id = ?", (reg_id,))

        elif step == 3:
            # Document uploads handled via AJAX. To move past this step, a
            # government photo ID (Passport or Aadhaar Card) must be uploaded.
            if action == 'continue':
                id_ok = conn.execute(
                    "SELECT 1 FROM client_documents WHERE registration_id = ? "
                    "AND doc_type IN ('Passport', 'Aadhaar Card') LIMIT 1", (reg_id,)).fetchone()
                if not id_ok:
                    conn.commit()
                    conn.close()
                    flash('Please upload a government photo ID (Passport or Aadhaar Card) before continuing.', 'error')
                    return redirect(url_for('client_form', reg_id=reg_id))
            if _advance:
                conn.execute("UPDATE client_registrations SET current_step = GREATEST(current_step, 4), updated_at = CURRENT_TIMESTAMP WHERE id = ?", (reg_id,))

        if action == 'submit':
            # A contactable parent/guardian is mandatory. Re-check from the saved
            # record — the block lives on step 1, so a draft could reach submit
            # without ever passing the step-1 gate.
            _pg_err = _parent_guardian_error(
                conn.execute("SELECT * FROM client_registrations WHERE id = ?", (reg_id,)).fetchone())
            if _pg_err:
                conn.commit()
                conn.close()
                flash(_pg_err + ' (Personal Details step)', 'error')
                return redirect(url_for('client_form', reg_id=reg_id))
            # Mandatory government photo ID: at least one Passport or Aadhaar Card.
            id_ok = conn.execute(
                "SELECT 1 FROM client_documents WHERE registration_id = ? "
                "AND doc_type IN ('Passport', 'Aadhaar Card') LIMIT 1", (reg_id,)).fetchone()
            if not id_ok:
                conn.commit()
                conn.close()
                flash('Please upload a government photo ID (Passport or Aadhaar Card) in the Documents step before submitting.', 'error')
                return redirect(url_for('client_form', reg_id=reg_id))
            conn.execute("""UPDATE client_registrations SET form_status = 'submitted',
                client_submitted_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP WHERE id = ?""", (reg_id,))
            conn.commit()
            conn.close()
            # Send notification to sales + ops
            _notify_client_submitted(reg_id)
            flash('Your registration has been submitted successfully!', 'success')
            return redirect(url_for('client_dashboard'))

        conn.commit()
        conn.close()
        if _advance:
            flash('Progress saved!', 'success')
            return redirect(url_for('client_form', reg_id=reg_id))
        # Draft save: stay exactly where they are. The step bar shows what is still
        # left, so they can close the form and pick up from the same place later.
        flash('Saved. You are still on Step %d of 4 — %s. You can close this and '
              'continue later from where you left off.'
              % (step, _FORM_STEP_NAMES.get(step, '')), 'success')
        return redirect(url_for('client_form', reg_id=reg_id, step=step))

    # Load lookup options for academic dropdowns. DEDUPE per category — the
    # same value is defined once per pathway (e.g. 'Rheumatology' for plab +
    # australia + consulting), so appending every row made each option appear
    # 3-4 times in the dropdown. Keep the first occurrence only.
    # Scope dropdowns to THIS client's pathway (prefer pathway rows, fall back to
    # the PLAB set per category) — this also naturally de-dupes the values that
    # previously appeared 3-4× because every pathway's rows were unioned.
    _cf_pathway = resolve_ops_pathway(conn, reg.get('product_id'), reg.get('product_name'))
    lookup_rows = conn.execute(
        "SELECT category, value, COALESCE(pathway,'plab') AS pw FROM lookup_options "
        "WHERE is_active = TRUE ORDER BY category, sort_order, value").fetchall()
    _lk = {}
    for row in lookup_rows:
        d = _lk.setdefault(row['category'], {'match': [], 'plab': []})
        if row['pw'] == _cf_pathway:
            d['match'].append(row['value'])
        if row['pw'] == 'plab':
            d['plab'].append(row['value'])
    lookup_options = {}
    for cat, d in _lk.items():
        vals, seen, out = (d['match'] or d['plab']), set(), []
        for v in vals:
            if v not in seen:
                seen.add(v); out.append(v)
        lookup_options[cat] = out
    # Central country reference (single source of truth): names feed the academic
    # 'Country' dropdown (via db:countries), and (name, dial, region) feed the
    # phone country-code picker — one list everywhere.
    try:
        _crows = conn.execute(
            "SELECT name, dial_code, region FROM countries WHERE is_active = TRUE ORDER BY name").fetchall()
    except Exception:
        _crows = []
    lookup_options['countries'] = [r['name'] for r in _crows]
    phone_countries = [{'name': r['name'], 'dial': r['dial_code'], 'region': r['region']}
                       for r in _crows if (r['dial_code'] or '').strip()]
    conn.close()
    return render_template('client_form.html',
        reg=reg, academics=academics, documents=documents,
        form_config=form_config, doc_requests=doc_requests, states=states,
        lookup_options=lookup_options, phone_countries=phone_countries)


def _store_client_upload(file, pathway, reg_number, doc_type):
    """Persist a client-uploaded file and return (file_path, size, content_type).

    Client uploads used to go to static/uploads/ on local disk. Render has no
    persistent disk, so every client document was destroyed on the next deploy or
    restart — the files simply stopped existing. Send them to R2, exactly like the
    ops-side uploads, and store the bare R2 key in file_path (never a leading '/',
    which is what marks a row as a dead legacy disk path).
    """
    from core import storage
    body = file.read()
    content_type = file.mimetype or 'application/octet-stream'
    if storage.is_configured():
        from werkzeug.utils import secure_filename
        key = storage.make_doc_key(pathway or 'client', reg_number or 'unknown',
                                   doc_type or 'Other',
                                   secure_filename(file.filename) or 'file')
        if not storage.upload_bytes(key, body, content_type):
            return None, 0, content_type
        return key, len(body), content_type
    # No R2 (local dev only) — keep the old disk behaviour so dev still works.
    import os, uuid
    ext = file.filename.rsplit('.', 1)[-1].lower() if '.' in file.filename else 'pdf'
    fname = f"client_{uuid.uuid4().hex[:10]}.{ext}"
    upload_dir = os.path.join(app.root_path, 'static', 'uploads', 'client_docs')
    os.makedirs(upload_dir, exist_ok=True)
    with open(os.path.join(upload_dir, fname), 'wb') as fh:
        fh.write(body)
    return f'/static/uploads/client_docs/{fname}', len(body), content_type


@app.route('/client/upload-doc/<int:reg_id>', methods=['POST'])
@client_required
def client_upload_doc(reg_id):
    acct_id = session.get('user_id')
    conn = get_db()
    reg = conn.execute(
        "SELECT cr.id, cr.registration_number, ps.pathway FROM client_registrations cr "
        "LEFT JOIN products_services ps ON ps.id = cr.product_id "
        "WHERE cr.id = ? AND cr.account_id = ?", (reg_id, acct_id)).fetchone()
    if not reg:
        conn.close()
        return jsonify({'error': 'Not found'}), 404
    doc_type = request.form.get('doc_type', 'Other')
    file = request.files.get('file')
    if not file or not file.filename:
        conn.close()
        return jsonify({'error': 'No file selected'}), 400
    file_path, file_size, _ct = _store_client_upload(
        file, reg['pathway'], reg['registration_number'] or f'reg_{reg_id}', doc_type)
    if not file_path:
        conn.close()
        return jsonify({'error': 'Upload failed — please try again.'}), 500
    # Re-uploading the same doc type replaces it. Without this a client who
    # uploaded Aadhaar twice ended up with two rows, and the copy to the master
    # record faithfully duplicated both ("Aadhaar — 2 files").
    conn.execute("DELETE FROM client_documents WHERE registration_id = ? AND doc_type = ?",
                 (reg_id, doc_type))
    doc_id = conn.execute(
        "INSERT INTO client_documents (registration_id, doc_type, file_name, file_path, file_size) "
        "VALUES (?, ?, ?, ?, ?) RETURNING id",
        (reg_id, doc_type, file.filename, file_path, file_size)
    ).fetchone()['id']
    # Clear the request this upload answers. By id when the client uploaded straight
    # from the request on their dashboard, and ALSO by matching doc_type — so a
    # request is never left hanging just because the file arrived by another route.
    # Ops now picks doc_type from CLIENT_DOC_TYPES, the same list the client uploads
    # against, so these actually match (they never did when it was a free-text box).
    doc_req_id = request.form.get('doc_request_id')
    # Did this upload answer an outstanding document request? Used only to decide
    # whether to fire the team notification below (not to change any behaviour).
    _had_request = bool(doc_req_id)
    if not _had_request:
        try:
            _pr = conn.execute("SELECT 1 FROM client_doc_requests WHERE registration_id = ? "
                               "AND LOWER(TRIM(doc_type)) = LOWER(TRIM(?)) "
                               "AND COALESCE(status,'pending') <> 'fulfilled' LIMIT 1",
                               (reg_id, doc_type)).fetchone()
            _had_request = bool(_pr)
        except Exception:
            _had_request = False
    if doc_req_id:
        conn.execute("UPDATE client_doc_requests SET status = 'fulfilled', fulfilled_at = CURRENT_TIMESTAMP "
                     "WHERE id = ?", (doc_req_id,))
    conn.execute("UPDATE client_doc_requests SET status = 'fulfilled', fulfilled_at = CURRENT_TIMESTAMP "
                 "WHERE registration_id = ? AND LOWER(TRIM(doc_type)) = LOWER(TRIM(?)) "
                 "AND COALESCE(status,'pending') <> 'fulfilled'", (reg_id, doc_type))
    conn.commit()
    # When the client fulfils a requested document, tell the team via the editable
    # 'sc_document_submitted' template. Sends nothing if the template is disabled,
    # so this stays dormant until the founder enables it. (founder 2026-07-22)
    if _had_request:
        try:
            info = conn.execute(
                "SELECT TRIM(COALESCE(prefix,'')||' '||COALESCE(first_name,'')||' '||"
                "COALESCE(last_name,'')) AS nm, counsellor_id "
                "FROM client_registrations WHERE id = ?", (reg_id,)).fetchone()
            _cname = ((info['nm'] or '').strip() if info else '')
            _sc = _sc_render(conn, 'sc_document_submitted', {
                'client_name': _cname, 'doc_type': doc_type,
                'registration_number': (reg['registration_number'] or '')})
            if _sc:
                from email_utils import send_email
                _ops = _dept_emails(conn, ['Operations'])
                _cons = []
                if info and info['counsellor_id']:
                    _ce = conn.execute("SELECT email FROM employees WHERE id = ?",
                                       (info['counsellor_id'],)).fetchone()
                    if _ce and _ce['email']:
                        _cons = [_ce['email']]
                _to = list(dict.fromkeys([e for e in (_ops + _cons) if e]))
                if _to:
                    _ds_subj, _ds_body = _sc
                    send_email(_to, _ds_subj, _ds_body, from_address="GooCampus <info@goocampus.in>")
        except Exception as _e:
            logging.warning(f"sc_document_submitted notify {reg_id}: {_e}")
    conn.close()
    # Nested under 'doc' with every field the client_form.html row-builder reads,
    # so the uploaded file shows up immediately in the list below the upload box.
    return jsonify({'success': True, 'doc': {
        'id': doc_id,
        'file_name': file.filename,
        'doc_type': doc_type,
        'file_size': file_size,
        'uploaded_at': 'Just now',
    }})


@app.route('/client/delete-doc/<int:doc_id>', methods=['POST'])
@client_required
def client_delete_doc(doc_id):
    acct_id = session.get('user_id')
    conn = get_db()
    doc = conn.execute('''SELECT d.* FROM client_documents d
        JOIN client_registrations r ON r.id = d.registration_id
        WHERE d.id = ? AND r.account_id = ?''', (doc_id, acct_id)).fetchone()
    if not doc:
        conn.close()
        return jsonify({'error': 'Not found'}), 404
    # Delete file
    import os
    fpath = os.path.join(app.root_path, doc['file_path'].lstrip('/'))
    if os.path.exists(fpath):
        os.remove(fpath)
    conn.execute("DELETE FROM client_documents WHERE id = ?", (doc_id,))
    conn.commit()
    conn.close()
    return jsonify({'success': True})


def _serve_doc_row(doc):
    """Serve a doc row from R2 (presigned redirect) or the legacy BYTEA column."""
    r2_key = _r2_object_key_or_none(doc['file_path'])
    if r2_key:
        try:
            from core import storage
            url = storage.presigned_get_url(r2_key)
            if url:
                return redirect(url, code=302)
        except Exception as e:
            logging.error(f"_serve_doc_row presign: {e}")
        return "Document temporarily unavailable", 503
    if doc.get('file_data'):
        data = doc['file_data']
        if isinstance(data, memoryview):
            data = bytes(data)
        return send_file(BytesIO(data), download_name=doc['file_name'],
                         as_attachment=False,
                         mimetype=doc.get('content_type') or 'application/octet-stream')
    # Legacy '/static/uploads/...' row: the file lived on Render's disk, which has
    # no persistence, so the bytes are long gone. Say so instead of a bare 404.
    return "This file is no longer available — please upload it again.", 410


@app.route('/client/doc/<int:doc_id>/file')
@client_required
def client_serve_reg_doc(doc_id):
    """A client viewing their own registration document (client_documents)."""
    conn = get_db()
    doc = conn.execute(
        "SELECT d.file_name, d.file_path, d.file_size FROM client_documents d "
        "JOIN client_registrations cr ON cr.id = d.registration_id "
        "WHERE d.id = ? AND cr.account_id = ?", (doc_id, session.get('user_id'))).fetchone()
    conn.close()
    if not doc:
        return "Document not found", 404
    return _serve_doc_row(dict(doc))


@app.route('/client/plab-doc/<int:doc_id>/file')
@client_required
def client_serve_plab_doc(doc_id):
    """A client viewing their own ops-side document (plab_client_documents).
    Ownership is proved by joining back to a registration on this account."""
    conn = get_db()
    doc = conn.execute(
        "SELECT d.file_name, d.file_path, d.file_data, d.content_type "
        "  FROM plab_client_documents d "
        "  JOIN plab_clients pc ON pc.id = d.client_id "
        "  JOIN client_registrations cr ON cr.registration_number = pc.registration_number "
        " WHERE d.id = ? AND cr.account_id = ? LIMIT 1",
        (doc_id, session.get('user_id'))).fetchone()
    conn.close()
    if not doc:
        return "Document not found", 404
    return _serve_doc_row(dict(doc))


