@app.route('/client/upload-plab-doc', methods=['POST'])
@client_required
def client_upload_plab_doc():
    """Client uploads a document to plab_client_documents for ops review."""
    acct_id = session.get('user_id')
    conn = get_db()
    # Find the client's registration. Prefer one that already has a reg number
    # (post-verify), but a pre-verify registration is fine too — the photo then
    # gets stored against the registration until ops verify creates the PLAB row.
    reg = conn.execute("""SELECT cr.id, cr.registration_number, cr.product_id FROM client_registrations cr
        WHERE cr.account_id = ?
        ORDER BY (cr.registration_number IS NOT NULL) DESC, cr.id DESC LIMIT 1""", (acct_id,)).fetchone()
    if not reg:
        conn.close()
        return jsonify({'error': 'No linked registration found'}), 404
    plab_client = None
    if reg['registration_number']:
        plab_client = conn.execute("SELECT id FROM plab_clients WHERE registration_number = ?",
                                   (reg['registration_number'],)).fetchone()
    doc_type = request.form.get('doc_type', 'Photograph')
    doc_category = request.form.get('doc_category', 'personal')
    file = request.files.get('file')
    if not file or not file.filename:
        conn.close()
        return jsonify({'error': 'No file selected'}), 400
    try:
        _pathway = resolve_ops_pathway(conn, reg.get('product_id'), None)
        file_path, file_size, content_type = _store_client_upload(
            file, _pathway, reg['registration_number'] or f"reg_{reg['id']}", doc_type)
        if not file_path:
            conn.close()
            return jsonify({'error': 'Upload failed — please try again.'}), 500
        if plab_client:
            # Verified client -> ops-side documents keyed by plab_client id.
            conn.execute("DELETE FROM plab_client_documents WHERE client_id = ? AND doc_type = ?",
                         (plab_client['id'], doc_type))
            conn.execute("""INSERT INTO plab_client_documents (client_id, doc_type, doc_category, file_name, file_path, file_size, uploaded_by, content_type)
                VALUES (?, ?, ?, ?, ?, ?, 'client', ?)""",
                (plab_client['id'], doc_type, doc_category, file.filename,
                 file_path, file_size, content_type))
        else:
            # Not yet verified -> store against the registration (client_documents).
            conn.execute("DELETE FROM client_documents WHERE registration_id = ? AND doc_type = ?",
                         (reg['id'], doc_type))
            conn.execute("""INSERT INTO client_documents (registration_id, doc_type, file_name, file_path, file_size)
                VALUES (?, ?, ?, ?, ?)""",
                (reg['id'], doc_type, file.filename, file_path, file_size))
        conn.commit()
    except Exception as e:
        logging.error(f"client_upload_plab_doc: {e}")
        try: conn.rollback()
        except Exception: pass
        conn.close()
        return jsonify({'error': 'Upload failed — please try again.'}), 500
    conn.close()
    return jsonify({'success': True})


def _dept_emails(conn, departments):
    """Active employees' emails for the given department names."""
    try:
        ph = ','.join(['?'] * len(departments))
        rows = conn.execute(
            f"SELECT DISTINCT email FROM employees WHERE is_active = 1 "
            f"AND department IN ({ph}) AND email IS NOT NULL AND email <> ''",
            list(departments)).fetchall()
        return [r['email'] for r in rows if r['email']]
    except Exception:
        return []


def _management_emails(conn):
    """Management: admins + management employee codes."""
    try:
        rows = conn.execute(
            "SELECT DISTINCT email FROM employees WHERE is_active = 1 "
            "AND (is_admin = 1 OR emp_code IN ('GC001','GC002','GC003')) "
            "AND email IS NOT NULL AND email <> ''").fetchall()
        return [r['email'] for r in rows if r['email']]
    except Exception:
        return []


def _lead_sales_member(conn, reg):
    """The sales member whose lead this is — the reg's counsellor, else the
    invitation's inviter. Returns (name, email)."""
    emp = None
    try:
        if reg.get('counsellor_id'):
            emp = conn.execute("SELECT name, email FROM employees WHERE id = ?", (reg['counsellor_id'],)).fetchone()
        if (not emp or not emp['email']) and reg.get('invitation_id'):
            inv = conn.execute("SELECT invited_by FROM client_invitations WHERE id = ?", (reg['invitation_id'],)).fetchone()
            if inv and inv['invited_by']:
                emp = conn.execute("SELECT name, email FROM employees WHERE id = ?", (inv['invited_by'],)).fetchone()
    except Exception:
        emp = None
    if emp:
        return (emp['name'] or '', emp['email'] or '')
    return ('', '')


def _client_photo_email_url(conn, reg):
    """Absolute, email-safe URL for the client's photograph, or ''."""
    try:
        row = conn.execute(
            "SELECT file_path FROM client_documents WHERE registration_id = ? "
            "AND doc_type = 'Photograph' ORDER BY id DESC LIMIT 1", (reg['id'],)).fetchone()
        fp = (row['file_path'] if row else '') or ''
        if not fp:
            return ''
        if fp.startswith('http'):
            return fp
        if 'static/' in fp:
            return 'https://goocampus.org/' + fp.lstrip('/')
        try:
            from core import storage
            return storage.presigned_get_url(fp) or ''
        except Exception:
            return ''
    except Exception:
        return ''


def _notify_client_submitted(reg_id):
    """Client submitted their registration form → email the SALES member whose
    lead it is + the whole Operations team a branded summary (client photo +
    whose-lead + product + basic details)."""
    try:
        conn = get_db()
        reg = conn.execute('''SELECT cr.*, ps.name as product_name, ps.pathway as pathway
            FROM client_registrations cr
            LEFT JOIN products_services ps ON ps.id = cr.product_id
            WHERE cr.id = ?''', (reg_id,)).fetchone()
        if not reg:
            conn.close()
            return
        client_name = f"{reg['prefix'] or ''} {reg['first_name'] or ''} {reg['last_name'] or ''}".strip()
        sm_name, sm_email = _lead_sales_member(conn, reg)
        ops_emails = _dept_emails(conn, ['Operations'])
        mgmt_emails = _management_emails(conn)
        photo_url = _client_photo_email_url(conn, reg)

        from email_utils import (send_email, render_branded_email, brand_detail_rows,
                                  brand_photo_block, brand_button)
        pathway_lbl = (reg['pathway'] or '').replace('_', ' ').title() if reg['pathway'] else ''
        details = brand_detail_rows([
            ('Client', client_name),
            ('Registration #', reg['registration_number']),
            ('Product', reg['product_name']),
            ('Pathway', pathway_lbl),
            ('Whose lead', sm_name),
            ('Mobile', reg['mobile']),
            ('Email', reg['email']),
        ])
        # 1) The LEAD's sales member — the ONLY one with the action button. Sales
        #    verification must happen first, so only they can act on it.
        if sm_email:
            s_inner = (brand_photo_block(photo_url, client_name) +
                f"<p style='margin:0 0 6px;'><strong>{client_name or 'A client'}</strong> has completed their "
                f"registration form. Please complete the <strong>Sales Verification</strong>.</p>" + details +
                brand_button('Open Sales Verification', 'https://goocampus.org/verifications/sales'))
            send_email([sm_email], f"Action needed — Sales Verification: {client_name}",
                       render_branded_email('New Registration — Sales Verification needed', s_inner,
                                            preheader=f"{client_name} completed their form"),
                       from_address="GooCampus <info@goocampus.in>")
        # 2) Operations + Management — PLAIN, NO button. Ops gets its action link only
        #    AFTER sales verifies (see _notify_sales_completed). Management is always plain.
        plain_to = list(dict.fromkeys([e for e in (ops_emails + mgmt_emails) if e and e != sm_email]))
        if plain_to:
            p_inner = (brand_photo_block(photo_url, client_name) +
                f"<p style='margin:0 0 6px;'><strong>{client_name or 'A client'}</strong> has completed their "
                f"registration form. It is now with <strong>{sm_name or 'Sales'}</strong> for sales verification — "
                f"the Operations team will be notified when it's ready to verify.</p>" + details)
            # Editable Standard Consulting template drives subject+body when the
            # founder has enabled it; else the built-in email above. (2026-07-22)
            _sc = _sc_render(conn, 'sc_registration_submitted', {
                'client_name': client_name,
                'product_name': (reg['product_name'] or ''),
                'registration_number': (reg['registration_number'] or ''),
                'counsellor_name': (sm_name or '')})
            if _sc:
                _subj, _body = _sc
            else:
                _subj = f"New Registration Submitted — {client_name}"
                _body = render_branded_email('New Registration Submitted', p_inner,
                                             preheader=f"{client_name} — awaiting sales verification")
            send_email(plain_to, _subj, _body,
                       from_address="GooCampus <info@goocampus.in>")

        recipients = list(dict.fromkeys([e for e in ([sm_email] + plain_to) if e]))
        conn.execute(
            "INSERT INTO client_notifications (registration_id, notification_type, channel, recipient, subject, message) VALUES (?, ?, ?, ?, ?, ?)",
            (reg_id, 'client_submitted', 'email', ','.join(recipients), f"New Registration Submitted — {client_name}", 'Sales member (button) + Ops/Mgmt (plain) notified'))
        conn.commit()
        conn.close()
    except Exception as e:
        logging.error(f"_notify_client_submitted: {e}")


