@app.route('/admin/client-invitations/create', methods=['POST'])
@login_required
def client_invitation_create():
    import uuid
    user = get_user()
    client_name = request.form.get('client_name', '').strip()
    client_mobile = request.form.get('client_mobile', '').strip()
    client_email = request.form.get('client_email', '').strip()
    product_id = request.form.get('product_id')

    if not client_name or not client_mobile or not product_id:
        flash('Client name, mobile and product are required', 'error')
        return redirect(url_for('client_invitations_list'))

    # Normalize mobile
    clean = client_mobile.lstrip('+').lstrip('0')
    if clean.startswith('91') and len(clean) == 12:
        clean = clean[2:]

    token = uuid.uuid4().hex
    conn = get_db()
    try:
        conn.execute(
            "INSERT INTO client_invitations (token, product_id, client_name, client_mobile, client_email, invited_by) VALUES (?, ?, ?, ?, ?, ?)",
            (token, product_id, client_name, clean, client_email, user['id']))
        conn.commit()
        invite_url = f"https://goocampus.org/client/register/{token}"

        wa_ok = False
        try:
            wa_ok = _send_client_invite_wa(clean, client_name, invite_url)
        except Exception as wa_err:
            logging.error(f"WA invite send failed: {wa_err}")

        email_ok = False
        if client_email:
            try:
                svc_name = ''
                try:
                    pr = conn.execute("SELECT name FROM products_services WHERE id = ?", (product_id,)).fetchone()
                    if pr: svc_name = pr['name'] or ''
                except Exception: pass
                email_ok = _send_client_invite_email(
                    client_email, client_name, invite_url,
                    service_name=svc_name, counsellor_name=(user.get('name') or ''))
            except Exception as em_err:
                logging.error(f"client invite email send failed: {em_err}")

        # Report what was actually delivered, so a silent failure is visible to
        # the rep — and always show the link so they can share it manually.
        sent = ([ 'WhatsApp' ] if wa_ok else []) + ([ 'email' ] if email_ok else [])
        if sent:
            flash(f"Invitation sent via {' + '.join(sent)}. Link: {invite_url}", 'success')
        else:
            flash(f"Invitation created, but automatic delivery failed "
                  f"(WhatsApp/email) — please share this link manually: {invite_url}", 'warning')

    except Exception as e:
        logging.error(f"client_invitation_create: {e}")
        try:
            conn.rollback()
        except Exception:
            pass
        flash('Error creating invitation', 'error')
    finally:
        conn.close()
    return redirect(url_for('client_invitations_list'))


