@app.route('/admin/diag/academics', methods=['GET'])
@login_required
def admin_diag_academics():
    """READ-ONLY diagnostic: for a client (by name or registration number), show
    where their academic details live across the 3 tables — the registration-side
    client_academics, the ops-side ops_academic_details, and whether a plab_clients
    master exists. Writes nothing. Used to trace 'academics not showing in the ops
    academic section' (founder 2026-07-21). Safe to leave in; admin-only."""
    user = get_user()
    if not (user and user['is_admin']):
        flash('Admin access required', 'error')
        return redirect(url_for('dashboard'))
    q = (request.args.get('q') or '').strip()
    conn = get_db()
    out = []
    try:
        if not q:
            conn.close()
            return "<pre>Pass ?q=Name or ?q=REGNUMBER</pre>"
        like = f"%{q}%"
        regs = conn.execute(
            "SELECT id, registration_number, first_name, last_name, product_id, "
            "       current_step, sales_completed, ops_status, ops_verified_at, created_at "
            "  FROM client_registrations "
            " WHERE first_name ILIKE ? OR last_name ILIKE ? OR registration_number ILIKE ? "
            "    OR (COALESCE(first_name,'')||' '||COALESCE(last_name,'')) ILIKE ? "
            " ORDER BY id DESC LIMIT 20",
            (like, like, like, like)).fetchall()
        for r in regs:
            rid = r['id']; rnum = r['registration_number']
            ca = conn.execute("SELECT * FROM client_academics WHERE registration_id = ?", (rid,)).fetchone()
            pc = conn.execute("SELECT id, created_at, pathway FROM plab_clients WHERE registration_number = ?", (rnum,)).fetchone()
            oad = conn.execute("SELECT * FROM ops_academic_details WHERE registration_number = ?", (rnum,)).fetchall()
            def _filled(row):
                if not row:
                    return None
                return {k: v for k, v in dict(row).items()
                        if k not in ('id', 'registration_id', 'registration_number', 'created_at', 'created_by')
                        and v not in (None, '', 0)}
            out.append({
                'reg_id': rid, 'reg_number': rnum,
                'name': f"{r['first_name'] or ''} {r['last_name'] or ''}".strip(),
                'product_id': r['product_id'], 'current_step': r['current_step'],
                'sales_completed': r['sales_completed'], 'ops_status': r['ops_status'],
                'ops_verified_at': r['ops_verified_at'],
                'plab_master': ('YES id=%s pathway=%s' % (pc['id'], pc['pathway'])) if pc else 'NO',
                'client_academics_row': 'PRESENT' if ca else 'MISSING',
                'client_academics_filled_fields': _filled(ca),
                'ops_academic_details_rows': len(oad),
                'ops_academic_details_filled_fields': [_filled(x) for x in oad] if oad else None,
            })
        import json as _json
        return "<pre>" + _json.dumps(out, indent=2, default=str) + "</pre>"
    finally:
        conn.close()


@app.route('/admin/attach-contract', methods=['GET', 'POST'])
@login_required
def admin_attach_contract():
    """Admin tool: attach a signed contract to an ALREADY-ONBOARDED client whose
    contract was missing at onboarding, and record their acceptance in one step —
    so the dashboard gate stays satisfied and they are NOT re-locked / re-prompted.
    Propagates the contract to registration + invitation + plab_clients master +
    Documents, and records a 'contract' agreement under the client's own name with
    an admin-backfill audit note. Refund policy untouched. (founder 2026-07-22)"""
    user = get_user()
    if not (user and user['is_admin']):
        flash('Admin access required', 'error'); return redirect(url_for('dashboard'))
    reg_number = (request.values.get('reg') or '').strip()
    conn = get_db()
    try:
        reg = None
        if reg_number:
            reg = conn.execute(
                "SELECT * FROM client_registrations WHERE registration_number = ? "
                "AND client_submitted_at IS NOT NULL ORDER BY id DESC LIMIT 1", (reg_number,)).fetchone()

        # ---- current-state snapshot (read-only) ----
        def _state(r):
            if not r:
                return None
            acct = r['account_id']; rid = r['id']
            pc = conn.execute("SELECT id, prefix, first_name, last_name, contract_path FROM plab_clients "
                              "WHERE registration_number = ?", (reg_number,)).fetchone()
            contract_signed = bool(conn.execute(
                "SELECT 1 FROM client_agreements WHERE account_id = ? AND registration_id = ? "
                "AND agreement_type = 'contract' LIMIT 1", (acct, rid)).fetchone())
            refund_signed = bool(conn.execute(
                "SELECT 1 FROM client_agreements WHERE account_id = ? AND agreement_type = 'refund_policy' LIMIT 1",
                (acct,)).fetchone())
            full = f"{(r['prefix'] or '')} {(r['first_name'] or '')} {(r['last_name'] or '')}".strip()
            return {'acct': acct, 'rid': rid, 'pc': pc, 'name': full,
                    'reg_contract': bool(r['contract_path']),
                    'pc_contract': bool(pc['contract_path']) if pc else False,
                    'contract_signed': contract_signed, 'refund_signed': refund_signed,
                    'onboarded': bool(r['client_submitted_at'])}

        if request.method == 'POST':
            if not reg:
                return f"<pre>No submitted registration found for '{reg_number}'.</pre>", 404
            st = _state(reg)
            agreed_name = (request.form.get('agreed_name') or '').strip() or st['name']
            cfile = request.files.get('contract_file')
            if not cfile or not cfile.filename:
                return "<pre>Please choose the signed contract PDF to upload.</pre>", 400
            cbytes = cfile.read()
            if len(cbytes) > 15 * 1024 * 1024:
                return "<pre>File too large (max 15 MB).</pre>", 400
            from core import storage
            if not storage.is_configured():
                return "<pre>File storage not configured — cannot save contract.</pre>", 500
            cext = cfile.filename.rsplit('.', 1)[-1].lower() if '.' in cfile.filename else 'pdf'
            ckey = storage.make_doc_key('client', f"reg_{reg['id']}", 'Contract', cfile.filename)
            if not storage.upload_bytes(ckey, cbytes, _CONTRACT_CT.get(cext, 'application/octet-stream')):
                return "<pre>Upload to storage failed. Try again.</pre>", 500

            # 1) registration + 2) invitation + 3) plab_clients master
            conn.execute("UPDATE client_registrations SET contract_path = ? WHERE id = ?", (ckey, reg['id']))
            if reg['invitation_id']:
                conn.execute("UPDATE client_invitations SET contract_path = ? WHERE id = ?", (ckey, reg['invitation_id']))
            conn.execute("UPDATE plab_clients SET contract_path = ?, updated_at = CURRENT_TIMESTAMP "
                         "WHERE registration_number = ?", (ckey, reg_number))
            # 4) Documents section (skip if a Signed Contract doc already exists)
            if st['pc']:
                dup = conn.execute("SELECT 1 FROM plab_client_documents WHERE client_id = ? AND doc_type = 'Signed Contract' LIMIT 1",
                                   (st['pc']['id'],)).fetchone()
                if not dup:
                    conn.execute(
                        "INSERT INTO plab_client_documents (client_id, doc_type, doc_category, file_name, "
                        " file_path, file_size, status, uploaded_by) "
                        "VALUES (?, 'Signed Contract', 'contract', 'Signed Contract', ?, ?, 'uploaded', 'admin-backfill')",
                        (st['pc']['id'], ckey, len(cbytes)))
            # 5) record the client's contract acceptance (under her name) — honest audit note
            if not st['contract_signed']:
                note = f"admin-recorded by {user['name']} (post-onboarding backfill) via /admin/attach-contract"
                conn.execute(
                    "INSERT INTO client_agreements (account_id, registration_id, agreement_type, agreed_name, ip_address) "
                    "VALUES (?, ?, 'contract', ?, ?)", (reg['account_id'], reg['id'], agreed_name, note))
            conn.commit()
            return ("<div style='font-family:system-ui;max-width:680px;margin:40px auto'>"
                    f"<h2>Done ✅</h2><p>Signed contract attached for <b>{agreed_name}</b> "
                    f"({reg_number}) and recorded as digitally accepted (under her name, admin-noted).</p>"
                    "<ul><li>Registration, invitation, client profile + Documents section all updated.</li>"
                    "<li>Her dashboard stays unlocked — she is NOT asked to re-sign.</li>"
                    "<li>Refund policy left exactly as it was.</li></ul>"
                    f"<a href='/admin/attach-contract?reg={reg_number}'>Re-check her state</a></div>")

        # ---- GET: show current state + upload form ----
        if not reg:
            return ("<div style='font-family:system-ui;max-width:680px;margin:40px auto'>"
                    "<h2>Attach signed contract (already-onboarded client)</h2>"
                    "<form method='GET'><label>Registration number: "
                    "<input name='reg' value='' style='padding:6px;width:220px'></label> "
                    "<button>Look up</button></form>"
                    + (f"<p style='color:#b91c1c'>No submitted registration found for '{reg_number}'.</p>" if reg_number else "")
                    + "</div>")
        st = _state(reg)
        def _yn(b): return "<b style='color:#065f46'>Yes</b>" if b else "<b style='color:#b91c1c'>No</b>"
        return (
            "<div style='font-family:system-ui;max-width:680px;margin:40px auto'>"
            f"<h2>{st['name']} — {reg_number}</h2>"
            "<table cellpadding='6' style='border-collapse:collapse'>"
            f"<tr><td>Onboarded (submitted)</td><td>{_yn(st['onboarded'])}</td></tr>"
            f"<tr><td>Contract file on record</td><td>{_yn(st['reg_contract'] or st['pc_contract'])}</td></tr>"
            f"<tr><td>Contract digitally signed</td><td>{_yn(st['contract_signed'])}</td></tr>"
            f"<tr><td>Refund policy signed</td><td>{_yn(st['refund_signed'])}</td></tr>"
            "</table>"
            "<hr><h3>Attach the signed contract + record her acceptance</h3>"
            "<p style='font-size:.9rem;color:#555'>Uploads the PDF to her registration, invitation, profile "
            "and Documents, and records it as digitally accepted under her name (with an admin audit note). "
            "She will NOT be re-prompted; refund policy is untouched.</p>"
            "<form method='POST' enctype='multipart/form-data'>"
            f"<input type='hidden' name='reg' value='{reg_number}'>"
            f"<p>Signatory name: <input name='agreed_name' value=\"{st['name']}\" style='padding:6px;width:280px'></p>"
            "<p>Signed contract (PDF): <input type='file' name='contract_file' accept='.pdf,.doc,.docx,.jpg,.png' required></p>"
            "<button style='padding:10px 20px;background:#F57C1F;color:#fff;border:none;border-radius:6px;font-weight:700;cursor:pointer'>"
            "Attach contract + mark accepted</button></form></div>")
    finally:
        try: conn.close()
        except Exception: pass


@app.route('/admin/set-registration-date', methods=['GET', 'POST'])
@login_required
def admin_set_registration_date():
    """Admin: correct a client's registration date to the sales CLOSE date (founder
    2026-07-22 — "the close date IS the registration date"). Going forward this is
    automatic; this fixes clients registered before the change. Read-only preview on GET."""
    user = get_user()
    if not (user and user['is_admin']):
        flash('Admin access required', 'error'); return redirect(url_for('dashboard'))
    reg_number = (request.values.get('reg') or '').strip()
    conn = get_db()
    try:
        pc = None
        if reg_number:
            pc = conn.execute("SELECT id, prefix, first_name, last_name, registration_date "
                              "FROM plab_clients WHERE registration_number = ?", (reg_number,)).fetchone()
        if request.method == 'POST':
            new_date = (request.form.get('new_date') or '').strip()
            if not pc:
                return f"<pre>No client found for '{reg_number}'.</pre>", 404
            if not new_date:
                return "<pre>Please choose the close/registration date.</pre>", 400
            conn.execute("UPDATE plab_clients SET registration_date = ?, updated_at = CURRENT_TIMESTAMP "
                         "WHERE registration_number = ?", (new_date, reg_number))
            conn.execute("UPDATE client_registrations SET sales_close_date = ? WHERE registration_number = ?",
                         (new_date, reg_number))
            conn.commit()
            return ("<div style='font-family:system-ui;max-width:620px;margin:40px auto'>"
                    f"<h2>Done ✅</h2><p>Registration date for <b>{(pc['first_name'] or '')} "
                    f"{(pc['last_name'] or '')}</b> ({reg_number}) set to <b>{new_date}</b> "
                    "on the profile.</p><a href='/admin/set-registration-date?reg="
                    f"{reg_number}'>Re-check</a></div>")
        # GET preview + form
        if not pc:
            return ("<div style='font-family:system-ui;max-width:620px;margin:40px auto'>"
                    "<h2>Set a client's registration date</h2>"
                    "<form method='GET'>Registration number: "
                    "<input name='reg' style='padding:6px;width:230px'> <button>Look up</button></form>"
                    + (f"<p style='color:#b91c1c'>No client found for '{reg_number}'.</p>" if reg_number else "")
                    + "</div>")
        cur = pc['registration_date'] or ''
        cur = cur.strftime('%Y-%m-%d') if hasattr(cur, 'strftime') else str(cur)[:10]
        return ("<div style='font-family:system-ui;max-width:620px;margin:40px auto'>"
                f"<h2>{(pc['prefix'] or '')} {(pc['first_name'] or '')} {(pc['last_name'] or '')} — {reg_number}</h2>"
                f"<p>Current registration date on the profile: <b>{cur or '(none)'}</b></p>"
                "<form method='POST'>"
                f"<input type='hidden' name='reg' value='{reg_number}'>"
                "<p>Set registration date (the sales close date): "
                f"<input type='date' name='new_date' value='{cur}' required></p>"
                "<button style='padding:10px 20px;background:#F57C1F;color:#fff;border:none;border-radius:6px;"
                "font-weight:700;cursor:pointer'>Update registration date</button></form></div>")
    finally:
        try: conn.close()
        except Exception: pass


@app.route('/admin/fix-lead', methods=['GET', 'POST'])
@login_required
def admin_fix_lead():
    """Admin: find a client's sales lead(s) by name/phone and close them (set to the
    Won stage) or delete a duplicate. Also surfaces if the Won stage is inactive (why
    'Closed Won' wouldn't appear in the pipeline dropdown). (founder 2026-07-22)"""
    user = get_user()
    if not (user and user['is_admin']):
        flash('Admin access required', 'error'); return redirect(url_for('dashboard'))
    q = (request.values.get('q') or '').strip()
    conn = get_db()
    try:
        won = conn.execute("SELECT id, name, is_active FROM sales_lead_stages WHERE is_won = 1 "
                           "ORDER BY is_active DESC, id LIMIT 1").fetchone()
        if request.method == 'POST':
            action = request.form.get('action')
            lead_id = request.form.get('lead_id', type=int)
            if action == 'set_won' and lead_id and won:
                conn.execute("UPDATE sales_leads SET stage_id = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
                             (won['id'], lead_id)); conn.commit()
                msg = f"Lead #{lead_id} set to {won['name']}."
            elif action == 'delete' and lead_id:
                conn.execute("DELETE FROM sales_leads WHERE id = ?", (lead_id,)); conn.commit()
                msg = f"Lead #{lead_id} deleted."
            elif action == 'activate_won' and won:
                conn.execute("UPDATE sales_lead_stages SET is_active = 1 WHERE id = ?", (won['id'],)); conn.commit()
                msg = f"Stage '{won['name']}' re-activated (now selectable in the pipeline)."
            else:
                msg = "Nothing to do."
            return (f"<div style='font-family:system-ui;max-width:640px;margin:40px auto'>"
                    f"<h2>Done ✅</h2><p>{msg}</p><a href='/admin/fix-lead?q={q}'>Back</a></div>")
        rows = []
        if q:
            like = f"%{q}%"
            digits = re.sub(r'[^0-9]', '', q)
            rows = conn.execute(
                "SELECT sl.id, sl.lead_name, sl.phone, sl.email, s.name AS stage, COALESCE(s.is_won,0) AS won "
                "FROM sales_leads sl LEFT JOIN sales_lead_stages s ON s.id = sl.stage_id "
                "WHERE sl.lead_name ILIKE ? "
                + ("OR RIGHT(regexp_replace(COALESCE(sl.phone,''),'[^0-9]','','g'),10) = ? " if len(digits) >= 10 else "")
                + "ORDER BY sl.id DESC",
                ((like, digits[-10:]) if len(digits) >= 10 else (like,))).fetchall()
        won_note = ""
        if won and not won['is_active']:
            won_note = (f"<div style='background:#FEF3C7;border:1px solid #FCD34D;padding:8px 12px;border-radius:6px;margin:10px 0;'>"
                        f"⚠ The Won stage '<b>{won['name']}</b>' is currently <b>inactive</b>, so it doesn't show in the pipeline "
                        f"stage dropdown. <form method='POST' style='display:inline'><input type='hidden' name='action' value='activate_won'>"
                        f"<button style='margin-left:8px;padding:4px 10px;cursor:pointer'>Re-activate it</button></form></div>")
        items = "".join(
            f"<tr><td>{r['id']}</td><td>{r['lead_name']}</td><td>{r['phone'] or '—'}</td>"
            f"<td>{'<b style=color:#065f46>'+ (r['stage'] or '—') +'</b>' if r['won'] else (r['stage'] or '—')}</td>"
            f"<td><form method='POST' style='display:inline'><input type='hidden' name='action' value='set_won'>"
            f"<input type='hidden' name='lead_id' value='{r['id']}'>"
            f"<button {'disabled' if r['won'] else ''} style='padding:4px 10px;cursor:pointer'>Set Closed Won</button></form> "
            f"<form method='POST' style='display:inline' onsubmit=\"return confirm('Delete this lead permanently?')\">"
            f"<input type='hidden' name='action' value='delete'><input type='hidden' name='lead_id' value='{r['id']}'>"
            f"<button style='padding:4px 10px;color:#b91c1c;cursor:pointer'>Delete</button></form></td></tr>"
            for r in rows)
        return ("<div style='font-family:system-ui;max-width:820px;margin:30px auto'>"
                "<h2>Fix a sales lead (close / dedupe)</h2>"
                "<form method='GET'>Search by name or phone: "
                f"<input name='q' value='{q}' style='padding:6px;width:260px'> <button>Search</button></form>"
                + won_note
                + (("<table border='1' cellpadding='6' cellspacing='0' style='border-collapse:collapse;width:100%;margin-top:12px'>"
                    "<tr style='background:#f3f4f6'><th>ID</th><th>Lead</th><th>Phone</th><th>Stage</th><th>Actions</th></tr>"
                    + items + "</table>") if rows else (f"<p>No leads found for '{q}'.</p>" if q else ""))
                + "</div>")
    finally:
        try: conn.close()
        except Exception: pass


def _pathway_audit_tables(conn):
    """Which OPS_PATHWAY_TABLES have BOTH a registration_number and a pathway column
    (so a row can be checked against its client's master pathway)."""
    out = []
    for t in OPS_PATHWAY_TABLES:
        try:
            cols = {c['column_name'] for c in conn.execute(
                "SELECT column_name FROM information_schema.columns WHERE table_name = ?", (t,)).fetchall()}
        except Exception:
            try: conn.rollback()
            except Exception: pass
            cols = set()
        if 'registration_number' in cols and 'pathway' in cols:
            out.append(t)
    return out


@app.route('/admin/recompute-closure', methods=['GET', 'POST'])
@login_required
def admin_recompute_closure():
    """Admin: recompute a sales closure's revenue/cost/margin from its plan's
    Package - Cost (the universal Sales Revenue rule), for closures saved before
    the plan's package/cost was set — e.g. a V2 closure stuck at 0. Read-only
    until you click Recompute on a specific row; never a silent backfill.
    (founder 2026-07-22)"""
    user = get_user()
    if not (user and user['is_admin']):
        flash('Admin access required', 'error'); return redirect(url_for('dashboard'))
    q = (request.values.get('q') or '').strip()
    conn = get_db()
    msg = None
    if request.method == 'POST':
        cid = request.form.get('closure_id', type=int)
        row = conn.execute(
            "SELECT sc.id, sc.product_id AS c_pid, sc.revenue, sc.cost, sc.margin, "
            "       sl.product_id AS l_pid, sl.plan_type "
            "  FROM sales_closures sc LEFT JOIN sales_leads sl ON sl.id = sc.lead_id "
            " WHERE sc.id = ?", (cid,)).fetchone()
        if not row:
            msg = ('error', f'Closure #{cid} not found.')
        else:
            pid = row['c_pid'] or row['l_pid']
            pt = (row['plan_type'] or '').strip()
            _disc = request.form.get('discount', 0)
            new_rev, new_cost = _closure_revenue_cost(conn, pid, pt, discount=_disc,
                                                      fallback_revenue=row['revenue'])
            new_margin = new_rev - new_cost
            conn.execute("UPDATE sales_closures SET revenue = ?, cost = ?, margin = ? WHERE id = ?",
                         (new_rev, new_cost, new_margin, cid))
            conn.commit()
            try:
                _dv = float(_disc or 0)
            except (TypeError, ValueError):
                _dv = 0.0
            msg = ('success', f'Closure #{cid}: revenue ₹{new_rev:,.0f}, cost ₹{new_cost:,.0f}, '
                              f'discount ₹{_dv:,.0f}, margin ₹{new_margin:,.0f} (plan "{pt or "—"}").')
    rows = []
    if q:
        like = f"%{q}%"
        rows = conn.execute(
            "SELECT sc.id, sc.client_name, sc.product_name, sc.revenue, sc.cost, sc.margin, "
            "       sc.product_id AS c_pid, sl.product_id AS l_pid, sl.plan_type, e.name AS emp, "
            "       (SELECT cr.discount_allowed FROM client_registrations cr "
            "         WHERE RIGHT(regexp_replace(COALESCE(cr.phone,''),'[^0-9]','','g'),10) "
            "             = RIGHT(regexp_replace(COALESCE(sl.phone,''),'[^0-9]','','g'),10) "
            "           AND cr.discount_allowed IS NOT NULL "
            "         ORDER BY cr.id DESC LIMIT 1) AS reg_discount "
            "  FROM sales_closures sc "
            "  LEFT JOIN sales_leads sl ON sl.id = sc.lead_id "
            "  LEFT JOIN employees e ON e.id = sc.employee_id "
            " WHERE sc.client_name ILIKE ? OR sc.product_name ILIKE ? OR e.name ILIKE ? "
            "    OR CAST(sc.id AS TEXT) = ? "
            " ORDER BY sc.id DESC LIMIT 50", (like, like, like, q)).fetchall()
    preview = []
    for r in rows:
        pid = r['c_pid'] or r['l_pid']
        pt = (r['plan_type'] or '').strip()
        disc = float(r['reg_discount'] or 0)
        nr, nc = _closure_revenue_cost(conn, pid, pt, discount=disc, fallback_revenue=r['revenue'])
        preview.append({
            'id': r['id'], 'client': r['client_name'] or '', 'product': r['product_name'] or '',
            'emp': r['emp'] or '', 'plan': pt or '—', 'discount': disc,
            'cur_rev': float(r['revenue'] or 0), 'cur_cost': float(r['cost'] or 0),
            'cur_margin': float(r['margin'] or 0),
            'new_rev': nr, 'new_cost': nc, 'new_margin': nr - nc,
            'changed': abs((nr - nc) - float(r['margin'] or 0)) > 0.5,
        })
    conn.close()
    def _f(v):
        return f'{v:,.0f}'
    trs = ''
    for p in preview:
        hl = 'background:#FEF9C3;' if p['changed'] else ''
        trs += (f'<tr style="{hl}"><td style="padding:6px 9px;">#{p["id"]}</td>'
                f'<td style="padding:6px 9px;">{p["client"]}</td>'
                f'<td style="padding:6px 9px;">{p["product"]}<br><small style="color:#64748b;">{p["plan"]}</small></td>'
                f'<td style="padding:6px 9px;">{p["emp"]}</td>'
                f'<td style="padding:6px 9px;text-align:right;color:#64748b;">&#8377;{_f(p["cur_margin"])}<br>'
                f'<small>rev {_f(p["cur_rev"])} &minus; cost {_f(p["cur_cost"])}</small></td>'
                f'<td style="padding:6px 9px;text-align:right;font-weight:700;color:#3730A3;">&#8377;{_f(p["new_margin"])}<br>'
                f'<small style="font-weight:400;">Pkg &minus; Cost &minus; Disc</small></td>'
                f'<td style="padding:6px 9px;text-align:center;white-space:nowrap;">'
                f'<form method="post" style="margin:0;display:flex;gap:6px;align-items:center;justify-content:center;">'
                f'<input type="hidden" name="closure_id" value="{p["id"]}">'
                f'<input type="hidden" name="q" value="{q}">'
                f'<label style="font-size:0.72rem;color:#64748b;">Disc &#8377;<input type="number" name="discount" value="{p["discount"]:.0f}" '
                f'style="width:78px;padding:4px 6px;border:1px solid #cbd5e1;border-radius:5px;font-size:0.8rem;"></label>'
                f'<button type="submit" style="background:#4338CA;color:#fff;border:0;border-radius:6px;padding:6px 12px;cursor:pointer;font-size:0.8rem;">'
                f'{"Recompute" if p["changed"] else "Re-save"}</button></form></td></tr>')
    banner = ''
    if msg:
        bg = '#DCFCE7' if msg[0] == 'success' else '#FEE2E2'
        fg = '#166534' if msg[0] == 'success' else '#991B1B'
        banner = f'<div style="background:{bg};color:{fg};padding:10px 14px;border-radius:8px;margin-bottom:14px;">{msg[1]}</div>'
    html = f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Recompute Sales Revenue</title></head>
<body style="font-family:system-ui,-apple-system,sans-serif;max-width:960px;margin:24px auto;padding:0 16px;color:#0f172a;">
<h1 style="font-size:1.3rem;color:#1e3a5f;">Recompute Sales Revenue on a Closure</h1>
<p style="color:#475569;font-size:0.9rem;">Sales revenue credited to a member = <strong>Package &minus; Cost &minus; Discount</strong> (Package &amp; Cost
defined per plan in Packages &amp; Services; Discount is the deal's discount, prefilled below and editable). Use this
for closures saved <em>before</em> a plan's Package/Cost was set — e.g. an AMC Consulting V2 closure that shows
&#8377;0. Yellow rows will change. Nothing changes until you click a button.</p>
{banner}
<form method="get" style="margin:12px 0 18px;">
  <input name="q" value="{q}" placeholder="Client name, product, sales member, or closure #"
    style="padding:9px 12px;width:70%;border:1px solid #cbd5e1;border-radius:8px;font-size:0.9rem;">
  <button type="submit" style="background:#1e3a5f;color:#fff;border:0;border-radius:8px;padding:9px 16px;cursor:pointer;">Find</button>
</form>
{'<table style="width:100%;border-collapse:collapse;font-size:0.85rem;border:1px solid #e2e8f0;"><thead><tr style="background:#f1f5f9;text-align:left;">'
 '<th style="padding:7px 9px;">#</th><th style="padding:7px 9px;">Client</th><th style="padding:7px 9px;">Product / Plan</th>'
 '<th style="padding:7px 9px;">Member</th><th style="padding:7px 9px;text-align:right;">Current (margin)</th>'
 '<th style="padding:7px 9px;text-align:right;">New (Package &minus; Cost &minus; Disc)</th><th style="padding:7px 9px;">Discount &amp; apply</th></tr></thead><tbody>'
 + trs + '</tbody></table>' if preview else ('<p style="color:#64748b;">No closures matched.</p>' if q else '')}
<p style="margin-top:18px;"><a href="/sales/dashboard" style="color:#4338CA;">&larr; Back to Sales</a></p>
</body></html>'''
    return html


@app.route('/admin/diag/pathway-audit', methods=['GET'])
@app.route('/admin/diag/academic-pathways', methods=['GET'])  # legacy link → same page
@login_required
def admin_pathway_audit_preview():
    """Preview (read-only): across EVERY ops pathway section, find records whose
    `pathway` doesn't match their client's real pathway on plab_clients — i.e. a
    client's data filed under the wrong pathway's page (so it's invisible there).
    Shows a per-section count + sample, plus one Fix-all button. (founder 2026-07-21)"""
    user = get_user()
    if not (user and user['is_admin']):
        flash('Admin access required', 'error'); return redirect(url_for('dashboard'))
    conn = get_db()
    sections = []
    total = 0
    try:
        for t in _pathway_audit_tables(conn):
            try:
                rows = conn.execute(
                    f"SELECT a.id, a.registration_number, a.pathway AS current_pathway, "
                    f"       p.pathway AS correct_pathway, p.prefix, p.first_name, p.last_name "
                    f"  FROM {t} a JOIN plab_clients p "
                    f"    ON a.registration_number = p.registration_number "
                    f" WHERE COALESCE(p.pathway,'') <> '' "
                    f"   AND COALESCE(a.pathway,'') <> COALESCE(p.pathway,'') "
                    f" ORDER BY a.id DESC").fetchall()
            except Exception:
                try: conn.rollback()
                except Exception: pass
                rows = []
            if rows:
                total += len(rows)
                sections.append((t, OPS_SECTION_LABELS.get(t, t), rows))
    finally:
        conn.close()

    blocks = ""
    for t, label, rows in sections:
        items = "".join(
            f"<tr><td>{r['registration_number']}</td>"
            f"<td>{(r['prefix'] or '')} {(r['first_name'] or '')} {(r['last_name'] or '')}</td>"
            f"<td style='color:#b91c1c'>{r['current_pathway']}</td>"
            f"<td style='color:#065f46;font-weight:700'>{r['correct_pathway']}</td></tr>"
            for r in rows)
        blocks += (f"<h3 style='margin:22px 0 6px'>{label} "
                   f"<span style='color:#9ca3af;font-weight:400'>({len(rows)} mis-filed)</span></h3>"
                   "<table border='1' cellpadding='6' cellspacing='0' style='border-collapse:collapse;width:100%'>"
                   "<tr style='background:#f3f4f6'><th>Reg #</th><th>Client</th><th>Filed as</th><th>Should be</th></tr>"
                   + items + "</table>")

    if total:
        btn = ("<form method='POST' action='/admin/diag/pathway-audit/apply' style='margin:20px 0'>"
               "<button style='padding:12px 22px;background:#F57C1F;color:#fff;border:none;border-radius:6px;"
               f"font-weight:700;cursor:pointer;font-size:1rem'>Fix all {total} record(s) across every section — "
               "re-file each under the correct pathway</button></form>")
        head = (f"<p><b>{total}</b> record(s) across <b>{len(sections)}</b> section(s) are filed under the wrong "
                "pathway, so they don't show on the client's pathway page. Fix re-files each under the pathway on "
                "their master profile. Nothing else changes.</p>")
    else:
        btn = ""
        head = "<p style='color:#065f46;font-weight:700'>Every record across every section is filed under the correct pathway. ✅</p>"

    return ("<div style='font-family:system-ui;max-width:920px;margin:30px auto'>"
            "<h2>Pathway-linking audit — all sections</h2>" + head + btn + blocks + "</div>")


@app.route('/admin/diag/pathway-audit/apply', methods=['POST'])
@app.route('/admin/diag/academic-pathways/apply', methods=['POST'])  # legacy
@login_required
def admin_pathway_audit_apply():
    """Across every ops pathway section, align each row's pathway to its client's
    master pathway. Only touches genuinely mis-filed rows; correct rows untouched."""
    user = get_user()
    if not (user and user['is_admin']):
        flash('Admin access required', 'error'); return redirect(url_for('dashboard'))
    conn = get_db()
    fixed = {}
    try:
        for t in _pathway_audit_tables(conn):
            try:
                cur = conn.execute(
                    f"UPDATE {t} a SET pathway = p.pathway "
                    f"  FROM plab_clients p "
                    f" WHERE a.registration_number = p.registration_number "
                    f"   AND COALESCE(p.pathway,'') <> '' "
                    f"   AND COALESCE(a.pathway,'') <> COALESCE(p.pathway,'')")
                n = cur.rowcount if hasattr(cur, 'rowcount') else 0
                if n:
                    fixed[OPS_SECTION_LABELS.get(t, t)] = n
                conn.commit()
            except Exception as e:
                try: conn.rollback()
                except Exception: pass
                logging.error(f"pathway-audit apply {t}: {e}")
    finally:
        conn.close()
    total = sum(fixed.values())
    lines = "".join(f"<li>{k}: <b>{v}</b></li>" for k, v in fixed.items()) or "<li>Nothing needed fixing.</li>"
    return ("<div style='font-family:system-ui;max-width:640px;margin:40px auto'>"
            f"<h2>Done ✅</h2><p>Re-filed <b>{total}</b> record(s) under the correct pathway:</p>"
            f"<ul>{lines}</ul>"
            "<p>Open each pathway's pages to confirm the clients now appear.</p>"
            "<a href='/admin/diag/pathway-audit'>Re-check</a></div>")


@app.route('/admin/email-templates', methods=['GET'])
@login_required
def admin_email_templates_list():
    user = get_user()
    if not (user and user['is_admin']):
        flash('Admin access required', 'error')
        return redirect(url_for('dashboard'))
    conn = get_db()
    try:
        rows = conn.execute("""
            SELECT id, template_key, stage, label, subject, enabled, category,
                   recipients_client, recipients_counsellor,
                   recipients_ops, recipients_parents, recipient_employee_ids, updated_at
              FROM email_templates
             ORDER BY (category IS NULL), category,
                      CASE stage
                        WHEN 'welcome_email' THEN 1
                        WHEN 'welcome_call_scheduled' THEN 2
                        WHEN 'kit_dispatched' THEN 3
                        WHEN 'onboarded' THEN 4
                        WHEN 'thirty_day_checkin' THEN 5
                        ELSE 99 END,
                      template_key
        """).fetchall()
    except Exception:
        rows = []
    templates = []
    for r in rows:
        d = dict(r)
        d['recipient_summary'] = ', '.join(
            label for col, label, _ in EMAIL_RECIPIENT_KEYS if d.get(col))
        if d.get('recipient_employee_ids'):
            n = len([i for i in d['recipient_employee_ids'].split(',') if i.strip()])
            if n:
                d['recipient_summary'] = (d['recipient_summary'] + ', ' if d['recipient_summary'] else '') + f'+{n} team member' + ('s' if n != 1 else '')
        if not d['recipient_summary']:
            d['recipient_summary'] = '(no recipients selected)'
        templates.append(d)
    conn.close()
    # Group by category for the list heading ("Standard Consulting" first, then the rest).
    from collections import OrderedDict
    grouped = OrderedDict()
    for t in templates:
        grouped.setdefault(t.get('category') or 'Other Templates', []).append(t)
    return render_template(
        'admin_email_templates_list.html',
        user=user, templates=templates, grouped_templates=grouped,
        active_section='company',
    )


def _send_sc_template(conn, key, subs, base_to=None):
    """Send an editable Standard Consulting template. Renders it with `subs`,
    resolves recipients (the base_to the caller wants + any active employees picked
    on the template), substitutes placeholders, and sends. Returns True if it sent
    via the template; False if the template is missing/disabled so the caller can
    fall back to its built-in email — nothing ever silently drops (founder 2026-07-20)."""
    try:
        tpl = conn.execute("SELECT * FROM email_templates WHERE template_key = ?", (key,)).fetchone()
    except Exception:
        return False
    if not tpl:
        return False
    tpl = dict(tpl)
    if tpl.get('enabled') is not None and not tpl.get('enabled'):
        return False
    subject = tpl.get('subject') or ''
    body = tpl.get('body_html') or ''
    for k, v in (subs or {}).items():
        subject = subject.replace(k, str(v if v is not None else ''))
        body = body.replace(k, str(v if v is not None else ''))
    to = list(base_to or [])
    to += [e for e in _template_staff_emails(conn, tpl) if e]
    to = [e for e in dict.fromkeys(to) if e]
    if not to:
        return False
    try:
        from email_utils import send_email
        send_email(to, subject, body)
        return True
    except Exception as e:
        logging.error("_send_sc_template %s: %s", key, e)
        return False


def _template_staff_emails(conn, tpl):
    """Emails of the ACTIVE employees picked as extra recipients on a template
    (recipient_employee_ids = comma-separated ids). Skips inactive/missing."""
    raw = ''
    try:
        raw = (tpl.get('recipient_employee_ids') if hasattr(tpl, 'get') else tpl['recipient_employee_ids']) or ''
    except Exception:
        raw = ''
    ids = [i for i in (raw or '').split(',') if i.strip().isdigit()]
    if not ids:
        return []
    ph = ','.join(['?'] * len(ids))
    try:
        rows = conn.execute(
            f"SELECT email FROM employees WHERE id IN ({ph}) AND COALESCE(is_active,1)=1 "
            f"AND email IS NOT NULL AND email <> ''", [int(i) for i in ids]).fetchall()
        return [r['email'] for r in rows]
    except Exception:
        return []


