# ── Item G-1: Time-slot request flow (calendar slot picker) ──────────
# Pattern A: ops triggers a slot request -> system generates N open
# 30-min slots over the next 5 working days -> client opens a public
# token URL and picks one -> chosen slot writes back into
# client_onboarding.welcome_call_date which lights up E-3's
# welcome_call_scheduled fire-point. Zero back-and-forth.

SLOT_CALL_HOURS = (10, 17)          # 10:00 - 17:00 IST (last slot starts 16:30)
SLOT_LENGTH_MIN = 30
SLOT_LOOKAHEAD_WORKING_DAYS = 5
SLOT_EXPIRES_DAYS = 14              # token good for 14 calendar days


def _generate_call_slots(holidays_set):
    """Build a list of ISO datetime strings for the next
    SLOT_LOOKAHEAD_WORKING_DAYS working days, 30-min slots between
    10:00 and 17:00 IST. Honours the F-1 5pm cutoff so 'today' is
    skipped after 17:00 IST.
    """
    from working_days import add_working_days, next_working_day, now_ist
    from datetime import datetime as _dt, timedelta as _td
    today_ist = now_ist().date()
    # Use add_working_days with n=0 to apply the cutoff rule to the
    # starting date in one place.
    start = add_working_days(today_ist, 0, holidays_set)
    days = [start]
    cur = start
    for _ in range(SLOT_LOOKAHEAD_WORKING_DAYS - 1):
        cur = add_working_days(cur, 1, holidays_set, cutoff_hour=None)
        days.append(cur)

    slots = []
    for d in days:
        slot_dt = _dt(d.year, d.month, d.day, SLOT_CALL_HOURS[0], 0)
        end_dt  = _dt(d.year, d.month, d.day, SLOT_CALL_HOURS[1], 0)
        while slot_dt + _td(minutes=SLOT_LENGTH_MIN) <= end_dt + _td(minutes=1):
            slots.append(slot_dt.isoformat(timespec='minutes'))
            slot_dt += _td(minutes=SLOT_LENGTH_MIN)
    return slots


def _gen_slot_token():
    """Random URL-safe token for the public client URL."""
    import secrets
    return secrets.token_urlsafe(16)


@app.route('/operations/onboarding/<int:client_id>/request-call-slot', methods=['POST'])
@admin_required
def ops_request_call_slot(client_id):
    """Ops trigger: create a slot request for a client. Returns the
    ops onboarding detail page with the share URL flashed up."""
    import json as _json
    from datetime import datetime as _dt, timedelta as _td
    user = get_user()
    conn = get_db()
    client = conn.execute("SELECT * FROM plab_clients WHERE id = ?", (client_id,)).fetchone()
    if not client:
        conn.close()
        flash('Client not found.', 'error')
        return redirect(url_for('ops_onboarding_list'))

    # Don't allow stacking requests -- if there's already a pending
    # request for this client + slot_type, reuse its token (so ops can
    # re-send the same link).
    existing = conn.execute(
        "SELECT * FROM scheduled_slots "
        " WHERE client_id = ? AND slot_type = 'welcome_call' "
        "   AND status = 'pending' "
        " ORDER BY id DESC LIMIT 1",
        (client_id,)
    ).fetchone()
    if existing:
        token = existing['token']
        is_new = False
    else:
        try:
            from working_days import load_holidays_set
            holidays_set = load_holidays_set(conn)
        except Exception:
            holidays_set = set()
        try:
            slots = _generate_call_slots(holidays_set)
        except Exception as e:
            logging.error(f"slot generation: {e}")
            slots = []
        token = _gen_slot_token()
        expires = _dt.utcnow() + _td(days=SLOT_EXPIRES_DAYS)
        try:
            conn.execute(
                "INSERT INTO scheduled_slots "
                "(token, client_id, slot_type, available_slots, "
                " status, requested_by, expires_at) "
                "VALUES (?, ?, 'welcome_call', ?, 'pending', ?, ?)",
                (token, client_id, _json.dumps(slots),
                 user['id'] if user else None,
                 expires.isoformat(timespec='seconds'))
            )
            conn.commit()
        except Exception as e:
            try: conn.rollback()
            except Exception: pass
            logging.error(f"ops_request_call_slot insert: {e}")
            conn.close()
            flash(f'Failed to create slot request: {e}', 'error')
            return redirect(url_for('ops_onboarding_detail', client_id=client_id))
        is_new = True
    pathway = (client['pathway'] if 'pathway' in client.keys() else None) or 'plab'
    conn.close()
    share_url = url_for('client_pick_slot', token=token, _external=True)
    if is_new:
        flash(
            f'Slot picker created. Share this link with the client: {share_url}',
            'success')
    else:
        flash(
            f'A pending slot request already exists. Reuse this link: {share_url}',
            'info')
    # Route back to the right place per pathway: Australia + PLAB have dedicated
    # onboarding-detail pages; the other pathways use their own client-profile page.
    if pathway == 'australia':
        return redirect(url_for('ops_au_onboarding_detail', client_id=client_id))
    if pathway == 'plab':
        return redirect(url_for('ops_onboarding_detail', client_id=client_id))
    return redirect(pathway_detail_url(pathway, client_id))


@app.route('/slot/<token>', methods=['GET'])
def client_pick_slot(token):
    """Public client-facing slot picker. No login required -- the
    token is the access control."""
    import json as _json
    from datetime import datetime as _dt
    conn = get_db()
    row = conn.execute(
        "SELECT * FROM scheduled_slots WHERE token = ?", (token,)
    ).fetchone()
    if not row:
        conn.close()
        return render_template('slot_pick.html',
            error='This link is invalid or has been removed.',
            row=None, slots_by_day={})
    row = dict(row)
    # Expiry check
    try:
        if row.get('expires_at'):
            exp = _dt.fromisoformat(str(row['expires_at'])[:19])
            if _dt.utcnow() > exp and row.get('status') == 'pending':
                row['status'] = 'expired'
    except Exception:
        pass
    # Client name for the friendly header
    client = conn.execute(
        "SELECT first_name, last_name, prefix FROM plab_clients WHERE id = ?",
        (row['client_id'],)
    ).fetchone()
    client_name = ''
    if client:
        client_name = (
            f"{client['prefix'] or ''} "
            f"{client['first_name'] or ''} "
            f"{client['last_name'] or ''}"
        ).strip()

    # Group slots by date for the UI
    slots_by_day = {}
    try:
        for iso in _json.loads(row.get('available_slots') or '[]'):
            day = iso[:10]
            slots_by_day.setdefault(day, []).append(iso)
    except Exception:
        pass
    conn.close()
    return render_template('slot_pick.html',
        row=row, slots_by_day=slots_by_day,
        client_name=client_name, error=None)


@app.route('/slot/<token>/pick', methods=['POST'])
def client_pick_slot_save(token):
    """Public submission: client picked a slot."""
    import json as _json
    from datetime import datetime as _dt
    chosen = (request.form.get('chosen_slot') or '').strip()
    if not chosen:
        flash('Please pick a time slot.', 'error')
        return redirect(url_for('client_pick_slot', token=token))
    conn = get_db()
    row = conn.execute(
        "SELECT * FROM scheduled_slots WHERE token = ?", (token,)
    ).fetchone()
    if not row:
        conn.close()
        flash('This link is invalid or has been removed.', 'error')
        return redirect(url_for('client_pick_slot', token=token))
    row = dict(row)
    if row.get('status') != 'pending':
        conn.close()
        return redirect(url_for('client_pick_slot', token=token))
    # Validate chosen against available
    try:
        avail = _json.loads(row.get('available_slots') or '[]')
    except Exception:
        avail = []
    if chosen not in avail:
        conn.close()
        flash('That slot is no longer available. Please pick another.',
              'error')
        return redirect(url_for('client_pick_slot', token=token))
    try:
        conn.execute(
            "UPDATE scheduled_slots SET "
            "  chosen_slot = ?, status = 'confirmed', "
            "  chosen_at = CURRENT_TIMESTAMP "
            "WHERE id = ?",
            (chosen, row['id']))
        # Wire back to client_onboarding so the D timeline + E-3
        # welcome_call_scheduled fire-point both light up. Snapshot
        # old state first so the transition is detected.
        onb = conn.execute(
            "SELECT * FROM client_onboarding WHERE client_id = ?",
            (row['client_id'],)
        ).fetchone()
        if not onb:
            client = conn.execute(
                "SELECT registration_number FROM plab_clients WHERE id = ?",
                (row['client_id'],)
            ).fetchone()
            if client:
                onb = _ensure_client_onboarding(
                    conn, row['client_id'], client['registration_number'])
        if onb:
            old_state = dict(onb)
            chosen_date = chosen[:10]  # YYYY-MM-DD
            conn.execute(
                "UPDATE client_onboarding SET "
                "  welcome_call_date = ?, updated_at = CURRENT_TIMESTAMP "
                "WHERE id = ?",
                (chosen_date, onb['id']))
            conn.commit()
            new_state = dict(conn.execute(
                "SELECT * FROM client_onboarding WHERE id = ?",
                (onb['id'],)
            ).fetchone() or {})
            _maybe_fire_stage_transitions(
                conn, row['client_id'], old_state, new_state)
        else:
            conn.commit()
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        logging.error(f"client_pick_slot_save: {e}")
        conn.close()
        flash(f'Save failed: {e}', 'error')
        return redirect(url_for('client_pick_slot', token=token))
    conn.close()
    return redirect(url_for('client_pick_slot', token=token))


# Toggle a client's welcome-kit item between done <-> pending.
@app.route('/admin/client/<int:reg_id>/welcome-kit/<int:cwk_id>/toggle', methods=['POST'])
@login_required
def client_welcome_kit_toggle(reg_id, cwk_id):
    user = get_user()
    conn = get_db()
    try:
        row = conn.execute(
            "SELECT status FROM client_welcome_kit "
            " WHERE id = ? AND registration_id = ?",
            (cwk_id, reg_id),
        ).fetchone()
        if row:
            if row['status'] == 'done':
                conn.execute(
                    "UPDATE client_welcome_kit SET status='pending', "
                    " completed_by=NULL, completed_at=NULL WHERE id = ?",
                    (cwk_id,),
                )
            else:
                conn.execute(
                    "UPDATE client_welcome_kit SET status='done', "
                    " completed_by = ?, completed_at = CURRENT_TIMESTAMP "
                    " WHERE id = ?",
                    (user['id'], cwk_id),
                )
            conn.commit()
    except Exception as e:
        logging.warning(f"client_welcome_kit_toggle: {e}")
    finally:
        conn.close()
    return redirect(url_for('admin_client_detail', reg_id=reg_id))


def _seed_client_welcome_kit_from_template(conn, registration_id):
    """Copy every active welcome_kit_items row for the registration's
    product into client_welcome_kit, one row per item. Idempotent via
    the UNIQUE(registration_id, kit_item_id) constraint -- re-running
    after the kit has been seeded is a no-op.

    Returns the number of items inserted (0 if the kit is already
    seeded or the product has no template).
    """
    reg = conn.execute(
        "SELECT product_id FROM client_registrations WHERE id = ?",
        (registration_id,),
    ).fetchone()
    if not reg or not reg['product_id']:
        return 0
    items = conn.execute(
        "SELECT id, item_name, item_type FROM welcome_kit_items "
        "WHERE product_id = ? AND is_active = 1 "
        "ORDER BY sort_order, id",
        (reg['product_id'],),
    ).fetchall()
    inserted = 0
    for it in items:
        try:
            conn.execute(
                "INSERT INTO client_welcome_kit "
                "(registration_id, kit_item_id, item_name, item_type, status) "
                "VALUES (?, ?, ?, ?, 'pending')",
                (registration_id, it['id'], it['item_name'], it['item_type']),
            )
            inserted += 1
        except Exception:
            # UNIQUE constraint -> kit already seeded for this item; skip.
            try: conn.rollback()
            except Exception: pass
    return inserted


def _auto_invite_from_closure(conn, *, product_id, client_name, client_mobile,
                              client_email, invited_by, closure_data=None):
    """Create a client_invitations row tied to a fresh closure and send the
    WhatsApp invite. Used by the sales -> closure auto-flow so the closing
    rep doesn't have to manually generate the invite.

    closure_data (Item C): optional dict of sales-collected fields
    (plan_type, package_amount, discount_allowed, final_package,
    inst1..inst4 amount/date/note, lead_source, additional_notes). When
    provided, JSON-serialized into client_invitations.closure_metadata
    so /client/register/<token> can pre-fill the registration row
    with what the client signed up for.

    Returns the token on success, or None when name/mobile are missing.
    Idempotent-ish: if a non-cancelled invitation already exists for this
    (mobile, product) pair we skip creating a duplicate.
    """
    import uuid, json
    if not client_name or not client_mobile:
        return None
    mobile = client_mobile.lstrip('+').lstrip('0')
    if mobile.startswith('91') and len(mobile) == 12:
        mobile = mobile[2:]
    if not mobile or len(mobile) < 10:
        return None
    try:
        existing = conn.execute(
            "SELECT token, COALESCE(status,'pending') AS status FROM client_invitations "
            " WHERE client_mobile = ? AND product_id = ? "
            "   AND COALESCE(status,'pending') <> 'cancelled' "
            " ORDER BY id DESC LIMIT 1",
            (mobile, product_id),
        ).fetchone()
    except Exception:
        existing = None
    closure_json = None
    if closure_data:
        try:
            closure_json = json.dumps(
                {k: v for k, v in closure_data.items() if v not in (None, '')}
            )
        except Exception as e:
            logging.warning(f"_auto_invite: closure_data serialize: {e}")
    if existing:
        token = existing['token']
        # Client already completed registration from this invite — don't
        # re-send (they'd get a "complete your registration" nudge for
        # something already done). Just hand back the token.
        if existing['status'] == 'registered':
            return token
        # Re-close of an existing (still-pending) lead: refresh the stored
        # closure metadata (e.g. include_training, corrected installments) and
        # counsellor, then fall through to re-send the invite. Previously the
        # old invitation was reused untouched, so a corrected re-close kept
        # sending the stale email format.
        try:
            conn.execute(
                "UPDATE client_invitations "
                "   SET closure_metadata = COALESCE(?, closure_metadata), "
                "       client_email = COALESCE(NULLIF(?, ''), client_email), "
                "       invited_by = COALESCE(?, invited_by) "
                " WHERE token = ?",
                (closure_json, client_email or '', invited_by, token),
            )
            conn.commit()
        except Exception as e:
            logging.warning(f"_auto_invite: refresh existing invite: {e}")
            try: conn.rollback()
            except Exception: pass
    else:
        token = uuid.uuid4().hex
        try:
            conn.execute(
                "INSERT INTO client_invitations "
                "(token, product_id, client_name, client_mobile, client_email, "
                " invited_by, closure_metadata) "
                "VALUES (?, ?, ?, ?, ?, ?, ?)",
                (token, product_id, client_name, mobile, client_email,
                 invited_by, closure_json),
            )
        except Exception as e:
            logging.warning(f"_auto_invite_from_closure: insert failed: {e}")
            try: conn.rollback()
            except Exception: pass
            return None
    # WhatsApp invite is a side-effect; don't let a delivery failure roll
    # back the row.
    try:
        invite_url = f"https://goocampus.org/client/register/{token}"
        _send_client_invite_wa(mobile, client_name, invite_url)
    except Exception as e:
        logging.warning(f"_auto_invite_from_closure: WA send failed: {e}")
    # Email the registration link too. Previously the client invite only sent
    # WhatsApp, so clients who gave an email (but no/invalid WhatsApp) got nothing.
    try:
        if client_email:
            svc_name, cns_name = '', ''
            try:
                pr = conn.execute("SELECT name FROM products_services WHERE id = ?", (product_id,)).fetchone()
                if pr: svc_name = pr['name'] or ''
            except Exception: pass
            try:
                if invited_by:
                    em = conn.execute("SELECT name FROM employees WHERE id = ?", (invited_by,)).fetchone()
                    if em: cns_name = em['name'] or ''
            except Exception: pass
            # Combined AMC Consulting + AMC MCQ (AMC 1) enrolment: the single
            # registration covers BOTH programs, so tell the client they're
            # signing up for consulting AND training (not consulting alone).
            also_svc = ''
            if closure_data and closure_data.get('include_training'):
                also_svc = 'AMC MCQ (AMC 1) — Training'
            _send_client_invite_email(client_email, client_name, invite_url,
                                      service_name=svc_name, counsellor_name=cns_name,
                                      also_service=also_svc)
    except Exception as e:
        logging.warning(f"_auto_invite_from_closure: email send failed: {e}")
    return token


def _send_client_invite_email(email, name, link, service_name='', counsellor_name='', also_service=''):
    """Email the client their registration-invitation link via Resend.
    Mirrors the partner-invite email. Returns True if Resend accepted it,
    False if email isn't configured or the send failed (never raises).

    service_name: the product/service the client signed up for, shown in the
    body so they know exactly what this registration is for.
    counsellor_name: the counsellor who sent the link, shown as
    "shared by your counsellor <name>"."""
    if not email:
        return False
    try:
        from email_utils import send_email
        # When the client is enrolling in TWO programs (AMC Consulting + AMC MCQ
        # / AMC 1 Training), list both clearly instead of naming only one so the
        # client knows this single registration covers both.
        combined_block = ''
        if also_service:
            service_line = ''
            combined_block = (
                f'<div style="background:#fff7ed;border:1px solid #fed7aa;border-radius:6px;'
                f'padding:14px 18px;margin:18px 0;">'
                f'<p style="margin:0 0 8px;font-weight:700;color:#1e3a5f;font-size:15px;">'
                f'You are registering for two programs:</p>'
                f'<ul style="margin:0;padding-left:20px;color:#333;font-size:15px;line-height:1.7;">'
                f'<li><strong>{service_name}</strong></li>'
                f'<li><strong>{also_service}</strong></li>'
                f'</ul></div>'
            )
        else:
            service_line = (f' for <strong>{service_name}</strong>' if service_name else '')
        counsellor_block = ''
        if counsellor_name:
            counsellor_block = (
                f'<p style="background:#f0f6ff;border-left:4px solid #1e3a5f;'
                f'padding:12px 16px;margin:18px 0;border-radius:4px;font-size:14px;">'
                f'This registration link was shared by your counsellor '
                f'<strong style="color:#1e3a5f;">{counsellor_name}</strong>, '
                f'who will guide you through the next steps.</p>'
            )
        html = f'''<html><body style="font-family:Arial,sans-serif;color:#333;line-height:1.6;margin:0;padding:0;">
  <div style="background-color:#1e3a5f;padding:20px;text-align:center;"><h1 style="color:white;margin:0;font-size:24px;">GooCampus Edu Solutions</h1></div>
  <div style="padding:30px;background-color:white;">
    <h2 style="color:#1e3a5f;margin-top:0;">Welcome to GooCampus!</h2>
    <p style="font-size:16px;">Hello {name},</p>
    <p>Thank you for choosing GooCampus{service_line}. Please click the button below to complete your registration and get started.</p>
    {combined_block}
    {counsellor_block}
    <div style="text-align:center;margin:30px 0;">
      <a href="{link}" style="background-color:#F58220;color:white;padding:14px 32px;text-decoration:none;border-radius:6px;font-weight:bold;font-size:16px;display:inline-block;">Complete Registration</a>
    </div>
    <p style="font-size:13px;color:#666;">Or copy this link into your browser:<br><a href="{link}" style="color:#F58220;word-break:break-all;">{link}</a></p>
    <p style="margin-top:30px;">Best regards,<br><strong style="color:#1e3a5f;">GooCampus Team</strong></p>
  </div>
  <div style="background-color:#f5f5f5;padding:15px;text-align:center;border-top:3px solid #F58220;"><p style="color:#999;font-size:11px;margin:0;">GooCampus Edu Solutions Pvt Ltd</p></div>
</body></html>'''
        return send_email([email], 'Complete Your GooCampus Registration', html,
                          from_address="GooCampus <info@goocampus.in>")
    except Exception as e:
        logging.error(f"_send_client_invite_email: {e}")
        return False


def _send_client_invite_wa(mobile, name, link):
    """Send WhatsApp template message with invitation link.

    Returns True if Infobip accepted the message, False otherwise. Unlike the
    old version (which returned silently and ignored the API response), this
    logs the REAL reason for any failure — missing config, or the Infobip
    rejection body (e.g. unapproved template / unregistered sender) — so a
    delivery problem is visible in the logs instead of looking like success."""
    import os, requests as http_requests
    infobip_key = os.environ.get('INFOBIP_API_KEY', '')
    infobip_base = os.environ.get('INFOBIP_BASE_URL', '')
    if not infobip_key or not infobip_base:
        logging.error("WA invite NOT sent: INFOBIP_API_KEY / INFOBIP_BASE_URL "
                      "not configured on this service")
        return False
    phone = mobile if mobile.startswith('91') else f'91{mobile}'
    url = f"https://{infobip_base}/whatsapp/1/message/template"
    headers = {"Authorization": f"App {infobip_key}", "Content-Type": "application/json"}
    payload = {
        "messages": [{
            "from": os.environ.get('INFOBIP_SENDER', '15558246314'),
            "to": phone,
            "content": {
                "templateName": "client_registration_invite",
                "templateData": {"body": {"placeholders": [name, link]}},
                "language": "en"
            }
        }]
    }
    try:
        resp = http_requests.post(url, json=payload, headers=headers, timeout=10)
        if resp.status_code >= 300:
            logging.error(f"WA invite REJECTED by Infobip ({resp.status_code}) "
                          f"to {phone}: {resp.text[:600]}")
            return False
        logging.info(f"WA invite accepted by Infobip for {phone}: {resp.text[:300]}")
        return True
    except Exception as e:
        logging.error(f"_send_client_invite_wa: {e}")
        return False


