@app.route('/admin/client/<int:reg_id>')
@login_required
def admin_client_detail(reg_id):
    user = get_user()
    conn = get_db()
    reg = conn.execute('''SELECT cr.*, ps.name as product_name
        FROM client_registrations cr
        LEFT JOIN products_services ps ON ps.id = cr.product_id
        WHERE cr.id = ?''', (reg_id,)).fetchone()
    if not reg:
        conn.close()
        flash('Client not found', 'error')
        return redirect(url_for('admin_clients_list'))
    academics = conn.execute("SELECT * FROM client_academics WHERE registration_id = ?", (reg_id,)).fetchone()
    documents = conn.execute("SELECT * FROM client_documents WHERE registration_id = ? ORDER BY uploaded_at", (reg_id,)).fetchall()
    # Resolve the ops member who raised each request — the page showed the raw
    # employees.id ("6"), which tells nobody anything. We already name who verified;
    # name who asked too (founder 2026-07-17).
    doc_requests = conn.execute(
        "SELECT dr.*, e.name AS requested_by_name "
        "  FROM client_doc_requests dr "
        "  LEFT JOIN employees e ON e.id = dr.requested_by "
        " WHERE dr.registration_id = ? ORDER BY dr.requested_at DESC", (reg_id,)).fetchall()
    notifications = conn.execute("SELECT * FROM client_notifications WHERE registration_id = ? ORDER BY sent_at DESC LIMIT 20", (reg_id,)).fetchall()
    counsellors = conn.execute("SELECT id, name FROM employees WHERE is_active = 1 ORDER BY name").fetchall()
    # Resolve the staff NAMES behind the sales-completed / ops-verified ids so the
    # detail page can show "Verified by Priya" instead of a raw employee id.
    def _emp_name(eid):
        if not eid:
            return ''
        try:
            r = conn.execute("SELECT name FROM employees WHERE id = ?", (eid,)).fetchone()
            return (r['name'] if r else '') or ''
        except Exception:
            return ''
    sales_completed_by_name = _emp_name(reg.get('sales_completed_by'))
    ops_verified_by_name = _emp_name(reg.get('ops_verified_by'))
    # Phase E: welcome-kit checklist for this client (rows are seeded on
    # ops-verify; an empty list means either ops hasn't verified yet or
    # the product has no welcome-kit template configured).
    try:
        welcome_kit = conn.execute(
            "SELECT cwk.*, e.name AS completed_by_name "
            "FROM client_welcome_kit cwk "
            "LEFT JOIN employees e ON e.id = cwk.completed_by "
            "WHERE cwk.registration_id = ? "
            "ORDER BY cwk.id",
            (reg_id,),
        ).fetchall()
    except Exception:
        welcome_kit = []
    # Sales-section fields are config-driven (client_form_configs role='sales'),
    # so the /admin/client-form-config settings page controls what sales fills.
    sales_config = conn.execute('''
        SELECT * FROM client_form_configs
        WHERE product_id = ? AND role = 'sales' AND is_visible = 1
          AND field_name NOT LIKE 'inst%%'
        ORDER BY step_number, display_order
    ''', (reg['product_id'],)).fetchall()
    # Ops-section fields are config-driven too (role='ops'); ops has its own
    # ops_notes on the verify form, so exclude the shared additional_notes.
    ops_config = conn.execute('''
        SELECT * FROM client_form_configs
        WHERE product_id = ? AND role = 'ops' AND is_visible = 1
          AND field_name <> 'additional_notes'
        ORDER BY step_number, display_order
    ''', (reg['product_id'],)).fetchall()
    # Sales/ops dropdowns (Joined Stage, Plan Type, Current Stage, Account Status…)
    # must show PATHWAY-specific values, not one global/PLAB list (founder
    # 2026-07-13). Resolve the client's pathway from their product, then prefer
    # that pathway's lookup values per category, falling back to the PLAB set for
    # any category not yet seeded for the pathway (same rule as get_lookup_options).
    detail_pathway = resolve_ops_pathway(conn, reg.get('product_id'), reg.get('product_name'))
    lookup_rows = conn.execute(
        "SELECT category, value, COALESCE(pathway,'plab') AS pw FROM lookup_options "
        "WHERE is_active = TRUE ORDER BY category, sort_order, value").fetchall()
    _lk = {}
    for row in lookup_rows:
        d = _lk.setdefault(row['category'], {'match': [], 'plab': []})
        if row['pw'] == detail_pathway:
            d['match'].append(row['value'])
        if row['pw'] == 'plab':
            d['plab'].append(row['value'])
    lookup_options = {}
    for cat, d in _lk.items():
        vals, seen, out = (d['match'] or d['plab']), set(), []
        for v in vals:
            if v not in seen:
                seen.add(v); out.append(v)
        lookup_options[cat] = out
    try:
        package_services = get_package_services(conn, reg.get('product_id'), reg.get('plan_type'))
    except Exception:
        package_services = []
    # Combined signup (e.g. AMC Consulting + AMC 1): other registrations from the
    # same invitation ride along with this one's verification. Surface them so the
    # verifier knows this single verification covers both (payments are separate).
    combined_siblings = []
    if reg.get('invitation_id') and reg.get('account_id'):
        try:
            for _cs in conn.execute(
                '''SELECT cr.*, ps.name AS product_name
                     FROM client_registrations cr
                     LEFT JOIN products_services ps ON ps.id = cr.product_id
                    WHERE cr.account_id = ? AND cr.invitation_id = ? AND cr.id <> ?''',
                (reg.get('account_id'), reg.get('invitation_id'), reg_id)).fetchall():
                _insts = []
                for _i in (1, 2, 3, 4):
                    _amt = _cs['inst%d_amount' % _i]
                    if _amt:
                        _insts.append({
                            'n': _i, 'amount': float(_amt or 0),
                            'date': _cs['inst%d_date' % _i] or '',
                            'note': _cs['inst%d_note' % _i] or '',
                            'method': _cs['inst%d_method' % _i] or '',
                            # Carried so the add-on's table can show Received/Pending
                            # like the main one, instead of calling every date a due
                            # date (founder 2026-07-17).
                            'status': _cs['inst%d_status' % _i] or '',
                        })
                combined_siblings.append({
                    'reg': _cs['registration_number'], 'plan_type': _cs['plan_type'],
                    'product': _cs['product_name'],
                    'package_amount': float(_cs['package_amount'] or 0),
                    'discount_allowed': float(_cs['discount_allowed'] or 0),
                    'final_package': float(_cs['final_package'] or 0),
                    'installments': _insts,
                })
        except Exception:
            combined_siblings = []
    conn.close()
    return render_template('admin_client_detail.html', reg=reg, academics=academics,
        documents=documents, doc_requests=doc_requests, notifications=notifications,
        counsellors=counsellors, welcome_kit=welcome_kit, sales_config=sales_config,
        ops_config=ops_config, lookup_options=lookup_options, package_services=package_services,
        sales_completed_by_name=sales_completed_by_name, ops_verified_by_name=ops_verified_by_name,
        combined_siblings=combined_siblings, user=user,
        # Stay in the section the queue sent us from (founder 2026-07-22):
        #   ?from=sales -> Sales sidebar + Sales header
        #   ?from=ops   -> Operations sidebar + Operations header
        # Both these bases fill {% block section_content %} so they render this page
        # correctly (the pathway ops_sidebar_base uses a different block and would blank).
        **({'base_template': 'sales_sidebar_base.html', 'active_section': 'sales'}
           if request.args.get('from') == 'sales'
           else ({'base_template': 'operations_verify_sidebar_base.html', 'active_section': 'operations'}
                 if request.args.get('from') == 'ops'
                 else {'active_section': 'clients'})),
        client_doc_types=CLIENT_DOC_TYPES,
        open_doc_requests=[d for d in (doc_requests or [])
                           if (d['status'] or 'pending') != 'fulfilled'])


# ── ADMIN: Sales completes their section ──

@app.route('/admin/client/<int:reg_id>/sales-complete', methods=['POST'])
@login_required
def admin_client_sales_complete(reg_id):
    user = get_user()
    conn = get_db()
    reg = conn.execute("SELECT id, form_status, product_id, counsellor_id FROM client_registrations WHERE id = ?", (reg_id,)).fetchone()
    if not reg:
        conn.close()
        flash('Client not found', 'error')
        return redirect(url_for('admin_clients_list'))

    # Only the lead's sales member (the counsellor who generated the lead) — or an
    # admin — may complete the sales section for this registration (founder rule
    # 2026-07-15). Ops/other members receive the email but cannot open + complete it.
    if not session.get('is_admin') and reg['counsellor_id'] and reg['counsellor_id'] != user['id']:
        conn.close()
        flash('Only the sales member who generated this lead can complete its Sales Verification.', 'error')
        return redirect(url_for('verification_sales'))

    # Config-driven sales fields (non-installment): the settings page decides
    # which the sales team fills. Whitelist to real columns; coerce numbers.
    _CR_SALES_COLS = {'joined_stage', 'plan_type', 'lead_source', 'package_amount',
                      'discount_allowed', 'final_package', 'additional_notes'}
    sales_cfg = conn.execute(
        "SELECT field_name, field_type FROM client_form_configs WHERE product_id = ? "
        "AND role = 'sales' AND is_visible = 1 AND field_name NOT LIKE 'inst%%'",
        (reg['product_id'],)).fetchall()
    dyn = {}
    for f in sales_cfg:
        fn = f['field_name']
        if fn not in _CR_SALES_COLS:
            continue
        # Only write fields the form actually submitted. Sales verification now
        # shows the lead-provided details (plan/package/lead source) READ-ONLY and
        # only Joined Stage is editable — so un-submitted fields must NOT be blanked
        # (founder 2026-07-13). A read-only field is absent from request.form.
        if fn not in request.form:
            continue
        v = request.form.get(fn, '')
        if f['field_type'] == 'number':
            v = float(v or 0)
        dyn[fn] = v

    # Counsellor auto-assigns to the sales member doing the verification (founder
    # 2026-07-13: "sales member is the counsellor"). If the form still posts an
    # explicit counsellor_id (e.g. assigning to a colleague) we honour it; otherwise
    # default to the logged-in user so it's never left blank / re-asked.
    counsellor_id = request.form.get('counsellor_id') or user['id']
    set_parts = ["counsellor_id = ?", "counsellor_name = (SELECT name FROM employees WHERE id = ?)"]
    vals = [counsellor_id, counsellor_id]
    # Installments are entered by the sales member in the lead form and already
    # copied onto the registration — sales verification only DISPLAYS them (with
    # GST) to confirm, it must not re-ask or overwrite them (founder 2026-07-13).
    # They remain editable in the Payments hub. Only write here if the form still
    # posts a value (backward-compatible; the new UI posts none).
    for i in (1, 2, 3, 4):
        if request.form.get(f'inst{i}_amount', '') != '':
            set_parts += [f"inst{i}_amount = ?", f"inst{i}_date = ?", f"inst{i}_note = ?"]
            vals += [float(request.form.get(f'inst{i}_amount', 0) or 0),
                     request.form.get(f'inst{i}_date', ''), request.form.get(f'inst{i}_note', '')]
    for k, v in dyn.items():
        set_parts.append(f"{k} = ?")
        vals.append(v)
    set_parts += ["sales_completed = 1", "sales_completed_at = CURRENT_TIMESTAMP",
                  "sales_completed_by = ?", "updated_at = CURRENT_TIMESTAMP"]
    vals.append(user['id'])
    conn.execute(f"UPDATE client_registrations SET {', '.join(set_parts)} WHERE id = ?", vals + [reg_id])
    conn.commit()
    conn.close()

    # Notify ops team
    _notify_sales_completed(reg_id)
    flash('Sales section completed! Operations team has been notified.', 'success')
    # Keep the Sales sidebar after the action (don't revert to Clients). (founder 2026-07-22)
    return redirect(url_for('admin_client_detail', reg_id=reg_id, **{'from': 'sales'}))


def _notify_sales_completed(reg_id):
    """Email ops team that sales section is complete."""
    try:
        conn = get_db()
        reg = conn.execute('''SELECT cr.*, ps.name as product_name
            FROM client_registrations cr
            LEFT JOIN products_services ps ON ps.id = cr.product_id
            WHERE cr.id = ?''', (reg_id,)).fetchone()
        if not reg:
            conn.close()
            return
        client_name = f"{reg['prefix'] or ''} {reg['first_name'] or ''} {reg['last_name'] or ''}".strip()
        ops_emails = _dept_emails(conn, ['Operations'])
        mgmt_emails = _management_emails(conn)
        from email_utils import send_email, render_branded_email, brand_detail_rows, brand_button
        details = brand_detail_rows([
            ('Client', client_name), ('Registration #', reg['registration_number']),
            ('Product', reg['product_name']), ('Plan', reg['plan_type']),
            ('Package', ('₹{:,.0f}'.format(reg['final_package']) if reg['final_package'] else '—'))])
        # Operations team — NOW gets the action button (Ops Verification).
        if ops_emails:
            o_inner = (f"<p><strong>Sales verification is complete</strong> for <strong>{client_name}</strong>. "
                       f"Please complete the <strong>Ops Verification</strong>.</p>" + details +
                       brand_button('Open Ops Verification', 'https://goocampus.org/verifications/ops'))
            send_email(ops_emails, f"Action needed — Ops Verification: {client_name}",
                       render_branded_email('Sales Verification Complete — Ops Verification needed', o_inner,
                                            preheader=f"{client_name} is ready for ops verification"),
                       from_address="GooCampus <info@goocampus.in>")
        # Management — plain informational note (never a button).
        mgmt_only = list(dict.fromkeys([e for e in mgmt_emails if e and e not in ops_emails]))
        if mgmt_only:
            m_inner = (f"<p>Sales verification is complete for <strong>{client_name}</strong>. "
                       f"It is now with Operations to verify.</p>" + details)
            send_email(mgmt_only, f"Sales Verification Complete — {client_name}",
                       render_branded_email('Sales Verification Complete', m_inner),
                       from_address="GooCampus <info@goocampus.in>")
        recipients = list(dict.fromkeys(ops_emails + mgmt_only))
        conn.execute(
            "INSERT INTO client_notifications (registration_id, notification_type, channel, recipient, subject) VALUES (?, ?, ?, ?, ?)",
            (reg_id, 'sales_completed', 'email', ','.join(recipients), 'Ops (button) + Management (plain) notified'))
        conn.commit()
        conn.close()
    except Exception as e:
        logging.error(f"_notify_sales_completed: {e}")


# ── ADMIN: Ops verification ──

@app.route('/admin/client/<int:reg_id>/ops-verify', methods=['POST'])
@login_required
def admin_client_ops_verify(reg_id):
    user = get_user()
    action = request.form.get('action')  # confirm or request_docs
    conn = get_db()

    if action == 'confirm':
        # Config-driven ops fields (role='ops'), whitelisted to real columns.
        # Dropped Date / Switched Program / Upgraded To are intentionally NOT
        # here (founder 2026-07-13): those are lifecycle edits done later in the
        # client profile, not part of ops verification. Ops only sets status +
        # current stage at verify time.
        _CR_OPS_COLS = {'account_status', 'current_stage'}
        prod = conn.execute("SELECT product_id FROM client_registrations WHERE id = ?", (reg_id,)).fetchone()
        ops_cfg = conn.execute(
            "SELECT field_name FROM client_form_configs WHERE product_id = ? "
            "AND role = 'ops' AND is_visible = 1", (prod['product_id'] if prod else None,)).fetchall()
        set_parts = ["ops_status = 'verified'", "ops_verified_by = ?", "ops_verified_at = CURRENT_TIMESTAMP",
                     "ops_notes = ?", "onboarding_status = 'confirmed'", "updated_at = CURRENT_TIMESTAMP"]
        vals = [user['id'], request.form.get('ops_notes', '')]
        for f in ops_cfg:
            if f['field_name'] in _CR_OPS_COLS:
                set_parts.append(f"{f['field_name']} = ?")
                vals.append(request.form.get(f['field_name'], ''))
        conn.execute(f"UPDATE client_registrations SET {', '.join(set_parts)} WHERE id = ?", vals + [reg_id])

        # Combined AMC Consulting + AMC 1: the AMC 1 (Training) sibling was auto-
        # created at registration (same account + invitation, client_submitted_at
        # NULL) and is hidden from the verify queue. Verifying the main reg verifies
        # it too — mark it verified with the same stamp; it's synced to its own
        # Training master below (info is common, payments are its own).
        sibling_ids = []
        _main = conn.execute(
            "SELECT account_id, invitation_id FROM client_registrations WHERE id = ?", (reg_id,)).fetchone()
        if _main and _main['invitation_id']:
            for _s in conn.execute(
                "SELECT id FROM client_registrations WHERE account_id = ? AND invitation_id = ? "
                "AND id <> ? AND client_submitted_at IS NULL AND COALESCE(ops_status,'') <> 'verified'",
                (_main['account_id'], _main['invitation_id'], reg_id)).fetchall():
                sibling_ids.append(_s['id'])
                conn.execute(
                    "UPDATE client_registrations SET ops_status='verified', ops_verified_by=?, "
                    "ops_verified_at=CURRENT_TIMESTAMP, onboarding_status='confirmed', "
                    "updated_at=CURRENT_TIMESTAMP WHERE id=?", (user['id'], _s['id']))
        # Welcome-kit checklist removed from the onboarding flow (founder
        # 2026-07-13: no welcome kit is being sent). We no longer seed it at
        # ops-verify. The welcome EMAIL still goes out via _notify_onboarding_confirmed.
        conn.commit()
        conn.close()
        _notify_onboarding_confirmed(reg_id)
        for _sid in sibling_ids:
            _sync_combined_sibling(reg_id, _sid, user['id'])
        if sibling_ids:
            flash('Onboarding confirmed for both AMC Consulting and AMC 1 (Training). Notifications sent.', 'success')
        else:
            flash('Client onboarding confirmed! Notifications sent.', 'success')

    elif action == 'request_docs':
        doc_type = request.form.get('doc_type', '')
        message = request.form.get('message', '')
        urgency = request.form.get('urgency', 'normal')
        conn.execute(
            "INSERT INTO client_doc_requests (registration_id, doc_type, message, urgency, requested_by) VALUES (?, ?, ?, ?, ?)",
            (reg_id, doc_type, message, urgency, user['id']))
        conn.commit()
        conn.close()
        # Notify client about doc request
        _notify_doc_request(reg_id, doc_type, message)
        flash('Document request sent to client.', 'success')

    else:
        conn.close()

    # Keep the Operations sidebar after ops verifies (don't revert to Clients). (2026-07-22)
    return redirect(url_for('admin_client_detail', reg_id=reg_id, **{'from': 'ops'}))


def _notify_onboarding_confirmed(reg_id):
    """Send welcome WA + email to client, and alert email to all team."""
    try:
        conn = get_db()
        reg = conn.execute('''SELECT cr.*, ps.name as product_name
            FROM client_registrations cr
            LEFT JOIN products_services ps ON ps.id = cr.product_id
            WHERE cr.id = ?''', (reg_id,)).fetchone()
        if not reg:
            conn.close()
            return
        client_name = f"{reg['prefix'] or ''} {reg['first_name'] or ''} {reg['last_name'] or ''}".strip()

        # 1. Welcome email to client — render the editable 'welcome_email'
        # template (admin can edit it at /admin/email-templates/welcome_email)
        # with the client's details substituted. Falls back to a built-in body
        # if the template is missing or disabled.
        if reg['email']:
            from email_utils import send_email
            # Resolve THIS client's counsellor for {{counsellor_name/number/email}}.
            # The template's contact table used to name a hardcoded counsellor, so
            # every client was told to call the same person regardless of whose lead
            # it was. Always look the phone/email up from the employee record.
            counsellor_nm = reg['counsellor_name'] or ''
            counsellor_ph, counsellor_em = '', ''
            if reg['counsellor_id']:
                _cr = conn.execute("SELECT name, email, phone FROM employees WHERE id = ?",
                                   (reg['counsellor_id'],)).fetchone()
                if _cr:
                    counsellor_nm = counsellor_nm or (_cr['name'] or '')
                    counsellor_ph = _cr['phone'] or ''
                    counsellor_em = _cr['email'] or ''
            tpl = conn.execute("SELECT * FROM email_templates WHERE template_key = 'welcome_email'").fetchone()
            tpl_enabled = bool(tpl and (tpl['enabled'] if 'enabled' in tpl.keys() and tpl['enabled'] is not None else 1))
            if tpl and tpl_enabled:
                subs = {
                    '{{client_name}}': client_name,
                    '{{counsellor_name}}': counsellor_nm or 'your counsellor',
                    '{{counsellor_number}}': counsellor_ph or '',
                    '{{counsellor_email}}': counsellor_em or '',
                    '{{product_name}}': reg['product_name'] or 'your programme',
                    '{{registration_number}}': reg['registration_number'] or '',
                    '{{plan_type}}': reg['plan_type'] or '',
                    '{{registration_date}}': (reg['created_at'].strftime('%d %b %Y') if hasattr(reg['created_at'], 'strftime') else str(reg['created_at'] or '')[:10]),
                    '{{portal_login_link}}': 'https://goocampus.org/client/login',
                    '{{refund_policy_link}}': 'https://goocampus.org/client/refund-policy',
                }
                client_subject = tpl['subject'] or 'Welcome to GooCampus'
                client_body = tpl['body_html'] or ''
                for _k, _v in subs.items():
                    client_subject = client_subject.replace(_k, str(_v))
                    client_body = client_body.replace(_k, str(_v))
            else:
                client_subject = f"Welcome to GooCampus — {reg['product_name'] or 'Your Program'}!"
                client_body = f"""<h2>Welcome to GooCampus, {client_name}!</h2>
                <p>Your onboarding for <strong>{reg['product_name'] or 'your program'}</strong> has been confirmed.</p>
                <p><strong>Registration #:</strong> {reg['registration_number']}</p>
                <p>You can log in to your client portal anytime to track your progress, upload documents, and stay updated.</p>
                <p><a href="https://goocampus.org/client/login">Log in to your portal</a></p>
                <p>Thank you for choosing GooCampus!</p>"""
            # Client + any active team members picked on the template (founder 2026-07-20).
            _to = [reg['email']] + [e for e in _template_staff_emails(conn, dict(tpl) if tpl else {})
                                    if e and e != reg['email']]
            send_email(list(dict.fromkeys(_to)), client_subject, client_body)

        # 2. Welcome WhatsApp to client
        if reg['mobile']:
            try:
                phone = reg['mobile'] if reg['mobile'].startswith('91') else f"91{reg['mobile']}"
                import os, requests as http_requests
                infobip_key = os.environ.get('INFOBIP_API_KEY', '')
                infobip_base = os.environ.get('INFOBIP_BASE_URL', '')
                if infobip_key and infobip_base:
                    url = f"https://{infobip_base}/whatsapp/1/message/template"
                    headers = {"Authorization": f"App {infobip_key}", "Content-Type": "application/json"}
                    payload = {"messages": [{"from": os.environ.get('INFOBIP_SENDER', '15558246314'), "to": phone,
                        "content": {"templateName": "client_welcome", "templateData": {"body": {"placeholders": [client_name]}}, "language": "en"}}]}
                    http_requests.post(url, json=payload, headers=headers, timeout=10)
            except Exception as wa_e:
                logging.error(f"Welcome WA: {wa_e}")

        # 3. Onboarding confirmation — a branded "client has registered with
        # GooCampus" note to Sales + Operations + Management + Digital Marketing.
        from email_utils import (send_email, render_branded_email, brand_detail_rows,
                                  brand_photo_block, brand_callout)
        sm_name, _sm_email = _lead_sales_member(conn, reg)
        onb_photo_url = _client_photo_email_url(conn, reg)
        # Editable + recipient-controlled via the 'client_onboarded_team' template:
        # edit the wording, tick exactly who gets it, or disable to switch it off.
        # Defaults to the historical broad recipient list + wording. (2026-07-22)
        _ob_row = conn.execute("SELECT * FROM email_templates WHERE template_key = 'client_onboarded_team'").fetchone()
        _ob_tpl = dict(_ob_row) if _ob_row else {}
        _ob_enabled = (_ob_tpl.get('enabled', 1) if _ob_tpl else 1)
        if _ob_enabled:
            team_recipients = _onboarded_team_recipients(conn, _ob_tpl, reg, _sm_email)
        else:
            team_recipients = []
        if team_recipients:
            _ob_r = _sc_render(conn, 'client_onboarded_team', {
                'client_name': client_name,
                'registration_number': (reg['registration_number'] or ''),
                'product_name': (reg['product_name'] or 'N/A'),
                'sales_member': (sm_name or ''),
                'mobile': (reg['mobile'] or ''),
                'email': (reg['email'] or '')})
            if _ob_r:
                team_subject, team_body = _ob_r
            else:
                team_subject = f"New Client Onboarded — {client_name} ({reg['product_name'] or 'N/A'})"
                team_inner = (
                    brand_photo_block(onb_photo_url, client_name) +
                    brand_callout(
                        f"<strong>{client_name}</strong> has successfully registered with GooCampus and "
                        f"completed both sales &amp; operations verification. The client is now onboarded.",
                        color='#F0FDF4', border='#BBF7D0', tcolor='#166534') +
                    brand_detail_rows([
                        ('Client', client_name),
                        ('Registration #', reg['registration_number']),
                        ('Product', reg['product_name']),
                        ('Whose lead', sm_name),
                        ('Mobile', reg['mobile']),
                        ('Email', reg['email']),
                    ])
                )
                team_body = render_branded_email('Client Registered with GooCampus', team_inner,
                                                 preheader=f"{client_name} is now onboarded")
            send_email(team_recipients, team_subject, team_body,
                       from_address="GooCampus <info@goocampus.in>")

        # 4. Auto-sync to plab_clients and ops_academic_details
        try:
            _sync_to_plab_and_academics(conn, reg, reg_id)
        except Exception as sync_e:
            logging.error(f"Auto-sync to plab/academics: {sync_e}")

        # 4b. Record onboarding-section timestamps: the welcome email was just sent,
        # and this ops verification IS the onboarding moment. Stamp both.
        try:
            pcob = conn.execute("SELECT id FROM plab_clients WHERE registration_number = ?",
                                (reg['registration_number'],)).fetchone()
            if pcob:
                _ensure_client_onboarding(conn, pcob['id'], reg['registration_number'])
                conn.execute(
                    "UPDATE client_onboarding SET welcome_email_sent = 1, "
                    "welcome_email_sent_at = COALESCE(welcome_email_sent_at, CURRENT_TIMESTAMP), "
                    "onboarded_at = COALESCE(onboarded_at, CURRENT_TIMESTAMP), "
                    "updated_at = CURRENT_TIMESTAMP WHERE client_id = ?", (pcob['id'],))
        except Exception as _obe:
            logging.warning(f"onboarding timestamps {reg_id}: {_obe}")

        # Log notifications
        conn.execute("INSERT INTO client_notifications (registration_id, notification_type, channel, recipient, subject) VALUES (?, ?, ?, ?, ?)",
            (reg_id, 'onboarding_confirmed', 'email', reg['email'] or '', 'Welcome email sent'))
        conn.execute("INSERT INTO client_notifications (registration_id, notification_type, channel, recipient, subject) VALUES (?, ?, ?, ?, ?)",
            (reg_id, 'onboarding_confirmed', 'whatsapp', reg['mobile'] or '', 'Welcome WA sent'))
        conn.execute("INSERT INTO client_notifications (registration_id, notification_type, channel, recipient, subject) VALUES (?, ?, ?, ?, ?)",
            (reg_id, 'new_client_alert', 'email', 'all_team', 'Team alert sent'))
        conn.commit()
        conn.close()
    except Exception as e:
        logging.error(f"_notify_onboarding_confirmed: {e}")


# ─── Welcome Call (hybrid): client requests a preferred slot, ops confirms ───

def _welcome_call_ics(summary, description, date_str, time_str, duration_min=30):
    """Build a base64 .ics calendar invite for a welcome call. date_str
    'YYYY-MM-DD' + time_str 'HH:MM' are IST; emitted as UTC so Google/Outlook/
    Apple calendars all read it correctly. Returns None on bad input."""
    from datetime import datetime as _dt, timedelta as _td
    import base64 as _b64
    _t = (time_str or '10:00 AM').strip()
    start_ist = None
    for _fmt_in in ("%Y-%m-%d %I:%M %p", "%Y-%m-%d %H:%M"):
        try:
            start_ist = _dt.strptime(f"{date_str} {_t}", _fmt_in)
            break
        except Exception:
            continue
    if start_ist is None:
        return None
    start_utc = start_ist - _td(hours=5, minutes=30)
    end_utc = start_utc + _td(minutes=duration_min)
    _fmt = lambda d: d.strftime("%Y%m%dT%H%M%SZ")
    now = datetime.utcnow()
    uid = f"wc-{date_str}-{(time_str or '').replace(':', '')}-{now.strftime('%Y%m%d%H%M%S')}@goocampus.org"
    def esc(s):
        return (s or '').replace('\\', '\\\\').replace(';', '\\;').replace(',', '\\,').replace('\n', '\\n')
    ics = "\r\n".join([
        "BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//GooCampus//Welcome Call//EN",
        "CALSCALE:GREGORIAN", "METHOD:REQUEST", "BEGIN:VEVENT",
        f"UID:{uid}", f"DTSTAMP:{_fmt(now)}", f"DTSTART:{_fmt(start_utc)}", f"DTEND:{_fmt(end_utc)}",
        f"SUMMARY:{esc(summary)}", f"DESCRIPTION:{esc(description)}",
        "STATUS:CONFIRMED", "END:VEVENT", "END:VCALENDAR", "",
    ])
    return _b64.b64encode(ics.encode('utf-8')).decode('ascii')


@app.route('/client/welcome-call', methods=['GET'])
@client_required
def client_welcome_call_page():
    """Polished 'registration complete → schedule your welcome call' page, shown
    right after the client finishes the form + contract + refund policy."""
    acct_id = session.get('user_id')
    conn = get_db()
    # Gate: the client MUST digitally sign the Contract (if any) + Refund Policy
    # before they can see the "registration complete / schedule welcome call" page.
    # Otherwise back-to-dashboard could skip signing and land here directly.
    _greg, _gate_step, _stages = _client_gate_status(conn, acct_id)
    if _gate_step == 'contract':
        conn.close()
        return redirect(url_for('client_contract'))
    if _gate_step == 'refund':
        conn.close()
        return redirect(url_for('client_refund_policy'))
    account = conn.execute("SELECT * FROM client_accounts WHERE id = ?", (acct_id,)).fetchone()
    reg = conn.execute('''SELECT cr.*, ps.name AS product_name FROM client_registrations cr
        LEFT JOIN products_services ps ON ps.id = cr.product_id
        WHERE cr.account_id = ? AND cr.client_submitted_at IS NOT NULL
        ORDER BY cr.created_at DESC LIMIT 1''', (acct_id,)).fetchone()
    conn.close()
    if not reg:
        return redirect(url_for('client_dashboard'))
    return render_template('client_welcome_call.html', account=account, reg=reg)


@app.route('/client/welcome-call/request', methods=['POST'])
@client_required
def client_welcome_call_request():
    """Client submits a PREFERRED welcome-call slot (after contract + refund).
    Ops sees it and sets/confirms the final one."""
    acct_id = session.get('user_id')
    reg_id = request.form.get('reg_id')
    conn = get_db()
    reg = conn.execute("SELECT id FROM client_registrations WHERE id = ? AND account_id = ?",
                       (reg_id, acct_id)).fetchone()
    if not reg:
        conn.close()
        flash('Registration not found.', 'error')
        return redirect(url_for('client_dashboard'))
    pdate = request.form.get('wc_pref_date', '')
    ptime = request.form.get('wc_pref_time', '')
    conn.execute(
        "UPDATE client_registrations SET wc_pref_date=?, wc_pref_time=?, wc_pref_notes=?, "
        "wc_status='requested', updated_at=CURRENT_TIMESTAMP WHERE id=?",
        (pdate, ptime, request.form.get('wc_pref_notes', ''), reg_id))
    conn.commit()
    # Notify the lead's sales member + Operations team that the client asked for a slot.
    try:
        full = conn.execute('''SELECT cr.*, ps.name AS product_name FROM client_registrations cr
            LEFT JOIN products_services ps ON ps.id = cr.product_id WHERE cr.id = ?''', (reg_id,)).fetchone()
        sm_name, sm_email = _lead_sales_member(conn, full)
        team_to = list(dict.fromkeys([e for e in ([sm_email] + _dept_emails(conn, ['Operations'])) if e]))
        cname = f"{full['prefix'] or ''} {full['first_name'] or ''} {full['last_name'] or ''}".strip()
        from email_utils import send_email, render_branded_email, brand_detail_rows, brand_button
        if team_to:
            inner = (brand_detail_rows([('Client', cname), ('Registration #', full['registration_number']),
                        ('Product', full['product_name']), ('Whose lead', sm_name),
                        ('Preferred date', pdate), ('Preferred time', ptime)]) +
                     brand_button('Open in portal', f"https://goocampus.org/admin/client/{reg_id}?from=ops"))
            send_email(team_to, f"Welcome Call Requested — {cname}",
                       render_branded_email('Client requested a Welcome Call', inner),
                       from_address="GooCampus <info@goocampus.in>")
    except Exception as e:
        logging.warning(f"welcome call request notify {reg_id}: {e}")
    conn.close()
    flash('Thanks! Your preferred welcome-call time has been shared with our team — we will confirm shortly.', 'success')
    return redirect(url_for('client_welcome_call_page'))


@app.route('/admin/client/<int:reg_id>/welcome-call/confirm', methods=['POST'])
@login_required
def admin_client_welcome_call_confirm(reg_id):
    """Ops sets the FINAL welcome-call slot + caller and confirms. Emails the
    client an .ics invite; the confirmation shows on their dashboard."""
    conn = get_db()
    reg = conn.execute('''SELECT cr.*, ps.name AS product_name FROM client_registrations cr
        LEFT JOIN products_services ps ON ps.id = cr.product_id WHERE cr.id = ?''', (reg_id,)).fetchone()
    if not reg:
        conn.close()
        flash('Client not found.', 'error')
        return redirect(url_for('admin_clients_list'))
    # Sales still has the call on hold — ops may confirm the onboarding, but not
    # the welcome call, until sales releases it (founder 2026-07-17).
    if reg['welcome_call_hold']:
        conn.close()
        flash("Sales has this welcome call on hold. It must be released before you can confirm or reschedule it.", 'error')
        return redirect(url_for('admin_client_detail', reg_id=reg_id) + '#operations')
    date_s = (request.form.get('wc_scheduled_date', '') or '').strip()
    time_s = (request.form.get('wc_scheduled_time', '') or '').strip()
    wc_by = (request.form.get('wc_by', '') or '').strip()
    if not date_s or not time_s:
        conn.close()
        flash('Please set the welcome-call date and time before confirming.', 'error')
        return redirect(url_for('admin_client_detail', reg_id=reg_id))
    conn.execute(
        "UPDATE client_registrations SET wc_scheduled_date=?, wc_scheduled_time=?, wc_by=?, "
        "wc_confirmed=1, wc_status='confirmed', wc_confirmed_at=CURRENT_TIMESTAMP, "
        # Confirming the call means it is no longer on hold. A stale hold flag left
        # by sales was making the client's dashboard show "pending" even after the
        # call was confirmed (founder 2026-07-17).
        "welcome_call_hold=0, "
        "updated_at=CURRENT_TIMESTAMP WHERE id=?",
        (date_s, time_s, wc_by, reg_id))
    conn.commit()
    conn.close()
    _notify_welcome_call_confirmed(reg_id)
    flash('Welcome call confirmed. The client has an invite; the sales & ops team have been notified.', 'success')
    return redirect(url_for('admin_client_detail', reg_id=reg_id))


def _notify_welcome_call_confirmed(reg_id):
    """Send the CONFIRMED welcome-call emails: the client gets a branded email +
    .ics; the lead's sales member, the Operations team and the caller get a
    branded internal notice. Used by both the ops direct-confirm and the client's
    confirm-of-a-proposed-slot paths."""
    try:
        conn = get_db()
        reg = conn.execute('''SELECT cr.*, ps.name AS product_name FROM client_registrations cr
            LEFT JOIN products_services ps ON ps.id = cr.product_id WHERE cr.id = ?''', (reg_id,)).fetchone()
        if not reg:
            conn.close(); return
        date_s = reg['wc_scheduled_date'] or ''
        time_s = reg['wc_scheduled_time'] or ''
        wc_by = reg['wc_by'] or ''
        client_name = f"{reg['prefix'] or ''} {reg['first_name'] or ''} {reg['last_name'] or ''}".strip()
        client_email = reg['email']
        product_name = reg['product_name'] or 'your program'
        sm_name, sm_email = _lead_sales_member(conn, reg)
        ops_emails = _dept_emails(conn, ['Operations'])
        caller_email = ''
        if wc_by:
            crow = conn.execute("SELECT email FROM employees WHERE is_active = 1 AND name = ? LIMIT 1", (wc_by,)).fetchone()
            caller_email = (crow['email'] if crow else '') or ''
        conn.close()
        from email_utils import (send_email, render_branded_email, brand_detail_rows, brand_callout)
        # Client email + .ics
        if client_email:
            desc = (f"Your GooCampus welcome call for {product_name}. "
                    f"Our team member {wc_by or 'GooCampus'} will call you at the scheduled time.")
            ics_b64 = _welcome_call_ics("GooCampus Welcome Call", desc, date_s, time_s)
            inner = (brand_callout(f"Your GooCampus welcome call is confirmed for "
                     f"<strong>{date_s} at {time_s} IST</strong>{(' with ' + wc_by) if wc_by else ''}.",
                     color='#F0FDF4', border='#BBF7D0', tcolor='#166534') +
                     f"<p>Dear {client_name or 'there'}, a calendar invite is attached so you can add it "
                     f"to your calendar. We look forward to speaking with you!</p><p>&mdash; Team GooCampus</p>")
            _sc = _sc_render(conn, 'sc_welcome_call_confirmed', {
                'client_name': client_name, 'wc_date': date_s, 'wc_time': time_s})
            if _sc:
                _wc_subj, body = _sc
            else:
                _wc_subj = "Your GooCampus Welcome Call is confirmed"
                body = render_branded_email('Welcome Call Confirmed', inner,
                                            preheader=f"{date_s} at {time_s} IST")
            atts = [{'filename': 'welcome-call.ics', 'content': ics_b64}] if ics_b64 else None
            try:
                send_email([client_email], _wc_subj, body,
                           attachments=atts, from_address="GooCampus <info@goocampus.in>")
            except Exception as e:
                logging.warning(f"welcome call client email {reg_id}: {e}")
        # Internal notice
        team_to = list(dict.fromkeys([e for e in ([sm_email, caller_email] + ops_emails) if e]))
        if team_to:
            t_inner = (brand_callout(
                f"Welcome call confirmed for <strong>{client_name}</strong> — "
                f"<strong>{date_s} at {time_s} IST</strong>"
                + (f", to be taken by <strong>{wc_by}</strong>" if wc_by else "") + ".") +
                brand_detail_rows([('Client', client_name), ('Registration #', reg['registration_number']),
                    ('Product', product_name), ('Whose lead', sm_name),
                    ('Call date', date_s), ('Call time', f"{time_s} IST"), ('Taken by', wc_by)]))
            t_body = render_branded_email('Welcome Call Confirmed', t_inner,
                                          preheader=f"{client_name}: {date_s} {time_s} IST")
            try:
                send_email(team_to, f"Welcome Call Confirmed — {client_name} ({date_s} {time_s} IST)",
                           t_body, from_address="GooCampus <info@goocampus.in>")
            except Exception as e:
                logging.warning(f"welcome call team email {reg_id}: {e}")
        # Record the confirmed call on the ops onboarding record too, so the pathway
        # Onboarding section + the client's journey status reflect it.
        try:
            conn3 = get_db()
            pc = conn3.execute("SELECT id FROM plab_clients WHERE registration_number = ?",
                               (reg['registration_number'],)).fetchone()
            if pc:
                _ensure_client_onboarding(conn3, pc['id'], reg['registration_number'])
                conn3.execute("UPDATE client_onboarding SET welcome_call_confirmed = 1, "
                              "welcome_call_date = ?, welcome_call_time = ?, welcome_call_by = ?, "
                              "updated_at = CURRENT_TIMESTAMP WHERE client_id = ?",
                              (date_s, time_s, wc_by, pc['id']))
                conn3.commit()
            conn3.close()
        except Exception as _oe:
            logging.warning(f"welcome call onboarding sync {reg_id}: {_oe}")
    except Exception as e:
        logging.error(f"_notify_welcome_call_confirmed({reg_id}): {e}")


@app.route('/admin/client/<int:reg_id>/welcome-call/propose', methods=['POST'])
@login_required
def admin_client_welcome_call_propose(reg_id):
    """Ops proposes a DIFFERENT welcome-call slot back to the client, who then
    confirms it on their dashboard. Emails the client the proposal."""
    conn = get_db()
    reg = conn.execute('''SELECT cr.*, ps.name AS product_name FROM client_registrations cr
        LEFT JOIN products_services ps ON ps.id = cr.product_id WHERE cr.id = ?''', (reg_id,)).fetchone()
    if not reg:
        conn.close(); flash('Client not found.', 'error'); return redirect(url_for('admin_clients_list'))
    if reg['welcome_call_hold']:
        conn.close()
        flash("Sales has this welcome call on hold. It must be released before you can reschedule or confirm it.", 'error')
        return redirect(url_for('admin_client_detail', reg_id=reg_id) + '#operations')
    date_s = (request.form.get('wc_proposed_date', '') or '').strip()
    time_s = (request.form.get('wc_proposed_time', '') or '').strip()
    wc_by = (request.form.get('wc_by', '') or '').strip()
    note = (request.form.get('wc_proposed_note', '') or '').strip()
    if not date_s or not time_s:
        conn.close(); flash('Please pick the proposed date and time.', 'error')
        return redirect(url_for('admin_client_detail', reg_id=reg_id))
    conn.execute("UPDATE client_registrations SET wc_proposed_date=?, wc_proposed_time=?, "
                 "wc_proposed_note=?, wc_by=?, wc_status='proposed', wc_confirmed=0, "
                 "updated_at=CURRENT_TIMESTAMP WHERE id=?", (date_s, time_s, note, wc_by, reg_id))
    conn.commit()
    client_name = f"{reg['prefix'] or ''} {reg['first_name'] or ''} {reg['last_name'] or ''}".strip()
    client_email = reg['email']
    conn.close()
    try:
        from email_utils import send_email, render_branded_email, brand_callout, brand_button
        if client_email:
            inner = (brand_callout(
                f"Our team has proposed a welcome-call time: <strong>{date_s} at {time_s} IST</strong>"
                + (f", with {wc_by}" if wc_by else "") + "."
                + (f"<br><span style='font-size:13px;'>{note}</span>" if note else "")) +
                f"<p>Dear {client_name or 'there'}, please log in and <strong>confirm</strong> this time, "
                f"or propose another slot that suits you.</p>" +
                brand_button('Confirm your welcome call', 'https://goocampus.org/client/welcome-call'))
            _sc = None
            try:
                _c2 = get_db()
                _sc = _sc_render(_c2, 'sc_welcome_call_reschedule', {
                    'client_name': client_name, 'wc_date': date_s, 'wc_time': time_s, 'note': (note or '')})
                _c2.close()
            except Exception:
                _sc = None
            if _sc:
                _rs_subj, body = _sc
            else:
                _rs_subj = "GooCampus Welcome Call — please confirm the time"
                body = render_branded_email('Welcome Call — please confirm the proposed time', inner,
                                            preheader=f"Proposed: {date_s} {time_s} IST")
            send_email([client_email], _rs_subj, body,
                       from_address="GooCampus <info@goocampus.in>")
    except Exception as e:
        logging.warning(f"welcome call propose email {reg_id}: {e}")
    flash('Proposed time sent to the client to confirm.', 'success')
    return redirect(url_for('admin_client_detail', reg_id=reg_id))


@app.route('/admin/client/<int:reg_id>/welcome-call/hold', methods=['POST'])
@login_required
def admin_client_welcome_call_hold(reg_id):
    """Put the welcome call ON HOLD (e.g. token payment, balance pending) so it
    can't be booked yet, or clear the hold.

    Only the sales member whose lead this is may hold/release it — they are the one
    who knows the payment position (founder 2026-07-16). Admins are allowed too, so
    the hold can still be managed when that person is unavailable."""
    conn = get_db()
    reg = conn.execute("SELECT counsellor_id, wc_confirmed, wc_status FROM client_registrations WHERE id = ?", (reg_id,)).fetchone()
    if not reg:
        conn.close()
        flash('Registration not found.', 'error')
        return redirect(url_for('admin_client_detail', reg_id=reg_id))
    if not session.get('is_admin') and reg['counsellor_id'] != session.get('user_id'):
        conn.close()
        flash("Only the sales member who generated this lead can hold or release the welcome call.", 'error')
        return redirect(url_for('admin_client_detail', reg_id=reg_id) + '#sales')
    # Once Operations has taken the welcome call over — confirmed it, or proposed a
    # reschedule — sales can no longer touch the hold, even via a direct/stale POST.
    # Re-holding after ops moved forward was flipping the client back to "pending"
    # and interrupting the flow (founder 2026-07-17).
    if reg['wc_confirmed'] or (reg['wc_status'] or '') == 'proposed':
        conn.close()
        flash("The welcome call is now with Operations and can no longer be put on hold.", 'error')
        return redirect(url_for('admin_client_detail', reg_id=reg_id) + '#sales')
    hold = 1 if request.form.get('hold') == '1' else 0
    conn.execute("UPDATE client_registrations SET welcome_call_hold=?, updated_at=CURRENT_TIMESTAMP WHERE id=?",
                 (hold, reg_id))
    conn.commit()
    # Notify the Operations team of the hold change — especially on RELEASE, so they
    # know the welcome call is ready to book.
    try:
        reg = conn.execute('''SELECT cr.*, ps.name AS product_name FROM client_registrations cr
            LEFT JOIN products_services ps ON ps.id = cr.product_id WHERE cr.id = ?''', (reg_id,)).fetchone()
        ops_emails = _dept_emails(conn, ['Operations'])
        cname = f"{reg['prefix'] or ''} {reg['first_name'] or ''} {reg['last_name'] or ''}".strip()
        from email_utils import send_email, render_branded_email, brand_callout, brand_detail_rows, brand_button
        if ops_emails:
            if hold:
                inner = (brand_callout(f"Sales has put the welcome call for <strong>{cname}</strong> ON HOLD "
                         f"(token / partial payment). No booking yet.", color='#FEF3C7', border='#FCD34D', tcolor='#92400E') +
                         brand_detail_rows([('Client', cname), ('Registration #', reg['registration_number']),
                             ('Product', reg['product_name'])]))
                subj = f"Welcome Call On Hold — {cname}"
                head = 'Welcome Call — On Hold by Sales'
            else:
                inner = (brand_callout(f"Sales has RELEASED the welcome-call hold for <strong>{cname}</strong> — "
                         f"payment received. Please book the welcome call.", color='#F0FDF4', border='#BBF7D0', tcolor='#166534') +
                         brand_detail_rows([('Client', cname), ('Registration #', reg['registration_number']),
                             ('Product', reg['product_name']),
                             ('Client requested', (reg['wc_pref_date'] or '') + (' at ' + reg['wc_pref_time'] if reg['wc_pref_time'] else ''))]) +
                         brand_button('Book the welcome call', f"https://goocampus.org/admin/client/{reg_id}?from=ops#operations"))
                subj = f"Welcome Call Ready to Book — {cname}"
                head = 'Welcome Call — Ready to Book'
            send_email(ops_emails, subj, render_branded_email(head, inner),
                       from_address="GooCampus <info@goocampus.in>")
    except Exception as e:
        logging.warning(f"welcome call hold notify {reg_id}: {e}")
    conn.close()
    flash('Welcome call put on hold — the client cannot schedule it yet.' if hold
          else 'Hold released — the client can now schedule, and the Ops team has been notified to book the call.', 'success')
    return redirect(url_for('admin_client_detail', reg_id=reg_id))


@app.route('/client/welcome-call/confirm-proposal', methods=['POST'])
@client_required
def client_welcome_call_confirm_proposal():
    """Client confirms the slot the ops team proposed. Locks it in as confirmed
    and fires the confirmed emails to client + team + caller."""
    acct_id = session.get('user_id')
    reg_id = request.form.get('reg_id')
    conn = get_db()
    reg = conn.execute("SELECT id, wc_proposed_date, wc_proposed_time FROM client_registrations "
                       "WHERE id = ? AND account_id = ?", (reg_id, acct_id)).fetchone()
    if not reg or not reg['wc_proposed_date']:
        conn.close(); flash('No proposed time to confirm.', 'error')
        return redirect(url_for('client_welcome_call_page'))
    conn.execute("UPDATE client_registrations SET wc_scheduled_date=wc_proposed_date, "
                 "wc_scheduled_time=wc_proposed_time, wc_confirmed=1, wc_status='confirmed', "
                 "wc_confirmed_at=CURRENT_TIMESTAMP, welcome_call_hold=0, "
                 "updated_at=CURRENT_TIMESTAMP WHERE id=?", (reg_id,))
    conn.commit(); conn.close()
    _notify_welcome_call_confirmed(reg_id)
    flash('Thank you — your welcome call is confirmed. A calendar invite has been emailed to you.', 'success')
    return redirect(url_for('client_welcome_call_page'))


def _sync_to_plab_and_academics(conn, reg, reg_id):
    """Sync confirmed client registration data into plab_clients and ops_academic_details."""
    reg_num = reg.get('registration_number', '')
    if not reg_num:
        return

    # Check if already synced
    existing = conn.execute("SELECT id FROM plab_clients WHERE registration_number = ?", (reg_num,)).fetchone()
    if existing:
        logging.info(f"plab_clients already has {reg_num}, skipping sync")
        return

    # Load academics from client_academics
    academics = conn.execute("SELECT * FROM client_academics WHERE registration_id = ?", (reg_id,)).fetchone()

    # Get counsellor details
    counsellor_name = reg.get('counsellor_name', '')
    counsellor_email = ''
    counsellor_number = ''
    if reg.get('counsellor_id'):
        emp = conn.execute("SELECT name, email, phone FROM employees WHERE id = ?", (reg['counsellor_id'],)).fetchone()
        if emp:
            counsellor_name = emp['name'] or ''
            counsellor_email = emp['email'] or ''
            counsellor_number = emp['phone'] or ''

    # Get created_by (the ops user who confirmed)
    created_by = reg.get('ops_verified_by') or reg.get('counsellor_id')

    # Resolve the client's REAL pathway from their product so the master record
    # is stamped correctly. Root fix for "everything shows PLAB": this insert
    # previously omitted pathway/product_id, so plab_clients.pathway fell back to
    # its 'plab' default for every pathway — hiding Australia/UAE/Consulting/
    # Portfolio/Training clients inside the PLAB lists + links. Mirrors the
    # internal-transfer path (_execute_internal_transfer), which does set pathway.
    product_id = reg.get('product_id')
    pathway = resolve_ops_pathway(conn, product_id, reg.get('product_name'))

    # INSERT into plab_clients
    conn.execute('''INSERT INTO plab_clients (
        registration_number, registration_date, prefix, first_name, last_name,
        mobile, whatsapp1, whatsapp2, email, dob, city, state,
        instagram, facebook, linkedin, photo_path,
        father_name, father_phone, mother_name, mother_phone, parents_email,
        joined_stage, plan_type, english_training, account_status, current_stage,
        counsellor, counsellor_email, counsellor_number,
        lead_source, operations_referral, portfolio_referral, australia_referral,
        package_amount, discount_allowed, additional_package_notes, final_package,
        inst1_amount, inst1_date, inst1_note,
        inst2_amount, inst2_date, inst2_note,
        inst3_amount, inst3_date, inst3_note,
        inst4_amount, inst4_date, inst4_note,
        additional_notes, created_by, pathway, product_id
    ) VALUES (
        ?, ?, ?, ?, ?,
        ?, ?, ?, ?, ?, ?, ?,
        ?, ?, ?, ?,
        ?, ?, ?, ?, ?,
        ?, ?, ?, ?, ?,
        ?, ?, ?,
        ?, ?, ?, ?,
        ?, ?, ?, ?,
        ?, ?, ?,
        ?, ?, ?,
        ?, ?, ?,
        ?, ?, ?,
        ?, ?, ?, ?
    )''', (
        # registration_date = the sales close date if present, else the form-submission
        # timestamp (founder 2026-07-22: "the close date IS the registration date").
        reg_num, (reg.get('sales_close_date') or reg.get('created_at', '')), reg.get('prefix', 'Dr.'),
        reg.get('first_name', ''), reg.get('last_name', ''),
        reg.get('mobile', ''), reg.get('whatsapp', ''), reg.get('whatsapp2', ''),
        reg.get('email', ''), reg.get('dob', ''), reg.get('city', ''), reg.get('state', ''),
        reg.get('instagram', ''), reg.get('facebook', ''), reg.get('linkedin', ''), reg.get('photo_path', ''),
        reg.get('father_name', ''), reg.get('father_phone', ''),
        reg.get('mother_name', ''), reg.get('mother_phone', ''), reg.get('parents_email', ''),
        # joined_stage + current_stage were hardcoded to '' here, so the stage sales
        # picked during verification and the stage ops set were both thrown away and
        # the pathway profile always showed them blank.
        reg.get('joined_stage', '') or '', reg.get('plan_type', ''), '',
        'In Process', reg.get('current_stage', '') or reg.get('joined_stage', '') or '',
        counsellor_name, counsellor_email, counsellor_number,
        reg.get('lead_source', ''), '', '', '',
        reg.get('package_amount', 0), reg.get('discount_allowed', 0), '',
        reg.get('final_package', 0),
        reg.get('inst1_amount', 0), reg.get('inst1_date', ''), reg.get('inst1_note', ''),
        reg.get('inst2_amount', 0), reg.get('inst2_date', ''), reg.get('inst2_note', ''),
        reg.get('inst3_amount', 0), reg.get('inst3_date', ''), reg.get('inst3_note', ''),
        reg.get('inst4_amount', 0), reg.get('inst4_date', ''), reg.get('inst4_note', ''),
        reg.get('additional_notes', ''), created_by, pathway, product_id
    ))

    # Copy the Parent/Guardian granular data onto the master record too (the flat
    # father_name/mother_name/parents_email are already in the insert above).
    try:
        conn.execute(
            "UPDATE plab_clients SET guardian_type=?, father_first_name=?, father_last_name=?, "
            "father_email=?, mother_first_name=?, mother_last_name=?, mother_email=?, "
            "guardian_first_name=?, guardian_last_name=?, guardian_email=?, guardian_phone=? "
            "WHERE registration_number = ?",
            (reg.get('guardian_type', ''), reg.get('father_first_name', ''), reg.get('father_last_name', ''),
             reg.get('father_email', ''), reg.get('mother_first_name', ''), reg.get('mother_last_name', ''),
             reg.get('mother_email', ''), reg.get('guardian_first_name', ''), reg.get('guardian_last_name', ''),
             reg.get('guardian_email', ''), reg.get('guardian_phone', ''), reg_num))
    except Exception as _g_err:
        logging.warning(f"sync guardian fields {reg_num}: {_g_err}")

    # INSERT into ops_academic_details (only if academics data exists).
    # CRITICAL: stamp the client's real `pathway`. Omitting it let the column fall
    # to its 'plab' default, so a Consulting/Australia/UAE/Portfolio/Training
    # client's academics were filed under PLAB and hidden from their own pathway's
    # Academic Details page (which filters `WHERE pathway = '<pathway>'`).
    # (founder 2026-07-21: "academic details we don't have what she filled")
    if academics:
        conn.execute('''INSERT INTO ops_academic_details (
            registration_number, img_fmg, img_medical_college, fmg_medical_college,
            country, mbbs_status, mbbs_start_date, mbbs_end_date,
            speciality_interest_1, speciality_interest_2,
            internship_status, internship_hospital, internship_location,
            internship_hospital_2, internship_location_2,
            internship_start_date, internship_end_date,
            internship_gap, gap_in_months, gap_reason,
            working_status, working_hospital_name, additional_info, created_by, pathway
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)''', (
            reg_num,
            academics.get('img_fmg', ''), academics.get('img_medical_college', ''),
            academics.get('fmg_medical_college', ''),
            academics.get('country', ''), academics.get('mbbs_status', ''),
            academics.get('mbbs_start_date', ''), academics.get('mbbs_end_date', ''),
            academics.get('speciality_interest_1', ''), academics.get('speciality_interest_2', ''),
            academics.get('internship_status', ''), academics.get('internship_hospital', ''),
            academics.get('internship_location', ''),
            academics.get('internship_hospital_2', ''), academics.get('internship_location_2', ''),
            academics.get('internship_start_date', ''), academics.get('internship_end_date', ''),
            academics.get('internship_gap', ''), academics.get('gap_in_months', ''),
            academics.get('gap_reason', ''),
            academics.get('working_status', ''), academics.get('working_hospital_name', ''),
            academics.get('additional_info', ''), created_by, (pathway or 'plab')
        ))

    # ── Carry the registration's documents into the ops pathway profile ──────
    # The pathway profile reads plab_client_documents (by client_id); the client
    # uploaded during registration to client_documents (by registration_id). Copy
    # them across so the PHOTO, CONTRACT and every uploaded document appear in the
    # ops profile's document section (and set the profile photo from the upload).
    try:
        pc = conn.execute("SELECT id, photo_path FROM plab_clients WHERE registration_number = ?", (reg_num,)).fetchone()
        if pc:
            pc_id = pc['id']
            # De-dupe per document, not "does this client have any document at all".
            # The coarse guard let a re-run copy nothing, while a client who uploaded
            # the same doc type twice had BOTH rows copied ("Aadhaar — 2 files").
            _have = set()
            for _r in conn.execute(
                    "SELECT doc_type, file_name FROM plab_client_documents WHERE client_id = ?",
                    (pc_id,)).fetchall():
                _have.add(((_r['doc_type'] or ''), (_r['file_name'] or '')))
            if True:
                docs = conn.execute(
                    "SELECT DISTINCT ON (doc_type) doc_type, file_name, file_path, file_size "
                    "  FROM client_documents WHERE registration_id = ? ORDER BY doc_type, id DESC",
                    (reg_id,)).fetchall()
                photo_fp = ''
                for d in docs:
                    if ((d['doc_type'] or ''), (d['file_name'] or '')) in _have:
                        continue
                    conn.execute(
                        "INSERT INTO plab_client_documents (client_id, doc_type, doc_category, file_name, "
                        " file_path, file_size, status, uploaded_by) "
                        "VALUES (?, ?, 'registration', ?, ?, ?, 'uploaded', 'registration')",
                        (pc_id, d['doc_type'] or 'Document', d['file_name'] or '',
                         d['file_path'] or '', d['file_size'] or 0))
                    if (d['doc_type'] or '') == 'Photograph' and d['file_path']:
                        photo_fp = d['file_path']
                # Set the profile photo from the uploaded Photograph if not already set.
                if photo_fp and not (pc['photo_path'] or ''):
                    conn.execute("UPDATE plab_clients SET photo_path = ? WHERE id = ?", (photo_fp, pc_id))
                # Carry the signed contract in as a document too...
                contract_fp = reg.get('contract_path') or ''
                if contract_fp and ('Signed Contract', 'Signed Contract') not in _have:
                    conn.execute(
                        "INSERT INTO plab_client_documents (client_id, doc_type, doc_category, file_name, "
                        " file_path, file_size, status, uploaded_by) "
                        "VALUES (?, 'Signed Contract', 'contract', 'Signed Contract', ?, 0, 'uploaded', 'registration')",
                        (pc_id, contract_fp))
                # ...and onto the master record itself. Every ops pathway profile
                # gates the contract card on plab_clients.contract_path, which the
                # master INSERT never sets — so the profile asked to "Upload
                # Contract" forever even though the client had already signed one.
                if contract_fp:
                    conn.execute("UPDATE plab_clients SET contract_path = ? "
                                 "WHERE id = ? AND COALESCE(contract_path,'') = ''",
                                 (contract_fp, pc_id))
    except Exception as _de:
        logging.warning(f"sync registration docs for {reg_num}: {_de}")

    logging.info(f"Auto-synced client {reg_num} to plab_clients + ops_academic_details + documents")


def _sync_combined_sibling(main_reg_id, sibling_reg_id, ops_user_id):
    """Combined AMC Consulting + AMC 1: create the AMC 1 (Training) master using the
    SAME personal + academic info as the main reg (info is common — the client filled
    it once), but the sibling's OWN plan, package, installments and product/pathway."""
    try:
        conn = get_db()
        main = conn.execute("SELECT * FROM client_registrations WHERE id = ?", (main_reg_id,)).fetchone()
        sib = conn.execute('''SELECT cr.*, ps.name AS product_name FROM client_registrations cr
            LEFT JOIN products_services ps ON ps.id = cr.product_id WHERE cr.id = ?''', (sibling_reg_id,)).fetchone()
        if not main or not sib:
            conn.close()
            return
        merged = dict(main)  # personal + academics source = the main (AMC Consulting) reg
        # The sibling's own identity + commercials override the main's.
        for k in ('registration_number', 'product_id', 'product_name', 'plan_type',
                  'package_amount', 'discount_allowed', 'final_package', 'additional_notes',
                  'inst1_amount', 'inst1_date', 'inst1_note', 'inst2_amount', 'inst2_date', 'inst2_note',
                  'inst3_amount', 'inst3_date', 'inst3_note', 'inst4_amount', 'inst4_date', 'inst4_note'):
            if k in sib.keys():
                merged[k] = sib[k]
        merged['ops_verified_by'] = ops_user_id
        # Academics are looked up by the MAIN reg id (the client filled them once).
        _sync_to_plab_and_academics(conn, merged, main_reg_id)
        conn.commit()
        conn.close()
    except Exception as e:
        logging.error(f"_sync_combined_sibling(main={main_reg_id}, sib={sibling_reg_id}): {e}")


# ── ADMIN: Test-client data cleanup (purge everything tied to an email) ──
#
# One-time-safe maintenance tool so a test email can be reused for a clean run.
# Resolves the client across leads / invites / accounts / registrations / master,
# then removes every child + parent record. PREVIEW first (counts), delete only
# on explicit confirm. Admin-only. Shared DB — this affects live + staging.

_PURGE_BY_REG_ID = ['installment_approvals', 'client_academics', 'client_documents',
                    'client_agreements', 'client_doc_requests', 'client_notifications',
                    'client_welcome_kit']
_PURGE_BY_REG_NUM = ['ops_coaching', 'ops_english_logins', 'ops_test_bookings', 'ops_call_notes',
                     'ops_self_assessment', 'ops_eligibility_letter', 'ops_data_flow', 'ops_payments',
                     'ops_epic_registration', 'ops_gmc_registration', 'ops_amc_registration',
                     'ops_research_publication', 'ops_job_stage', 'ops_online_subscriptions',
                     'ops_webinars_conferences', 'ops_uk_visa_travel', 'ops_academic_details',
                     'ops_online_courses', 'ops_uk_observerships', 'ops_ngo_activities', 'ops_mentorship',
                     'ops_uk_cab_bookings', 'internal_transfers', 'refunds', 'client_onboarding']
_PURGE_BY_CLIENT_ID = ['plab_client_documents', 'scheduled_slots']
# Account-keyed rows. The refund-policy agreement is written with account_id only
# (registration_id stays NULL), so the by-registration_id pass never matches it and
# the signature would survive a purge. Sweep by account_id too.
_PURGE_BY_ACCOUNT_ID = ['client_agreements']


def _purge_collect_keys(conn, emails):
    """Resolve every id/number tied to these client emails."""
    emails = [e.strip().lower() for e in emails if e and e.strip()]
    if not emails:
        return None
    eph = ','.join(['?'] * len(emails))
    def ids(sql, params):
        try:
            return [r[list(r.keys())[0]] for r in conn.execute(sql, params).fetchall()]
        except Exception:
            return []
    lead_ids = ids(f"SELECT id FROM sales_leads WHERE LOWER(email) IN ({eph})", emails)
    account_ids = ids(f"SELECT id FROM client_accounts WHERE LOWER(email) IN ({eph})", emails)
    # The login account is keyed by MOBILE (unique), and its email can be blank or
    # differ from the registration's. Matching on email alone left the account
    # behind, and the next signup silently reused it — old password, old name, old
    # agreements. Also resolve accounts via the mobile on this email's records.
    _mobiles = set()
    for _sql in (f"SELECT mobile FROM client_registrations WHERE LOWER(email) IN ({eph})",
                 f"SELECT mobile FROM client_accounts WHERE LOWER(email) IN ({eph})"):
        for _m in ids(_sql, emails):
            _m = (_m or '').strip().lstrip('+').lstrip('0')
            if _m.startswith('91') and len(_m) == 12:
                _m = _m[2:]
            if _m:
                _mobiles.add(_m)
    if _mobiles:
        mph = ','.join(['?'] * len(_mobiles))
        account_ids += [i for i in ids(f"SELECT id FROM client_accounts WHERE mobile IN ({mph})",
                                       list(_mobiles)) if i not in account_ids]
    reg_where, reg_params = f"LOWER(email) IN ({eph})", list(emails)
    if account_ids:
        reg_where += f" OR account_id IN ({','.join(['?']*len(account_ids))})"
        reg_params += account_ids
    regs = []
    try:
        regs = conn.execute(f"SELECT id, registration_number FROM client_registrations WHERE {reg_where}", reg_params).fetchall()
    except Exception:
        pass
    reg_ids = [r['id'] for r in regs]
    reg_nums = set(r['registration_number'] for r in regs if r['registration_number'])
    plab_where, plab_params = f"LOWER(email) IN ({eph})", list(emails)
    if reg_nums:
        plab_where += f" OR registration_number IN ({','.join(['?']*len(reg_nums))})"
        plab_params += list(reg_nums)
    plabs = []
    try:
        plabs = conn.execute(f"SELECT id, registration_number FROM plab_clients WHERE {plab_where}", plab_params).fetchall()
    except Exception:
        pass
    plab_ids = [r['id'] for r in plabs]
    for r in plabs:
        if r['registration_number']:
            reg_nums.add(r['registration_number'])
    return {'emails': emails, 'lead_ids': lead_ids, 'account_ids': account_ids,
            'reg_ids': reg_ids, 'reg_nums': list(reg_nums), 'plab_ids': plab_ids}


def _purge_run(conn, keys, do_delete):
    """Count (and optionally delete) every record for the resolved keys.
    Commits per table so one missing table can't undo prior deletes."""
    report = []
    def op(table, col, values):
        if not values:
            return
        ph = ','.join(['?'] * len(values))
        try:
            n = conn.execute(f"SELECT COUNT(*) AS c FROM {table} WHERE {col} IN ({ph})", list(values)).fetchone()['c']
        except Exception:
            try: conn.rollback()
            except Exception: pass
            return
        if n:
            report.append((table, n))
            if do_delete:
                try:
                    conn.execute(f"DELETE FROM {table} WHERE {col} IN ({ph})", list(values))
                    conn.commit()
                except Exception as e:
                    logging.warning(f"purge delete {table}.{col}: {e}")
                    try: conn.rollback()
                    except Exception: pass
    for t in _PURGE_BY_REG_ID:
        op(t, 'registration_id', keys['reg_ids'])
    for t in _PURGE_BY_REG_NUM:
        op(t, 'registration_number', keys['reg_nums'])
    for t in _PURGE_BY_CLIENT_ID:
        op(t, 'client_id', keys['plab_ids'])
    # Must run before client_accounts is deleted below — otherwise these rows orphan.
    for t in _PURGE_BY_ACCOUNT_ID:
        op(t, 'account_id', keys['account_ids'])
    # Parents last
    op('plab_clients', 'id', keys['plab_ids'])
    op('client_registrations', 'id', keys['reg_ids'])
    op('client_accounts', 'id', keys['account_ids'])
    # client_invitations by email (case-insensitive)
    if keys['emails']:
        ph = ','.join(['?'] * len(keys['emails']))
        try:
            n = conn.execute(f"SELECT COUNT(*) AS c FROM client_invitations WHERE LOWER(client_email) IN ({ph})", keys['emails']).fetchone()['c']
            if n:
                report.append(('client_invitations', n))
                if do_delete:
                    conn.execute(f"DELETE FROM client_invitations WHERE LOWER(client_email) IN ({ph})", keys['emails']); conn.commit()
        except Exception:
            try: conn.rollback()
            except Exception: pass
    op('sales_closures', 'lead_id', keys['lead_ids'])
    op('sales_leads', 'id', keys['lead_ids'])
    return report


@app.route('/admin/maintenance/purge-client', methods=['GET', 'POST'])
@admin_required
def admin_purge_client():
    from flask import render_template_string
    emails_raw = (request.values.get('emails') or '').strip()
    emails = [e.strip() for e in emails_raw.replace(',', '\n').splitlines() if e.strip()]
    action = request.form.get('action', '')
    report, deleted = None, False
    if emails:
        conn = get_db()
        keys = _purge_collect_keys(conn, emails)
        if keys:
            do_delete = (request.method == 'POST' and action == 'delete')
            report = _purge_run(conn, keys, do_delete)
            deleted = do_delete
        conn.close()
    return render_template_string(_PURGE_HTML, emails_raw=emails_raw, emails=emails,
                                  default_emails="miraclesofkrish@gmail.com\nbigdaysquad@gmail.com",
                                  report=report, deleted=deleted, total=(sum(n for _, n in report) if report else 0))


@app.route('/admin/maintenance/reg-status', methods=['GET'])
@admin_required
def admin_reg_status():
    """Diagnostic: show a client's registrations with the exact fields the
    verification queues filter on, so we can see why a reg isn't appearing."""
    from flask import render_template_string
    email = (request.args.get('email') or 'miraclesofkrish@gmail.com').strip()
    rows = []
    if email:
        conn = get_db()
        try:
            rows = conn.execute('''SELECT cr.id, cr.registration_number AS reg, cr.first_name, cr.last_name,
                cr.email, cr.form_status, COALESCE(cr.sales_completed,0) AS sales_completed,
                cr.client_submitted_at, COALESCE(cr.ops_status,'') AS ops_status,
                cr.counsellor_id, cr.counsellor_name, cr.invitation_id, cr.created_at,
                cr.joined_stage, sc.name AS sales_by, inv.invited_by,
                iby.name AS invited_by_name,
                ps.name AS product_name, ps.pathway AS pathway
                FROM client_registrations cr
                LEFT JOIN products_services ps ON ps.id = cr.product_id
                LEFT JOIN employees sc ON sc.id = cr.sales_completed_by
                LEFT JOIN client_invitations inv ON inv.id = cr.invitation_id
                LEFT JOIN employees iby ON iby.id = inv.invited_by
                WHERE LOWER(cr.email) = LOWER(?) ORDER BY cr.id DESC''', (email,)).fetchall()
        except Exception as e:
            conn.close()
            return f"<pre>error: {e}</pre>"
        conn.close()
    def why(r):
        if r['form_status'] != 'submitted':
            return f"NOT in queue — form_status is '{r['form_status']}' (needs 'submitted')"
        if not r['client_submitted_at']:
            return "NOT in queue — client_submitted_at is NULL"
        if r['sales_completed'] == 1 and r['ops_status'] != 'verified':
            return "in OPS-VERIFY queue (sales done)"
        if r['sales_completed'] == 0:
            return "should be in SALES-FILL queue ✓"
        if r['ops_status'] == 'verified':
            return "fully verified (not in any queue)"
        return "?"
    trs = "".join(
        f"<tr><td>{r['id']}</td><td>{r['reg'] or '—'}</td><td>{(r['first_name'] or '')} {(r['last_name'] or '')}</td>"
        f"<td>{r['product_name'] or '—'}</td><td><b>{r['form_status']}</b></td><td>{r['sales_completed']}</td>"
        f"<td>{r['sales_by'] or '—'}</td>"
        f"<td>{'set' if r['client_submitted_at'] else '<b style=color:red>NULL</b>'}</td>"
        f"<td>{r['ops_status'] or '—'}</td><td>{r['joined_stage'] or '—'}</td>"
        f"<td>{r['counsellor_name'] or r['counsellor_id'] or '—'}</td>"
        f"<td>{r['invited_by_name'] or '—'}</td>"
        f"<td style='color:#0369a1'>{why(r)}</td></tr>"
        for r in rows)
    html = (f"<!doctype html><meta charset=utf-8><title>Reg status</title>"
            f"<body style='font-family:system-ui;padding:24px;color:#1e293b'>"
            f"<h2>Registration status &mdash; {email}</h2>"
            f"<form><input name=email value='{email}' style='padding:8px;width:320px'> "
            f"<button style='padding:8px 14px'>Check</button></form>"
            f"<p>{len(rows)} registration(s) found.</p>"
            f"<table border=1 cellpadding=6 cellspacing=0 style='border-collapse:collapse;font-size:13px'>"
            f"<tr style='background:#f1f5f9'><th>ID</th><th>Reg</th><th>Name</th><th>Product</th>"
            f"<th>form_status</th><th>sales_done</th><th>sales done by</th><th>client_submitted_at</th>"
            f"<th>ops_status</th><th>joined_stage</th><th>counsellor</th><th>invited by</th>"
            f"<th>Queue status</th></tr>{trs}</table></body>")
    return html


@app.route('/admin/maintenance/client-login-check', methods=['GET'])
@admin_required
def admin_client_login_check():
    """Read-only: why can a client not log in? Shows the login account for a mobile
    or email exactly as the login route looks it up. Never renders the password."""
    q = (request.args.get('q') or '').strip()
    clean = q.lstrip('+').lstrip('0')
    if clean.startswith('91') and len(clean) == 12:
        clean = clean[2:]
    rows, regs, note = [], [], ''
    if q:
        conn = get_db()
        try:
            rows = conn.execute(
                "SELECT id, mobile, email, first_name, last_name, COALESCE(is_active,0) AS is_active, "
                "last_login, created_at, (password_hash IS NOT NULL AND password_hash <> '') AS has_pw "
                "FROM client_accounts WHERE mobile = ? OR LOWER(email) = LOWER(?) ORDER BY id",
                (clean, q)).fetchall()
        except Exception as e:
            note = f'account lookup failed: {e}'
            conn.rollback()
        try:
            regs = conn.execute(
                "SELECT id, registration_number, account_id, mobile, email, form_status, current_step "
                "FROM client_registrations WHERE mobile = ? OR LOWER(email) = LOWER(?) ORDER BY id",
                (clean, q)).fetchall()
        except Exception:
            conn.rollback()
        conn.close()
    def esc(v):
        return '—' if v in (None, '') else str(v)
    arows = "".join(
        f"<tr><td>{r['id']}</td><td><b>{esc(r['mobile'])}</b></td><td>{esc(r['email'])}</td>"
        f"<td>{esc(r['first_name'])} {esc(r['last_name'])}</td>"
        f"<td>{'<b style=color:green>yes</b>' if r['is_active'] else '<b style=color:red>NO — login blocked</b>'}</td>"
        f"<td>{'yes' if r['has_pw'] else '<b style=color:red>NO</b>'}</td>"
        f"<td>{esc(r['last_login'])}</td><td>{esc(r['created_at'])}</td></tr>" for r in rows)
    rrows = "".join(
        f"<tr><td>{r['id']}</td><td>{esc(r['registration_number'])}</td><td>{esc(r['account_id'])}</td>"
        f"<td>{esc(r['mobile'])}</td><td>{esc(r['email'])}</td><td>{esc(r['form_status'])}</td>"
        f"<td>{esc(r['current_step'])}</td></tr>" for r in regs)
    verdict = ('<p style="color:#b91c1c"><b>No login account exists for that mobile/email.</b> '
               'The client must register again from their invitation link.</p>'
               if q and not rows else '')
    return (f"<!doctype html><meta charset=utf-8><title>Client login check</title>"
            f"<body style='font-family:system-ui;padding:24px;color:#1e293b'>"
            f"<h2>Client login check</h2>"
            f"<form><input name=q value='{q}' placeholder='mobile or email' style='padding:8px;width:320px'> "
            f"<button style='padding:8px 14px'>Check</button></form>"
            f"<p style='color:#64748b;font-size:13px'>Login matches on the 10-digit mobile"
            f"{(' — searching <b>' + clean + '</b>') if q else ''}. Passwords are never shown.</p>"
            f"{('<p style=color:#b91c1c>' + note + '</p>') if note else ''}{verdict}"
            f"<h3>Login accounts ({len(rows)})</h3>"
            f"<table border=1 cellpadding=6 cellspacing=0 style='border-collapse:collapse;font-size:13px'>"
            f"<tr style='background:#f1f5f9'><th>ID</th><th>mobile</th><th>email</th><th>name</th>"
            f"<th>is_active</th><th>password set</th><th>last_login</th><th>created</th></tr>{arows}</table>"
            f"<h3>Registrations ({len(regs)})</h3>"
            f"<table border=1 cellpadding=6 cellspacing=0 style='border-collapse:collapse;font-size:13px'>"
            f"<tr style='background:#f1f5f9'><th>ID</th><th>Reg</th><th>account_id</th><th>mobile</th>"
            f"<th>email</th><th>form_status</th><th>current_step</th></tr>{rrows}</table></body>")


@app.route('/admin/maintenance/employee-check', methods=['GET'])
@admin_required
def admin_employee_check():
    """Read-only: is a (deleted?) employee still present, and what data references
    an employee id that no longer exists (orphans we can recover)."""
    q = (request.args.get('q') or '').strip()
    conn = get_db()
    emps = []
    try:
        if q:
            emps = conn.execute(
                "SELECT id, name, emp_code, email, department, COALESCE(is_active,0) AS is_active "
                "FROM employees WHERE LOWER(name) LIKE LOWER(?) ORDER BY name", (f'%{q}%',)).fetchall()
        else:
            emps = conn.execute(
                "SELECT id, name, emp_code, email, department, COALESCE(is_active,0) AS is_active "
                "FROM employees ORDER BY COALESCE(is_active,0), name").fetchall()
    except Exception as e:
        conn.close(); return f"<pre>employees error: {e}</pre>"
    # Orphaned counsellor references: an employee id used on clients but no longer
    # present in employees — recoverable (we know the id + a name snapshot).
    orphans = []
    try:
        orphans = conn.execute('''
            SELECT emp_id, MAX(nm) AS name, COUNT(*) AS refs FROM (
              SELECT counsellor_id AS emp_id, counsellor_name AS nm FROM client_registrations WHERE counsellor_id IS NOT NULL
              UNION ALL
              SELECT counsellor_id, counsellor FROM plab_clients WHERE counsellor_id IS NOT NULL
            ) t WHERE emp_id NOT IN (SELECT id FROM employees) GROUP BY emp_id ORDER BY emp_id
        ''').fetchall()
    except Exception:
        orphans = []
    # Orphaned lead-owner / creator ids (ids only — leads keep no name snapshot).
    lead_orphans = []
    try:
        lead_orphans = conn.execute('''
            SELECT emp_id, COUNT(*) AS refs FROM (
              SELECT owner_employee_id AS emp_id FROM sales_leads WHERE owner_employee_id IS NOT NULL
              UNION ALL SELECT created_by FROM sales_leads WHERE created_by IS NOT NULL
            ) t WHERE emp_id NOT IN (SELECT id FROM employees) GROUP BY emp_id ORDER BY emp_id
        ''').fetchall()
    except Exception:
        lead_orphans = []
    conn.close()
    erows = "".join(
        f"<tr style='{'background:#fef2f2' if not e['is_active'] else ''}'>"
        f"<td>{e['id']}</td><td>{e['name']}</td><td>{e['emp_code'] or '—'}</td>"
        f"<td>{e['email'] or '—'}</td><td>{e['department'] or '—'}</td>"
        f"<td><b style='color:{'#16a34a' if e['is_active'] else '#dc2626'}'>{'Active' if e['is_active'] else 'INACTIVE'}</b></td></tr>"
        for e in emps)
    orows = "".join(f"<tr><td>{o['emp_id']}</td><td>{o['name'] or '(no name snapshot)'}</td><td>{o['refs']}</td></tr>" for o in orphans)
    lrows = "".join(f"<tr><td>{o['emp_id']}</td><td>{o['refs']}</td></tr>" for o in lead_orphans)
    html = (f"<!doctype html><meta charset=utf-8><title>Employee check</title>"
            f"<body style='font-family:system-ui;padding:24px;color:#1e293b'>"
            f"<h2>Employee check</h2>"
            f"<form><input name=q value='{q}' placeholder='search name e.g. Robin' style='padding:8px;width:260px'> "
            f"<button style='padding:8px 14px'>Search</button> <a href='?'>show all</a></form>"
            f"<h3>Employees ({len(emps)})</h3>"
            f"<table border=1 cellpadding=6 style='border-collapse:collapse;font-size:13px'>"
            f"<tr style='background:#f1f5f9'><th>ID</th><th>Name</th><th>Code</th><th>Email</th><th>Dept</th><th>Status</th></tr>{erows}</table>"
            f"<h3>Orphaned counsellor references — recoverable with name ({len(orphans)})</h3>"
            f"<p style='color:#64748b;font-size:13px'>An employee ID that clients still point to, but which no longer exists in the employees table = a deleted employee. Name is from a saved snapshot.</p>"
            f"<table border=1 cellpadding=6 style='border-collapse:collapse;font-size:13px'>"
            f"<tr style='background:#f1f5f9'><th>Missing Emp ID</th><th>Name (snapshot)</th><th># clients</th></tr>{orows or '<tr><td colspan=3>None</td></tr>'}</table>"
            f"<h3>Orphaned lead owner/creator IDs — ID only ({len(lead_orphans)})</h3>"
            f"<table border=1 cellpadding=6 style='border-collapse:collapse;font-size:13px'>"
            f"<tr style='background:#f1f5f9'><th>Missing Emp ID</th><th># leads</th></tr>{lrows or '<tr><td colspan=2>None</td></tr>'}</table>"
            f"</body>")
    return html


