@app.route('/admin/employee/<int:emp_id>/edit', methods=['GET', 'POST'])
@admin_required
def admin_employee_edit(emp_id):
    user = get_user()
    conn = get_db()

    employee = conn.execute('SELECT * FROM employees WHERE id = ?', (emp_id,)).fetchone()
    if not employee:
        flash('Employee not found', 'error')
        conn.close()
        return redirect(url_for('admin_dashboard'))

    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        email = request.form.get('email', '').strip()
        phone = request.form.get('phone', '').strip()
        dob = request.form.get('dob', '').strip()
        address = request.form.get('address', '').strip()
        department = request.form.get('department', '').strip()
        designation = request.form.get('designation', '').strip()
        joining_date = request.form.get('joining_date', '').strip()
        carry_forward = request.form.get('carry_forward', '0').strip()

        try:
            carry_forward = float(carry_forward)
        except ValueError:
            carry_forward = 0

        reporting_to = request.form.get('reporting_to', '').strip()
        reporting_to = int(reporting_to) if reporting_to else None

        emergency_contact_name = request.form.get('emergency_contact_name', '').strip()
        emergency_contact_phone = request.form.get('emergency_contact_phone', '').strip()
        emergency_contact_relation = request.form.get('emergency_contact_relation', '').strip()

        # Phase B — employment status / exit process. Anything other than
        # 'active' flips is_active=0 so the employee can no longer log in.
        employment_status = (request.form.get('employment_status') or 'active').strip().lower()
        is_active = 1 if employment_status == 'active' else 0
        if employment_status == 'active':
            # Re-activated / staying active — clear exit fields.
            last_working_day = None
            exit_reason = None
            exit_notes = None
        else:
            last_working_day = (request.form.get('last_working_day') or '').strip() or None
            exit_reason = (request.form.get('exit_reason') or '').strip() or None
            exit_notes = (request.form.get('exit_notes') or '').strip() or None

        conn.execute('''
            UPDATE employees
            SET name = ?, email = ?, phone = ?, dob = ?, address = ?, department = ?,
                designation = ?, joining_date = ?, carry_forward = ?, reporting_to = ?,
                emergency_contact_name = ?, emergency_contact_phone = ?, emergency_contact_relation = ?,
                employment_status = ?, is_active = ?, last_working_day = ?, exit_reason = ?, exit_notes = ?
            WHERE id = ?
        ''', (name, email, phone, dob, address, department, designation, joining_date, carry_forward,
              reporting_to, emergency_contact_name, emergency_contact_phone, emergency_contact_relation,
              employment_status, is_active, last_working_day, exit_reason, exit_notes, emp_id))
        conn.commit()
        conn.close()

        msg = 'Exit recorded — employee marked ' + employment_status if employment_status != 'active' else 'Employee updated successfully'
        flash(msg, 'success')
        return redirect(url_for('admin_employee_detail', emp_id=emp_id))

    # Get all active employees as potential managers (exclude the employee being edited)
    managers = conn.execute('SELECT id, name, emp_code FROM employees WHERE is_active = 1 AND id != ? ORDER BY name', (emp_id,)).fetchall()

    conn.close()

    departments = ['Sales', 'Operations', 'Marketing', 'Admin', 'Senior Management', 'HR', 'Management']

    return render_template('admin_employee_profile.html',
                         user=user,
                         employee=employee,
                         departments=departments,
                         managers=managers,
                    active_section='hr')

@app.route('/admin/employee/<int:emp_id>/upload-photo', methods=['POST'])
@admin_required
def admin_upload_photo(emp_id):
    conn = get_db()
    employee = conn.execute('SELECT * FROM employees WHERE id = ?', (emp_id,)).fetchone()
    if not employee:
        flash('Employee not found', 'error')
        conn.close()
        return redirect(url_for('admin_dashboard'))

    if 'photo' not in request.files:
        flash('No photo selected', 'error')
        conn.close()
        return redirect(url_for('admin_employee_edit', emp_id=emp_id))

    file = request.files['photo']
    if file.filename == '':
        flash('No photo selected', 'error')
        conn.close()
        return redirect(url_for('admin_employee_edit', emp_id=emp_id))

    if file and allowed_file(file.filename):
        ext = file.filename.rsplit('.', 1)[1].lower()
        filename = f"{employee['emp_code']}.{ext}"
        filepath = os.path.join(PHOTO_FOLDER, filename)

        # Remove old photos with different extensions
        for old_ext in ALLOWED_EXTENSIONS:
            old_path = os.path.join(PHOTO_FOLDER, f"{employee['emp_code']}.{old_ext}")
            if os.path.exists(old_path) and old_path != filepath:
                os.remove(old_path)

        file.save(filepath)

        # Update photo_url in database
        conn.execute('UPDATE employees SET photo_url = ? WHERE id = ?', (filename, emp_id))
        conn.commit()
        conn.close()

        flash('Photo uploaded successfully', 'success')
        return redirect(url_for('admin_employee_edit', emp_id=emp_id))
    else:
        flash('Invalid file type. Allowed: png, jpg, jpeg, gif, webp', 'error')
        conn.close()
        return redirect(url_for('admin_employee_edit', emp_id=emp_id))

@app.route('/admin/add-leave', methods=['GET', 'POST'])
@admin_required
def admin_add_leave():
    user = get_user()
    conn = get_db()

    employees = conn.execute("SELECT id, name FROM employees WHERE is_active = 1 AND emp_code != 'admin' ORDER BY name").fetchall()

    if request.method == 'POST':
        employee_id = request.form.get('employee_id', '').strip()
        leave_type = request.form.get('leave_type', '').strip()
        from_date = request.form.get('from_date', '').strip()
        to_date = request.form.get('to_date', '').strip()
        day_portion = request.form.get('day_portion', 'full').strip()
        last_day_portion = request.form.get('last_day_portion', 'full').strip()
        reason = request.form.get('reason', '').strip()

        if not employee_id or not leave_type or not from_date:
            flash('Required fields missing', 'error')
            return render_template('admin_add_leave.html', user=user, employees=employees,
                    active_section='hr')

        try:
            employee_id = int(employee_id)
        except ValueError:
            flash('Invalid input', 'error')
            return render_template('admin_add_leave.html', user=user, employees=employees,
                    active_section='hr')

        if leave_type not in ['annual', 'sick', 'casual']:
            flash('Invalid leave type', 'error')
            return render_template('admin_add_leave.html', user=user, employees=employees,
                    active_section='hr')

        if not to_date:
            to_date = from_date

        from_dt = datetime.strptime(from_date, '%Y-%m-%d')
        to_dt = datetime.strptime(to_date, '%Y-%m-%d')

        if to_dt < from_dt:
            flash('To date cannot be before from date', 'error')
            return render_template('admin_add_leave.html', user=user, employees=employees,
                    active_section='hr')

        holidays_db = {row['holiday_date'] for row in conn.execute('SELECT holiday_date FROM holidays').fetchall()}

        # Build working days list (skip weekends + holidays)
        leave_days = []
        current = from_dt
        while current <= to_dt:
            date_str = current.strftime('%Y-%m-%d')
            if current.weekday() < 5 and date_str not in holidays_db:
                leave_days.append(current)
            current += timedelta(days=1)

        if not leave_days:
            flash('No working days in the selected date range (weekends and holidays are excluded)', 'error')
            conn.close()
            return render_template('admin_add_leave.html', user=user, employees=employees,
                    active_section='hr')

        import uuid
        now_str = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        group_id = str(uuid.uuid4())[:12]
        total_days = 0
        wfh_adjusted = 0

        for i, day in enumerate(leave_days):
            date_str = day.strftime('%Y-%m-%d')
            is_single = (len(leave_days) == 1)
            is_last = (i == len(leave_days) - 1 and len(leave_days) > 1)

            if is_single:
                portion = day_portion if day_portion in ['full', 'first_half', 'second_half'] else 'full'
            elif is_last:
                portion = last_day_portion if last_day_portion in ['full', 'first_half', 'second_half'] else 'full'
            else:
                portion = 'full'

            day_val = 0.5 if portion in ['first_half', 'second_half'] else 1.0

            # Check for existing leave on this date
            existing = conn.execute('SELECT id FROM leave_records WHERE employee_id = ? AND leave_date = ? AND status != ?',
                                    (employee_id, date_str, 'rejected')).fetchone()
            if existing:
                flash(f'Employee already has a leave record for {date_str} — skipped', 'warning')
                continue

            # Auto-cancel overlapping WFH
            overlapping_wfh = conn.execute(
                "SELECT id, from_date, to_date FROM wfh_requests WHERE employee_id = ? AND status IN ('approved','pending') AND from_date <= ? AND to_date >= ?",
                (employee_id, date_str, date_str)).fetchall()
            for wfh in overlapping_wfh:
                conn.execute("UPDATE wfh_requests SET status = 'cancelled' WHERE id = ?", (wfh['id'],))
                wfh_adjusted += 1

            total_days += day_val
            conn.execute('''
                INSERT INTO leave_records (employee_id, leave_type, leave_date, days, day_portion, reason, status, approved_by, approved_at, created_at, leave_group_id)
                VALUES (?, ?, ?, ?, ?, ?, 'approved', ?, ?, ?, ?)
            ''', (employee_id, leave_type, date_str, day_val, portion, reason or '', user['id'], now_str, now_str, group_id))

        conn.commit()
        conn.close()

        msg = f'Leave added: {total_days:.1f} day(s) across {len(leave_days)} working day(s)'
        if wfh_adjusted:
            msg += f'. {wfh_adjusted} overlapping WFH request(s) auto-cancelled.'
        flash(msg, 'success')
        return redirect(url_for('admin_dashboard'))

    conn.close()

    return render_template('admin_add_leave.html', user=user, employees=employees,
                    active_section='hr')

@app.route('/admin/bulk-leave', methods=['GET', 'POST'])
@admin_required
def admin_bulk_leave():
    user = get_user()
    conn = get_db()

    employees = conn.execute("SELECT id, name FROM employees WHERE is_active = 1 AND emp_code != 'admin' ORDER BY name").fetchall()

    if request.method == 'POST':
        department = request.form.get('department', '').strip()
        leave_type = request.form.get('leave_type', '').strip()
        leave_date = request.form.get('leave_date', '').strip()
        days = request.form.get('days', '').strip()
        reason = request.form.get('reason', '').strip()

        if not department or not leave_type or not leave_date or not days:
            flash('All fields required', 'error')
            return render_template('admin_bulk_leave.html', user=user, employees=employees,
                    active_section='hr')

        try:
            days = float(days)
            if days <= 0:
                flash('Days must be positive', 'error')
                return render_template('admin_bulk_leave.html', user=user, employees=employees,
                    active_section='hr')
        except ValueError:
            flash('Invalid days value', 'error')
            return render_template('admin_bulk_leave.html', user=user, employees=employees,
                    active_section='hr')

        # Get all employees in department
        dept_employees = conn.execute('SELECT id FROM employees WHERE department = ? AND is_active = 1', (department,)).fetchall()

        import uuid
        count = 0
        for emp in dept_employees:
            group_id = str(uuid.uuid4())[:12]
            conn.execute('''
                INSERT INTO leave_records (employee_id, leave_type, leave_date, days, reason, status, approved_by, approved_at, created_at, leave_group_id)
                VALUES (?, ?, ?, ?, ?, 'approved', ?, ?, ?, ?)
            ''', (emp['id'], leave_type, leave_date, days, reason or '', user['id'], datetime.now().strftime('%Y-%m-%d %H:%M:%S'), datetime.now().strftime('%Y-%m-%d %H:%M:%S'), group_id))
            count += 1

        conn.commit()
        conn.close()

        flash(f'Added leave for {count} employees', 'success')
        return redirect(url_for('admin_dashboard'))

    conn.close()

    departments = ['Sales', 'Operations', 'Marketing', 'Admin', 'Senior Management', 'HR', 'Management']

    return render_template('admin_bulk_leave.html', user=user, employees=employees, departments=departments,
                    active_section='hr')

@app.route('/admin/manage-employees', methods=['GET', 'POST'])
@admin_required
def manage_employees():
    user = get_user()
    conn = get_db()

    if request.method == 'POST':
        name = request.form.get('name', '').strip()
        emp_code = request.form.get('emp_code', '').strip()
        email = request.form.get('email', '').strip()
        department = request.form.get('department', '').strip()
        # Phase A lifecycle fields. Default behaviour preserved -- if
        # the user submits no employment_status, treat as active.
        employment_status = (request.form.get('employment_status') or 'active').strip().lower()
        joining_date = (request.form.get('joining_date') or '').strip() or datetime.now().strftime('%Y-%m-%d')
        last_working_day = (request.form.get('last_working_day') or '').strip() or None
        exit_reason = (request.form.get('exit_reason') or '').strip() or None
        exit_notes = (request.form.get('exit_notes') or '').strip() or None

        if not name or not emp_code or not department:
            flash('Required fields missing', 'error')
            return redirect(url_for('manage_employees'))

        # Check if emp_code already exists
        existing = conn.execute('SELECT id FROM employees WHERE emp_code = ?', (emp_code,)).fetchone()
        if existing:
            flash('Employee code already exists', 'error')
            return redirect(url_for('manage_employees'))

        # Non-active employment_status flips is_active=0 so login is
        # blocked + per-section access checks fail safely.
        is_active = 1 if employment_status == 'active' else 0

        conn.execute('''
            INSERT INTO employees (
                name, emp_code, password, department, email,
                is_active, joining_date, created_at,
                employment_status, last_working_day, exit_reason, exit_notes
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ''', (
            name, emp_code,
            hash_password(name.split()[0].lower()),
            department, email or None,
            is_active,
            joining_date,
            datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
            employment_status, last_working_day, exit_reason, exit_notes,
        ))
        conn.commit()

        label = 'Past employee added' if employment_status != 'active' else 'Employee added successfully'
        flash(label, 'success')
        return redirect(url_for('manage_employees', show=request.form.get('return_to') or 'active'))

    # Filter view: ?show=active | past | all  (default = active)
    show = (request.args.get('show') or 'active').strip().lower()
    if show == 'past':
        emp_filter = "COALESCE(employment_status,'active') != 'active'"
    elif show == 'all':
        emp_filter = "1=1"
    else:
        show = 'active'
        emp_filter = "(COALESCE(employment_status,'active') = 'active' OR is_active = 1)"

    employees = conn.execute(
        f"SELECT * FROM employees WHERE {emp_filter} AND emp_code != 'admin' "
        f"ORDER BY department, name"
    ).fetchall()

    # Counts for the tab badges -- always shows totals regardless of
    # which tab is active.
    counts = {
        'active': conn.execute(
            "SELECT COUNT(*) AS c FROM employees WHERE COALESCE(employment_status,'active') = 'active' AND emp_code != 'admin'"
        ).fetchone()['c'],
        'past': conn.execute(
            "SELECT COUNT(*) AS c FROM employees WHERE COALESCE(employment_status,'active') != 'active' AND emp_code != 'admin'"
        ).fetchone()['c'],
    }
    counts['all'] = counts['active'] + counts['past']

    # Group employees by department
    dept_employees = {}
    for emp in employees:
        dept = emp['department'] or 'Unassigned'
        if dept not in dept_employees:
            dept_employees[dept] = []
        dept_employees[dept].append(emp)

    conn.close()

    departments = ['Sales', 'Operations', 'Marketing', 'Admin', 'Senior Management', 'HR', 'Management']

    return render_template('manage_employees.html',
                         user=user,
                         employees=employees,
                         dept_employees=dept_employees,
                         departments=departments,
                         show=show,
                         counts=counts,
                    active_section='hr')

@app.route('/admin/delete-employee/<int:emp_id>', methods=['POST'])
@admin_required
def delete_employee(emp_id):
    conn = get_db()

    employee = conn.execute('SELECT * FROM employees WHERE id = ?', (emp_id,)).fetchone()
    if not employee:
        flash('Employee not found', 'error')
        conn.close()
        return redirect(url_for('manage_employees'))

    # Soft-deactivate — do NOT hard-delete. Permanently removing an employee
    # orphans their leads, clients, counsellor links and sales history (and can
    # break attribution). Deactivating keeps all history intact and just hides
    # them from active lists/dropdowns.
    conn.execute('UPDATE employees SET is_active = 0 WHERE id = ?', (emp_id,))
    try:
        conn.execute('UPDATE sales_team SET is_active = 0 WHERE employee_id = ?', (emp_id,))
    except Exception:
        pass
    conn.commit()
    conn.close()

    flash(f'Employee {employee["name"]} has been deactivated (all history kept). '
          f'They no longer appear in active lists or dropdowns.', 'success')
    return redirect(url_for('manage_employees'))


@app.route('/admin/reset-passwords', methods=['GET', 'POST'])
@admin_required
def admin_reset_passwords():
    """Admin-only password reset for any user. Restricted to emp_code='admin'."""
    user = get_user()
    # Extra check: only the admin account, not management
    if user['emp_code'] != 'admin':
        flash('Only the admin account can reset passwords', 'error')
        return redirect(url_for('dashboard'))

    conn = get_db()

    if request.method == 'POST':
        emp_id = request.form.get('emp_id', type=int)
        new_password = request.form.get('new_password', '').strip()
        confirm_password = request.form.get('confirm_password', '').strip()

        if not emp_id or not new_password:
            flash('Please select an employee and enter a new password', 'error')
        elif len(new_password) < 4:
            flash('Password must be at least 4 characters', 'error')
        elif new_password != confirm_password:
            flash('Passwords do not match', 'error')
        else:
            emp = conn.execute('SELECT id, name, emp_code FROM employees WHERE id = ?', (emp_id,)).fetchone()
            if not emp:
                flash('Employee not found', 'error')
            else:
                conn.execute('UPDATE employees SET password = ? WHERE id = ?',
                             (hash_password(new_password), emp_id))
                conn.commit()
                flash(f'Password reset successfully for {emp["name"]} ({emp["emp_code"]})', 'success')

    employees = conn.execute(
        "SELECT id, name, emp_code, department, is_active FROM employees WHERE emp_code != 'admin' ORDER BY is_active DESC, department, name"
    ).fetchall()
    conn.close()

    return render_template('admin_reset_passwords.html', user=user, employees=employees,
                    active_section='company')


@app.route('/admin/delete-leave/<int:leave_id>', methods=['POST'])
@admin_required
def delete_leave(leave_id):
    conn = get_db()

    # Support group delete via ?group_id=xxx
    group_id = request.args.get('group_id', '').strip()

    if group_id and not group_id.startswith('single_'):
        # Delete entire group
        deleted = conn.execute('DELETE FROM leave_records WHERE leave_group_id = ?', (group_id,)).rowcount
        conn.commit()
        conn.close()
        flash(f'{deleted} leave record(s) deleted', 'success')
        return redirect(request.referrer or url_for('admin_dashboard'))

    leave = conn.execute('SELECT * FROM leave_records WHERE id = ?', (leave_id,)).fetchone()
    if not leave:
        flash('Leave not found', 'error')
        conn.close()
        return redirect(url_for('admin_dashboard'))

    conn.execute('DELETE FROM leave_records WHERE id = ?', (leave_id,))
    conn.commit()
    conn.close()

    flash('Leave record deleted', 'success')
    return redirect(request.referrer or url_for('admin_dashboard'))

@app.route('/admin/monthly-report')
@admin_required
def admin_monthly_report():
    user = get_user()
    year = int(request.args.get('year', datetime.now().year))
    month = int(request.args.get('month', datetime.now().month))

    conn = get_db()
    employees = conn.execute("SELECT * FROM employees WHERE is_active = 1 AND emp_code != 'admin' ORDER BY name").fetchall()

    report_data = []
    for emp in employees:
        # Per-month figures under the accrual+accumulation rule: this month's
        # allocation + accumulated surplus (deficit never carries) − taken;
        # excess is the salary deduction. See leave_month_figures().
        fig = leave_month_figures(emp['id'], year, month)
        report_data.append({
            'name': emp['name'],
            'emp_code': emp['emp_code'],
            'department': emp['department'],
            'monthly_allocation': fig['monthly_alloc'],
            'balance_start': round(fig['balance_start'], 2),
            'balance_available': round(fig['balance_available'], 2),
            'days_taken': round(fig['days_taken'], 2),
            'deduction': round(fig['deduction'], 2)
        })

    conn.close()

    month_name = calendar.month_name[month]

    return render_template('admin_monthly_report.html',
                         user=user,
                         year=year,
                         month=month,
                         month_name=month_name,
                         report_data=report_data,
                    active_section='hr')

@app.route('/admin/monthly-report/download')
@admin_required
def admin_monthly_report_download():
    year = int(request.args.get('year', datetime.now().year))
    month = int(request.args.get('month', datetime.now().month))
    file_format = request.args.get('format', 'xlsx')

    conn = get_db()
    employees = conn.execute("SELECT * FROM employees WHERE is_active = 1 AND emp_code != 'admin' ORDER BY name").fetchall()

    if file_format == 'xlsx':
        wb = Workbook()
        ws = wb.active
        ws.title = f"Leave Report {month}-{year}"

        # Headers
        headers = ['Name', 'Employee Code', 'Department', 'Monthly Allocation', 'Balance Start', 'Balance Available', 'Days Taken', 'Salary Deduction']
        ws.append(headers)

        # Style headers
        header_fill = PatternFill(start_color='1a56db', end_color='1a56db', fill_type='solid')
        header_font = Font(bold=True, color='FFFFFF')

        for cell in ws[1]:
            cell.fill = header_fill
            cell.font = header_font
            cell.alignment = Alignment(horizontal='center', vertical='center')

        # Data — same accrual+accumulation rule as the on-screen report.
        for emp in employees:
            fig = leave_month_figures(emp['id'], year, month)
            ws.append([
                emp['name'],
                emp['emp_code'],
                emp['department'],
                fig['monthly_alloc'],
                round(fig['balance_start'], 2),
                round(fig['balance_available'], 2),
                round(fig['days_taken'], 2),
                round(fig['deduction'], 2)
            ])

        # Adjust column widths
        ws.column_dimensions['A'].width = 20
        ws.column_dimensions['B'].width = 15
        ws.column_dimensions['C'].width = 18
        ws.column_dimensions['D'].width = 16
        ws.column_dimensions['E'].width = 14
        ws.column_dimensions['F'].width = 17
        ws.column_dimensions['G'].width = 12
        ws.column_dimensions['H'].width = 17

        output = BytesIO()
        wb.save(output)
        output.seek(0)

        conn.close()

        return send_file(
            output,
            mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            as_attachment=True,
            download_name=f'Leave_Report_{month}_{year}.xlsx'
        )

    conn.close()
    flash('Invalid format', 'error')
    return redirect(url_for('admin_monthly_report', year=year, month=month))

