# ─── Admin Employee Leave Report (select any employee) ───
@app.route('/admin/employee-leave-report')
@admin_required
def admin_employee_leave_report():
    user = get_user()
    conn = get_db()

    employees = conn.execute("SELECT id, name, emp_code, department FROM employees WHERE is_active = 1 AND emp_code != 'admin' ORDER BY name").fetchall()

    selected_emp_id = request.args.get('employee_id', type=int)
    selected_emp = None
    monthly_leave_data = []
    all_leaves = []
    total_allocation = 0
    total_taken = 0
    annual_total = 0
    sick_total = 0
    casual_total = 0
    total_deduction = 0
    available_balance = 0
    current_carry = 0
    type_balances = {'annual': 0, 'sick': 0, 'casual': 0}
    type_alloc = {'annual': 0, 'sick': 0, 'casual': 0}
    pending_count = 0
    carry_forward = 0
    monthly_alloc = 'Apr=3, Others=2'

    today = datetime.now()
    current_month = today.month
    fy_year = today.year if current_month >= 4 else today.year - 1

    if selected_emp_id:
        selected_emp = conn.execute('SELECT * FROM employees WHERE id = ?', (selected_emp_id,)).fetchone()
        if selected_emp:
            carry_forward = selected_emp['carry_forward'] or 0
            total_allocation = 25 + carry_forward

            pending_count = conn.execute(
                "SELECT COUNT(*) as cnt FROM leave_records WHERE employee_id = ? AND status = 'pending'",
                (selected_emp_id,)
            ).fetchone()['cnt']

            # Rule: each month's allocation + accumulated surplus − taken;
            # deficit never carries (floored at 0), surplus accumulates; the
            # excess taken in a month is that month's deduction (LOP).
            running_balance = float(carry_forward or 0)  # accumulated surplus (>= 0)
            current_available = running_balance
            for m in range(12):
                report_month = ((m + 3) % 12) + 1
                report_year = fy_year if report_month >= 4 else fy_year + 1
                m_alloc = get_monthly_alloc(report_month)

                month_data = conn.execute('''
                    SELECT SUM(days) as total_days,
                           SUM(CASE WHEN leave_type = 'annual' THEN days ELSE 0 END) as annual,
                           SUM(CASE WHEN leave_type = 'sick' THEN days ELSE 0 END) as sick,
                           SUM(CASE WHEN leave_type = 'casual' THEN days ELSE 0 END) as casual,
                           COUNT(*) as count
                    FROM leave_records
                    WHERE employee_id = ? AND status = 'approved'
                    AND strftime('%Y', leave_date) = ? AND strftime('%m', leave_date) = ?
                ''', (selected_emp_id, str(report_year), str(report_month).zfill(2))).fetchone()

                month_total = month_data['total_days'] or 0
                available_this = running_balance + m_alloc
                deduction = max(0.0, month_total - available_this)
                running_balance = round(max(0.0, available_this - month_total), 2)  # deficit never carries
                if (report_year, report_month) <= (today.year, current_month):
                    current_available = running_balance

                monthly_leave_data.append({
                    'month': calendar.month_name[report_month],
                    'month_short': calendar.month_abbr[report_month],
                    'year': report_year,
                    'total': month_total,
                    'annual': month_data['annual'] or 0,
                    'sick': month_data['sick'] or 0,
                    'casual': month_data['casual'] or 0,
                    'count': month_data['count'] or 0,
                    'monthly_alloc': m_alloc,
                    'deduction': round(deduction, 2),
                    'balance': running_balance
                })

            all_leaves_raw = conn.execute('''
                SELECT *, leave_group_id FROM leave_records
                WHERE employee_id = ?
                AND ((strftime('%Y', leave_date) = ? AND strftime('%m', leave_date) >= '04')
                     OR (strftime('%Y', leave_date) = ? AND strftime('%m', leave_date) < '04'))
                ORDER BY leave_date DESC
            ''', (selected_emp_id, str(fy_year), str(fy_year + 1))).fetchall()

            from collections import OrderedDict
            all_groups = OrderedDict()
            for r in all_leaves_raw:
                d = dict(r)
                gid = d.get('leave_group_id') or f"single_{d['id']}"
                if gid not in all_groups:
                    all_groups[gid] = {
                        **d,
                        'group_id': gid,
                        'group_ids': [d['id']],
                        'group_total_days': d['days'],
                        'group_count': 1,
                        'date_from': d['leave_date'],
                        'date_to': d['leave_date'],
                    }
                else:
                    g = all_groups[gid]
                    g['group_ids'].append(d['id'])
                    g['group_total_days'] += d['days']
                    g['group_count'] += 1
                    if d['leave_date'] < g['date_from']:
                        g['date_from'] = d['leave_date']
                    if d['leave_date'] > g['date_to']:
                        g['date_to'] = d['leave_date']
            all_leaves = list(all_groups.values())

            total_taken = sum(m['total'] for m in monthly_leave_data)
            annual_total = sum(m['annual'] for m in monthly_leave_data)
            sick_total = sum(m['sick'] for m in monthly_leave_data)
            casual_total = sum(m['casual'] for m in monthly_leave_data)
            total_deduction = round(sum(m['deduction'] for m in monthly_leave_data), 2)
            # Leave balance = entitlement − PAID leaves taken (deducted days were
            # charged to salary and don't reduce the paid-leave balance).
            available_balance = round(total_allocation - (total_taken - total_deduction), 2)
            current_carry = round(current_available, 2)
            # Per-type balances (Annual/Sick/Casual) summing to available_balance.
            _tb = leave_type_balances(selected_emp_id, fy_year)
            type_balances = _tb['balance']
            type_alloc = _tb['alloc']

    conn.close()

    return render_template('admin_employee_leave_report.html',
                         user=user,
                         employees=employees,
                         selected_emp=selected_emp,
                         selected_emp_id=selected_emp_id,
                         monthly_leave_data=monthly_leave_data,
                         all_leaves=all_leaves,
                         fy_year=fy_year,
                         total_allocation=total_allocation,
                         total_taken=total_taken,
                         annual_total=annual_total,
                         sick_total=sick_total,
                         casual_total=casual_total,
                         total_deduction=total_deduction,
                         available_balance=available_balance,
                         current_carry=current_carry,
                         type_balances=type_balances, type_alloc=type_alloc,
                         pending_count=pending_count,
                         carry_forward=carry_forward,
                         monthly_alloc=monthly_alloc,
                    active_section='hr')


