@app.route('/b2b/meeting/<int:meeting_id>/edit', methods=['POST'])
@login_required
@sales_access_required
def edit_b2b_meeting_save(meeting_id):
    """Save edits with an audit trail + spawn a linked follow-up meeting.

    When a NEW follow-up date is scheduled (different from what was there
    before), we create a child b2b_meetings row carrying forward the same
    school/partner context, so the follow-up keeps its lineage.
    """
    user = get_user()
    conn = get_db()
    meeting = conn.execute('SELECT * FROM b2b_meetings WHERE id = ?', (meeting_id,)).fetchone()
    if not meeting:
        flash('Meeting not found', 'error')
        conn.close()
        return redirect(url_for('b2b_trips_list'))

    old = dict(meeting)

    def g(k):
        return (request.form.get(k) or '').strip()

    new_vals = {
        'meeting_date':       g('meeting_date') or None,
        'meeting_time':       g('meeting_time') or None,
        'contact_type':       g('contact_type') or None,
        'status':             g('status') or None,
        'notes':              g('notes') or None,
        'contact_person':     g('contact_person') or None,
        'contact_phone':      g('contact_phone') or None,
        'next_followup_date': g('next_followup_date') or None,
        'next_followup_note': g('next_followup_note') or None,
    }
    handler_raw = g('handler_employee_id')
    new_vals['handler_employee_id'] = int(handler_raw) if handler_raw.isdigit() else old.get('handler_employee_id')

    old_followup = old.get('next_followup_date') or None
    new_followup = new_vals['next_followup_date']
    # A genuinely new follow-up was scheduled (set + changed from before).
    spawn_followup = bool(new_followup) and (str(new_followup) != str(old_followup or ''))

    # Audit each changed field.
    for field, new_val in new_vals.items():
        old_val = old.get(field)
        if str(old_val if old_val is not None else '') != str(new_val if new_val is not None else ''):
            conn.execute(
                "INSERT INTO b2b_meeting_audit (meeting_id, field, old_value, new_value, changed_by) "
                "VALUES (?, ?, ?, ?, ?)",
                (meeting_id,
                 field,
                 str(old_val) if old_val is not None else None,
                 str(new_val) if new_val is not None else None,
                 user['id'])
            )

    if spawn_followup:
        # The parent's follow-up has been actioned into a child row, so
        # clear it on the parent (cleaner — avoids double-counting in the
        # follow-ups-due card).
        parent_followup_to_store = None
    else:
        parent_followup_to_store = new_followup

    conn.execute(
        "UPDATE b2b_meetings SET "
        "  meeting_date = ?, meeting_time = ?, contact_type = ?, status = ?, "
        "  notes = ?, contact_person = ?, contact_phone = ?, "
        "  next_followup_date = ?, next_followup_note = ?, handler_employee_id = ? "
        "WHERE id = ?",
        (new_vals['meeting_date'], new_vals['meeting_time'], new_vals['contact_type'],
         new_vals['status'], new_vals['notes'], new_vals['contact_person'],
         new_vals['contact_phone'], parent_followup_to_store,
         new_vals['next_followup_note'], new_vals['handler_employee_id'], meeting_id)
    )

    if spawn_followup:
        # Create the carried-forward follow-up meeting as a child row.
        conn.execute(
            "INSERT INTO b2b_meetings "
            "(trip_id, meeting_type_id, meeting_with, entity_id, project_id, location, "
            " contact_person, contact_phone, handler_employee_id, "
            " meeting_date, status, notes, next_followup_date, parent_meeting_id) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'Follow up', ?, NULL, ?)",
            (old.get('trip_id'), old.get('meeting_type_id'), old.get('meeting_with'),
             old.get('entity_id'), old.get('project_id'), old.get('location'),
             new_vals['contact_person'], new_vals['contact_phone'],
             new_vals['handler_employee_id'],
             new_followup, new_vals['next_followup_note'], meeting_id)
        )

    conn.commit()
    conn.close()
    flash('Meeting updated' + (' — follow-up scheduled' if spawn_followup else ''), 'success')
    return redirect(url_for('b2b_trip_detail', trip_id=old.get('trip_id')))


# ─── Meeting Types Management (Admin) ───

@app.route('/admin/meeting-types', methods=['GET', 'POST'])
@admin_required
def manage_meeting_types():
    user = get_user()
    conn = get_db()

    if request.method == 'POST':
        action = request.form.get('action')
        if action == 'add':
            name = request.form.get('name', '').strip()
            if name:
                conn.execute('INSERT INTO meeting_types (name) VALUES (?)', (name,))
                conn.commit()
                flash('Meeting type added', 'success')
        elif action == 'toggle':
            mt_id = request.form.get('id')
            conn.execute('UPDATE meeting_types SET is_active = CASE WHEN is_active = 1 THEN 0 ELSE 1 END WHERE id = ?', (mt_id,))
            conn.commit()
            flash('Meeting type updated', 'success')
        elif action == 'delete':
            mt_id = request.form.get('id')
            conn.execute('DELETE FROM meeting_types WHERE id = ?', (mt_id,))
            conn.commit()
            flash('Meeting client type deleted', 'success')
        conn.close()
        return redirect(url_for('manage_meeting_types'))

    types = conn.execute('SELECT * FROM meeting_types ORDER BY name').fetchall()
    conn.close()
    return render_template('manage_meeting_types.html', user=user, types=types, page_title='Meeting Client Types',
                    active_section='sales')


# ─── Module Access Management (Admin) ───

@app.route('/admin/module-access', methods=['GET', 'POST'])
@admin_required
def manage_module_access():
    user = get_user()
    conn = get_db()

    if request.method == 'POST':
        action = request.form.get('action')

        if action == 'grant':
            employee_ids = request.form.getlist('employee_ids')
            modules = request.form.getlist('modules')
            # access_level only meaningful for sales. 'standard' or 'admin_view'.
            raw_level = (request.form.get('access_level') or 'standard').strip().lower()
            sales_level = 'admin_view' if raw_level == 'admin_view' else 'standard'
            if employee_ids and modules:
                for emp_id in employee_ids:
                    for module in modules:
                        level = sales_level if module == 'sales' else 'standard'
                        conn.execute('''
                            INSERT INTO module_access (employee_id, module, granted_by, is_active, access_level)
                            VALUES (?, ?, ?, 1, ?)
                            ON CONFLICT (employee_id, module) DO UPDATE SET is_active = 1, granted_by = ?, access_level = ?
                        ''', (emp_id, module, user['id'], level, user['id'], level))
                conn.commit()
                flash(f'Access granted to {len(employee_ids)} employee(s) for {len(modules)} module(s)', 'success')
            else:
                flash('Please select at least one employee and one module', 'error')

        elif action == 'toggle':
            access_id = request.form.get('access_id')
            new_status = request.form.get('new_status', '1')
            if access_id:
                conn.execute('UPDATE module_access SET is_active = ? WHERE id = ?', (int(new_status), access_id))
                conn.commit()
                flash('Access status updated', 'success')

        elif action == 'set_level':
            # Flip access_level between 'standard' and 'admin_view' (sales only).
            access_id = request.form.get('access_id')
            new_level = (request.form.get('new_level') or 'standard').strip().lower()
            if new_level not in ('standard', 'admin_view'):
                new_level = 'standard'
            if access_id:
                conn.execute(
                    "UPDATE module_access SET access_level = ? WHERE id = ? AND module = 'sales'",
                    (new_level, access_id)
                )
                conn.commit()
                flash('Access level updated', 'success')

        elif action == 'revoke':
            access_id = request.form.get('access_id')
            if access_id:
                conn.execute('DELETE FROM module_access WHERE id = ?', (access_id,))
                conn.commit()
                flash('Access revoked', 'success')

        conn.close()
        return redirect(url_for('manage_module_access'))

    employees = conn.execute("SELECT id, name, emp_code, department, photo_url FROM employees WHERE is_active = 1 AND emp_code != 'admin' ORDER BY name").fetchall()
    access_list = conn.execute('''
        SELECT ma.id as access_id, ma.employee_id, ma.module, ma.is_active,
               COALESCE(ma.access_level, 'standard') as access_level, ma.created_at,
               e.name, e.emp_code, e.department, e.photo_url,
               g.name as granted_by_name
        FROM module_access ma
        JOIN employees e ON ma.employee_id = e.id
        LEFT JOIN employees g ON ma.granted_by = g.id
        ORDER BY e.name, ma.module
    ''').fetchall()

    modules = ['sales', 'projects', 'b2b_meetings']
    conn.close()
    return render_template('manage_module_access.html', user=user, employees=employees,
                         access_list=access_list, modules=modules,
                    active_section='sales')


def ensure_management_admins():
    """Ensure MANAGEMENT_CODES employees always have is_admin = 1."""
    try:
        conn = get_db()
        for code in MANAGEMENT_CODES:
            conn.execute('UPDATE employees SET is_admin = 1 WHERE emp_code = ? AND is_admin = 0', (code,))
        conn.commit()
        conn.close()
    except Exception as e:
        logging.error(f"ensure_management_admins: {e}")

# ─── Leave Applications (All) ─── Admin / Management view ───
@app.route('/admin/leave-applications')
@login_required
@admin_required
def admin_leave_applications():
    user = get_user()
    conn = get_db()

    # Read filter params
    f_employee = request.args.get('employee', '').strip()
    f_type = request.args.get('leave_type', '').strip()
    f_status = request.args.get('status', '').strip()
    f_from = request.args.get('from_date', '').strip()
    f_to = request.args.get('to_date', '').strip()

    # Build query
    query = '''
        SELECT lr.id, lr.employee_id, lr.leave_type, lr.leave_date, lr.days,
               lr.day_portion, lr.reason, lr.status, lr.is_late,
               lr.original_id, lr.modification_reason, lr.original_reason,
               lr.approved_by, lr.approved_at, lr.created_at,
               lr.leave_group_id,
               e.name        AS employee_name,
               e.emp_code    AS emp_code,
               e.department  AS department,
               e.designation AS designation,
               e.email       AS email,
               e.phone       AS mobile,
               e.photo_url   AS photo_url,
               a.name        AS approver_name
        FROM leave_records lr
        JOIN employees e ON lr.employee_id = e.id
        LEFT JOIN employees a ON lr.approved_by = a.id
        WHERE 1=1
    '''
    params = []

    if f_employee:
        query += " AND (LOWER(e.name) LIKE LOWER(?) OR LOWER(e.emp_code) LIKE LOWER(?))"
        params.extend([f'%{f_employee}%', f'%{f_employee}%'])
    if f_type:
        query += " AND lr.leave_type = ?"
        params.append(f_type)
    if f_status:
        query += " AND lr.status = ?"
        params.append(f_status)
    if f_from:
        query += " AND lr.leave_date >= ?"
        params.append(f_from)
    if f_to:
        query += " AND lr.leave_date <= ?"
        params.append(f_to)

    query += " ORDER BY lr.leave_date DESC, lr.created_at DESC"

    leaves_raw = conn.execute(query, params).fetchall()

    # Enrich rows
    enriched = []
    for r in leaves_raw:
        d = dict(r)
        p = d.get('photo_url') or ''
        d['photo_src'] = (p if p.startswith('http') else f'/static/photos/{p}') if p else ''
        raw = d.get('reason') or ''
        if '[Late Application Reason]:' in raw:
            parts = raw.split('\n\n[Late Application Reason]:', 1)
            d['reason_main'] = parts[0].strip()
            d['late_reason'] = parts[1].strip() if len(parts) > 1 else ''
        else:
            d['reason_main'] = raw
            d['late_reason'] = ''
        enriched.append(d)

    # Group by leave_group_id for display
    from collections import OrderedDict
    groups = OrderedDict()
    for d in enriched:
        gid = d.get('leave_group_id') or f"single_{d['id']}"
        if gid not in groups:
            groups[gid] = {
                **d,
                'group_id': gid,
                'group_ids': [d['id']],
                'group_dates': [d['leave_date']],
                'group_total_days': d['days'],
                'group_count': 1,
                'date_from': d['leave_date'],
                'date_to': d['leave_date'],
            }
        else:
            g = groups[gid]
            g['group_ids'].append(d['id'])
            g['group_dates'].append(d['leave_date'])
            g['group_total_days'] += d['days']
            g['group_count'] += 1
            if d['leave_date'] < g['date_from']:
                g['date_from'] = d['leave_date']
            if d['leave_date'] > g['date_to']:
                g['date_to'] = d['leave_date']
    leaves = list(groups.values())

    # Get employee list for filter dropdown
    employees = conn.execute(
        "SELECT id, name, emp_code FROM employees WHERE is_active = 1 AND emp_code != 'admin' ORDER BY name"
    ).fetchall()

    # Summary counts (on grouped entries)
    total = len(leaves)
    pending_count = sum(1 for l in leaves if l['status'] == 'pending')
    approved_count = sum(1 for l in leaves if l['status'] == 'approved')
    rejected_count = sum(1 for l in leaves if l['status'] == 'rejected')

    conn.close()
    today_str = datetime.now().strftime('%Y-%m-%d')
    return render_template('admin_leave_applications.html',
        user=user, leaves=leaves, employees=employees,
        total=total, pending_count=pending_count,
        approved_count=approved_count, rejected_count=rejected_count,
        f_employee=f_employee, f_type=f_type, f_status=f_status,
        f_from=f_from, f_to=f_to, today=today_str,
                    active_section='hr')


