@app.route('/operations/vendors-providers')
@login_required
def ops_vendors_providers():
    """Vendors & Providers management page.

    Pathway-aware via ?pathway= query param. Vendors are already scoped by
    the legacy `country` column (values like 'UK Pathway', 'Australia
    Pathway') — we just translate the pathway slug to the matching country
    label and filter. Default (no param) shows ALL vendors.
    """
    pathway = (request.args.get('pathway') or '').strip().lower()
    PATHWAY_TO_COUNTRY = {
        'plab':       'UK Pathway',
        'australia':  'AMC Pathway',
        'usmle':      'USMLE Pathway',
        'germany':    'Germany Pathway',
        # X-4d: consulting added so its sidebar Vendors & Providers
        # link filters to consulting-tagged vendors instead of showing
        # everything.
        'consulting': 'Standard Consulting',
        # Phase 4 lightweight pathways — scope vendors per pathway too.
        'portfolio':  'Portfolio Pathway',
        'training':   'Training Pathway',
        'uae':        'UAE Pathway',
    }
    country_filter = PATHWAY_TO_COUNTRY.get(pathway)

    conn = get_db()
    if country_filter:
        vendors = conn.execute("""
            SELECT vp.*, GROUP_CONCAT(vsm.service_name, ', ') as services
            FROM vendors_providers vp
            LEFT JOIN vendor_service_map vsm ON vp.id = vsm.vendor_id
            WHERE vp.country = ?
            GROUP BY vp.id
            ORDER BY vp.category, vp.sort_order, vp.name
        """, (country_filter,)).fetchall()
    else:
        vendors = conn.execute("""
            SELECT vp.*, GROUP_CONCAT(vsm.service_name, ', ') as services
            FROM vendors_providers vp
            LEFT JOIN vendor_service_map vsm ON vp.id = vsm.vendor_id
            GROUP BY vp.id
            ORDER BY vp.country, vp.category, vp.sort_order, vp.name
        """).fetchall()
    conn.close()

    # Section grouping
    VP_SECTION_CATS = ['Training Programs', 'Online Courses', 'Online Subscriptions', 'Research & Publications', 'NGO Activities']
    CB_SECTION_CATS = ['Certification Bodies']

    vendors_list = []
    for v in vendors:
        vd = dict(v)
        cats = [c.strip() for c in (vd.get('category') or '').split(',')]
        # Determine section: if any category is in CB_SECTION_CATS and none in VP_SECTION_CATS → certification
        is_cb = any(c in CB_SECTION_CATS for c in cats)
        is_vp = any(c in VP_SECTION_CATS for c in cats)
        vd['section'] = 'both' if (is_cb and is_vp) else ('certification' if is_cb else 'vendors')
        vd['categories_list'] = cats
        vendors_list.append(vd)

    # Deliverables per category for the multi-select in the modal. Start from a
    # few sensible defaults, then UNION every course/service already in use
    # (vendor_service_map) so the checklist reflects real data — not a stale
    # hardcoded list. Users can still type brand-new ones via the "+ Add" box.
    deliverables = {
        'Training Programs': ['IELTS Training', 'OET Training', 'PLAB 1 Training', 'PLAB 2 Training', 'PLAB 2 Mock', 'MRCP 1'],
        'Online Courses': ['Interview skills training', 'Clinical Audit and QIP', 'CCrISP', 'ALS', 'ATLS', 'BLS'],
        'Online Subscriptions': [],
        'Certification Bodies': [],
        'Research & Publications': [],
        'NGO Activities': [],
    }
    try:
        dconn = get_db()
        for row in dconn.execute(
            """SELECT vp.category AS cats, vsm.service_name AS svc
                 FROM vendor_service_map vsm
                 JOIN vendors_providers vp ON vp.id = vsm.vendor_id
                WHERE COALESCE(vsm.service_name, '') <> ''""").fetchall():
            svc = (row['svc'] or '').strip()
            for cat in (row['cats'] or '').split(','):
                cat = cat.strip()
                if cat in deliverables and svc and svc not in deliverables[cat]:
                    deliverables[cat].append(svc)
        dconn.close()
        for k in deliverables:
            deliverables[k] = sorted(set(deliverables[k]), key=str.lower)
    except Exception as e:
        logging.warning(f"vendor deliverables union: {e}")

    return render_template('ops_vendors_providers.html',
                         vendors=vendors_list,
                         countries=VENDOR_COUNTRIES,
                         categories=VENDOR_CATEGORIES,
                         deliverables=deliverables,
                         active_ops_page='vendors-providers',
                         active_pathway=(pathway if pathway else 'plab'))


@app.route('/operations/vendors-providers/add', methods=['POST'])
@login_required
def ops_vendor_add():
    """Add a new vendor/provider."""
    try:
        data = request.json
        name = data.get('name', '').strip()
        country = data.get('country', '').strip()
        # Support categories as array (multi-select) or single string
        categories_raw = data.get('categories', data.get('category', ''))
        if isinstance(categories_raw, list):
            category = ', '.join(c.strip() for c in categories_raw if c.strip())
        else:
            category = categories_raw.strip() if categories_raw else ''
        services = data.get('services', [])
        if isinstance(services, str):
            services = [s.strip() for s in services.split(',') if s.strip()]

        if not name or not country or not category:
            return jsonify({'error': 'Name, country and category are required'}), 400

        conn = get_db()
        max_order = conn.execute("SELECT MAX(sort_order) as m FROM vendors_providers WHERE country = ?", (country,)).fetchone()['m']
        max_order = (max_order or 0) + 1
        conn.execute("INSERT INTO vendors_providers (name, country, category, is_active, sort_order) VALUES (?, ?, ?, TRUE, ?)",
                    (name, country, category, max_order))
        conn.commit()
        vid = conn.execute("SELECT id FROM vendors_providers WHERE name = ? AND country = ? ORDER BY id DESC LIMIT 1",
                          (name, country)).fetchone()['id']
        for svc in services:
            if isinstance(svc, str) and svc.strip():
                conn.execute("INSERT INTO vendor_service_map (vendor_id, service_name) VALUES (?, ?)", (vid, svc.strip()))
        conn.commit()
        sync_vendors_to_lookup_options(conn)
        conn.close()
        return jsonify({'success': True, 'id': vid, 'message': f'Added {name}'})
    except Exception as e:
        logging.error(f"ops_vendor_add error: {e}")
        return jsonify({'error': str(e)}), 500


@app.route('/operations/vendors-providers/<int:vid>/edit', methods=['POST'])
@login_required
def ops_vendor_edit(vid):
    """Edit a vendor/provider."""
    try:
        data = request.json
        name = data.get('name', '').strip()
        country = data.get('country', '').strip()
        categories_raw = data.get('categories', data.get('category', ''))
        if isinstance(categories_raw, list):
            category = ', '.join(c.strip() for c in categories_raw if c.strip())
        else:
            category = categories_raw.strip() if categories_raw else ''
        services = data.get('services', [])
        if isinstance(services, str):
            services = [s.strip() for s in services.split(',') if s.strip()]

        if not name:
            return jsonify({'error': 'Name is required'}), 400

        conn = get_db()
        conn.execute("UPDATE vendors_providers SET name=?, country=?, category=? WHERE id=?",
                    (name, country, category, vid))
        # Replace services
        conn.execute("DELETE FROM vendor_service_map WHERE vendor_id = ?", (vid,))
        for svc in services:
            if isinstance(svc, str) and svc.strip():
                conn.execute("INSERT INTO vendor_service_map (vendor_id, service_name) VALUES (?, ?)", (vid, svc.strip()))
        conn.commit()
        sync_vendors_to_lookup_options(conn)
        conn.close()
        return jsonify({'success': True, 'message': f'Updated {name}'})
    except Exception as e:
        logging.error(f"ops_vendor_edit error: {e}")
        return jsonify({'error': str(e)}), 500


