@app.route('/operations/reports')
@admin_required
def ops_reports():
    """Reports page with template management and quick download.

    Pathway-aware: ?pathway=australia keeps the Australia sidebar active.
    Report templates are pathway-agnostic for now (admin can scope each
    template manually) — adding a `pathway` column to report_templates
    would let us filter the list, but the user said "look into Reports
    for Australia" without specifying separate report sets, so we keep
    the list shared and just route the sidebar correctly.
    """
    pathway = (request.args.get('pathway') or 'plab').strip().lower()
    if pathway not in {'plab', 'australia', 'uae', 'consulting', 'portfolio', 'training'}:
        pathway = 'plab'

    conn = get_db()
    try:
        templates = conn.execute(
            "SELECT * FROM report_templates ORDER BY updated_at DESC"
        ).fetchall()
    except Exception:
        templates = []

    # Quick-download sections for the active pathway: Registration + every ops
    # section table, each with its row count so the team sees what's there.
    def _count(tbl):
        try:
            return conn.execute(
                f"SELECT COUNT(*) AS c FROM {tbl} WHERE COALESCE(pathway,'plab') = ?",
                (pathway,)).fetchone()['c']
        except Exception:
            return 0
    download_sections = [{'table': 'plab_clients', 'label': 'Registration / Clients',
                          'count': _count('plab_clients')}]
    for tbl in OPS_PATHWAY_TABLES:
        download_sections.append({'table': tbl, 'label': OPS_SECTION_LABELS.get(tbl, tbl),
                                  'count': _count(tbl)})

    # Per-section column lists for the field-picker download (below the preset
    # all-columns download). {table: [{'name':.., 'label':..}, ...]}
    section_columns = {}
    for s in download_sections:
        try:
            cols = conn.execute(
                "SELECT column_name FROM information_schema.columns "
                "WHERE table_name = ? ORDER BY ordinal_position", (s['table'],)).fetchall()
            section_columns[s['table']] = [
                {'name': c['column_name'], 'label': c['column_name'].replace('_', ' ').title()}
                for c in cols]
        except Exception:
            section_columns[s['table']] = []
    conn.close()

    pathway_tabs = [('plab', 'UK PGCP'), ('australia', 'AUS PGCP'), ('consulting', 'Consulting'),
                    ('portfolio', 'Portfolio'), ('training', 'Training'), ('uae', 'UAE')]

    return render_template('ops_reports.html',
        templates=templates,
        field_defs=REPORT_FIELD_DEFS,
        download_sections=download_sections,
        section_columns=section_columns,
        pathway_tabs=pathway_tabs,
        active_ops_page='reports',
        active_section='operations',
        active_pathway=pathway)


@app.route('/operations/reports/template', methods=['POST'])
@admin_required
def ops_reports_save_template():
    """Save or update a report template."""
    import json
    template_id = request.form.get('template_id')
    name = request.form.get('name', '').strip()
    section = request.form.get('section', 'plab_clients')
    selected_fields = request.form.getlist('fields')
    filters_data = {}
    for ff in REPORT_FIELD_DEFS.get(section, {}).get('filter_fields', []):
        val = request.form.get(f"filter_{ff['key']}", '').strip()
        if val:
            filters_data[ff['key']] = val

    if not name or not selected_fields:
        flash('Template name and at least one field are required.', 'error')
        return redirect(url_for('ops_reports'))

    conn = get_db()
    try:
        if template_id:
            conn.execute(
                "UPDATE report_templates SET name=?, section=?, selected_fields=?, filters=?, updated_at=CURRENT_TIMESTAMP WHERE id=?",
                (name, section, json.dumps(selected_fields), json.dumps(filters_data), template_id)
            )
        else:
            conn.execute(
                "INSERT INTO report_templates (name, section, selected_fields, filters, created_by) VALUES (?, ?, ?, ?, ?)",
                (name, section, json.dumps(selected_fields), json.dumps(filters_data), session.get('user_id'))
            )
        conn.commit()
        flash(f'Template "{name}" saved successfully.', 'success')
    except Exception as e:
        logging.error(f"ops_reports_save_template: {e}")
        flash('Error saving template.', 'error')
    conn.close()
    return redirect(url_for('ops_reports'))


