@app.route('/operations/plab/import-documents', methods=['POST'])
@admin_required
def ops_plab_import_documents():
    """Bulk import client documents from a folder. Files must be named: REGNUM_DocType.ext"""
    import os, shutil, uuid
    source_dir = request.form.get('source_dir', '')
    if not source_dir or not os.path.isdir(source_dir):
        flash('Source directory not found', 'error')
        return redirect(url_for('ops_documents_list'))

    # Mapping from filename doc type to DB doc type + category
    DOC_TYPE_MAP = {
        'Photograph': ('Photograph', 'personal'),
        'Passport_size_Photograph': ('Passport size Photograph', 'personal'),
        'Pasport': ('Passport Copy (Front)', 'personal'),
        'Passport_Copy_Back': ('Passport Copy (Back)', 'personal'),
        'Aadhar_Copy_Optional': ('Aadhar Copy (Optional)', 'personal'),
        'MBBS_Final_Certificate': ('MBBS Final Certificate', 'academic'),
        'MBBS_Course_Completion_Certificate': ('MBBS Course Completion Certificate', 'academic'),
        'Internship_Certificate1': ('Internship Certificate', 'academic'),
        'State_Registration_Certificate': ('State Registration Certificate', 'academic'),
    }

    conn = get_db()
    upload_dir = os.path.join(app.root_path, 'static', 'uploads', 'plab_docs')
    os.makedirs(upload_dir, exist_ok=True)

    imported = 0
    skipped = 0
    errors = []

    for fname in os.listdir(source_dir):
        fpath = os.path.join(source_dir, fname)
        if not os.path.isfile(fpath):
            continue

        # Parse: GCUKIP-XX-XX-NNN_DocType.ext
        # Split at first underscore after reg number
        parts = fname.split('_', 1)
        if len(parts) < 2:
            errors.append(f"Cannot parse: {fname}")
            continue

        reg_num = parts[0]  # e.g. GCUKIP-24-25-003
        doc_part = parts[1].rsplit('.', 1)[0]  # e.g. Photograph or MBBS_Final_Certificate
        # Remove trailing " (1)" duplicates
        doc_part = doc_part.rstrip()
        if doc_part.endswith(')'):
            import re
            doc_part = re.sub(r'\s*\(\d+\)$', '', doc_part)

        ext = fname.rsplit('.', 1)[-1].lower() if '.' in fname else 'bin'

        # Map doc type
        mapped = DOC_TYPE_MAP.get(doc_part)
        if not mapped:
            errors.append(f"Unknown doc type '{doc_part}' in: {fname}")
            skipped += 1
            continue

        doc_type, doc_category = mapped

        # Find client by registration_number
        client = conn.execute("SELECT id FROM plab_clients WHERE registration_number = ?", (reg_num,)).fetchone()
        if not client:
            errors.append(f"Client not found for reg: {reg_num} ({fname})")
            skipped += 1
            continue

        client_id = client['id']

        # Check if same doc_type already exists for this client (skip duplicates)
        existing = conn.execute(
            "SELECT id FROM plab_client_documents WHERE client_id = ? AND doc_type = ?",
            (client_id, doc_type)
        ).fetchone()
        if existing:
            skipped += 1
            continue

        # Copy file to upload dir
        dest_name = f"plab_{client_id}_{uuid.uuid4().hex[:8]}.{ext}"
        dest_path = os.path.join(upload_dir, dest_name)
        shutil.copy2(fpath, dest_path)
        file_size = os.path.getsize(dest_path)

        # Insert DB record
        conn.execute(
            "INSERT INTO plab_client_documents (client_id, doc_type, doc_category, file_name, file_path, file_size, uploaded_by) VALUES (?, ?, ?, ?, ?, ?, ?)",
            (client_id, doc_type, doc_category, fname, f'/static/uploads/plab_docs/{dest_name}', file_size, 'bulk_import')
        )
        imported += 1

    conn.commit()
    conn.close()
    flash(f'Import complete: {imported} documents imported, {skipped} skipped. {len(errors)} errors.', 'success' if imported > 0 else 'warning')
    if errors:
        for e in errors[:10]:
            flash(e, 'warning')
    return redirect(url_for('ops_documents_list'))


@app.route('/operations/plab/import', methods=['GET', 'POST'])
@admin_required
def ops_plab_import():
    """Import PLAB clients from CSV (combined Zoho export)."""
    if request.method == 'POST':
        import csv, io
        file = request.files.get('csv_file')
        if not file or not file.filename.endswith('.csv'):
            flash('Please upload a CSV file', 'error')
            return redirect(request.url)
        try:
            stream = io.StringIO(file.stream.read().decode('utf-8-sig'))
            reader = csv.DictReader(stream)
            conn = get_db()
            imported = 0
            skipped = 0

            # Zoho CSV column → internal field name mapping
            COL_MAP = {
                'Customer ID': 'customer_id',
                'Registration Number': 'registration_number',
                'Registration Date (Payment Date)': 'registration_date',
                'Plan Type': 'plan_type',
                'Joined Stage': 'joined_stage',
                'PLAB Stage (Current Status)': 'current_stage',
                'Candidate Name': 'candidate_name',
                'Candidate Email': 'email',
                'Mobile Number': 'mobile',
                'Whats App Number': 'whatsapp1',
                'Whats App Number 2': 'whatsapp2',
                'D.O.B': 'dob',
                'CITY': 'city',
                'STATE': 'state',
                'Account Status': 'account_status',
                'Switched Program': 'switched_program',
                'Counsellor': 'counsellor',
                'Additional Notes (Discount Given, Package reduced reason)': 'additional_package_notes',
                'Package (Mention Plab Actual Package)': 'package_amount',
                'Discount Allowed (Discount Offer + Stage Discount)': 'discount_allowed',
                'Final Package': 'final_package',
                'Upgraded To': 'upgraded_to',
                'Mothers Name': 'mother_name',
                'Instagram Name': 'instagram',
                'Facebook Name': 'facebook',
                'LinkedIn Name': 'linkedin',
                'Fathers Name': 'father_name',
                'Fathers Mobile Number': 'father_phone',
                'Mothers Mobile Number': 'mother_phone',
                'Parents Email ID': 'parents_email',
                'Dropped Out / Switched Program Date': 'dropped_date',
                'Counsellor Email': 'counsellor_email',
                'Counsellor Number': 'counsellor_number',
                'Lead Source': 'lead_source',
                'UK Client Referral': 'referral_type',
                'Operations Team Referral': 'operations_referral',
                'Finalised Package': 'finalised_package',
                '1st Installment': 'inst1_amount',
                '1st Instalment Date': 'inst1_date',
                'Ist Installment Note': 'inst1_note',
                '2nd Installment': 'inst2_amount',
                '2nd Instalment Date': 'inst2_date',
                '2nd Installment Note': 'inst2_note',
                '3rd Installment': 'inst3_amount',
                '3rd Instalment Date': 'inst3_date',
                '3rd Installment Note': 'inst3_note',
                '4th Installment': 'inst4_amount',
                '4th Instalment Date': 'inst4_date',
                '4th Installment Note': 'inst4_note',
                'Additional Notes': 'additional_notes',
            }
            # Status normalization map (fix Zoho typos)
            status_fix = {'Oh Hold': 'On Hold'}

            def g(row, key, default=''):
                """Get value from row using either mapped Zoho name or internal key."""
                val = row.get(key, '')
                if not val:
                    # Try reverse lookup: find Zoho column that maps to this key
                    for zoho_col, internal in COL_MAP.items():
                        if internal == key:
                            val = row.get(zoho_col, '')
                            break
                return (val or default).strip() if isinstance(val, str) else val

            for row in reader:
                reg_num = g(row, 'registration_number')
                # Parse candidate name: "Dr. Ashwin Rahul" → prefix, first, last
                candidate_name = g(row, 'candidate_name')
                first_name = g(row, 'first_name')
                last_name = g(row, 'last_name')
                prefix = g(row, 'prefix', 'Dr.')
                if candidate_name and not first_name:
                    parts = candidate_name.strip().split()
                    if parts and parts[0].rstrip('.') in ('Dr', 'Mr', 'Mrs', 'Ms', 'Prof'):
                        prefix = parts[0]
                        parts = parts[1:]
                    if len(parts) >= 2:
                        first_name = parts[0]
                        last_name = ' '.join(parts[1:])
                    elif parts:
                        first_name = parts[0]

                if not first_name and not reg_num:
                    skipped += 1
                    continue
                # Check duplicate by registration number
                if reg_num:
                    exists = conn.execute("SELECT id FROM plab_clients WHERE registration_number = ?", (reg_num,)).fetchone()
                    if exists:
                        skipped += 1
                        continue

                pkg = _safe_float(g(row, 'package_amount', '0'))
                disc = _safe_float(g(row, 'discount_allowed', '0'))
                final = _safe_float(g(row, 'finalised_package', '0') or g(row, 'final_package', '0')) or (pkg - disc)
                i1 = _safe_float(g(row, 'inst1_amount', '0'))
                i2 = _safe_float(g(row, 'inst2_amount', '0'))
                i3 = _safe_float(g(row, 'inst3_amount', '0'))
                i4 = _safe_float(g(row, 'inst4_amount', '0'))
                total_paid = i1 + i2 + i3 + i4
                raw_status = g(row, 'account_status', 'In Process')
                account_status = status_fix.get(raw_status, raw_status)

                conn.execute('''INSERT INTO plab_clients (
                    registration_number, registration_date, customer_id,
                    prefix, first_name, last_name,
                    mobile, whatsapp1, whatsapp2, email, dob, city, state,
                    instagram, facebook, linkedin,
                    father_name, father_phone, mother_name, mother_phone, parents_email,
                    joined_stage, plan_type,
                    account_status, current_stage, switched_program,
                    counsellor, counsellor_email, counsellor_number,
                    lead_source, referral_type, operations_referral,
                    package_amount, discount_allowed, additional_package_notes,
                    final_package, total_paid,
                    inst1_amount, inst1_date, inst1_note,
                    inst2_amount, inst2_date, inst2_note,
                    inst3_amount, inst3_date, inst3_note,
                    inst4_amount, inst4_date, inst4_note,
                    dropped_date, upgraded_to,
                    additional_notes, created_by
                ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)''', (
                    reg_num or _next_registration_number(conn),
                    g(row, 'registration_date'),
                    g(row, 'customer_id'),
                    prefix, first_name, last_name,
                    g(row, 'mobile'), g(row, 'whatsapp1'), g(row, 'whatsapp2'),
                    g(row, 'email'), g(row, 'dob'), g(row, 'city'), g(row, 'state'),
                    g(row, 'instagram'), g(row, 'facebook'), g(row, 'linkedin'),
                    g(row, 'father_name'), g(row, 'father_phone'),
                    g(row, 'mother_name'), g(row, 'mother_phone'), g(row, 'parents_email'),
                    g(row, 'joined_stage'), g(row, 'plan_type'),
                    account_status, g(row, 'current_stage'), g(row, 'switched_program'),
                    g(row, 'counsellor'), g(row, 'counsellor_email'), g(row, 'counsellor_number'),
                    g(row, 'lead_source'), g(row, 'referral_type'), g(row, 'operations_referral'),
                    pkg, disc, g(row, 'additional_package_notes'),
                    final, total_paid,
                    i1, g(row, 'inst1_date'), g(row, 'inst1_note'),
                    i2, g(row, 'inst2_date'), g(row, 'inst2_note'),
                    i3, g(row, 'inst3_date'), g(row, 'inst3_note'),
                    i4, g(row, 'inst4_date'), g(row, 'inst4_note'),
                    g(row, 'dropped_date'), g(row, 'upgraded_to'),
                    g(row, 'additional_notes'),
                    session['user_id']
                ))
                imported += 1
            conn.commit()
            conn.close()
            flash(f'Imported {imported} clients, skipped {skipped} (duplicates/empty)', 'success')
            return redirect(url_for('ops_plab_list'))
        except Exception as e:
            logging.error(f"ops_plab_import: {e}")
            flash(f'Import error: {e}', 'error')
    return render_template('ops_plab_import.html', active_ops_page='import')


@app.route('/operations/plab/fix-switched-program')
@admin_required
def ops_plab_fix_switched_program():
    """Diagnostic + fix: directly update switched_program for all 53 clients."""
    conn = get_db()
    results = []
    SP_DATA = {
        'GCUKIP/25-26/017': 'Australia',
        'GCUKIP/25-26/008': 'Australia',
        'GCUKIP/25-26/004': 'Australia',
        'GCUKIP/24-25/008': 'Australia',
        'GCUKIP/24-25/005': 'NEET India',
        'GCUKIP/23-24/088': 'Australia',
        'GCUKIP/23-24/087': 'Australia',
        'GCUKIP/2023/070': 'Australia',
        'GCUKIP/2023/062': 'Australia',
        'GCUKIP/2023/058': 'Australia',
        'GCUKIP/2023/040': 'NEET India',
        'GCUKIP/2023/036': 'NEET India',
        'GCUKIP/2023/029': 'BAPIO Program',
        'GCUKIP/2023/019': 'Australia',
        'GCUKIP/2023/012': 'Australia',
        'GCUKIP/2023/001': 'USMLE Pathway',
        'GCUKIP/2022/103': 'Australia',
        'GCUKIP/2022/096': 'Australia',
        'GCUKIP/2022/089': 'NEET India',
        'GCUKIP/2022/076': 'Australia',
        'GCUKIP/2022/065': 'Australia',
        'GCUKIP/2022/062': 'USMLE Pathway',
        'GCUKIP/2022/044': 'NEET India',
        'GCUKIP/2022/036': 'USMLE Pathway',
        'GCUKIP/2022/024': 'NEET India',
        'GCUKIP/2022/014': 'BAPIO Program',
        'GCUKIP/2022/009': 'NEET India',
        'GCUKIP/2022/008': 'NEET India',
        'GCUKIP/2022/006': 'NEET India',
        'GCUKIP/2021/093': 'USMLE Pathway',
        'GCUKIP/2021/077': 'BAPIO Program',
        'GCUKIP/2021/073': 'BAPIO Program',
        'GCUKIP/2021/064': 'NEET India',
        'GCUKIP/2021/059': 'USMLE Pathway',
        'GCUKIP/2021/054': 'NEET India',
        'GCUKIP/2021/039': 'NEET India',
        'GCUKIP/2021/037': 'NEET India',
        'GCUKIP/2021/034': 'USMLE Pathway',
        'GCUKIP/2021/027': 'NEET India',
        'GCUKIP/2021/019': 'NEET India',
        'GCUKIP/2021/012': 'USMLE Pathway',
        'GCUKIP/2021/005': 'USMLE Pathway',
        'GCUKIP/2021/004': 'NEET India',
        'GCUKIP/2021/002': 'Australia',
        'GCUKIP/2020/050': 'BAPIO Program',
        'GCUKIP/2020/045': 'NEET India',
        'GCUKIP/2020/034': 'NEET India',
        'GCUKIP/2020/029': 'NEET India',
        'GCUKIP/2020/025': 'USMLE Pathway',
        'GCUKIP/2020/004': 'BAPIO Program',
        'GCUKIP/2020/003': 'NEET India',
        'GCUKIP/2019/011': 'NEET India',
        'GCUKIP/2019/003': 'BAPIO Program',
    }
    try:
        # Step 1: Check column exists (PostgreSQL needs ROLLBACK after failed query)
        col_exists = False
        try:
            conn.execute("SELECT switched_program FROM plab_clients LIMIT 1")
            col_exists = True
            results.append("✅ switched_program column exists")
        except Exception as col_err:
            try:
                conn.rollback()
            except Exception:
                pass
            results.append(f"⚠️ Column missing: {col_err}")
            try:
                conn.execute("ALTER TABLE plab_clients ADD COLUMN switched_program TEXT")
                conn.commit()
                col_exists = True
                results.append("✅ Column added successfully")
            except Exception as add_err:
                try:
                    conn.rollback()
                except Exception:
                    pass
                results.append(f"❌ Could not add column: {add_err}")

        if not col_exists:
            conn.close()
            return '<br>'.join(results)

        # Step 2: Check before state
        before = conn.execute("SELECT COUNT(*) as cnt FROM plab_clients WHERE switched_program IS NOT NULL AND switched_program != ''").fetchone()
        results.append(f"Before fix: {before['cnt']} clients have switched_program")

        # Step 3: Run updates one by one
        updated = 0
        not_found = []
        for reg_num, sp_val in SP_DATA.items():
            # Check if client exists
            client = conn.execute("SELECT id, registration_number, switched_program FROM plab_clients WHERE registration_number = ?", (reg_num,)).fetchone()
            if client:
                conn.execute("UPDATE plab_clients SET switched_program = ? WHERE id = ?", (sp_val, client['id']))
                updated += 1
            else:
                # Try with TRIM in case of spaces
                client2 = conn.execute("SELECT id, registration_number FROM plab_clients WHERE TRIM(registration_number) = ?", (reg_num,)).fetchone()
                if client2:
                    conn.execute("UPDATE plab_clients SET switched_program = ? WHERE id = ?", (sp_val, client2['id']))
                    updated += 1
                    results.append(f"⚠️ {reg_num} matched with TRIM (had spaces)")
                else:
                    not_found.append(reg_num)
        conn.commit()

        # Step 4: Check after state
        after = conn.execute("SELECT COUNT(*) as cnt FROM plab_clients WHERE switched_program IS NOT NULL AND switched_program != ''").fetchone()
        results.append(f"Updated: {updated} clients")
        results.append(f"After fix: {after['cnt']} clients have switched_program")
        if not_found:
            results.append(f"Not found in DB: {', '.join(not_found[:10])}{'...' if len(not_found)>10 else ''}")

        # Step 5: Show Dr. Ashwin Rahul specifically
        ashwin = conn.execute("SELECT id, registration_number, first_name, last_name, switched_program, account_status FROM plab_clients WHERE registration_number = 'GCUKIP/25-26/017'").fetchone()
        if ashwin:
            results.append(f"Dr. Ashwin Rahul: switched_program=[{ashwin['switched_program']}], status=[{ashwin['account_status']}]")
        else:
            # Try LIKE match
            ashwin_pattern = '%' + '25-26/017' + '%'
            ashwin2 = conn.execute("SELECT id, registration_number, first_name, last_name, switched_program, account_status FROM plab_clients WHERE registration_number LIKE ?", (ashwin_pattern,)).fetchone()
            if ashwin2:
                results.append(f"Found via LIKE: reg=[{ashwin2['registration_number']}], sp=[{ashwin2['switched_program']}]")
            else:
                results.append("❌ GCUKIP/25-26/017 NOT FOUND in plab_clients")

        conn.close()
    except Exception as e:
        results.append(f"❌ Error: {e}")
        import traceback
        results.append(traceback.format_exc())

    return '<br>'.join(results)


def _safe_float(val):
    """Parse a float from a string, stripping currency symbols and commas."""
    if not val:
        return 0.0
    try:
        return float(str(val).replace(',', '').replace('₹', '').replace('$', '').strip())
    except (ValueError, TypeError):
        return 0.0


