@app.route('/operations/call-notes')
@admin_required
def ops_call_notes_list():
    """List call notes with detailed filters: registration number, client name, added_by, note text."""
    # Default to tracker tab unless explicitly requesting notes
    if not request.args.get('tab') and not request.args.get('reg') and not request.args.get('client_name') and not request.args.get('added_by') and not request.args.get('note_search') and not request.args.get('q') and not request.args.get('client') and not request.args.get('page'):
        return redirect(url_for('ops_call_notes_tracker'))
    conn = get_db()
    # Filter parameters
    reg = request.args.get('reg', '').strip()
    client_name = request.args.get('client_name', '').strip()
    added_by_filter = request.args.get('added_by', '').strip()
    note_search = request.args.get('note_search', '').strip()
    # Legacy support: 'client' param maps to reg, 'q' maps to note_search
    if not reg and request.args.get('client', ''):
        reg = request.args.get('client', '').strip()
    if not note_search and request.args.get('q', ''):
        note_search = request.args.get('q', '').strip()

    page = request.args.get('page', 1, type=int)
    if page < 1:
        page = 1

    per_page = 50
    offset = (page - 1) * per_page

    try:
        # Get distinct added_by values for dropdown
        added_by_list = conn.execute("SELECT DISTINCT added_by FROM ops_call_notes WHERE added_by IS NOT NULL AND added_by != '' ORDER BY added_by").fetchall()
        added_by_options = [r['added_by'] for r in added_by_list]

        # Build base query
        sql_base = '''SELECT n.*, p.first_name, p.last_name, p.prefix
                      FROM ops_call_notes n
                      LEFT JOIN plab_clients p ON n.registration_number = p.registration_number
                      WHERE COALESCE(n.pathway, 'plab') = 'plab' '''
        params = []
        if reg:
            sql_base += ' AND n.registration_number ILIKE ?'
            params.append(f'%{reg}%')
        if client_name:
            sql_base += """ AND (p.first_name ILIKE ? OR p.last_name ILIKE ?
                OR (p.first_name || ' ' || p.last_name) ILIKE ?
                OR n.registration_number ILIKE ?
                OR (COALESCE(p.prefix,'')||' '||p.first_name||' '||COALESCE(p.last_name,'')) ILIKE ?)"""
            params.extend([f'%{client_name}%'] * 5)
        if added_by_filter:
            sql_base += ' AND n.added_by = ?'
            params.append(added_by_filter)
        if note_search:
            sql_base += ' AND n.call_note ILIKE ?'
            params.append(f'%{note_search}%')

        # Get total count
        count_sql = f'SELECT COUNT(*) as total FROM (SELECT 1 {sql_base[sql_base.find("FROM"):]})'
        total_count = conn.execute(count_sql, params).fetchone()['total']
        total_pages = (total_count + per_page - 1) // per_page

        # Ensure page is within valid range
        if page > total_pages and total_pages > 0:
            page = total_pages
            offset = (page - 1) * per_page

        # Get paginated records
        sql = sql_base + ' ORDER BY n.call_date DESC NULLS LAST, n.id DESC LIMIT ? OFFSET ?'
        sql_params = params + [per_page, offset]
        records = conn.execute(sql, sql_params).fetchall()
    except Exception as e:
        logging.error(f"ops_call_notes_list: {e}")
        records = []
        total_count = 0
        total_pages = 0
        added_by_options = []
    conn.close()

    # Check if any filter is active
    has_filters = bool(reg or client_name or added_by_filter or note_search)

    return render_template('ops_call_notes_list.html',
        records=records, reg=reg, client_name=client_name,
        added_by_filter=added_by_filter, note_search=note_search,
        added_by_options=added_by_options, has_filters=has_filters,
        page=page, per_page=per_page, total_count=total_count, total_pages=total_pages,
        tracker_data=[], summary={'never':0,'critical':0,'overdue':0,'attention':0,'ok':0,'recent':0,'total':0},
        gap_filter='', search_q='', stage_filter='', stage_counts={}, stage_intervals=STAGE_FOLLOWUP_DAYS,
        active_tab='notes', active_ops_page='call-notes')


@app.route('/operations/api/client-search')
@admin_required
def ops_client_search_api():
    """Return matching client names for autocomplete (JSON).

    Pathway-scoped via the ?pathway= query string. Defaults to PLAB so
    existing call sites keep working. The Australia Call Notes "add" form
    passes ?pathway=australia so only Australia clients are suggested.
    """
    q = request.args.get('q', '').strip()
    pathway = (request.args.get('pathway') or 'plab').strip().lower()
    # pathway='all' (referral picker) searches across EVERY pathway and returns
    # each client's pathway so the referral can be linked + the pathway derived.
    all_pw = pathway in ('all', 'any')
    if not all_pw and pathway not in {'plab', 'australia', 'uae', 'consulting', 'portfolio', 'training'}:
        pathway = 'plab'
    if len(q) < 2:
        return jsonify([])
    conn = get_db()
    try:
        inner = ("first_name ILIKE ? OR last_name ILIKE ? "
                 "OR (first_name || ' ' || last_name) ILIKE ? OR registration_number ILIKE ?")
        params = [f'%{q}%', f'%{q}%', f'%{q}%', f'%{q}%']
        # Central Search opts in (?contact=1) to ALSO match mobile + email — a
        # 10-digit number matches inside a stored '+91…' value via substring.
        if request.args.get('contact') in ('1', 'true', 'yes'):
            inner += (" OR mobile ILIKE ? OR whatsapp1 ILIKE ? OR whatsapp2 ILIKE ? "
                      "OR father_phone ILIKE ? OR mother_phone ILIKE ? OR email ILIKE ?")
            params += [f'%{q}%', f'%{q}%', f'%{q}%', f'%{q}%', f'%{q}%', f'%{q}%']
        where = "(" + inner + ")"
        if not all_pw:
            where = "COALESCE(pathway, 'plab') = ? AND " + where
            params = [pathway] + params
        rows = conn.execute(f'''
            SELECT id, registration_number, prefix, first_name, last_name, COALESCE(pathway,'plab') AS pw
            FROM plab_clients
            WHERE {where}
            ORDER BY first_name, last_name
            LIMIT 20
        ''', tuple(params)).fetchall()
        results = []
        for r in rows:
            name = f"{r['prefix']} {r['first_name']} {r['last_name']}" if r['prefix'] else f"{r['first_name']} {r['last_name']}"
            pw = r['pw']
            results.append({'id': r['id'], 'name': name.strip(), 'reg': r['registration_number'],
                            'display_reg': format_reg_filter(r['registration_number']),
                            'pathway': pw, 'pathway_label': REFERRAL_PATHWAY_LABELS.get(pw, pw)})
    except Exception as e:
        logging.error(f"ops_client_search_api: {e}")
        results = []
    conn.close()
    return jsonify(results)


