@app.route('/operations/api/candidate-card')
@admin_required
def ops_candidate_card_api():
    """Rich candidate detail for one registration number, for the central
    search candidate card. Returns the per-pathway profile URL too."""
    reg = (request.args.get('reg') or '').strip()
    if not reg:
        return jsonify({'error': 'missing reg'}), 400
    conn = get_db()
    try:
        c = conn.execute(
            "SELECT * FROM plab_clients WHERE registration_number = ? LIMIT 1",
            (reg,)).fetchone()
        if not c:
            conn.close()
            return jsonify({'error': 'not found'}), 404
        pw = (c['pathway'] or 'plab')
        name = (f"{c['prefix']} {c['first_name']} {c['last_name']}"
                if c['prefix'] else f"{c['first_name']} {c['last_name']}").strip()
        p = c['photo_path'] or ''
        photo = (p if (p.startswith('http') or p.startswith('/')) else f'/static/photos/{p}') if p else ''
        if pw == 'plab':
            profile_url = f"/operations/plab/{c['id']}"
        else:
            profile_url = f"/operations/{pw}/clients/by-reg/{reg}"
        try:
            tp = conn.execute(
                "SELECT COALESCE(SUM(amount_paid), 0) AS t FROM ops_payments "
                "WHERE registration_number = ?", (reg,)).fetchone()
            total_paid = float(tp['t'] or 0) if tp else 0
        except Exception:
            total_paid = 0
        conn.close()
        return jsonify({
            'name': name,
            'reg': format_reg_filter(reg),
            'pathway': pw,
            'pathway_label': REFERRAL_PATHWAY_LABELS.get(pw, pw),
            'photo': photo,
            'mobile': c['mobile'] or '',
            'email': c['email'] or '',
            'city': c['city'] or '',
            'state': c['state'] or '',
            'stage': c['current_stage'] or '',
            'account_status': c['account_status'] or '',
            'counsellor': c['counsellor'] or '',
            'plan_type': c['plan_type'] or '',
            'final_package': c['final_package'] or '',
            'total_paid_ex_gst': (f"₹ {total_paid:,.0f}" if total_paid else ''),
            'lead_source': c['lead_source'] or '',
            'profile_url': profile_url,
        })
    except Exception as e:
        logging.error(f"ops_candidate_card_api: {e}")
        try: conn.close()
        except Exception: pass
        return jsonify({'error': str(e)}), 500


_last_exam_flip = {'date': None}


@app.before_request
def _auto_attend_past_exams():
    """Once a day (first /operations request), flip Booked exams whose date has
    passed to 'Attended', so the pipeline reflects who has sat the exam and now
    awaits results. 'Booked' is valid only up to the exam date; no-shows are
    corrected to 'Missed' manually by the team."""
    try:
        if not request.path.startswith('/operations'):
            return
    except Exception:
        return
    from datetime import date as _date
    today = _date.today().isoformat()
    if _last_exam_flip['date'] == today:
        return
    conn = None
    try:
        conn = get_db()
        conn.execute(
            "UPDATE ops_test_bookings SET exam_status = 'Attended' "
            "WHERE exam_status = 'Booked' "
            "  AND exam_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}' "
            "  AND exam_date < ?", (today,))
        conn.commit()
        _last_exam_flip['date'] = today
    except Exception as e:
        logging.error(f"_auto_attend_past_exams: {e}")
        try:
            if conn: conn.rollback()
        except Exception:
            pass
    finally:
        try:
            if conn: conn.close()
        except Exception:
            pass


# Human-friendly pathway labels for the centralised referrals report.
REFERRAL_PATHWAY_LABELS = {
    'plab': 'UK Pathway',
    'australia': 'AMC Pathway',
    'portfolio': 'Portfolio Pathway',
    'consulting': 'Standard Consulting',
    'training': 'Training Pathway',
    'uae': 'UAE Pathway',
}


@app.route('/operations/referrals')
@admin_required
def ops_referrals_report():
    """Cross-pathway referral leaderboard.

    Lists referrers ranked by how many clients they referred, with an
    optional ?pathway= filter (the referrer's own pathway). For each
    referrer we also list the referred clients (name + their pathway + reg).
    """
    pathway_filter = (request.args.get('pathway') or '').strip().lower()
    if pathway_filter not in REFERRAL_PATHWAY_LABELS:
        pathway_filter = ''
    channel_filter = (request.args.get('channel') or '').strip().lower()
    if channel_filter not in ('sales', 'operations'):
        channel_filter = ''

    conn = get_db()
    leaders = []
    by_pathway = []
    by_channel = {'sales': 0, 'operations': 0}
    try:
        sql = (
            "SELECT referral_client_name, referral_source_pathway, COUNT(*) AS n "
            "  FROM plab_clients "
            " WHERE referral_client_reg IS NOT NULL AND referral_client_reg <> '' "
        )
        params = []
        if pathway_filter:
            sql += " AND COALESCE(referral_source_pathway, '') = ? "
            params.append(pathway_filter)
        if channel_filter:
            sql += " AND LOWER(COALESCE(referral_channel, '')) = ? "
            params.append(channel_filter)
        sql += " GROUP BY referral_client_name, referral_source_pathway ORDER BY n DESC, referral_client_name "
        rows = conn.execute(sql, params).fetchall()

        for r in rows:
            referrer_name = r['referral_client_name']
            src_pw = r['referral_source_pathway']
            # The referred clients under this referrer (matched by name + source pathway).
            try:
                referred = conn.execute(
                    "SELECT registration_number, "
                    "       TRIM(COALESCE(prefix,'') || ' ' || COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')) AS name, "
                    "       COALESCE(pathway, 'plab') AS pathway "
                    "  FROM plab_clients "
                    " WHERE referral_client_name = ? AND COALESCE(referral_source_pathway,'') = COALESCE(?, '') "
                    " ORDER BY name",
                    (referrer_name, src_pw)).fetchall()
            except Exception:
                referred = []
            leaders.append({
                'name': referrer_name,
                'source_pathway': src_pw,
                'source_pathway_label': REFERRAL_PATHWAY_LABELS.get((src_pw or '').lower(), src_pw or '—'),
                'count': r['n'],
                'referred': referred,
            })
        # Per-pathway totals (full, independent of the filter) for the stat cards.
        bprows = conn.execute(
            "SELECT COALESCE(referral_source_pathway,'') AS pw, COUNT(*) AS n FROM plab_clients "
            "WHERE referral_client_reg IS NOT NULL AND referral_client_reg <> '' "
            "GROUP BY referral_source_pathway ORDER BY n DESC").fetchall()
        for br in bprows:
            pw = (br['pw'] or '')
            by_pathway.append({'pathway': pw,
                               'label': REFERRAL_PATHWAY_LABELS.get(pw.lower(), pw or '—'),
                               'count': br['n']})
        # Sales vs Operations split (full, independent of filters).
        chrows = conn.execute(
            "SELECT LOWER(COALESCE(referral_channel,'')) AS ch, COUNT(*) AS n FROM plab_clients "
            "WHERE referral_client_reg IS NOT NULL AND referral_client_reg <> '' "
            "GROUP BY LOWER(COALESCE(referral_channel,''))").fetchall()
        for cr in chrows:
            if cr['ch'] in ('sales', 'operations'):
                by_channel[cr['ch']] = cr['n']
    except Exception as e:
        logging.error(f"ops_referrals_report: {e}")
        leaders = []
    finally:
        conn.close()

    total_referrals = sum(l['count'] for l in leaders)     # respects the pathway filter
    unique_referrers = len(leaders)
    grand_total = sum(b['count'] for b in by_pathway)       # all referrals (unfiltered)
    return render_template('ops_referrals_report.html',
                           leaders=leaders,
                           by_pathway=by_pathway,
                           by_channel=by_channel,
                           total_referrals=total_referrals,
                           unique_referrers=unique_referrers,
                           grand_total=grand_total,
                           pathway_filter=pathway_filter,
                           channel_filter=channel_filter,
                           pathway_labels=REFERRAL_PATHWAY_LABELS,
                           active_ops_page='referrals',
                           active_pathway=None)


@app.route('/operations/api/plan-types')
@admin_required
def ops_plan_types_api():
    """Plan types for a pathway, optionally filtered to a product (cascade).

    Drives Pathway -> Product -> Plan Type on the registration forms.
    ?pathway=plab|australia|consulting|training|portfolio  (required)
    ?product=<product name>  (optional; when given, only that product's plans)
    """
    pathway = (request.args.get('pathway') or 'plab').strip().lower()
    product = (request.args.get('product') or '').strip()
    conn = get_db()
    try:
        if product:
            rows = conn.execute(
                "SELECT value FROM lookup_options WHERE category='plan_type' "
                "AND COALESCE(pathway,'plab')=? AND COALESCE(product_name,'')=? "
                "AND COALESCE(is_active,true) IS NOT FALSE ORDER BY value", (pathway, product)).fetchall()
        else:
            rows = conn.execute(
                "SELECT value FROM lookup_options WHERE category='plan_type' "
                "AND COALESCE(pathway,'plab')=? AND COALESCE(is_active,true) IS NOT FALSE "
                "ORDER BY value", (pathway,)).fetchall()
        vals = [r['value'] for r in rows if r['value']]
    except Exception as e:
        logging.error(f"ops_plan_types_api: {e}")
        vals = []
    conn.close()
    return jsonify(vals)


