@app.route('/operations/api/vendor-services')
@admin_required
def ops_vendor_services_api():
    """Vendor-first cascade: the deliverables/services linked to a vendor.

    Drives the section forms where the user picks a Vendor first and the
    Deliverable/Service dropdown then narrows to that vendor's services
    (from vendor_service_map). Params:
        ?vendor=<name>&pathway=<plab|australia|...>[&category=<vp_category>]
    """
    vendor = (request.args.get('vendor') or '').strip()
    pathway = (request.args.get('pathway') or 'plab').strip().lower()
    category = (request.args.get('category') or '').strip()
    if not vendor:
        return jsonify([])
    country = VENDOR_COUNTRY_BY_PATHWAY.get(pathway, 'UK Pathway')
    conn = get_db()
    try:
        sql = ("SELECT DISTINCT m.service_name FROM vendor_service_map m "
               "JOIN vendors_providers v ON v.id = m.vendor_id "
               "WHERE v.country = ? AND LOWER(TRIM(v.name)) = LOWER(TRIM(?))")
        params = [country, vendor]
        if category:
            sql += " AND v.category = ?"
            params.append(category)
        sql += " ORDER BY m.service_name"
        rows = conn.execute(sql, tuple(params)).fetchall()
        out = [r['service_name'] for r in rows]
    except Exception as e:
        logging.error(f"ops_vendor_services_api: {e}")
        out = []
    conn.close()
    return jsonify(out)


def _products_for_pathway(pathway):
    """Active Products/Services for a pathway as a list of dict rows.

    Used to populate the server-side Product/Service <select> on the
    registration (client add/edit) forms. Mirrors ops_products_api().
    """
    conn = get_db()
    try:
        rows = conn.execute(
            "SELECT id, name FROM products_services "
            "WHERE COALESCE(pathway,'')=? AND COALESCE(status,'active')='active' ORDER BY name",
            ((pathway or 'plab').strip().lower(),)).fetchall()
        out = [{'id': r['id'], 'name': r['name']} for r in rows]
    except Exception as e:
        logging.error(f"_products_for_pathway: {e}")
        out = []
    conn.close()
    return out


def derive_product_id_from_plan(pathway, plan_type):
    """Reverse-lookup the Product/Service a plan_type belongs to, so EDIT
    forms auto-fill Product for legacy records that have a plan_type but no
    saved product_id (avoids the user re-picking and accidentally resetting
    the plan). Returns products_services.id or None."""
    if not plan_type:
        return None
    conn = get_db()
    try:
        r = conn.execute(
            "SELECT ps.id FROM lookup_options lo "
            "JOIN products_services ps ON LOWER(TRIM(ps.name)) = LOWER(TRIM(lo.product_name)) "
            "WHERE lo.category='plan_type' AND COALESCE(lo.pathway,'plab')=? "
            "AND LOWER(TRIM(lo.value))=LOWER(TRIM(?)) "
            "AND COALESCE(ps.pathway,'')=? LIMIT 1",
            ((pathway or 'plab').strip().lower(), plan_type, (pathway or 'plab').strip().lower())).fetchone()
        return r['id'] if r else None
    except Exception as e:
        logging.error(f"derive_product_id_from_plan: {e}")
        return None
    finally:
        conn.close()


@app.route('/operations/call-notes/tracker')
@admin_required
def ops_call_notes_tracker():
    """Client Follow-up Tracker: shows all 'In Process' clients with stage-based priority."""
    from datetime import date

    conn = get_db()
    search_q = request.args.get('q', '').strip()
    gap_filter = request.args.get('gap', '').strip()
    stage_filter = request.args.get('stage', '').strip()

    try:
        sql = '''
            SELECT p.registration_number, p.prefix, p.first_name, p.last_name,
                   p.current_stage, p.mobile, p.account_status,
                   MAX(CASE WHEN COALESCE(n.contacted_status, 'Yes') = 'Yes' THEN n.call_date END) as last_call_date,
                   COUNT(n.id) as note_count,
                   COUNT(CASE WHEN COALESCE(n.contacted_status, 'Yes') = 'Yes' THEN 1 END) as contacted_count,
                   COUNT(CASE WHEN n.contacted_status = 'No' THEN 1 END) as not_contacted_count,
                   MAX(CASE WHEN COALESCE(n.contacted_status, 'Yes') = 'Yes' THEN n.contact_type END) as last_contact_type
            FROM plab_clients p
            LEFT JOIN ops_call_notes n ON p.registration_number = n.registration_number
            WHERE COALESCE(p.pathway, 'plab') = 'plab'
              AND p.account_status = 'In Process'
        '''
        params = []

        if stage_filter:
            sql += " AND p.current_stage = ?"
            params.append(stage_filter)

        if search_q:
            sql += " AND (p.first_name ILIKE ? OR p.last_name ILIKE ? OR p.registration_number ILIKE ? OR (p.prefix || ' ' || p.first_name || ' ' || p.last_name) ILIKE ?)"
            params.extend([f'%{search_q}%'] * 4)

        sql += '''
            GROUP BY p.registration_number, p.prefix, p.first_name, p.last_name,
                     p.current_stage, p.mobile, p.account_status
            ORDER BY last_call_date ASC NULLS FIRST
        '''

        rows = conn.execute(sql, params).fetchall()

        today = date.today()
        tracker_data = []
        category_counts = {
            'never': 0, 'critical': 0, 'overdue': 0, 'attention': 0, 'ok': 0, 'recent': 0
        }
        # Count clients per stage for stage filter badges
        stage_counts = {}

        for row in rows:
            last_call_date = row['last_call_date']
            contacted_count = row['contacted_count'] or 0
            not_contacted_count = row['not_contacted_count'] or 0
            last_contact_type = row['last_contact_type'] or ''
            client_stage = row['current_stage'] or ''

            # Count stages (before filtering by gap)
            stage_counts[client_stage] = stage_counts.get(client_stage, 0) + 1

            if not last_call_date or contacted_count == 0:
                category = 'never'
                days_since = None
            else:
                try:
                    if isinstance(last_call_date, str):
                        last_call = datetime.strptime(last_call_date, '%Y-%m-%d').date()
                    else:
                        last_call = last_call_date if isinstance(last_call_date, date) else last_call_date.date()
                except:
                    last_call = None

                if last_call:
                    days_since = (today - last_call).days
                    category = categorise_by_stage(days_since, client_stage)
                else:
                    category = 'never'
                    days_since = None

            category_counts[category] += 1

            client_name = f"{row['prefix']} {row['first_name']} {row['last_name']}" if row['prefix'] else f"{row['first_name']} {row['last_name']}"
            interval = get_stage_interval(client_stage)

            tracker_data.append({
                'registration_number': row['registration_number'],
                'name': client_name.strip(),
                'stage': client_stage,
                'mobile': row['mobile'],
                'last_call_date': last_call_date,
                'note_count': row['note_count'],
                'contacted_count': contacted_count,
                'not_contacted_count': not_contacted_count,
                'last_contact_type': last_contact_type,
                'days_since': days_since,
                'category': category,
                'followup_interval': interval,
                'days_overdue': max(0, (days_since or 0) - interval) if days_since is not None else None
            })

        if gap_filter:
            tracker_data = [d for d in tracker_data if d['category'] == gap_filter]

        summary = {
            'never': category_counts['never'],
            'critical': category_counts['critical'],
            'overdue': category_counts['overdue'],
            'attention': category_counts['attention'],
            'ok': category_counts['ok'],
            'recent': category_counts['recent'],
            'total': len(tracker_data) if gap_filter else sum(category_counts.values())
        }

    except Exception as e:
        logging.error(f"ops_call_notes_tracker: {e}")
        tracker_data = []
        summary = {'never': 0, 'critical': 0, 'overdue': 0, 'attention': 0, 'ok': 0, 'recent': 0, 'total': 0}
        stage_counts = {}

    conn.close()

    return render_template('ops_call_notes_list.html',
        tracker_data=tracker_data, summary=summary,
        gap_filter=gap_filter, search_q=search_q, stage_filter=stage_filter,
        stage_counts=stage_counts, stage_intervals=STAGE_FOLLOWUP_DAYS,
        records=[], added_by_options=[], has_filters=False,
        reg='', client_name='', added_by_filter='', note_search='',
        page=1, per_page=50, total_count=0, total_pages=0,
        active_tab='tracker', active_ops_page='call-notes')


