@app.route('/operations/api/tracker-details')
@login_required
def ops_call_notes_tracker_details():
    """JSON API: Return client details and their call note history."""
    reg = request.args.get('reg', '').strip()
    if not reg:
        return jsonify({'error': 'Missing registration number'}), 400
    conn = get_db()

    try:
        # Get client details
        client = conn.execute(
            "SELECT registration_number, prefix, first_name, last_name, current_stage, mobile, email FROM plab_clients WHERE registration_number = ?",
            (reg,)
        ).fetchone()

        if not client:
            conn.close()
            return jsonify({'error': 'Client not found'}), 404

        # Get all call notes for this client, ordered by date desc
        notes = conn.execute(
            '''SELECT id, call_date, call_note, added_by, contacted_status, contact_type FROM ops_call_notes
               WHERE registration_number = ?
               ORDER BY call_date DESC, created_at DESC''',
            (reg,)
        ).fetchall()

        # Format notes
        notes_list = []
        for note in notes:
            notes_list.append({
                'id': note['id'],
                'date': note['call_date'],
                'added_by': note['added_by'],
                'text': note['call_note'],
                'contacted_status': note['contacted_status'] or 'Yes',
                'contact_type': note['contact_type'] or 'Call'
            })

        # Client name
        client_name = f"{client['prefix']} {client['first_name']} {client['last_name']}" if client['prefix'] else f"{client['first_name']} {client['last_name']}"

        result = {
            'registration_number': client['registration_number'],
            'formatted_reg': format_reg_filter(client['registration_number']),
            'name': client_name.strip(),
            'stage': client['current_stage'],
            'mobile': client['mobile'],
            'email': client['email'],
            'total_notes': len(notes_list),
            'notes': notes_list
        }

    except Exception as e:
        logging.error(f"ops_call_notes_tracker_details: {e}")
        conn.close()
        return jsonify({'error': str(e)}), 500

    conn.close()
    return jsonify(result)


