# ─────────────────────────────────────────────────────────
#  Payment Approvals + Follow-up (new-registration installment flow)
#  A Received installment on a new-reg client needs admin sign-off before it
#  posts into that pathway's Payments; Pending ones show on the Follow-up page.
# ─────────────────────────────────────────────────────────
_INST_ORD = {1: '1st', 2: '2nd', 3: '3rd', 4: '4th'}


def _reg_pathway(conn, product_id):
    """Pathway slug for a client_registrations product (same logic as reg-number prefix)."""
    if not product_id:
        return 'plab'
    try:
        p = conn.execute("SELECT name FROM products_services WHERE id = ?", (product_id,)).fetchone()
    except Exception:
        p = None
    from core.registration import pathway_from_product_name
    return pathway_from_product_name(p['name'] if p else None)


def _new_reg_installments(conn):
    """Every installment with an amount on a new-registration client, with its
    base/gst/total (base stored; total = base+18%) and current decision state."""
    rows = conn.execute(
        "SELECT id, registration_number, product_id, first_name, last_name, "
        "       counsellor_id, counsellor_name, "
        "       inst1_amount, inst1_date, inst1_method, inst1_status, "
        "       inst2_amount, inst2_date, inst2_method, inst2_status, "
        "       inst3_amount, inst3_date, inst3_method, inst3_status, "
        "       inst4_amount, inst4_date, inst4_method, inst4_status "
        "  FROM client_registrations "
        " WHERE registration_number IS NOT NULL AND registration_number <> '' "
        " ORDER BY id DESC"
    ).fetchall()
    decided = {}
    try:
        for a in conn.execute("SELECT registration_id, inst_no, status FROM installment_approvals").fetchall():
            decided[(a['registration_id'], a['inst_no'])] = a['status']
    except Exception:
        pass
    out = []
    for r in rows:
        for i in (1, 2, 3, 4):
            base = float(r[f'inst{i}_amount'] or 0)
            if base <= 0:
                continue
            gst = round(base * 0.18)
            total = round(base + gst)
            status = (r[f'inst{i}_status'] or '').strip()
            out.append({
                'registration_id': r['id'],
                'registration_number': r['registration_number'],
                'name': (f"{r['first_name'] or ''} {r['last_name'] or ''}").strip() or '(unnamed)',
                'counsellor_id': r['counsellor_id'],
                'counsellor_name': r['counsellor_name'] or '',
                'inst_no': i, 'ordinal': _INST_ORD[i],
                'base': base, 'gst': gst, 'total': total,
                'date': r[f'inst{i}_date'] or '',
                'method': r[f'inst{i}_method'] or '',
                'status': status or 'Pending',
                'decision': decided.get((r['id'], i)),
            })
    return out


@app.route('/operations/payment-approvals')
@admin_required
def ops_payment_approvals():
    conn = get_db()
    _ensure_installment_approvals(conn)
    items = _new_reg_installments(conn)
    pending = [x for x in items if x['status'].lower() == 'received' and not x['decision']]
    approved = [x for x in items if x['decision'] == 'approved']
    conn.close()
    return render_template('ops_payment_approvals.html',
        pending=pending, approved=approved, active_ops_page='payment-approvals')


def _ensure_installment_approvals(conn):
    """Guarantee the installment_approvals table exists at request time — the boot
    migration can miss it on a Render cold start (DB not ready at import), which
    made approve 500 with 'relation does not exist' (founder 2026-07-20)."""
    try:
        conn.execute('''CREATE TABLE IF NOT EXISTS installment_approvals (
            id SERIAL PRIMARY KEY,
            registration_id INTEGER,
            registration_number TEXT,
            inst_no INTEGER,
            base_amount NUMERIC(14,2) DEFAULT 0,
            gst_amount NUMERIC(14,2) DEFAULT 0,
            total_amount NUMERIC(14,2) DEFAULT 0,
            payment_method TEXT,
            payment_date TEXT,
            pathway TEXT,
            status TEXT DEFAULT \'pending\',
            ops_payment_id INTEGER,
            reviewed_by INTEGER,
            reviewed_at TIMESTAMP,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(registration_id, inst_no)
        )''')
        conn.commit()
    except Exception:
        try: conn.rollback()
        except Exception: pass
    # The approve route also posts an ops_payments row tagged with a `source`
    # column. Its ADD COLUMN lives in the same boot block that can miss on a
    # cold start, so ensure it here too (founder 2026-07-21).
    try:
        conn.execute("ALTER TABLE ops_payments ADD COLUMN IF NOT EXISTS source TEXT DEFAULT 'manual'")
        conn.commit()
    except Exception:
        try: conn.rollback()
        except Exception: pass


@app.route('/operations/payment-approvals/<int:reg_id>/<int:inst_no>/approve', methods=['POST'])
@admin_required
def ops_payment_approve(reg_id, inst_no):
    conn = get_db()
    _ensure_installment_approvals(conn)
    try:
        if inst_no not in (1, 2, 3, 4):
            conn.close(); flash('Invalid installment', 'error'); return redirect(url_for('ops_payment_approvals'))
        existing = conn.execute("SELECT status FROM installment_approvals WHERE registration_id = ? AND inst_no = ?",
                                (reg_id, inst_no)).fetchone()
        if existing and existing['status'] == 'approved':
            conn.close(); flash('That installment was already approved', 'info'); return redirect(url_for('ops_payment_approvals'))
        r = conn.execute("SELECT * FROM client_registrations WHERE id = ?", (reg_id,)).fetchone()
        if not r:
            conn.close(); flash('Client not found', 'error'); return redirect(url_for('ops_payment_approvals'))
        reg_no = r['registration_number']
        # ops_payments.registration_number has a FK to plab_clients — a client only
        # exists there once Ops Verification is done. Approving a payment before
        # that would violate the FK and 500, so guard with a clear message.
        in_master = conn.execute("SELECT 1 FROM plab_clients WHERE registration_number = ?", (reg_no,)).fetchone()
        if not in_master:
            conn.close()
            flash('This client is not onboarded to Operations yet — complete Ops Verification first, then approve the payment.', 'error')
            return redirect(url_for('ops_payment_approvals'))
        base_plan = float(r[f'inst{inst_no}_amount'] or 0)
        # Editable at approval: the ACTUAL total received (incl GST). Defaults to the
        # planned installment total (base + 18%); admin can adjust for split / combined
        # / bundled collections (e.g. AMC Consulting + Training) before it posts.
        try:
            total = float(request.form.get('total_amount') or round(base_plan * 1.18, 2))
        except (TypeError, ValueError):
            total = round(base_plan * 1.18, 2)
        if total <= 0:
            conn.close(); flash('Enter the amount received before approving.', 'error'); return redirect(url_for('ops_payment_approvals'))
        amount = round(total / 1.18, 2)
        gst = round(total - amount, 2)
        method = (request.form.get('payment_method') or r[f'inst{inst_no}_method'] or '')
        pdate = (request.form.get('payment_date') or r[f'inst{inst_no}_date'] or None)
        pathway = _reg_pathway(conn, r['product_id'])
        conn.execute(
            "INSERT INTO ops_payments (registration_number, payment_date, amount_paid, gst_paid, "
            " total_amount_paid, instalment, payment_method, notes, pathway, source, created_by) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'installment', ?)",
            (reg_no, pdate, amount, gst, total, _INST_ORD[inst_no], method,
             f"Auto-posted from {_INST_ORD[inst_no]} installment (approved)", pathway, session.get('user_id')))
        pay = conn.execute(
            "SELECT id FROM ops_payments WHERE registration_number = ? AND source = 'installment' "
            "AND instalment = ? ORDER BY id DESC LIMIT 1", (reg_no, _INST_ORD[inst_no])).fetchone()
        pay_id = pay['id'] if pay else None
        # Explicit upsert instead of ON CONFLICT — the live table may predate the
        # UNIQUE(registration_id, inst_no) constraint (CREATE TABLE IF NOT EXISTS
        # never adds a constraint to an existing table), which made ON CONFLICT 500
        # (founder 2026-07-20). This works regardless of the constraint.
        if existing:
            conn.execute(
                "UPDATE installment_approvals SET status = 'approved', base_amount = ?, gst_amount = ?, "
                " total_amount = ?, payment_method = ?, payment_date = ?, pathway = ?, ops_payment_id = ?, "
                " reviewed_by = ?, reviewed_at = CURRENT_TIMESTAMP WHERE registration_id = ? AND inst_no = ?",
                (amount, gst, total, method, pdate, pathway, pay_id, session.get('user_id'), reg_id, inst_no))
        else:
            conn.execute(
                "INSERT INTO installment_approvals (registration_id, registration_number, inst_no, base_amount, "
                " gst_amount, total_amount, payment_method, payment_date, pathway, status, ops_payment_id, reviewed_by, reviewed_at) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'approved', ?, ?, CURRENT_TIMESTAMP)",
                (reg_id, reg_no, inst_no, amount, gst, total, method, pdate, pathway, pay_id, session.get('user_id')))
        conn.commit(); conn.close()
        flash(f'{_INST_ORD[inst_no]} installment approved and posted to {pathway.title()} Payments', 'success')
    except Exception as e:
        try: conn.rollback(); conn.close()
        except Exception: pass
        logging.error(f"ops_payment_approve {reg_id}/{inst_no}: {e}")
        flash('Could not approve the installment (a technical error was logged). Details: ' + str(e)[:180], 'error')
    return redirect(url_for('ops_payment_approvals'))


@app.route('/operations/payment-approvals/<int:reg_id>/<int:inst_no>/reject', methods=['POST'])
@admin_required
def ops_payment_reject(reg_id, inst_no):
    conn = get_db()
    _ensure_installment_approvals(conn)
    try:
        r = conn.execute("SELECT registration_number FROM client_registrations WHERE id = ?", (reg_id,)).fetchone()
        reg_no = r['registration_number'] if r else None
        # Explicit upsert (the live table may predate the UNIQUE constraint, which
        # broke ON CONFLICT — founder 2026-07-20).
        existing = conn.execute("SELECT id FROM installment_approvals WHERE registration_id = ? AND inst_no = ?",
                                (reg_id, inst_no)).fetchone()
        if existing:
            conn.execute("UPDATE installment_approvals SET status = 'rejected', reviewed_by = ?, "
                         "reviewed_at = CURRENT_TIMESTAMP WHERE registration_id = ? AND inst_no = ?",
                         (session.get('user_id'), reg_id, inst_no))
        else:
            conn.execute(
                "INSERT INTO installment_approvals (registration_id, registration_number, inst_no, status, reviewed_by, reviewed_at) "
                "VALUES (?, ?, ?, 'rejected', ?, CURRENT_TIMESTAMP)",
                (reg_id, reg_no, inst_no, session.get('user_id')))
        conn.commit(); conn.close()
        flash('Installment rejected', 'success')
    except Exception as e:
        try: conn.rollback(); conn.close()
        except Exception: pass
        logging.error(f"ops_payment_reject {reg_id}/{inst_no}: {e}")
        flash('Could not reject the installment. Details: ' + str(e)[:180], 'error')
    return redirect(url_for('ops_payment_approvals'))


@app.route('/operations/payment-followup')
@admin_required
def ops_payment_followup():
    conn = get_db()
    items = _new_reg_installments(conn)
    pending = [x for x in items if x['status'].lower() != 'received' and x['decision'] != 'approved']
    pending.sort(key=lambda x: (x['date'] == '', x['date']))
    conn.close()
    return render_template('ops_payment_followup.html',
        pending=pending, active_ops_page='payment-followup')


@app.route('/sales/payment-followup')
@login_required
def sales_payment_followup():
    """Sales-scoped payments: a sales member sees only THEIR OWN clients'
    installments (admins see everyone's) — split into Received (paid) and Due
    (pending, with due dates). Sales can update a due installment, which writes
    to the registration (source of truth) and feeds the ops payment-approval flow."""
    user = get_user()
    uid = user['id'] if user else None
    is_admin = bool(session.get('is_admin'))
    conn = get_db()
    items = _new_reg_installments(conn)
    conn.close()
    if not is_admin:
        items = [x for x in items if x.get('counsellor_id') == uid]
    def _is_received(x):
        return x['status'].lower() == 'received' or x['decision'] == 'approved'
    received = sorted([x for x in items if _is_received(x)], key=lambda x: (x['date'] == '', x['date']), reverse=True)
    due = sorted([x for x in items if not _is_received(x)], key=lambda x: (x['date'] == '', x['date']))
    return render_template('sales_payment_followup.html',
        received=received, due=due, is_admin=is_admin, user=user,
        base_template='sales_sidebar_base.html', active_section='sales')


@app.route('/sales/payment-followup/<int:reg_id>/<int:inst_no>/update', methods=['POST'])
@login_required
def sales_payment_update(reg_id, inst_no):
    """Sales updates a client's installment (amount / due date / method / status).
    Restricted to the lead's counsellor (or admin). Writes to client_registrations
    — the source of truth — so it reflects everywhere incl. the payment approvals."""
    if inst_no not in (1, 2, 3, 4):
        flash('Invalid installment.', 'error')
        return redirect(url_for('sales_payment_followup'))
    user = get_user()
    conn = get_db()
    reg = conn.execute("SELECT counsellor_id FROM client_registrations WHERE id = ?", (reg_id,)).fetchone()
    if not reg:
        conn.close(); flash('Client not found.', 'error'); return redirect(url_for('sales_payment_followup'))
    if not session.get('is_admin') and reg['counsellor_id'] and reg['counsellor_id'] != user['id']:
        conn.close(); flash('You can only update your own clients.', 'error'); return redirect(url_for('sales_payment_followup'))
    # Stored installment amount is the ex-GST base (the form saves total ÷1.18).
    try:
        total = float(request.form.get('total_amount') or 0)
    except (TypeError, ValueError):
        total = 0
    due_date = (request.form.get('due_date') or '').strip()
    method = (request.form.get('method') or '').strip()
    status = (request.form.get('status') or '').strip()
    sets, vals = [], []
    if total > 0:
        sets.append(f"inst{inst_no}_amount = ?"); vals.append(round(total / 1.18, 2))
    sets.append(f"inst{inst_no}_date = ?"); vals.append(due_date)
    if method:
        sets.append(f"inst{inst_no}_method = ?"); vals.append(method)
    if status:
        sets.append(f"inst{inst_no}_status = ?"); vals.append(status)
    sets.append("updated_at = CURRENT_TIMESTAMP")
    conn.execute(f"UPDATE client_registrations SET {', '.join(sets)} WHERE id = ?", vals + [reg_id])
    conn.commit()
    conn.close()
    flash('Payment updated. It now reflects in the client record and payment approvals.', 'success')
    return redirect(url_for('sales_payment_followup'))


# ─────────────────────────────────────────────────────────
#  ADMIN – Centralised Payments Hub (all products)
# ─────────────────────────────────────────────────────────
# One place for admin to add/update payments for any client across every
# pathway. GST is computed server-side (authoritative); the form mirrors it
# for live preview. "Switched from other program" captures the source product
# (internal-transfer groundwork). Adding a payment notifies the ops team.

HUB_PAYMENT_METHODS = ['Bank Transfer', 'Cash Deposit', 'Online Payment', 'Cheque',
                       'Discount', 'Switched from other program']
HUB_NO_GST_METHODS = {'Discount'}
HUB_TRANSFER_METHOD = 'Switched from other program'


def _compute_payment_amounts(total, method):
    """GST-inclusive: the entered total is what the client paid.
    Returns (amount_paid_base, gst, total). Discount carries no GST."""
    total = round(float(total or 0), 2)
    if method in HUB_NO_GST_METHODS:
        return total, 0.0, total
    base = round(total / 1.18, 2)
    return base, round(total - base, 2), total


def _notify_payment_added(conn, client_name, amount, pathway, method):
    """In-app activity to every ops/admin team member when a payment is added."""
    try:
        ops = conn.execute("SELECT id FROM employees WHERE is_admin = 1 AND is_active = 1").fetchall()
        msg = f"₹{amount:,.0f} ({method}) recorded for {client_name} — {(pathway or 'plab').upper()}"
        link = url_for('admin_payments_hub')
        for e in ops:
            try:
                create_notification(conn, e['id'], "Payment added", msg, 'payment', link)
            except Exception:
                pass
    except Exception as ex:
        logging.warning(f"_notify_payment_added: {ex}")


def _sync_internal_transfer(conn, payment_id, reg, from_product, to_pathway, amount, date, created_by):
    """Keep an internal_transfers row in step with a transfer-method payment.
    One transfer per payment_id: upsert when it's a transfer, delete otherwise."""
    try:
        existing = conn.execute("SELECT id FROM internal_transfers WHERE payment_id = ?", (payment_id,)).fetchone()
        if from_product:
            if existing:
                conn.execute("""UPDATE internal_transfers SET registration_number=?, from_product=?,
                    to_pathway=?, amount=?, transfer_date=? WHERE payment_id=?""",
                    (reg, from_product, to_pathway, amount, date, payment_id))
            else:
                conn.execute("""INSERT INTO internal_transfers
                    (registration_number, from_product, to_pathway, amount, transfer_date, payment_id, created_by)
                    VALUES (?, ?, ?, ?, ?, ?, ?)""",
                    (reg, from_product, to_pathway, amount, date, payment_id, created_by))
        elif existing:
            # method was changed away from transfer — drop the stale transfer row
            conn.execute("DELETE FROM internal_transfers WHERE payment_id = ?", (payment_id,))
    except Exception as ex:
        logging.warning(f"_sync_internal_transfer: {ex}")


@app.route('/admin/payments')
@admin_required
def admin_payments_hub():
    conn = get_db()
    q = request.args.get('q', '').strip()
    method = request.args.get('method', '').strip()
    pathway = request.args.get('pathway', '').strip()
    where, params = [], []
    if q:
        where.append("(LOWER(p.first_name) LIKE LOWER(?) OR LOWER(p.last_name) LIKE LOWER(?) OR LOWER(t.registration_number) LIKE LOWER(?))")
        params += [f"%{q}%", f"%{q}%", f"%{q}%"]
    if method:
        where.append("t.payment_method = ?"); params.append(method)
    if pathway:
        where.append("COALESCE(p.pathway, t.pathway, 'plab') = ?"); params.append(pathway)
    wsql = ("WHERE " + " AND ".join(where)) if where else ""
    rows = conn.execute(f"""
        SELECT t.*, p.prefix, p.first_name, p.last_name,
               COALESCE(p.pathway, t.pathway, 'plab') AS client_pathway
          FROM ops_payments t
     LEFT JOIN plab_clients p ON t.registration_number = p.registration_number
          {wsql}
      ORDER BY t.payment_date DESC, t.id DESC
         LIMIT 500""", params).fetchall()
    stats = conn.execute(f"""SELECT COUNT(*) AS n,
               COALESCE(SUM(t.total_amount_paid),0) AS total,
               COALESCE(SUM(t.gst_paid),0) AS gst
          FROM ops_payments t
     LEFT JOIN plab_clients p ON t.registration_number = p.registration_number {wsql}""", params).fetchone()
    methods = conn.execute("SELECT DISTINCT payment_method FROM ops_payments WHERE payment_method IS NOT NULL AND payment_method <> '' ORDER BY payment_method").fetchall()
    pathways = conn.execute("SELECT DISTINCT COALESCE(pathway,'plab') AS pw FROM ops_payments ORDER BY pw").fetchall()
    conn.close()
    return render_template('admin_payments_hub.html', rows=rows, stats=stats, q=q,
        method=method, pathway=pathway, methods=[m['payment_method'] for m in methods],
        pathways=[p['pw'] for p in pathways], active_section='clients')


@app.route('/admin/payments/add', methods=['GET', 'POST'])
@admin_required
def admin_payments_add():
    conn = get_db()
    if request.method == 'POST':
        reg = request.form.get('registration_number', '').strip()
        method = request.form.get('payment_method', '')
        source_product = request.form.get('source_product', '') if method == HUB_TRANSFER_METHOD else ''
        try:
            amount_paid, gst_paid, total_amount_paid = _compute_payment_amounts(request.form.get('total_amount_paid', '0'), method)
            crow = conn.execute("SELECT COALESCE(pathway,'plab') AS pw, prefix, first_name, last_name FROM plab_clients WHERE registration_number = ? LIMIT 1", (reg,)).fetchone()
            pathway = crow['pw'] if crow else 'plab'
            conn.execute('''INSERT INTO ops_payments
                (registration_number, payment_date, amount_paid, gst_paid, total_amount_paid,
                 instalment, payment_method, total_package, notes, source_product, pathway, created_by)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)''',
                (reg, request.form.get('payment_date'), amount_paid, gst_paid, total_amount_paid,
                 request.form.get('instalment'), method, float(request.form.get('total_package', 0) or 0),
                 request.form.get('notes', ''), source_product, pathway, session.get('user_id')))
            cname = (f"{crow['prefix'] or ''} {crow['first_name'] or ''} {crow['last_name'] or ''}".strip() if crow else reg) or reg
            _notify_payment_added(conn, cname, total_amount_paid, pathway, method)
            if method == HUB_TRANSFER_METHOD and source_product:
                newp = conn.execute("SELECT id FROM ops_payments WHERE registration_number = ? AND created_by = ? ORDER BY id DESC LIMIT 1",
                                    (reg, session.get('user_id'))).fetchone()
                if newp:
                    _sync_internal_transfer(conn, newp['id'], reg, source_product, pathway,
                                            total_amount_paid, request.form.get('payment_date'), session.get('user_id'))
            conn.commit()
            conn.close()
            flash('Payment added. Operations team notified.', 'success')
            return redirect(url_for('admin_payments_hub'))
        except Exception as e:
            logging.error(f"admin_payments_add: {e}")
            flash('Error adding payment', 'error')
    products = conn.execute("SELECT name FROM products_services WHERE COALESCE(status,'active')='active' ORDER BY name").fetchall()
    conn.close()
    return render_template('admin_payment_form.html', record=None, products=[p['name'] for p in products],
        payment_methods=HUB_PAYMENT_METHODS, no_gst_methods=list(HUB_NO_GST_METHODS),
        transfer_method=HUB_TRANSFER_METHOD, instalment_options=get_lookup_options('instalment'),
        active_section='clients')


@app.route('/admin/payments/<int:record_id>/edit', methods=['GET', 'POST'])
@admin_required
def admin_payments_edit(record_id):
    conn = get_db()
    record = conn.execute("""SELECT t.*, p.prefix, p.first_name, p.last_name,
               COALESCE(p.pathway, t.pathway, 'plab') AS client_pathway
          FROM ops_payments t
     LEFT JOIN plab_clients p ON t.registration_number = p.registration_number
         WHERE t.id = ?""", (record_id,)).fetchone()
    if not record:
        conn.close()
        flash('Payment not found', 'error')
        return redirect(url_for('admin_payments_hub'))
    if request.method == 'POST':
        method = request.form.get('payment_method', '')
        source_product = request.form.get('source_product', '') if method == HUB_TRANSFER_METHOD else ''
        try:
            amount_paid, gst_paid, total_amount_paid = _compute_payment_amounts(request.form.get('total_amount_paid', '0'), method)
            conn.execute('''UPDATE ops_payments SET registration_number = ?, payment_date = ?, amount_paid = ?,
                gst_paid = ?, total_amount_paid = ?, instalment = ?, payment_method = ?, total_package = ?,
                notes = ?, source_product = ? WHERE id = ?''',
                (request.form.get('registration_number'), request.form.get('payment_date'), amount_paid,
                 gst_paid, total_amount_paid, request.form.get('instalment'), method,
                 float(request.form.get('total_package', 0) or 0), request.form.get('notes', ''),
                 source_product, record_id))
            _sync_internal_transfer(conn, record_id, request.form.get('registration_number'),
                                    source_product, record['client_pathway'], total_amount_paid,
                                    request.form.get('payment_date'), session.get('user_id'))
            conn.commit()
            conn.close()
            flash('Payment updated', 'success')
            return redirect(url_for('admin_payments_hub'))
        except Exception as e:
            logging.error(f"admin_payments_edit: {e}")
            flash('Error updating payment', 'error')
    products = conn.execute("SELECT name FROM products_services WHERE COALESCE(status,'active')='active' ORDER BY name").fetchall()
    conn.close()
    return render_template('admin_payment_form.html', record=record, products=[p['name'] for p in products],
        payment_methods=HUB_PAYMENT_METHODS, no_gst_methods=list(HUB_NO_GST_METHODS),
        transfer_method=HUB_TRANSFER_METHOD, instalment_options=get_lookup_options('instalment'),
        active_section='clients')


@app.route('/admin/internal-transfers')
@admin_required
def admin_internal_transfers():
    """Ledger of internal transfers (clients moved between products)."""
    conn = get_db()
    cols = """it.*, sc.prefix, sc.first_name, sc.last_name,
              e.name AS raised_by_name, ap.name AS approved_by_name
         FROM internal_transfers it
    LEFT JOIN plab_clients sc ON sc.registration_number = it.from_reg
    LEFT JOIN employees e ON e.id = it.created_by
    LEFT JOIN employees ap ON ap.id = it.approved_by"""
    pending = conn.execute(f"SELECT {cols} WHERE it.status = 'pending' ORDER BY it.id DESC", []).fetchall()
    history = conn.execute(f"SELECT {cols} WHERE COALESCE(it.status,'approved') <> 'pending' ORDER BY it.transfer_date DESC, it.id DESC", []).fetchall()
    # Utilized line items for the pending cards.
    items_by_t = {}
    for it in pending:
        items_by_t[it['id']] = conn.execute("SELECT name, amount FROM internal_transfer_items WHERE transfer_id = ? ORDER BY id", (it['id'],)).fetchall()
    summary = conn.execute("SELECT COUNT(*) AS n, COALESCE(SUM(amount),0) AS amt FROM internal_transfers WHERE COALESCE(status,'approved')='approved'", []).fetchone()
    conn.close()
    return render_template('admin_internal_transfers.html', pending=pending, history=history,
                           items_by_t=items_by_t, summary=summary, is_admin=bool(session.get('is_admin')),
                           active_section='clients')


