@app.route('/admin/internal-transfers/reconcile', methods=['GET', 'POST'])
@admin_required
def admin_internal_transfers_reconcile():
    """Link the existing 'Switched Program' clients (whose switched_program is
    free text like 'NEET India' / 'Australia') to a real product, so the data is
    consistent. Updates plab_clients.switched_program to the chosen product name."""
    conn = get_db()
    if request.method == 'POST':
        updated = 0
        for k, v in request.form.items():
            if k.startswith('map_') and (v or '').strip():
                reg = k[4:]
                conn.execute("""UPDATE plab_clients SET switched_program = ?, updated_at = CURRENT_TIMESTAMP
                    WHERE registration_number = ? AND account_status = 'Switched Program'""", (v.strip(), reg))
                updated += 1
        conn.commit()
        conn.close()
        flash(f'Linked {updated} record(s) to a product.', 'success')
        return redirect(url_for('admin_internal_transfers_reconcile'))
    rows = conn.execute("""SELECT registration_number, prefix, first_name, last_name,
        COALESCE(pathway,'plab') AS pathway, COALESCE(switched_program,'') AS switched_program
        FROM plab_clients WHERE account_status = 'Switched Program'
        ORDER BY COALESCE(NULLIF(switched_program,''),'~~~'), first_name""", []).fetchall()
    products = conn.execute("""SELECT name, COALESCE(pathway,'') AS pathway FROM products_services
        WHERE COALESCE(status,'active')='active' ORDER BY pathway, name""", []).fetchall()
    prod_names = set(p['name'] for p in products)
    conn.close()
    return render_template('admin_internal_transfers_reconcile.html', rows=rows, products=products,
                           prod_names=prod_names, active_section='clients')


@app.route('/api/view-prefs')
@login_required
def get_view_prefs():
    """Return the effective hidden-columns list for the current user on a section.
    Member's own row wins; otherwise the admin default (employee_id NULL)."""
    import json as _json
    section = (request.args.get('section') or '').strip()
    base = {'hidden': [], 'extra': [], 'default_hidden': [], 'default_extra': [],
            'has_mine': False, 'has_default': False, 'is_admin': bool(session.get('is_admin'))}
    if not section:
        return jsonify(base)
    uid = session.get('user_id')
    conn = get_db()
    try:
        mine = conn.execute("SELECT hidden_columns FROM view_preferences WHERE employee_id = ? AND section_key = ?", (uid, section)).fetchone()
        deflt = conn.execute("SELECT hidden_columns FROM view_preferences WHERE employee_id IS NULL AND section_key = ?", (section,)).fetchone()
    finally:
        try: conn.close()
        except Exception: pass
    def _norm(r):
        # Stored value may be a legacy list (hidden only) or {hidden, extra}.
        if not r or not r['hidden_columns']:
            return None
        try: v = _json.loads(r['hidden_columns'])
        except Exception: return None
        if isinstance(v, list): return {'hidden': v, 'extra': []}
        if isinstance(v, dict): return {'hidden': v.get('hidden') or [], 'extra': v.get('extra') or []}
        return None
    mine_n = _norm(mine)
    def_n = _norm(deflt)
    eff = mine_n if mine_n is not None else (def_n or {'hidden': [], 'extra': []})
    return jsonify({'hidden': eff['hidden'], 'extra': eff['extra'],
                    'default_hidden': (def_n or {}).get('hidden', []), 'default_extra': (def_n or {}).get('extra', []),
                    'has_mine': mine_n is not None, 'has_default': def_n is not None,
                    'is_admin': bool(session.get('is_admin'))})


@app.route('/api/view-prefs', methods=['POST'])
@login_required
def save_view_prefs():
    """Save hidden columns for a section. scope='me' (per member), 'default'
    (admin-wide, admin only), or 'reset' (drop the member's override)."""
    import json as _json
    data = request.get_json(silent=True) or {}
    section = (data.get('section') or '').strip()
    scope = (data.get('scope') or 'me').strip()
    if not section:
        return jsonify({'error': 'section required'}), 400
    uid = session.get('user_id')
    conn = get_db()
    try:
        if scope == 'reset':
            conn.execute("DELETE FROM view_preferences WHERE employee_id = ? AND section_key = ?", (uid, section))
            conn.commit()
            return jsonify({'ok': True, 'reset': True})
        if scope == 'default':
            if not session.get('is_admin'):
                return jsonify({'error': 'admin only'}), 403
            target = None
        else:
            target = uid
        hidden = data.get('hidden')
        extra = data.get('extra')
        if not isinstance(hidden, list):
            hidden = []
        if not isinstance(extra, list):
            extra = []
        hj = _json.dumps({'hidden': [str(x) for x in hidden], 'extra': [str(x) for x in extra]})
        if target is None:
            ex = conn.execute("SELECT id FROM view_preferences WHERE employee_id IS NULL AND section_key = ?", (section,)).fetchone()
        else:
            ex = conn.execute("SELECT id FROM view_preferences WHERE employee_id = ? AND section_key = ?", (target, section)).fetchone()
        if ex:
            conn.execute("UPDATE view_preferences SET hidden_columns = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?", (hj, ex['id']))
        else:
            conn.execute("INSERT INTO view_preferences (employee_id, section_key, hidden_columns) VALUES (?, ?, ?)", (target, section, hj))
        conn.commit()
        return jsonify({'ok': True})
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        return jsonify({'error': str(e)}), 500
    finally:
        try: conn.close()
        except Exception: pass


