# ─────────────────────────────────────────────────────────
#  OPERATIONS – Bulk Add / Bulk Edit (generic, all sections)
# ─────────────────────────────────────────────────────────
# One tool to (a) add the SAME record to many clients at once, and (b) edit
# chosen fields on many existing records. Generic: works for every ops_* section
# via the table schema. Tables + columns are whitelisted; values parameterised.

OPS_SECTION_LABELS = {
    'ops_academic_details': 'Academic Details', 'ops_call_notes': 'Call Notes',
    'ops_coaching': 'Coaching', 'ops_english_logins': 'English Logins',
    'ops_epic_registration': 'EPIC Registration', 'ops_gmc_registration': 'GMC Registration',
    'ops_amc_registration': 'AMC Registration', 'ops_mentorship': 'Mentorship',
    'ops_ngo_activities': 'NGO Activities', 'ops_online_courses': 'Online Courses',
    'ops_online_subscriptions': 'Online Subscriptions', 'ops_payments': 'Payments',
    'ops_research_publication': 'Research & Publications', 'ops_test_bookings': 'Test Bookings',
    'ops_uk_cab_bookings': 'Cab Bookings', 'ops_uk_observerships': 'Observerships',
    'ops_uk_visa_travel': 'Visa & Travel', 'ops_webinars_conferences': 'Webinars & Conferences',
}
_BULK_SYS_COLS = {'id', 'registration_number', 'pathway', 'created_at', 'created_by',
                  'updated_at', 'updated_by', 'updated_by_name'}
# Columns that are inherently free text — never coerce into a dropdown even if
# they happen to have few distinct values (e.g. notes that are full sentences).
_BULK_FREETEXT_HINTS = ('note', 'remark', 'comment', 'description', 'reason', 'address',
                        'detail', 'feedback', 'message', 'instruction', 'score', 'link',
                        'url', 'email', 'name')
BULK_PATHWAYS = ['plab', 'australia', 'consulting', 'portfolio', 'training', 'uae']

# Canonical pathway -> client-profile endpoint. The single place that knows which
# ops profile a client of a given pathway lives on, so links/redirects after
# verification route to the RIGHT pathway (not always PLAB). Pairs with the
# master-record pathway fix.
PATHWAY_DETAIL_ENDPOINT = {
    'plab': 'ops_plab_dashboard',
    'australia': 'ops_australia_client_detail',
    'consulting': 'ops_consulting_client_detail',
    'portfolio': 'ops_portfolio_client_detail',
    'training': 'ops_training_client_detail',
    'uae': 'ops_uae_client_detail',
}


def pathway_detail_url(pathway, client_id):
    """URL of the ops client-profile page for this pathway (defaults to PLAB)."""
    ep = PATHWAY_DETAIL_ENDPOINT.get((pathway or 'plab').strip().lower(), 'ops_plab_dashboard')
    return url_for(ep, client_id=client_id)


def resolve_ops_pathway(conn, product_id, product_name=None):
    """Canonical ops pathway slug for a client's product — the ONE place that
    decides it, so pathway-scoped dropdowns (Joined Stage, Current Stage, …) and
    links resolve consistently. products_services.pathway can be a legacy slug
    (standard_consulting / amc_training) or unset, so we normalise it and, when it
    isn't a real ops pathway, infer from the product NAME (keyword map:
    'AMC Consulting' -> consulting, 'AMC MCQ' -> training, 'AUS PGCP' -> australia…).
    """
    from core.registration import pathway_from_product_name
    pw = ''
    if product_id:
        try:
            r = conn.execute("SELECT pathway, name FROM products_services WHERE id = ?", (product_id,)).fetchone()
            if r:
                pw = ((r['pathway'] or '')).strip().lower()
                if not product_name:
                    product_name = r['name']
        except Exception:
            pw = ''
    pw = {'standard_consulting': 'consulting', 'amc_training': 'training'}.get(pw, pw)
    if pw in ('plab', 'australia', 'consulting', 'portfolio', 'training', 'uae'):
        return pw
    return pathway_from_product_name(product_name or '')


def _bulk_columns(conn, table, pathway=None):
    """Editable columns for an ops_* table (whitelisted), with input types.

    Text columns that have a constrained value set render as dropdowns so the
    bulk team picks an existing value instead of free-typing (avoids mismatch).
    Options come from a matching lookup_options category plus the distinct values
    already in that column for this pathway. Free-text columns (many distinct
    values, e.g. notes/names) stay as text inputs."""
    if table not in OPS_PATHWAY_TABLES:
        return []
    try:
        rows = conn.execute("SELECT column_name AS n, data_type AS t FROM information_schema.columns WHERE table_name = ? ORDER BY ordinal_position", (table,)).fetchall()
        cols = [(r['n'], (r['t'] or '')) for r in rows]
    except Exception:
        try:
            rows = conn.execute(f"PRAGMA table_info({table})").fetchall()
            cols = [(r['name'], (r['type'] or '')) for r in rows]
        except Exception:
            cols = []
    try:
        lookup_cats = {r['c'] for r in conn.execute("SELECT DISTINCT category AS c FROM lookup_options WHERE is_active = TRUE", []).fetchall()}
    except Exception:
        lookup_cats = set()
    out = []
    for name, dt in cols:
        if name in _BULK_SYS_COLS:
            continue
        dl = dt.lower()
        numeric = ('int' in dl or 'numeric' in dl or 'double' in dl or 'real' in dl or 'decimal' in dl)
        if numeric:
            out.append({'name': name, 'label': name.replace('_', ' ').title(), 'type': 'number', 'numeric': True, 'options': []})
            continue
        if 'date' in name.lower():
            out.append({'name': name, 'label': name.replace('_', ' ').title(), 'type': 'date', 'numeric': False, 'options': []})
            continue
        # Inherently free-text columns stay as text (never a sentence dropdown).
        if any(h in name.lower() for h in _BULK_FREETEXT_HINTS):
            out.append({'name': name, 'label': name.replace('_', ' ').title(), 'type': 'text', 'numeric': False, 'options': []})
            continue
        # Text column — decide dropdown vs free text.
        options = []
        if name in lookup_cats:
            try:
                options = list(get_lookup_options(name, pathway=pathway) if pathway else get_lookup_options(name))
            except Exception:
                try:
                    options = list(get_lookup_options(name))
                except Exception:
                    options = []
        try:
            if pathway:
                existing = [r[0] for r in conn.execute(
                    f"SELECT DISTINCT {name} FROM {table} WHERE COALESCE(pathway,'plab') = ? AND {name} IS NOT NULL AND {name} <> '' ORDER BY {name} LIMIT 60", (pathway,)).fetchall()]
            else:
                existing = [r[0] for r in conn.execute(
                    f"SELECT DISTINCT {name} FROM {table} WHERE {name} IS NOT NULL AND {name} <> '' ORDER BY {name} LIMIT 60", []).fetchall()]
        except Exception:
            existing = []
        if options or (1 <= len(existing) <= 40):
            merged = list(dict.fromkeys((options or []) + existing))
            out.append({'name': name, 'label': name.replace('_', ' ').title(), 'type': 'select', 'numeric': False, 'options': merged})
        else:
            out.append({'name': name, 'label': name.replace('_', ' ').title(), 'type': 'text', 'numeric': False, 'options': []})
    return out


@app.route('/operations/bulk')
@admin_required
def ops_bulk():
    pathway = (request.args.get('pathway') or 'plab').strip().lower()
    if pathway not in BULK_PATHWAYS:
        pathway = 'plab'
    table = (request.args.get('table') or '').strip()
    if table and table not in OPS_PATHWAY_TABLES:
        table = ''
    conn = get_db()
    columns, records = [], []
    if table:
        columns = _bulk_columns(conn, table, pathway)
        # existing records for the bulk-edit panel (this pathway + section)
        try:
            records = conn.execute(f"""
                SELECT t.*, p.prefix, p.first_name, p.last_name
                  FROM {table} t
             LEFT JOIN plab_clients p ON t.registration_number = p.registration_number
                 WHERE COALESCE(t.pathway, 'plab') = ?
              ORDER BY t.id DESC LIMIT 300""", (pathway,)).fetchall()
        except Exception:
            records = []
    sections = [(t, OPS_SECTION_LABELS.get(t, t)) for t in OPS_PATHWAY_TABLES]
    conn.close()
    return render_template('ops_bulk.html', pathway=pathway, table=table, columns=columns,
        records=records, sections=sections, pathways=BULK_PATHWAYS,
        section_label=OPS_SECTION_LABELS.get(table, table), active_ops_page='bulk')


@app.route('/operations/bulk/add', methods=['POST'])
@admin_required
def ops_bulk_add():
    table = (request.form.get('table') or '').strip()
    pathway = (request.form.get('pathway') or 'plab').strip().lower()
    if table not in OPS_PATHWAY_TABLES or pathway not in BULK_PATHWAYS:
        flash('Invalid section', 'error')
        return redirect(url_for('ops_bulk'))
    regs = [r for r in request.form.getlist('registration_number') if r.strip()]
    conn = get_db()
    cols = _bulk_columns(conn, table, pathway)
    # only the fields the user actually filled
    fills = {}
    for c in cols:
        v = request.form.get(f"f_{c['name']}", '')
        if v != '':
            fills[c['name']] = (float(v or 0) if c['numeric'] else v)
    if not regs:
        conn.close()
        flash('Select at least one client', 'error')
        return redirect(url_for('ops_bulk', pathway=pathway, table=table))
    insert_cols = ['registration_number', 'pathway'] + list(fills.keys()) + ['created_by']
    placeholders = ', '.join(['?'] * len(insert_cols))
    made = 0
    for reg in regs:
        vals = [reg, pathway] + list(fills.values()) + [session.get('user_id')]
        try:
            conn.execute(f"INSERT INTO {table} ({', '.join(insert_cols)}) VALUES ({placeholders})", vals)
            made += 1
        except Exception as e:
            logging.error(f"ops_bulk_add {table} {reg}: {e}")
    conn.commit()
    conn.close()
    flash(f'Added {made} record(s) across {len(regs)} client(s).', 'success')
    return redirect(url_for('ops_bulk', pathway=pathway, table=table))


@app.route('/operations/bulk/edit', methods=['POST'])
@admin_required
def ops_bulk_edit():
    table = (request.form.get('table') or '').strip()
    pathway = (request.form.get('pathway') or 'plab').strip().lower()
    if table not in OPS_PATHWAY_TABLES or pathway not in BULK_PATHWAYS:
        flash('Invalid section', 'error')
        return redirect(url_for('ops_bulk'))
    ids = [i for i in request.form.getlist('record_ids') if i.strip().isdigit()]
    edit_cols = request.form.getlist('edit_cols')
    conn = get_db()
    cols = {c['name']: c for c in _bulk_columns(conn, table, pathway)}
    sets, vals = [], []
    for col in edit_cols:
        if col not in cols:
            continue
        v = request.form.get(f"v_{col}", '')
        sets.append(f"{col} = ?")
        vals.append(float(v or 0) if cols[col]['numeric'] else v)
    if not ids or not sets:
        conn.close()
        flash('Select records and at least one field to change.', 'error')
        return redirect(url_for('ops_bulk', pathway=pathway, table=table))
    placeholders = ', '.join(['?'] * len(ids))
    try:
        conn.execute(f"UPDATE {table} SET {', '.join(sets)} WHERE id IN ({placeholders}) AND COALESCE(pathway,'plab') = ?",
                     vals + [int(i) for i in ids] + [pathway])
        conn.commit()
        flash(f'Updated {len(ids)} record(s).', 'success')
    except Exception as e:
        logging.error(f"ops_bulk_edit {table}: {e}")
        flash('Error applying bulk edit', 'error')
    conn.close()
    return redirect(url_for('ops_bulk', pathway=pathway, table=table))


@app.route('/operations/record/<table>/<int:rec_id>/edit', methods=['GET', 'POST'])
@login_required
def ops_record_edit(table, rec_id):
    """Edit a single ops section record in place — from the client profile drawer,
    no hunting for it in the section (founder 2026-07-18). Generic + whitelisted:
    reuses _bulk_columns so every field renders with the right type + dropdowns,
    prefilled from the record. Tracks who edited it and when. Works for every
    section in every pathway from one route."""
    if table not in OPS_PATHWAY_TABLES:
        return "Unknown section", 404
    conn = get_db()
    rec = conn.execute("SELECT * FROM {} WHERE id = ?".format(table), (rec_id,)).fetchone()
    if not rec:
        conn.close()
        return "Record not found", 404
    rec = dict(rec)
    pathway = (rec.get('pathway') or 'plab')
    cols = _bulk_columns(conn, table, pathway)

    if request.method == 'POST':
        sets, vals = [], []
        for c in cols:
            key = 'f_' + c['name']
            if key not in request.form:
                continue
            v = request.form.get(key, '')
            if c['numeric']:
                try: v = float(v) if v != '' else None
                except (TypeError, ValueError): v = None
            sets.append("{} = ?".format(c['name']))
            vals.append(v)
        # Edit tracking — WHO changed it and WHEN.
        uid = session.get('user_id')
        uname = ''
        try:
            _e = conn.execute("SELECT name FROM employees WHERE id = ?", (uid,)).fetchone()
            uname = (_e['name'] if _e else '') or ''
        except Exception:
            pass
        sets += ["updated_at = CURRENT_TIMESTAMP", "updated_by = ?", "updated_by_name = ?"]
        vals += [uid, uname]
        try:
            conn.execute("UPDATE {} SET {} WHERE id = ?".format(table, ', '.join(sets)), vals + [rec_id])
            conn.commit()
        except Exception as e:
            logging.error("ops_record_edit %s#%s: %s", table, rec_id, e)
            conn.rollback()
            conn.close()
            flash('Could not save the change — please try again.', 'error')
            return redirect(url_for('ops_record_edit', table=table, rec_id=rec_id,
                                    embed=request.args.get('embed')))
        conn.close()
        # Land on a NON-/edit URL so the drawer detects the save and closes+refreshes.
        return redirect(url_for('ops_record_saved'))

    conn.close()
    label = OPS_SECTION_LABELS.get(table, table.replace('ops_', '').replace('_', ' ').title())
    client_name = (("{} {} {}".format(rec.get('prefix') or '', rec.get('first_name') or '',
                                      rec.get('last_name') or '')).strip()) or (rec.get('registration_number') or '')
    return render_template('ops_record_edit.html', table=table, rec=rec, cols=cols,
                           section_label=label, client_name=client_name,
                           embed=request.args.get('embed'))


@app.route('/operations/record/saved')
@login_required
def ops_record_saved():
    """Tiny landing page after a drawer edit — its URL has no /edit, so the parent
    drawer script closes the drawer and reloads the profile."""
    return ("<!doctype html><meta charset=utf-8>"
            "<body style='font-family:system-ui;padding:24px;color:#166534;'>"
            "✓ Saved. Closing…</body>")


