# ── EPIC + GMC CSV Import (Zoho export) ─────────────────────────────
def _parse_zoho_date(val):
    """Convert Zoho date strings like '25-Dec-2025' or epoch ms to YYYY-MM-DD."""
    if not val or (isinstance(val, str) and not val.strip()):
        return ''
    # Handle datetime objects from openpyxl
    from datetime import datetime as dt, date as dt_date
    if isinstance(val, (dt, dt_date)):
        return val.strftime('%Y-%m-%d')
    val = str(val).strip()
    # epoch milliseconds
    if val.isdigit() and len(val) > 10:
        try:
            return dt.utcfromtimestamp(int(val) / 1000).strftime('%Y-%m-%d')
        except Exception:
            return ''
    # DD-Mon-YYYY
    for fmt in ('%d-%b-%Y', '%Y-%m-%d', '%d-%m-%Y'):
        try:
            return dt.strptime(val, fmt).strftime('%Y-%m-%d')
        except ValueError:
            continue
    return val


def _extract_reg_number(candidate_str):
    """Extract registration number from 'Dr.Name - GCUKIP/XX-XX/XXX' format."""
    if not candidate_str:
        return ''
    candidate_str = str(candidate_str).strip()
    # Try ' - ' separator first (old format: "Dr.Name - GCUKIP/2019/001")
    parts = candidate_str.rsplit(' - ', 1)
    if len(parts) == 2:
        return parts[1].strip()
    # Look for GCUKIP anywhere after a dash/space (new format: "Dr.Name -GCUKIP/24-25/002")
    m = re.search(r'[-\s](GCUKIP/\S+)', candidate_str)
    if m:
        return m.group(1).strip()
    return ''


def _read_import_file(data_file):
    """Read CSV or XLSX file and return list of dicts (rows).
    Supports both .csv and .xlsx uploads from Zoho."""
    import csv, io
    filename = data_file.filename.lower()
    if filename.endswith('.xlsx'):
        import openpyxl
        wb = openpyxl.load_workbook(data_file.stream, read_only=True)
        ws = wb.active
        headers = [cell.value for cell in ws[1]]
        rows = []
        for row in ws.iter_rows(min_row=2, values_only=True):
            row_dict = {}
            for i, val in enumerate(row):
                if i < len(headers) and headers[i]:
                    row_dict[headers[i]] = val if val is not None else ''
            rows.append(row_dict)
        wb.close()
        return rows
    elif filename.endswith('.csv'):
        data_stream = io.StringIO(data_file.stream.read().decode('utf-8-sig'))
        return list(csv.DictReader(data_stream))
    else:
        raise ValueError('Please upload a CSV or XLSX file')


@app.route('/operations/epic/import', methods=['GET', 'POST'])
@admin_required
def ops_epic_import():
    """Import EPIC registration records from Zoho CSV/XLSX export.
    Upserts: updates existing records by registration_number, inserts new ones."""
    if request.method == 'POST':
        data_file = request.files.get('csv_file')
        if not data_file:
            flash('Please upload a file', 'error')
            return redirect(request.url)
        try:
            rows = _read_import_file(data_file)
            conn = get_db()
            imported = updated = skipped = 0
            for row in rows:
                candidate = str(row.get('Enter Candidate Name', '')).strip()
                reg_num = _extract_reg_number(candidate)
                if not reg_num:
                    skipped += 1
                    continue
                client = conn.execute(
                    "SELECT registration_number FROM plab_clients WHERE registration_number = ?",
                    (reg_num,)
                ).fetchone()
                if not client:
                    skipped += 1
                    continue

                _s = lambda k: str(row.get(k, '') or '').strip()
                epic_reg = _s('EPIC Registration')
                epic_status = _s('EPIC Status')
                notary = _s('Notary Camp')
                reg_date = _parse_zoho_date(row.get('Registration Date', ''))
                doc_stage = _s('Documents Stage')
                doc_status = _s('Document Stage Status')
                login_id = _s('Login ID')
                login_pwd = _s('Login Pwd')
                sq1 = _s('Secret Question 1'); sa1 = _s('Secret Answer 1')
                sq2 = _s('Secret Question 2'); sa2 = _s('Secret Answer 2')
                sq3 = _s('Secret Question 3'); sa3 = _s('Secret Answer 3')
                sq4 = _s('Secret Question 4'); sa4 = _s('Secret Answer 4')
                epic_id = _s('EPIC ID Number')
                notary_login = _s('Notary Camp Login')
                notary_pwd = _s('Notary Camp Password')

                exists = conn.execute(
                    "SELECT id FROM ops_epic_registration WHERE registration_number = ?",
                    (reg_num,)
                ).fetchone()
                if exists:
                    conn.execute('''UPDATE ops_epic_registration SET
                        epic_registration=?, epic_status=?, notary_camp=?,
                        registration_date=?, documents_stage=?, document_stage_status=?,
                        login_id=?, login_pwd=?,
                        secret_question_1=?, secret_answer_1=?,
                        secret_question_2=?, secret_answer_2=?,
                        secret_question_3=?, secret_answer_3=?,
                        secret_question_4=?, secret_answer_4=?,
                        epic_id_number=?, notary_camp_login=?, notary_camp_password=?,
                        updated_at=? WHERE id=?''', (
                        epic_reg, epic_status, notary, reg_date, doc_stage, doc_status,
                        login_id, login_pwd, sq1, sa1, sq2, sa2, sq3, sa3, sq4, sa4,
                        epic_id, notary_login, notary_pwd, datetime.now(), exists['id']
                    ))
                    updated += 1
                else:
                    conn.execute('''INSERT INTO ops_epic_registration (
                        registration_number, epic_registration, epic_status,
                        notary_camp, registration_date, documents_stage, document_stage_status,
                        login_id, login_pwd,
                        secret_question_1, secret_answer_1,
                        secret_question_2, secret_answer_2,
                        secret_question_3, secret_answer_3,
                        secret_question_4, secret_answer_4,
                        epic_id_number, notary_camp_login, notary_camp_password,
                        created_by
                    ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)''', (
                        reg_num, epic_reg, epic_status, notary, reg_date, doc_stage, doc_status,
                        login_id, login_pwd, sq1, sa1, sq2, sa2, sq3, sa3, sq4, sa4,
                        epic_id, notary_login, notary_pwd, session.get('user_id', 0)
                    ))
                    imported += 1
            conn.commit()
            conn.close()
            flash(f'EPIC import complete: {imported} new, {updated} updated, {skipped} skipped', 'success')
            return redirect(url_for('ops_epic_list'))
        except Exception as e:
            logging.error(f"EPIC import error: {e}")
            flash(f'Import error: {e}', 'error')
            return redirect(request.url)
    return render_template('ops_epic_import.html', active_ops_page='epic')


@app.route('/operations/gmc/import', methods=['GET', 'POST'])
@admin_required
def ops_gmc_import():
    """Import GMC registration records from Zoho CSV/XLSX export.
    Upserts: updates existing records by registration_number, inserts new ones."""
    if request.method == 'POST':
        data_file = request.files.get('csv_file')
        if not data_file:
            flash('Please upload a file', 'error')
            return redirect(request.url)
        try:
            rows = _read_import_file(data_file)
            conn = get_db()
            imported = updated = skipped = 0
            for row in rows:
                candidate = str(row.get('Enter Candidate Name', '')).strip()
                reg_num = _extract_reg_number(candidate)
                if not reg_num:
                    skipped += 1
                    continue
                client = conn.execute(
                    "SELECT registration_number FROM plab_clients WHERE registration_number = ?",
                    (reg_num,)
                ).fetchone()
                if not client:
                    skipped += 1
                    continue

                _s = lambda k: str(row.get(k, '') or '').strip()
                gmc_ref = _s('GMC Reference Number')
                login_pwd = _s('Login Pwd')
                sq = _s('Secret Question 1')
                sa = _s('Secret Answer')
                gmc_setup = _s('GMC Setup')
                reg_date = _parse_zoho_date(row.get('Registration Date', ''))
                eng_exam = _s('English Exam')
                exam_date = _parse_zoho_date(row.get('Exam Date', ''))
                eng_expiry = _parse_zoho_date(row.get('English Result Expiry Date', ''))
                license_val = _s('License') or _s('License ') or _s('Licence')
                license_date = _parse_zoho_date(row.get('License Received Date', ''))
                candidate_email = _s('Candidate Email')
                mobile_number = _s('Mobile Number')

                exists = conn.execute(
                    "SELECT id FROM ops_gmc_registration WHERE registration_number = ?",
                    (reg_num,)
                ).fetchone()
                if exists:
                    conn.execute('''UPDATE ops_gmc_registration SET
                        gmc_reference_number=?, login_pwd=?,
                        secret_question=?, secret_answer=?,
                        gmc_setup=?, registration_date=?,
                        english_exam=?, exam_date=?, english_result_expiry_date=?,
                        license=?, license_received_date=?,
                        candidate_email=?, mobile_number=?,
                        updated_at=? WHERE id=?''', (
                        gmc_ref, login_pwd, sq, sa, gmc_setup, reg_date,
                        eng_exam, exam_date, eng_expiry, license_val, license_date,
                        candidate_email, mobile_number,
                        datetime.now(), exists['id']
                    ))
                    updated += 1
                else:
                    conn.execute('''INSERT INTO ops_gmc_registration (
                        registration_number, gmc_reference_number, login_pwd,
                        secret_question, secret_answer,
                        gmc_setup, registration_date,
                        english_exam, exam_date, english_result_expiry_date,
                        license, license_received_date,
                        candidate_email, mobile_number,
                        created_by
                    ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)''', (
                        reg_num, gmc_ref, login_pwd, sq, sa, gmc_setup, reg_date,
                        eng_exam, exam_date, eng_expiry, license_val, license_date,
                        candidate_email, mobile_number,
                        session.get('user_id', 0)
                    ))
                    imported += 1
            conn.commit()
            conn.close()
            flash(f'GMC import complete: {imported} new, {updated} updated, {skipped} skipped', 'success')
            return redirect(url_for('ops_gmc_list'))
        except Exception as e:
            logging.error(f"GMC import error: {e}")
            flash(f'Import error: {e}', 'error')
            return redirect(request.url)
    return render_template('ops_gmc_import.html', active_ops_page='gmc')


# =====================================================================
# ====================  SALES CRM (leads, closures, targets, calls)  ===
# =====================================================================
def ensure_sales_crm_tables():
    """Create the Sales CRM tables (leads, closures, targets, call logs,
    stage definitions, team roster). Idempotent on every boot."""
    try:
        conn = get_db()
        # 1) Configurable lead pipeline stages
        conn.execute('''CREATE TABLE IF NOT EXISTS sales_lead_stages (
            id SERIAL PRIMARY KEY,
            name VARCHAR(80) NOT NULL,
            sort_order INTEGER DEFAULT 0,
            is_won INTEGER DEFAULT 0,
            is_lost INTEGER DEFAULT 0,
            color VARCHAR(20),
            is_active INTEGER DEFAULT 1,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )''')
        # 2) Sales team roster (which employees are sales reps; who reports to whom)
        conn.execute('''CREATE TABLE IF NOT EXISTS sales_team (
            employee_id INTEGER PRIMARY KEY REFERENCES employees(id) ON DELETE CASCADE,
            manager_employee_id INTEGER REFERENCES employees(id),
            role VARCHAR(20) DEFAULT 'rep',
            is_active INTEGER DEFAULT 1,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )''')
        # 3) Hot leads
        conn.execute('''CREATE TABLE IF NOT EXISTS sales_leads (
            id SERIAL PRIMARY KEY,
            lead_name VARCHAR(160) NOT NULL,
            company VARCHAR(160),
            phone VARCHAR(40),
            email VARCHAR(160),
            source VARCHAR(80),
            product_id INTEGER REFERENCES products_services(id),
            stream_id INTEGER REFERENCES revenue_streams(id),
            stage_id INTEGER REFERENCES sales_lead_stages(id),
            owner_employee_id INTEGER REFERENCES employees(id),
            expected_value NUMERIC(14,2) DEFAULT 0,
            expected_close_date DATE,
            is_hot INTEGER DEFAULT 0,
            notes TEXT,
            created_by INTEGER REFERENCES employees(id),
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )''')
        # AUD rate-lock (AMC 1 / AMC 2): frozen at lead generation, never re-floats.
        # amc_fx_rate = live AUD→INR; amc_fx_effective = live * (1+markup%); amc_inr_amount
        # = aud * effective (what the client pays, collected in INR). Date+time in locked_at.
        for _c, _t in (('amc_plan_type', 'TEXT'), ('amc_currency', 'TEXT'), ('amc_aud_amount', 'NUMERIC(12,2)'),
                       ('amc_fx_rate', 'NUMERIC(10,4)'), ('amc_fx_markup', 'NUMERIC(5,2)'),
                       ('amc_fx_effective', 'NUMERIC(10,4)'), ('amc_inr_amount', 'NUMERIC(14,2)'),
                       ('amc_fx_locked_at', 'TIMESTAMP'), ('amc_payment_route', 'TEXT')):
            try:
                conn.execute(f"ALTER TABLE sales_leads ADD COLUMN IF NOT EXISTS {_c} {_t}")
                conn.commit()
            except Exception:
                try: conn.rollback()
                except Exception: pass
        # 4) Sales closures (won deals; margin auto-computed)
        conn.execute('''CREATE TABLE IF NOT EXISTS sales_closures (
            id SERIAL PRIMARY KEY,
            lead_id INTEGER REFERENCES sales_leads(id) ON DELETE SET NULL,
            employee_id INTEGER REFERENCES employees(id),
            product_id INTEGER REFERENCES products_services(id),
            product_name VARCHAR(200),
            project_id INTEGER REFERENCES projects(id),
            client_name VARCHAR(160),
            revenue NUMERIC(14,2) DEFAULT 0,
            cost NUMERIC(14,2) DEFAULT 0,
            margin NUMERIC(14,2) DEFAULT 0,
            currency VARCHAR(8) DEFAULT 'INR',
            close_date DATE,
            notes TEXT,
            created_by INTEGER REFERENCES employees(id),
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )''')
        # 5) Sales targets (margin-based). period_type = 'annual' | 'quarter' | 'month'
        #    period_value: year for annual; 1-4 for quarter; 1-12 for month
        conn.execute('''CREATE TABLE IF NOT EXISTS sales_targets (
            id SERIAL PRIMARY KEY,
            employee_id INTEGER REFERENCES employees(id) ON DELETE CASCADE,
            year INTEGER NOT NULL,
            period_type VARCHAR(10) NOT NULL,
            period_value INTEGER NOT NULL,
            target_margin NUMERIC(14,2) DEFAULT 0,
            notes TEXT,
            created_by INTEGER REFERENCES employees(id),
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE (employee_id, year, period_type, period_value)
        )''')
        # 6) Daily call logs (rep enters at end of day)
        conn.execute('''CREATE TABLE IF NOT EXISTS sales_call_logs (
            id SERIAL PRIMARY KEY,
            employee_id INTEGER REFERENCES employees(id) ON DELETE CASCADE,
            log_date DATE NOT NULL,
            num_calls INTEGER DEFAULT 0,
            talk_time_minutes INTEGER DEFAULT 0,
            notes TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE (employee_id, log_date)
        )''')
        conn.commit()
        # Seed default stages if empty
        cnt = conn.execute('SELECT COUNT(*) AS c FROM sales_lead_stages').fetchone()
        if cnt and (cnt['c'] if 'c' in cnt.keys() else cnt[0]) == 0:
            defaults = [
                ('New', 1, 0, 0, '#3b82f6'),
                ('Contacted', 2, 0, 0, '#8b5cf6'),
                ('Qualified', 3, 0, 0, '#06b6d4'),
                ('Demo / Meeting', 4, 0, 0, '#f59e0b'),
                ('Proposal Sent', 5, 0, 0, '#f97316'),
                ('Negotiation', 6, 0, 0, '#eab308'),
                ('Closed Won', 7, 1, 0, '#10b981'),
                ('Closed Lost', 8, 0, 1, '#ef4444'),
            ]
            for d in defaults:
                conn.execute(
                    'INSERT INTO sales_lead_stages (name, sort_order, is_won, is_lost, color) VALUES (?, ?, ?, ?, ?)',
                    d
                )
            conn.commit()
        conn.close()
        logging.info("Sales CRM tables ensured.")
    except Exception as e:
        logging.error(f"ensure_sales_crm_tables: {e}")


# ---- Visibility helpers -------------------------------------------------
def get_sales_role(user):
    """Return 'admin', 'viewer', 'manager', 'rep', or None (no sales access).

    Roles:
      - admin: full control (is_admin=1)
      - viewer: read-only, sees all data like admin, not a sales seller
      - manager: sees self + direct reports, can write own data
      - rep (Sales Member): sees only self, can write own data
    """
    if not user:
        return None
    if user['is_admin'] == 1:
        return 'admin'
    try:
        conn = get_db()
        # First: check module_access for admin_view level on sales module.
        # Viewer role is now driven by Module Access (not Sales Team).
        ma = conn.execute(
            "SELECT access_level FROM module_access "
            "WHERE employee_id = ? AND module = 'sales' AND is_active = 1",
            (user['id'],)
        ).fetchone()
        if ma and (ma['access_level'] or 'standard').lower() == 'admin_view':
            conn.close()
            return 'viewer'
        # Otherwise, fall back to sales_team membership for rep/manager/legacy viewer.
        row = conn.execute(
            'SELECT role FROM sales_team WHERE employee_id = ? AND is_active = 1',
            (user['id'],)
        ).fetchone()
        conn.close()
        if not row:
            return None
        r = (row['role'] or 'rep').lower()
        if r == 'manager':
            return 'manager'
        if r == 'viewer':
            return 'viewer'
        return 'rep'
    except Exception:
        return None


def is_sales_viewer(user):
    """True if the user has sales viewer role (read-only)."""
    return get_sales_role(user) == 'viewer'


def get_visible_sales_employee_ids(user):
    """Return list of employee ids whose data this user can see.
    - admin → all sales_team employees (excluding viewers)
    - viewer → all sales_team employees (excluding viewers) — view-only like admin
    - manager → self + reps who have manager_employee_id = user.id
    - rep → just [self]

    Viewers are excluded from the returned list because they don't own
    leads/closures/targets — there is nothing to show under a viewer.
    """
    role = get_sales_role(user)
    if not role:
        return []
    try:
        conn = get_db()
        if role in ('admin', 'viewer'):
            rows = conn.execute(
                "SELECT employee_id FROM sales_team WHERE is_active = 1 "
                "AND COALESCE(role, 'rep') != 'viewer'"
            ).fetchall()
            ids = [r['employee_id'] for r in rows]
            # Admin is always included (even if not in sales_team) so they see their own legacy data
            if role == 'admin' and user['id'] not in ids:
                ids.append(user['id'])
        elif role == 'manager':
            rows = conn.execute(
                'SELECT employee_id FROM sales_team '
                'WHERE is_active = 1 AND (employee_id = ? OR manager_employee_id = ?)',
                (user['id'], user['id'])
            ).fetchall()
            ids = [r['employee_id'] for r in rows]
        else:
            ids = [user['id']]
        conn.close()
        return ids
    except Exception as e:
        logging.error(f"get_visible_sales_employee_ids: {e}")
        return [user['id']]


def sales_crm_required(f):
    """Decorator: sales module access AND a sales role (admin/viewer/manager/rep)."""
    @wraps(f)
    def wrapper(*args, **kwargs):
        if 'user_id' not in session:
            return redirect(url_for('login'))
        user = get_user()
        if not has_section_permission(user, 'sales', 'meetings', 'view'):
            flash('Sales module access required', 'error')
            return redirect(url_for('dashboard'))
        if not get_sales_role(user):
            flash('You are not part of the Sales team. Ask an admin to add you under Sales → Team.', 'error')
            # Redirect to main dashboard (not sales_dashboard) to avoid redirect loop,
            # since sales_dashboard itself is decorated with sales_crm_required.
            return redirect(url_for('dashboard'))
        return f(*args, **kwargs)
    return wrapper


def sales_write_required(f):
    """Decorator: blocks viewers from write endpoints (lead/closure/target/call add/edit/delete)."""
    @wraps(f)
    def wrapper(*args, **kwargs):
        if 'user_id' not in session:
            return redirect(url_for('login'))
        user = get_user()
        if not has_section_permission(user, 'sales', 'meetings', 'view'):
            flash('Sales module access required', 'error')
            return redirect(url_for('dashboard'))
        role = get_sales_role(user)
        if not role:
            flash('You are not part of the Sales team.', 'error')
            return redirect(url_for('dashboard'))
        if role == 'viewer':
            flash('Viewer role — Sales CRM is read-only for you.', 'error')
            return redirect(url_for('sales_dashboard'))
        return f(*args, **kwargs)
    return wrapper


# ---- Sales dashboard helpers -------------------------------------------
def _get_sales_member_snapshot(conn, eid, year, month, quarter):
    """Compute a single sales team member's dashboard data — targets,
    achieved margin, lead/call activity, and the top of their leads/closures lists.
    Used by both the personal 'My Sales' view and the admin drill-down."""
    ta = conn.execute(
        "SELECT COALESCE(SUM(target_margin),0) AS t FROM sales_targets "
        "WHERE employee_id = ? AND year = ? AND period_type = 'annual'",
        (eid, year)
    ).fetchone()
    tq = conn.execute(
        "SELECT COALESCE(SUM(target_margin),0) AS t FROM sales_targets "
        "WHERE employee_id = ? AND year = ? AND period_type = 'quarter' AND period_value = ?",
        (eid, year, quarter)
    ).fetchone()
    tm = conn.execute(
        "SELECT COALESCE(SUM(target_margin),0) AS t FROM sales_targets "
        "WHERE employee_id = ? AND year = ? AND period_type = 'month' AND period_value = ?",
        (eid, year, month)
    ).fetchone()
    aa = conn.execute(
        "SELECT COALESCE(SUM(margin),0) AS a FROM sales_closures "
        "WHERE employee_id = ? AND EXTRACT(YEAR FROM close_date) = ?",
        (eid, year)
    ).fetchone()
    aq_start = (quarter - 1) * 3 + 1
    aq = conn.execute(
        "SELECT COALESCE(SUM(margin),0) AS a FROM sales_closures "
        "WHERE employee_id = ? AND EXTRACT(YEAR FROM close_date) = ? "
        "AND EXTRACT(MONTH FROM close_date) BETWEEN ? AND ?",
        (eid, year, aq_start, aq_start + 2)
    ).fetchone()
    am = conn.execute(
        "SELECT COALESCE(SUM(margin),0) AS a FROM sales_closures "
        "WHERE employee_id = ? AND EXTRACT(YEAR FROM close_date) = ? "
        "AND EXTRACT(MONTH FROM close_date) = ?",
        (eid, year, month)
    ).fetchone()
    leads_open = conn.execute(
        "SELECT COUNT(*) AS c FROM sales_leads sl "
        "LEFT JOIN sales_lead_stages s ON sl.stage_id = s.id "
        "WHERE sl.owner_employee_id = ? AND COALESCE(s.is_won,0)=0 AND COALESCE(s.is_lost,0)=0",
        (eid,)
    ).fetchone()
    leads_hot = conn.execute(
        "SELECT COUNT(*) AS c FROM sales_leads "
        "WHERE owner_employee_id = ? AND is_hot = 1",
        (eid,)
    ).fetchone()
    calls_month = conn.execute(
        "SELECT COALESCE(SUM(num_calls),0) AS calls, COALESCE(SUM(talk_time_minutes),0) AS mins "
        "FROM sales_call_logs WHERE employee_id = ? "
        "AND EXTRACT(YEAR FROM log_date) = ? AND EXTRACT(MONTH FROM log_date) = ?",
        (eid, year, month)
    ).fetchone()
    my_leads = conn.execute(
        "SELECT sl.id, sl.lead_name, sl.company, sl.expected_value, sl.expected_close_date, sl.is_hot, "
        "s.name AS stage_name, s.color AS stage_color "
        "FROM sales_leads sl LEFT JOIN sales_lead_stages s ON sl.stage_id = s.id "
        "WHERE sl.owner_employee_id = ? "
        "AND COALESCE(s.is_won,0)=0 AND COALESCE(s.is_lost,0)=0 "
        "ORDER BY sl.is_hot DESC, sl.expected_close_date NULLS LAST LIMIT 10",
        (eid,)
    ).fetchall()
    my_closures = conn.execute(
        "SELECT id, client_name, product_name, revenue, margin, close_date "
        "FROM sales_closures WHERE employee_id = ? "
        "AND EXTRACT(YEAR FROM close_date) = ? "
        "ORDER BY close_date DESC LIMIT 6",
        (eid, year)
    ).fetchall()
    annual_t = float(ta['t'] or 0); annual_a = float(aa['a'] or 0)
    quarter_t = float(tq['t'] or 0); quarter_a = float(aq['a'] or 0)
    month_t = float(tm['t'] or 0); month_a = float(am['a'] or 0)
    return {
        'annual_target': annual_t, 'annual_achieved': annual_a,
        'annual_diff': annual_a - annual_t,
        'annual_pct': (annual_a / annual_t * 100) if annual_t > 0 else 0,
        'quarter_target': quarter_t, 'quarter_achieved': quarter_a,
        'quarter_diff': quarter_a - quarter_t,
        'quarter_pct': (quarter_a / quarter_t * 100) if quarter_t > 0 else 0,
        'month_target': month_t, 'month_achieved': month_a,
        'month_diff': month_a - month_t,
        'month_pct': (month_a / month_t * 100) if month_t > 0 else 0,
        'leads_open': leads_open['c'] if leads_open else 0,
        'leads_hot': leads_hot['c'] if leads_hot else 0,
        'calls_month': calls_month['calls'] if calls_month else 0,
        'talk_minutes_month': calls_month['mins'] if calls_month else 0,
        'my_leads': my_leads,
        'my_closures': my_closures,
    }


def _render_team_overview(user, role, year, month, quarter, month_label):
    """Shared team overview rendering for admin / viewer / manager roles.
    Each per-member row is clickable and drills into /sales/member/<id>."""
    visible_ids = get_visible_sales_employee_ids(user)
    if not visible_ids:
        return render_template('sales_crm_dashboard.html', user=user, role=role,
                               rows=[], totals=None, top_products=[], hot_leads=[],
                               news=[], year=year, month=month, quarter=quarter,
                               month_label=month_label, is_admin=(role == 'admin'),
                    active_section='sales')
    placeholders = ','.join(['?'] * len(visible_ids))
    conn = get_db()
    rep_rows_raw = conn.execute(
        f'SELECT e.id, e.name, e.emp_code, e.photo_url, st.role '
        f'FROM employees e JOIN sales_team st ON st.employee_id = e.id '
        f'WHERE st.is_active = 1 AND e.id IN ({placeholders}) '
        f'ORDER BY e.name',
        visible_ids
    ).fetchall()
    rows = []
    tot_annual_t = tot_quarter_t = tot_month_t = 0.0
    tot_annual_a = tot_quarter_a = tot_month_a = 0.0
    for r in rep_rows_raw:
        snap = _get_sales_member_snapshot(conn, r['id'], year, month, quarter)
        rows.append({
            'id': r['id'], 'name': r['name'], 'emp_code': r['emp_code'],
            'photo_url': r['photo_url'], 'role': r['role'] or 'rep',
            'annual_target': snap['annual_target'], 'annual_achieved': snap['annual_achieved'],
            'annual_diff': snap['annual_diff'], 'annual_pct': snap['annual_pct'],
            'quarter_target': snap['quarter_target'], 'quarter_achieved': snap['quarter_achieved'],
            'quarter_diff': snap['quarter_diff'], 'quarter_pct': snap['quarter_pct'],
            'month_target': snap['month_target'], 'month_achieved': snap['month_achieved'],
            'month_diff': snap['month_diff'], 'month_pct': snap['month_pct'],
            'leads_open': snap['leads_open'], 'leads_hot': snap['leads_hot'],
            'calls_month': snap['calls_month'],
            'talk_minutes_month': snap['talk_minutes_month'],
        })
        tot_annual_t += snap['annual_target']; tot_annual_a += snap['annual_achieved']
        tot_quarter_t += snap['quarter_target']; tot_quarter_a += snap['quarter_achieved']
        tot_month_t += snap['month_target']; tot_month_a += snap['month_achieved']
    totals = {
        'annual_target': tot_annual_t, 'annual_achieved': tot_annual_a,
        'annual_diff': tot_annual_a - tot_annual_t,
        'quarter_target': tot_quarter_t, 'quarter_achieved': tot_quarter_a,
        'quarter_diff': tot_quarter_a - tot_quarter_t,
        'month_target': tot_month_t, 'month_achieved': tot_month_a,
        'month_diff': tot_month_a - tot_month_t,
    }
    top_products = conn.execute(
        f"SELECT product_name, COUNT(*) AS deals, COALESCE(SUM(revenue),0) AS revenue, "
        f"COALESCE(SUM(margin),0) AS margin "
        f"FROM sales_closures WHERE employee_id IN ({placeholders}) "
        f"AND EXTRACT(YEAR FROM close_date) = ? AND EXTRACT(MONTH FROM close_date) = ? "
        f"GROUP BY product_name ORDER BY margin DESC LIMIT 8",
        list(visible_ids) + [year, month]
    ).fetchall()
    hot_leads = conn.execute(
        f"SELECT sl.id, sl.lead_name, sl.company, sl.expected_value, sl.expected_close_date, "
        f"e.name AS owner_name, e.id AS owner_id, s.name AS stage_name, s.color AS stage_color "
        f"FROM sales_leads sl "
        f"LEFT JOIN employees e ON sl.owner_employee_id = e.id "
        f"LEFT JOIN sales_lead_stages s ON sl.stage_id = s.id "
        f"WHERE sl.is_hot = 1 AND sl.owner_employee_id IN ({placeholders}) "
        f"ORDER BY sl.expected_close_date NULLS LAST LIMIT 10",
        visible_ids
    ).fetchall()
    news = conn.execute(
        "SELECT n.*, e.name AS posted_by_name, e.photo_url "
        "FROM sales_news n JOIN employees e ON n.posted_by = e.id "
        "WHERE n.is_active = 1 ORDER BY n.created_at DESC LIMIT 3"
    ).fetchall()
    conn.close()
    return render_template('sales_crm_dashboard.html', user=user, role=role,
                           rows=rows, totals=totals,
                           top_products=top_products, hot_leads=hot_leads,
                           news=news, year=year, month=month, quarter=quarter,
                           month_label=month_label, is_admin=(role == 'admin'),
                    active_section='sales')


# ---- Sales dashboard (unified CRM landing) -----------------------------
@app.route('/sales')
@login_required
@sales_crm_required
def sales_dashboard():
    """Unified Sales landing page. Role-aware:
      - rep: personal 'My Sales' view (hero stats, quick actions, my leads)
      - admin / viewer / manager: team overview with clickable member drill-down
    """
    import traceback
    try:
        user = get_user()
        role = get_sales_role(user)
        now = datetime.now()
        year = int(request.args.get('year') or now.year)
        month = int(request.args.get('month') or now.month)
        quarter = (month - 1) // 3 + 1
        month_label = calendar.month_name[month] + ' ' + str(year)

        if role == 'rep':
            conn = get_db()
            snap = _get_sales_member_snapshot(conn, user['id'], year, month, quarter)
            try:
                news = conn.execute(
                    "SELECT n.*, e.name AS posted_by_name, e.photo_url "
                    "FROM sales_news n JOIN employees e ON n.posted_by = e.id "
                    "WHERE n.is_active = 1 ORDER BY n.created_at DESC LIMIT 3"
                ).fetchall()
            except Exception as news_err:
                logging.error(f"sales_dashboard news fetch: {news_err}")
                try:
                    conn.rollback()
                except Exception:
                    pass
                news = []
            conn.close()
            return render_template('sales_my.html', user=user, role=role, viewing='self',
                                   member=user, snap=snap, news=news,
                                   year=year, month=month, quarter=quarter,
                                   month_label=month_label,
                    active_section='sales')
        # admin / viewer / manager
        return _render_team_overview(user, role, year, month, quarter, month_label)
    except Exception as e:
        logging.error(f"sales_dashboard ERROR: {e}\n{traceback.format_exc()}")
        flash(f'Sales dashboard error: {type(e).__name__}: {e}', 'error')
        return redirect(url_for('dashboard'))


