# ---- Lead stages admin -------------------------------------------------
@app.route('/sales/stages', methods=['GET', 'POST'])
@login_required
@sales_crm_required
def sales_stages():
    user = get_user()
    role = get_sales_role(user)
    if role != 'admin':
        flash('Admins only', 'error')
        return redirect(url_for('sales_crm_dashboard'))
    conn = get_db()
    if request.method == 'POST':
        action = request.form.get('action')
        if action == 'add':
            name = (request.form.get('name') or '').strip()
            if name:
                so = int(request.form.get('sort_order') or 0)
                color = (request.form.get('color') or '#3b82f6').strip()
                is_won = 1 if request.form.get('is_won') else 0
                is_lost = 1 if request.form.get('is_lost') else 0
                conn.execute(
                    'INSERT INTO sales_lead_stages (name, sort_order, color, is_won, is_lost) VALUES (?, ?, ?, ?, ?)',
                    (name, so, color, is_won, is_lost)
                )
                conn.commit()
                flash('Stage added', 'success')
        elif action == 'edit':
            sid = int(request.form.get('id'))
            conn.execute(
                'UPDATE sales_lead_stages SET name=?, sort_order=?, color=?, is_won=?, is_lost=?, is_active=? WHERE id=?',
                (
                    (request.form.get('name') or '').strip(),
                    int(request.form.get('sort_order') or 0),
                    (request.form.get('color') or '#3b82f6').strip(),
                    1 if request.form.get('is_won') else 0,
                    1 if request.form.get('is_lost') else 0,
                    1 if request.form.get('is_active') else 0,
                    sid
                )
            )
            conn.commit()
            flash('Stage updated', 'success')
        elif action == 'delete':
            sid = int(request.form.get('id'))
            conn.execute('UPDATE sales_lead_stages SET is_active = 0 WHERE id = ?', (sid,))
            conn.commit()
            flash('Stage deactivated', 'success')
        conn.close()
        return redirect(url_for('sales_stages'))

    stages = conn.execute(
        'SELECT * FROM sales_lead_stages ORDER BY is_active DESC, sort_order, name'
    ).fetchall()
    conn.close()
    return render_template('sales_stages.html', user=user, stages=stages,
                    active_section='sales')


# ---- Sales team admin --------------------------------------------------
@app.route('/sales/team', methods=['GET', 'POST'])
@login_required
@sales_crm_required
def sales_team_admin():
    user = get_user()
    role = get_sales_role(user)
    if role != 'admin':
        flash('Admins only', 'error')
        return redirect(url_for('sales_crm_dashboard'))
    conn = get_db()
    if request.method == 'POST':
        action = request.form.get('action')
        if action == 'add':
            eid = int(request.form.get('employee_id'))
            r = (request.form.get('role') or 'rep').strip().lower()
            # Manager role is no longer offered in the UI; only accept rep/viewer from new adds.
            # ('manager' is still tolerated from legacy edit rows.)
            if r not in ('rep', 'manager', 'viewer'):
                r = 'rep'
            try:
                # No manager assignment — manager_employee_id is always NULL now.
                conn.execute(
                    'INSERT INTO sales_team (employee_id, manager_employee_id, role, is_active) VALUES (?, NULL, ?, 1) '
                    'ON CONFLICT (employee_id) DO UPDATE SET manager_employee_id = NULL, '
                    'role = EXCLUDED.role, is_active = 1',
                    (eid, r)
                )
                conn.commit()
                flash('Sales team member saved', 'success')
            except Exception as e:
                conn.rollback()
                flash(f'Could not save: {e}', 'error')
        elif action == 'update':
            eid = int(request.form.get('employee_id'))
            r = (request.form.get('role') or 'rep').strip().lower()
            if r not in ('rep', 'manager', 'viewer'):
                r = 'rep'
            try:
                # Role change only; manager hierarchy is no longer used.
                conn.execute(
                    'UPDATE sales_team SET role = ?, manager_employee_id = NULL WHERE employee_id = ?',
                    (r, eid)
                )
                conn.commit()
                flash('Member updated', 'success')
            except Exception as e:
                conn.rollback()
                flash(f'Could not update: {e}', 'error')
        elif action == 'remove':
            eid = int(request.form.get('employee_id'))
            conn.execute('UPDATE sales_team SET is_active = 0 WHERE employee_id = ?', (eid,))
            conn.commit()
            flash('Removed from sales team', 'success')
        conn.close()
        return redirect(url_for('sales_team_admin'))

    members = conn.execute('''
        SELECT st.employee_id, st.role, st.manager_employee_id, st.is_active,
               e.name, e.emp_code, e.photo_url, e.designation, e.reporting_to,
               m.name AS manager_name
        FROM sales_team st
        JOIN employees e ON st.employee_id = e.id
        LEFT JOIN employees m ON st.manager_employee_id = m.id
        WHERE st.is_active = 1
        ORDER BY st.role DESC, e.name
    ''').fetchall()
    member_ids = [m['employee_id'] for m in members]
    # Only show employees who already have Sales module access — they need it to use the CRM.
    # Admins are always allowed (is_admin = 1 bypasses the module_access check at runtime).
    available_emps_q = (
        "SELECT e.id, e.name, e.emp_code, e.designation, e.reporting_to FROM employees e "
        "WHERE e.is_active = 1 AND e.emp_code != 'admin' "
        "AND (e.is_admin = 1 OR EXISTS ("
        "  SELECT 1 FROM module_access ma "
        "  WHERE ma.employee_id = e.id AND ma.module = 'sales' AND ma.is_active = 1"
        "))"
    )
    if member_ids:
        ph = ','.join(['?'] * len(member_ids))
        available_emps_q += f' AND e.id NOT IN ({ph})'
        available_emps = conn.execute(available_emps_q + ' ORDER BY e.name', member_ids).fetchall()
    else:
        available_emps = conn.execute(available_emps_q + ' ORDER BY e.name').fetchall()
    # Count employees who have sales module access but aren't yet on the team — surfaced as a hint.
    no_access_count = conn.execute(
        "SELECT COUNT(*) AS c FROM employees e "
        "WHERE e.is_active = 1 AND e.emp_code != 'admin' AND e.is_admin = 0 "
        "AND NOT EXISTS (SELECT 1 FROM module_access ma "
        "                WHERE ma.employee_id = e.id AND ma.module = 'sales' AND ma.is_active = 1)"
    ).fetchone()
    no_access_count = no_access_count['c'] if no_access_count else 0
    conn.close()
    return render_template('sales_team.html', user=user, members=members,
                           available_emps=available_emps,
                           no_access_count=no_access_count,
                    active_section='sales')


# ---- Leads -------------------------------------------------------------
@app.route('/sales/leads')
@login_required
@sales_crm_required
def sales_leads_list():
    user = get_user()
    role = get_sales_role(user)
    visible_ids = get_visible_sales_employee_ids(user)
    if not visible_ids:
        return render_template('sales_leads.html', user=user, leads=[], stages=[], owners=[], role=role,
                    active_section='sales')
    placeholders = ','.join(['?'] * len(visible_ids))
    f_stage = request.args.get('stage')
    f_owner = request.args.get('owner')
    f_hot = request.args.get('hot')

    # Show the team's own leads AND unassigned inbound leads (website leads land
    # with no owner — they must be visible so someone claims them, else they were
    # invisible on the board, founder 2026-07-20).
    where = [f'(sl.owner_employee_id IN ({placeholders}) OR sl.owner_employee_id IS NULL)']
    params = list(visible_ids)
    if f_stage and f_stage.isdigit():
        where.append('sl.stage_id = ?'); params.append(int(f_stage))
    if f_owner and f_owner.isdigit():
        where.append('sl.owner_employee_id = ?'); params.append(int(f_owner))
    if f_hot == '1':
        where.append('sl.is_hot = 1')

    conn = get_db()
    leads = conn.execute(
        f'''SELECT sl.*, s.name AS stage_name, s.color AS stage_color,
                  s.is_won AS stage_won, s.is_lost AS stage_lost,
                  e.name AS owner_name, e.photo_url AS owner_photo,
                  ps.name AS product_name, p.name AS project_name
           FROM sales_leads sl
           LEFT JOIN sales_lead_stages s ON sl.stage_id = s.id
           LEFT JOIN employees e ON sl.owner_employee_id = e.id
           LEFT JOIN products_services ps ON sl.product_id = ps.id
           LEFT JOIN projects p ON ps.project_id = p.id
           WHERE {' AND '.join(where)}
           ORDER BY sl.is_hot DESC, sl.expected_close_date NULLS LAST, sl.created_at DESC''',
        params
    ).fetchall()
    stages = conn.execute('SELECT * FROM sales_lead_stages WHERE is_active = 1 ORDER BY sort_order').fetchall()
    owners = conn.execute(
        f'SELECT id, name, photo_url FROM employees WHERE id IN ({placeholders}) ORDER BY name',
        visible_ids
    ).fetchall()
    conn.close()
    leads_dicts = []
    for l in leads:
        d = dict(l)
        d['photo_src'] = d.get('owner_photo') or ''
        leads_dicts.append(d)
    return render_template('sales_leads.html', user=user, leads=leads_dicts,
                           stages=stages, owners=owners, role=role,
                           f_stage=f_stage, f_owner=f_owner, f_hot=f_hot,
                    active_section='sales')


@app.route('/sales/leads/add', methods=['GET', 'POST'])
@login_required
@sales_write_required
def sales_leads_add():
    user = get_user()
    role = get_sales_role(user)
    visible_ids = get_visible_sales_employee_ids(user)
    conn = get_db()
    if request.method == 'POST':
        # Non-admin users always own their own leads; only admin can assign to others
        if role == 'admin':
            owner = request.form.get('owner_employee_id')
            owner_id = int(owner) if owner and owner.isdigit() else user['id']
        else:
            owner_id = user['id']
        product_id = request.form.get('product_id')
        product_id = int(product_id) if product_id and product_id.isdigit() else None
        stream_id = request.form.get('stream_id')
        stream_id = int(stream_id) if stream_id and stream_id.isdigit() else None
        # 2026-06-02: sales no longer tracks open pipeline -- every new lead
        # is a finalised (closed) client. Force the stage to Closed Won
        # regardless of what the form submits, so the auto-closure +
        # auto-invitation flow fires every time.
        won_row = conn.execute(
            "SELECT id FROM sales_lead_stages WHERE is_won = 1 AND is_active = 1 "
            "ORDER BY sort_order LIMIT 1"
        ).fetchone()
        stage_id = won_row['id'] if won_row else None
        try:
            ev = float(request.form.get('expected_value') or 0)
        except ValueError:
            ev = 0.0
        ecd = request.form.get('expected_close_date') or None
        lead_name_new = (request.form.get('lead_name') or '').strip() or 'Untitled lead'
        company_new = (request.form.get('company') or '').strip()
        conn.execute(
            '''INSERT INTO sales_leads
               (lead_name, company, phone, email, source, product_id, stream_id, stage_id,
                owner_employee_id, expected_value, expected_close_date, is_hot, notes, created_by)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)''',
            (
                lead_name_new, company_new,
                (request.form.get('phone') or '').strip(),
                (request.form.get('email') or '').strip(),
                (request.form.get('source') or '').strip(),
                product_id, stream_id, stage_id, owner_id, ev, ecd,
                0,  # is_hot retired with the "hot lead" UI cleanup
                (request.form.get('notes') or '').strip(),
                user['id']
            )
        )
        # If stage is Won, auto-create closure for the newly added lead
        if stage_id:
            won_stage = conn.execute(
                'SELECT id FROM sales_lead_stages WHERE id = ? AND is_won = 1',
                (stage_id,)
            ).fetchone()
            if won_stage:
                new_lead_row = conn.execute(
                    'SELECT id FROM sales_leads WHERE lead_name = ? AND owner_employee_id = ? ORDER BY id DESC LIMIT 1',
                    (lead_name_new, owner_id)
                ).fetchone()
                new_lead_id = new_lead_row['id'] if new_lead_row else None
                # AUD rate-lock (AMC 1 / AMC 2): freeze the live AUD→INR rate + markup
                # + timestamp onto the lead at generation. The client then pays this
                # locked INR (in installments); it never re-floats.
                amc_lock = None
                try:
                    _plan = (request.form.get('plan_type') or '').strip()
                    _amc_wl = bool(request.form.get('amc_website_link'))
                    amc_lock = amc_aud_quote(_plan, conn=conn)
                    if amc_lock and _amc_wl:
                        # Client paid the fee directly via Website Link — record the
                        # FLAT foreign amount, no live rate / markup / ₹ conversion.
                        amc_lock['live_rate'] = 1
                        amc_lock['effective_rate'] = 1
                        amc_lock['markup_pct'] = 0
                        amc_lock['inr'] = amc_lock['aud']
                        amc_lock['route'] = 'website_link'
                    if new_lead_id and amc_lock:
                        conn.execute(
                            "UPDATE sales_leads SET amc_plan_type=?, amc_currency=?, amc_aud_amount=?, amc_fx_rate=?, "
                            "amc_fx_markup=?, amc_fx_effective=?, amc_inr_amount=?, amc_payment_route=?, "
                            "amc_fx_locked_at=CURRENT_TIMESTAMP WHERE id=?",
                            (_plan, amc_lock.get('currency', 'AUD'), amc_lock['aud'], amc_lock['live_rate'],
                             amc_lock['markup_pct'], amc_lock['effective_rate'], amc_lock['inr'],
                             ('website_link' if _amc_wl else 'inr'), new_lead_id))
                        conn.commit()
                except Exception as _fxe:
                    logging.warning(f"AMC AUD lock (add): {_fxe}")
                    try: conn.rollback()
                    except Exception: pass
                # AMC 1 training add-on (AMC Consulting + AMC 1 combo) is AUD-priced too —
                # lock its rate so the combined deal's training portion is billed the locked INR.
                train_lock = None
                _tr_wl = bool(request.form.get('training_website_link'))
                try:
                    if request.form.get('include_training') in ('on', '1', 'true', 'yes'):
                        train_lock = amc_aud_quote('AMC 1', conn=conn)
                        if train_lock and _tr_wl:
                            # Client paid the AMC 1 fee directly via Website Link —
                            # record the FLAT AUD, no live rate / markup / ₹ conversion.
                            train_lock['live_rate'] = 1
                            train_lock['effective_rate'] = 1
                            train_lock['markup_pct'] = 0
                            train_lock['inr'] = train_lock['aud']
                except Exception:
                    train_lock = None
                if new_lead_id:
                    # Sales revenue is defined ONCE per plan in Packages:
                    # margin = Package - Cost - Discount, the number the sales
                    # dashboard credits the member on. Same rule across every
                    # product + plan type. (founder 2026-07-22)
                    cl_revenue, cl_cost = _closure_revenue_cost(
                        conn, product_id, (request.form.get('plan_type') or '').strip(),
                        discount=(request.form.get('discount_allowed') or 0),
                        fallback_revenue=(request.form.get('closure_revenue') or ev or 0))
                    cl_margin = cl_revenue - cl_cost
                    cl_currency = (request.form.get('closure_currency') or 'INR').upper()
                    cl_close_date = datetime.now().strftime('%Y-%m-%d')
                    cl_product_name = ''
                    cl_project_id = None
                    if product_id:
                        prow = conn.execute(
                            'SELECT name, project_id FROM products_services WHERE id = ?',
                            (product_id,)
                        ).fetchone()
                        if prow:
                            cl_product_name = prow['name']
                            cl_project_id = prow['project_id']
                    conn.execute(
                        '''INSERT INTO sales_closures
                           (lead_id, employee_id, product_id, product_name, project_id,
                            client_name, revenue, cost, margin, currency, close_date,
                            notes, created_by)
                           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)''',
                        (
                            new_lead_id, owner_id, product_id, cl_product_name or None,
                            cl_project_id,
                            company_new or lead_name_new,
                            cl_revenue, cl_cost, cl_margin, cl_currency, cl_close_date,
                            f'Auto-closure: {lead_name_new}',
                            user['id']
                        )
                    )
                    # 2026-06-02: auto-generate the client invitation +
                    # send the WhatsApp link. Failure here doesn't block
                    # the lead/closure save.
                    try:
                        # Item C: capture full sales closure details from the
                        # form so the client_registrations row created when
                        # the client accepts the invitation is pre-filled.
                        def _f(name, default=''):
                            return (request.form.get(name) or default).strip() \
                                if isinstance(request.form.get(name), str) \
                                else (request.form.get(name) or default)
                        def _n(name):
                            try: return float(request.form.get(name) or 0)
                            except ValueError: return 0
                        # Installments are normally entered incl. 18% GST -> stored base
                        # (÷1.18). But a Website Link payment is a flat foreign amount paid
                        # abroad (no Indian GST, no conversion), so store it as-is. The main
                        # plan and the AMC 1 training add-on have their own Website Link flags.
                        _inst_div = 1.0 if request.form.get('amc_website_link') else 1.18
                        _tr_inst_div = 1.0 if request.form.get('training_website_link') else 1.18
                        closure_data = {
                            'plan_type':                _f('plan_type'),
                            # AUD plans (AMC 1/AMC 2): the client pays the locked INR
                            # (aud × frozen rate), no discount. Otherwise use the form values.
                            'package_amount':           (amc_lock['inr'] if amc_lock else _n('package_amount')),
                            'discount_allowed':         (0 if amc_lock else _n('discount_allowed')),
                            'final_package':            (amc_lock['inr'] if amc_lock else _n('final_package')),
                            'additional_package_notes': _f('additional_package_notes'),
                            # Installment amounts are ENTERED as the total incl. GST;
                            # store the base (÷1.18) so existing base-stored records and
                            # the base->GST->total display stay consistent.
                            'inst1_amount':             round(_n('inst1_amount')/_inst_div, 2),
                            'inst1_date':               _f('inst1_date'),
                            'inst1_note':               _f('inst1_note'),
                            'inst1_method':             _f('inst1_method'),
                            'inst1_status':             _f('inst1_status'),
                            'inst2_amount':             round(_n('inst2_amount')/_inst_div, 2),
                            'inst2_date':               _f('inst2_date'),
                            'inst2_note':               _f('inst2_note'),
                            'inst2_method':             _f('inst2_method'),
                            'inst2_status':             _f('inst2_status'),
                            'inst3_amount':             round(_n('inst3_amount')/_inst_div, 2),
                            'inst3_date':               _f('inst3_date'),
                            'inst3_note':               _f('inst3_note'),
                            'inst3_method':             _f('inst3_method'),
                            'inst3_status':             _f('inst3_status'),
                            'inst4_amount':             round(_n('inst4_amount')/_inst_div, 2),
                            'inst4_date':               _f('inst4_date'),
                            'inst4_note':               _f('inst4_note'),
                            'inst4_method':             _f('inst4_method'),
                            'inst4_status':             _f('inst4_status'),
                            # AMC Consulting + AMC 1 combined signup — the Training (AMC 1)
                            # split. Installments entered as total incl GST -> stored base.
                            'include_training':         (request.form.get('include_training') in ('on', '1', 'true', 'yes')),
                            # AMC 1 is AUD-priced: bill the locked INR (no discount) and record
                            # the frozen forex breakup. Falls back to the form value if not AUD.
                            'training_package':         (train_lock['inr'] if train_lock else _n('training_package')),
                            'training_discount':        (0 if train_lock else _n('training_discount')),
                            'training_final':           (train_lock['inr'] if train_lock else _n('training_final')),
                            'training_aud':             (train_lock['aud'] if train_lock else 0),
                            'training_fx_rate':         (train_lock['live_rate'] if train_lock else 0),
                            'training_fx_markup':       (train_lock['markup_pct'] if train_lock else 0),
                            'training_fx_effective':    (train_lock['effective_rate'] if train_lock else 0),
                            'training_fx_locked_at':    (datetime.now().strftime('%Y-%m-%d %H:%M:%S') if train_lock else ''),
                            'training_payment_route':   ('website_link' if _tr_wl else 'inr'),
                            'training_inst1_amount':    round(_n('training_inst1_amount')/_tr_inst_div, 2),
                            'training_inst1_date':      _f('training_inst1_date'),
                            'training_inst1_method':    _f('training_inst1_method'),
                            'training_inst1_status':    _f('training_inst1_status'),
                            'training_inst2_amount':    round(_n('training_inst2_amount')/_tr_inst_div, 2),
                            'training_inst2_date':      _f('training_inst2_date'),
                            'training_inst2_method':    _f('training_inst2_method'),
                            'training_inst2_status':    _f('training_inst2_status'),
                            'training_inst3_amount':    round(_n('training_inst3_amount')/_tr_inst_div, 2),
                            'training_inst3_date':      _f('training_inst3_date'),
                            'training_inst3_method':    _f('training_inst3_method'),
                            'training_inst3_status':    _f('training_inst3_status'),
                            'training_inst4_amount':    round(_n('training_inst4_amount')/_tr_inst_div, 2),
                            'training_inst4_date':      _f('training_inst4_date'),
                            'training_inst4_method':    _f('training_inst4_method'),
                            'training_inst4_status':    _f('training_inst4_status'),
                            'lead_source':              _f('source') or _f('lead_source'),
                            # 'notes' is the rep's INTERNAL note ("not shown to client")
                            # -> route to ops_notes so it never reaches the client portal.
                            # The client sees additional_notes, which we feed from the
                            # client-facing 'Additional Package Notes' field only.
                            'additional_notes':         _f('additional_package_notes') or _f('additional_notes'),
                            'ops_notes':                _f('notes') or _f('ops_notes'),
                            # Welcome-call handling chosen by Sales at entry (founder 2026-07-22):
                            #   'standard'  – normal (client schedules after onboarding)
                            #   'hold'      – hold until payment; client doesn't see it until released
                            #   'completed' – already done before onboarding; record the past details
                            'wc_mode':                  _f('wc_mode') or 'standard',
                            'wc_hold_note':             _f('wc_hold_note'),
                            'wc_completed_date':        _f('wc_completed_date'),
                            'wc_completed_time':        _f('wc_completed_time'),
                            'wc_completed_by':          _f('wc_completed_by'),
                            'wc_completed_notes':       _f('wc_completed_notes'),
                            # The sales close date becomes the client's registration date.
                            'close_date':               _f('close_date'),
                        }
                        # Counsellor = the sales member who GENERATED the lead
                        # (founder rule 2026-07-15). Use the lead's creator as
                        # invited_by so the registration's counsellor_id + "Your
                        # counsellor" card + invite email reflect the generator,
                        # not the Owner field (which drives revenue) or whoever is
                        # logged in. Falls back to Owner, then the current user.
                        _counsellor_id = None
                        try:
                            _gen = conn.execute("SELECT created_by FROM sales_leads WHERE id = ?",
                                                (new_lead_id,)).fetchone()
                            if _gen and _gen['created_by']:
                                _counsellor_id = _gen['created_by']
                        except Exception:
                            _counsellor_id = None
                        if not _counsellor_id:
                            try:
                                _counsellor_id = int(request.form.get('owner_employee_id') or 0) or user['id']
                            except (TypeError, ValueError):
                                _counsellor_id = user['id']
                        token = _auto_invite_from_closure(
                            conn,
                            product_id=product_id,
                            client_name=lead_name_new,
                            client_mobile=(request.form.get('phone') or '').strip(),
                            client_email=(request.form.get('email') or '').strip(),
                            invited_by=_counsellor_id,
                            closure_data=closure_data,
                        )
                        if token:
                            flash('Closed client recorded and invitation sent on WhatsApp', 'success')
                            # Attach the signed contract (if uploaded) to the invitation.
                            # It's copied to the client_registrations row when the client
                            # accepts, then shown to them to read + digitally agree.
                            try:
                                cfile = request.files.get('contract_file')
                                if cfile and cfile.filename:
                                    cbytes = cfile.read()
                                    if len(cbytes) > 15 * 1024 * 1024:
                                        flash('Contract not saved: file too large (max 15 MB)', 'warning')
                                    else:
                                        from core import storage
                                        if storage.is_configured():
                                            cext = cfile.filename.rsplit('.', 1)[-1].lower() if '.' in cfile.filename else 'pdf'
                                            ckey = storage.make_doc_key('client', f'invite_{token[:12]}', 'Contract', cfile.filename)
                                            if storage.upload_bytes(ckey, cbytes, _CONTRACT_CT.get(cext, 'application/octet-stream')):
                                                conn.execute("UPDATE client_invitations SET contract_path = ? WHERE token = ?", (ckey, token))
                                                conn.commit()
                                            else:
                                                flash('Contract not saved: upload to storage failed', 'warning')
                                        else:
                                            flash('Contract not saved: file storage not configured', 'warning')
                            except Exception as _ce:
                                logging.warning(f"closure contract upload failed: {_ce}")
                                try: conn.rollback()
                                except Exception: pass
                                flash('Contract not saved (upload error -- check logs)', 'warning')
                        else:
                            flash('Closed client recorded (invitation skipped: phone missing or duplicate)', 'success')
                    except Exception as inv_err:
                        logging.warning(f"auto_invite from leads_add failed: {inv_err}")
                        flash('Closed client recorded (invitation send failed -- check logs)', 'warning')
        conn.commit()
        conn.close()
        # Fallback flash only if no won-stage flash fired (e.g. no Closed Won
        # row exists in sales_lead_stages -- unusual but possible).
        if not stage_id:
            flash('Lead recorded (no Closed Won stage configured -- closure + invitation skipped)', 'warning')
        return redirect(url_for('sales_leads_list'))

    stages = conn.execute('SELECT * FROM sales_lead_stages WHERE is_active = 1 ORDER BY sort_order').fetchall()
    won_stage_ids = [s['id'] for s in stages if s['is_won']]
    products = conn.execute(
        "SELECT id, name FROM products_services WHERE status = 'active' ORDER BY name"
    ).fetchall()
    streams = conn.execute("SELECT id, name FROM revenue_streams WHERE is_active = 1 ORDER BY name").fetchall()
    if visible_ids:
        ph = ','.join(['?'] * len(visible_ids))
        owners = conn.execute(
            f'SELECT id, name FROM employees WHERE id IN ({ph}) ORDER BY name',
            visible_ids
        ).fetchall()
    else:
        owners = []
    conn.close()
    return render_template('sales_lead_form.html', user=user, lead=None, mode='add',
                           stages=stages, products=products, streams=streams, owners=owners,
                           role=role, won_stage_ids=won_stage_ids,
                           already_has_closure=False,
                           lead_sources=get_lookup_options('lead_source'),
                    active_section='sales')


@app.route('/sales/leads/<int:lead_id>/edit', methods=['GET', 'POST'])
@login_required
@sales_write_required
def sales_leads_edit(lead_id):
    user = get_user()
    role = get_sales_role(user)
    visible_ids = get_visible_sales_employee_ids(user)
    conn = get_db()
    lead = conn.execute('SELECT * FROM sales_leads WHERE id = ?', (lead_id,)).fetchone()
    if not lead:
        conn.close()
        flash('Lead not found', 'error')
        return redirect(url_for('sales_leads_list'))
    if lead['owner_employee_id'] not in visible_ids and role != 'admin':
        conn.close()
        flash('Access denied', 'error')
        return redirect(url_for('sales_leads_list'))
    if request.method == 'POST':
        # Non-admin users keep the existing owner; only admin can reassign
        if role == 'admin':
            owner = request.form.get('owner_employee_id')
            owner_id = int(owner) if owner and owner.isdigit() else lead['owner_employee_id']
        else:
            owner_id = lead['owner_employee_id']
        product_id = request.form.get('product_id')
        product_id = int(product_id) if product_id and product_id.isdigit() else None
        stream_id = request.form.get('stream_id')
        stream_id = int(stream_id) if stream_id and stream_id.isdigit() else None
        stage_id = request.form.get('stage_id')
        stage_id = int(stage_id) if stage_id and stage_id.isdigit() else None
        try:
            ev = float(request.form.get('expected_value') or 0)
        except ValueError:
            ev = 0.0
        ecd = request.form.get('expected_close_date') or None
        lead_name_new = (request.form.get('lead_name') or '').strip() or lead['lead_name']
        company_new = (request.form.get('company') or '').strip()
        conn.execute(
            '''UPDATE sales_leads SET
               lead_name = ?, company = ?, phone = ?, email = ?, source = ?,
               product_id = ?, stream_id = ?, stage_id = ?, owner_employee_id = ?,
               expected_value = ?, expected_close_date = ?, is_hot = ?, notes = ?,
               updated_at = CURRENT_TIMESTAMP
               WHERE id = ?''',
            (
                lead_name_new, company_new,
                (request.form.get('phone') or '').strip(),
                (request.form.get('email') or '').strip(),
                (request.form.get('source') or '').strip(),
                product_id, stream_id, stage_id, owner_id, ev, ecd,
                1 if request.form.get('is_hot') else 0,
                (request.form.get('notes') or '').strip(),
                lead_id
            )
        )
        # --- Auto-create closure when stage changes to Won -----------------
        if stage_id:
            won_stage = conn.execute(
                'SELECT id FROM sales_lead_stages WHERE id = ? AND is_won = 1',
                (stage_id,)
            ).fetchone()
            old_was_won = False
            if lead['stage_id']:
                old_won_check = conn.execute(
                    'SELECT id FROM sales_lead_stages WHERE id = ? AND is_won = 1',
                    (lead['stage_id'],)
                ).fetchone()
                old_was_won = old_won_check is not None
            if won_stage and not old_was_won:
                # Only auto-create if no closure already linked to this lead
                existing_closure = conn.execute(
                    'SELECT id FROM sales_closures WHERE lead_id = ?', (lead_id,)
                ).fetchone()
                if not existing_closure:
                    # Sales revenue is defined ONCE per plan in Packages:
                    # margin = Package - Cost - Discount (same rule for every
                    # product + plan type); the dashboard credits the member on
                    # SUM(margin). (founder 2026-07-22)
                    cl_revenue, cl_cost = _closure_revenue_cost(
                        conn, product_id, (request.form.get('plan_type') or '').strip(),
                        discount=(request.form.get('discount_allowed') or 0),
                        fallback_revenue=(request.form.get('closure_revenue') or ev or 0))
                    cl_margin = cl_revenue - cl_cost
                    cl_currency = (request.form.get('closure_currency') or 'INR').upper()
                    cl_close_date = datetime.now().strftime('%Y-%m-%d')
                    # Resolve product name and project
                    cl_product_name = ''
                    cl_project_id = None
                    if product_id:
                        prow = conn.execute(
                            'SELECT name, project_id FROM products_services WHERE id = ?',
                            (product_id,)
                        ).fetchone()
                        if prow:
                            cl_product_name = prow['name']
                            cl_project_id = prow['project_id']
                    conn.execute(
                        '''INSERT INTO sales_closures
                           (lead_id, employee_id, product_id, product_name, project_id,
                            client_name, revenue, cost, margin, currency, close_date,
                            notes, created_by)
                           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)''',
                        (
                            lead_id, owner_id, product_id, cl_product_name or None,
                            cl_project_id,
                            company_new or lead_name_new,
                            cl_revenue, cl_cost, cl_margin, cl_currency, cl_close_date,
                            f'Auto-closure: {lead_name_new}',
                            user['id']
                        )
                    )
                    flash('Closure auto-recorded from won lead', 'success')
        # -------------------------------------------------------------------
        # Persist edited Service/Package + installment details back to the
        # client invitation (closure_metadata) and the client_registration (if
        # the client already registered), so editing a closed lead actually
        # updates what the client sees. Only UPDATEs existing rows — never
        # creates an invitation here.
        try:
            import json as _json
            def _ef(n, d=''):
                v = request.form.get(n)
                return v.strip() if isinstance(v, str) else (v if v is not None else d)
            def _en(n):
                try: return float(request.form.get(n) or 0)
                except (TypeError, ValueError): return 0
            edited = {
                'plan_type':                _ef('plan_type'),
                'package_amount':           _en('package_amount'),
                'discount_allowed':         _en('discount_allowed'),
                'final_package':            _en('final_package'),
                'additional_package_notes': _ef('additional_package_notes'),
                'lead_source':              _ef('source') or _ef('lead_source'),
                'additional_notes':         _ef('notes') or _ef('additional_notes'),
            }
            # Website Link payment (flat AUD, no Indian GST) stores installments as-is;
            # normal installments are entered incl. GST and stored base (÷1.18). The main
            # plan and the AMC 1 training add-on each have their own Website Link flag.
            _inst_div = 1.0 if request.form.get('amc_website_link') else 1.18
            _tr_inst_div = 1.0 if request.form.get('training_website_link') else 1.18
            for i in (1, 2, 3, 4):
                # Amount entered as total incl. GST -> store base (÷1.18), unless Website Link.
                edited[f'inst{i}_amount'] = round(_en(f'inst{i}_amount')/_inst_div, 2)
                edited[f'inst{i}_date']   = _ef(f'inst{i}_date')
                edited[f'inst{i}_note']   = _ef(f'inst{i}_note')
                edited[f'inst{i}_method'] = _ef(f'inst{i}_method')
                edited[f'inst{i}_status'] = _ef(f'inst{i}_status')
            # AMC Consulting + AMC 1 (Training) combo — capture it on EDIT too, else
            # saving an edit wiped the training enrolment out of closure_metadata.
            edited['include_training'] = (request.form.get('include_training') in ('on', '1', 'true', 'yes'))
            edited['training_payment_route'] = ('website_link' if request.form.get('training_website_link') else 'inr')
            edited['training_package']  = _en('training_package')
            edited['training_discount'] = _en('training_discount')
            edited['training_final']    = _en('training_final')
            for i in (1, 2, 3, 4):
                edited[f'training_inst{i}_amount'] = round(_en(f'training_inst{i}_amount')/_tr_inst_div, 2)
                edited[f'training_inst{i}_date']   = _ef(f'training_inst{i}_date')
                edited[f'training_inst{i}_method'] = _ef(f'training_inst{i}_method')
                edited[f'training_inst{i}_status'] = _ef(f'training_inst{i}_status')
            _ph = (request.form.get('phone') or lead['phone'] or '').lstrip('+').lstrip('0')
            if _ph.startswith('91') and len(_ph) == 12:
                _ph = _ph[2:]
            if _ph and product_id:
                inv = conn.execute(
                    "SELECT id, closure_metadata FROM client_invitations WHERE client_mobile = ? AND product_id = ? "
                    "AND COALESCE(status,'pending') <> 'cancelled' ORDER BY id DESC LIMIT 1",
                    (_ph, product_id)).fetchone()
                if inv:
                    # Merge onto the EXISTING closure_metadata so we never wipe keys the
                    # edit form didn't resubmit (e.g. ops_notes) — the earlier bug that
                    # lost the AMC-training enrolment on save.
                    try:
                        _base = _json.loads(inv['closure_metadata']) if inv['closure_metadata'] else {}
                    except Exception:
                        _base = {}
                    _merged = {**_base, **edited}
                    conn.execute("UPDATE client_invitations SET closure_metadata = ? WHERE id = ?",
                                 (_json.dumps({k: v for k, v in _merged.items() if v not in (None, '')}), inv['id']))
                reg = conn.execute(
                    "SELECT id FROM client_registrations "
                    "WHERE regexp_replace(mobile, '[^0-9]', '', 'g') LIKE ? AND product_id = ? "
                    "ORDER BY id DESC LIMIT 1",
                    ('%' + _ph, product_id)).fetchone()
                if reg:
                    conn.execute('''UPDATE client_registrations SET
                        plan_type = ?, package_amount = ?, discount_allowed = ?, final_package = ?,
                        additional_notes = ?,
                        inst1_amount = ?, inst1_date = ?, inst1_note = ?, inst1_method = ?, inst1_status = ?,
                        inst2_amount = ?, inst2_date = ?, inst2_note = ?, inst2_method = ?, inst2_status = ?,
                        inst3_amount = ?, inst3_date = ?, inst3_note = ?, inst3_method = ?, inst3_status = ?,
                        inst4_amount = ?, inst4_date = ?, inst4_note = ?, inst4_method = ?, inst4_status = ?,
                        updated_at = CURRENT_TIMESTAMP
                        WHERE id = ?''',
                        (edited['plan_type'], edited['package_amount'], edited['discount_allowed'],
                         edited['final_package'], edited['additional_notes'],
                         edited['inst1_amount'], edited['inst1_date'], edited['inst1_note'], edited['inst1_method'], edited['inst1_status'],
                         edited['inst2_amount'], edited['inst2_date'], edited['inst2_note'], edited['inst2_method'], edited['inst2_status'],
                         edited['inst3_amount'], edited['inst3_date'], edited['inst3_note'], edited['inst3_method'], edited['inst3_status'],
                         edited['inst4_amount'], edited['inst4_date'], edited['inst4_note'], edited['inst4_method'], edited['inst4_status'],
                         reg['id']))
                # Signed contract (edit / re-close): if the rep attached or replaced
                # a contract, store it on the invitation AND the registration (if the
                # client already registered) so the updated contract reaches the client.
                try:
                    cfile = request.files.get('contract_file')
                    if cfile and cfile.filename:
                        cbytes = cfile.read()
                        if len(cbytes) > 15 * 1024 * 1024:
                            flash('Contract not saved: file too large (max 15 MB)', 'warning')
                        else:
                            from core import storage
                            if storage.is_configured():
                                cext = cfile.filename.rsplit('.', 1)[-1].lower() if '.' in cfile.filename else 'pdf'
                                _basis = f"invite_{inv['id']}" if inv else f"lead_{lead_id}"
                                ckey = storage.make_doc_key('client', _basis, 'Contract', cfile.filename)
                                if storage.upload_bytes(ckey, cbytes, _CONTRACT_CT.get(cext, 'application/octet-stream')):
                                    _linked = False
                                    if inv:
                                        conn.execute("UPDATE client_invitations SET contract_path = ? WHERE id = ?", (ckey, inv['id'])); _linked = True
                                    if reg:
                                        conn.execute("UPDATE client_registrations SET contract_path = ? WHERE id = ?", (ckey, reg['id'])); _linked = True
                                    if _linked:
                                        flash('✓ Contract uploaded and attached to this client. They will read & sign it in their dashboard.', 'success')
                                    else:
                                        flash('Contract uploaded but no invitation/registration was found to attach it to — check the client’s phone/product match.', 'warning')
                                else:
                                    flash('Contract not saved: upload to storage failed', 'warning')
                            else:
                                flash('Contract not saved: file storage not configured', 'warning')
                except Exception as _ce2:
                    logging.warning(f"sales_leads_edit contract upload: {_ce2}")
        except Exception as _pe:
            logging.warning(f"sales_leads_edit closure persist: {_pe}")
        conn.commit()
        conn.close()
        flash('Lead updated', 'success')
        return redirect(url_for('sales_leads_list'))

    stages = conn.execute('SELECT * FROM sales_lead_stages WHERE is_active = 1 ORDER BY sort_order').fetchall()
    won_stage_ids = [s['id'] for s in stages if s['is_won']]
    already_has_closure = False
    if lead:
        already_has_closure = conn.execute(
            'SELECT id FROM sales_closures WHERE lead_id = ?', (lead_id,)
        ).fetchone() is not None
    products = conn.execute(
        "SELECT id, name FROM products_services WHERE status = 'active' ORDER BY name"
    ).fetchall()
    streams = conn.execute("SELECT id, name FROM revenue_streams WHERE is_active = 1 ORDER BY name").fetchall()
    if visible_ids:
        ph = ','.join(['?'] * len(visible_ids))
        owners = conn.execute(
            f'SELECT id, name FROM employees WHERE id IN ({ph}) ORDER BY name',
            visible_ids
        ).fetchall()
    else:
        owners = []
    # Pre-fill the Service/Package + installment fields when editing. These are
    # NOT stored on sales_leads — they live on the auto-created client invitation
    # (closure_metadata JSON) and, once the client registers, on the
    # client_registration row. Read both: invitation JSON as the base, then
    # overlay the registration values (source of truth once registered).
    closure = {}
    try:
        import json as _json
        _ph = (lead['phone'] or '').lstrip('+').lstrip('0')
        if _ph.startswith('91') and len(_ph) == 12:
            _ph = _ph[2:]
        if _ph and lead['product_id']:
            inv = conn.execute(
                "SELECT * FROM client_invitations "
                "WHERE client_mobile = ? AND product_id = ? "
                "  AND COALESCE(status,'pending') <> 'cancelled' "
                "ORDER BY id DESC LIMIT 1", (_ph, lead['product_id'])).fetchone()
            if inv and inv.get('closure_metadata'):
                try:
                    closure = _json.loads(inv['closure_metadata']) or {}
                except Exception:
                    closure = {}
            if inv and inv.get('contract_path'):
                closure['contract_path'] = inv['contract_path']
            reg = conn.execute(
                "SELECT * FROM client_registrations "
                "WHERE regexp_replace(mobile, '[^0-9]', '', 'g') LIKE ? AND product_id = ? "
                "ORDER BY id DESC LIMIT 1",
                ('%' + _ph, lead['product_id'])).fetchone()
            if reg:
                closure['plan_type']        = reg['plan_type'] or closure.get('plan_type', '')
                closure['package_amount']   = reg['package_amount'] if reg['package_amount'] is not None else closure.get('package_amount', 0)
                closure['discount_allowed'] = reg['discount_allowed'] if reg['discount_allowed'] is not None else closure.get('discount_allowed', 0)
                closure['final_package']    = reg['final_package'] if reg['final_package'] is not None else closure.get('final_package', 0)
                closure['additional_notes'] = reg['additional_notes'] or closure.get('additional_notes', '')
                if reg.get('contract_path'):
                    closure['contract_path'] = reg['contract_path']
                for i in (1, 2, 3, 4):
                    closure[f'inst{i}_amount'] = reg[f'inst{i}_amount'] if reg[f'inst{i}_amount'] is not None else closure.get(f'inst{i}_amount', 0)
                    closure[f'inst{i}_date']   = reg[f'inst{i}_date'] or closure.get(f'inst{i}_date', '')
                    closure[f'inst{i}_note']   = reg[f'inst{i}_note'] or closure.get(f'inst{i}_note', '')
    except Exception as _ce:
        logging.warning(f"sales_leads_edit closure prefill: {_ce}")
        closure = {}
    conn.close()
    return render_template('sales_lead_form.html', user=user, lead=lead, mode='edit',
                           stages=stages, products=products, streams=streams, owners=owners,
                           role=role, won_stage_ids=won_stage_ids,
                           already_has_closure=already_has_closure,
                           closure=closure,
                           lead_sources=get_lookup_options('lead_source'),
                    active_section='sales')


@app.route('/sales/leads/<int:lead_id>/view')
@login_required
def sales_leads_view(lead_id):
    """Read-only profile of a lead — everything the sales member filled, including
    the closure details (plan, package, installments, contract). Lives in the Sales
    section and links back to the leads list (founder 2026-07-18)."""
    user = get_user()
    role = get_sales_role(user)
    visible_ids = get_visible_sales_employee_ids(user) or []
    conn = get_db()
    lead = conn.execute(
        '''SELECT sl.*, s.name AS stage_name, s.color AS stage_color, s.is_won AS stage_won,
                  s.is_lost AS stage_lost, e.name AS owner_name, cb.name AS created_by_name,
                  ps.name AS product_name, p.name AS project_name, st.name AS stream_name
             FROM sales_leads sl
             LEFT JOIN sales_lead_stages s ON sl.stage_id = s.id
             LEFT JOIN employees e ON sl.owner_employee_id = e.id
             LEFT JOIN employees cb ON sl.created_by = cb.id
             LEFT JOIN products_services ps ON sl.product_id = ps.id
             LEFT JOIN projects p ON ps.project_id = p.id
             LEFT JOIN revenue_streams st ON sl.stream_id = st.id
            WHERE sl.id = ?''', (lead_id,)).fetchone()
    if not lead:
        conn.close()
        flash('Lead not found.', 'error')
        return redirect(url_for('sales_leads_list'))
    # Same visibility rule as the list: you see your own leads; admins see all.
    if role != 'admin' and lead['owner_employee_id'] not in visible_ids:
        conn.close()
        flash('You can only view your own leads.', 'error')
        return redirect(url_for('sales_leads_list'))

    # The rich closure fields live on the auto-created invitation (closure_metadata
    # JSON) and, once the client registers, on client_registrations. Read invitation
    # as the base, then overlay the registration (source of truth once registered) —
    # the exact merge the edit form uses.
    closure, reg_status = {}, None
    try:
        import json as _json
        _ph = (lead['phone'] or '').lstrip('+').lstrip('0')
        if _ph.startswith('91') and len(_ph) == 12:
            _ph = _ph[2:]
        if _ph and lead['product_id']:
            inv = conn.execute(
                "SELECT * FROM client_invitations WHERE client_mobile = ? AND product_id = ? "
                "AND COALESCE(status,'pending') <> 'cancelled' ORDER BY id DESC LIMIT 1",
                (_ph, lead['product_id'])).fetchone()
            if inv and inv.get('closure_metadata'):
                try: closure = _json.loads(inv['closure_metadata']) or {}
                except Exception: closure = {}
            if inv and inv.get('contract_path'):
                closure['contract_path'] = inv['contract_path']
            reg = conn.execute(
                "SELECT * FROM client_registrations "
                "WHERE regexp_replace(mobile, '[^0-9]', '', 'g') LIKE ? AND product_id = ? "
                "ORDER BY id DESC LIMIT 1", ('%' + _ph, lead['product_id'])).fetchone()
            if reg:
                reg_status = {'registration_number': reg['registration_number'],
                              'form_status': reg['form_status'],
                              'sales_completed': reg['sales_completed'],
                              'ops_status': reg['ops_status']}
                closure['plan_type']        = reg['plan_type'] or closure.get('plan_type', '')
                closure['package_amount']   = reg['package_amount'] if reg['package_amount'] is not None else closure.get('package_amount', 0)
                closure['discount_allowed'] = reg['discount_allowed'] if reg['discount_allowed'] is not None else closure.get('discount_allowed', 0)
                closure['final_package']    = reg['final_package'] if reg['final_package'] is not None else closure.get('final_package', 0)
                closure['additional_notes'] = reg['additional_notes'] or closure.get('additional_notes', '')
                if reg.get('contract_path'):
                    closure['contract_path'] = reg['contract_path']
                for i in (1, 2, 3, 4):
                    closure[f'inst{i}_amount'] = reg[f'inst{i}_amount'] if reg[f'inst{i}_amount'] is not None else closure.get(f'inst{i}_amount', 0)
                    closure[f'inst{i}_date']   = reg[f'inst{i}_date'] or closure.get(f'inst{i}_date', '')
                    closure[f'inst{i}_note']   = reg[f'inst{i}_note'] or closure.get(f'inst{i}_note', '')
                    closure[f'inst{i}_status'] = reg[f'inst{i}_status'] or closure.get(f'inst{i}_status', '')
    except Exception as _ce:
        logging.warning(f"sales_leads_view closure load: {_ce}")
    conn.close()
    return render_template('sales_lead_view.html', user=user, lead=lead, closure=closure,
                           reg_status=reg_status, role=role, active_section='sales')


@app.route('/sales/leads/<int:lead_id>/delete', methods=['POST'])
@login_required
@sales_write_required
def sales_leads_delete(lead_id):
    user = get_user()
    role = get_sales_role(user)
    if role != 'admin':
        flash('Admins only', 'error')
        return redirect(url_for('sales_leads_list'))
    conn = get_db()
    # Delete the lead's closures too. Previously only the lead row was removed,
    # so a deleted (e.g. duplicate) lead left ORPHAN closures behind — which kept
    # counting toward Closures revenue (the "1 lead but 2 closures / inflated
    # revenue" symptom). Closures carry the revenue, so removing the lead should
    # remove its closures.
    n_cl = conn.execute('SELECT COUNT(*) AS n FROM sales_closures WHERE lead_id = ?', (lead_id,)).fetchone()
    conn.execute('DELETE FROM sales_closures WHERE lead_id = ?', (lead_id,))
    conn.execute('DELETE FROM sales_leads WHERE id = ?', (lead_id,))
    conn.commit()
    conn.close()
    _cln = (n_cl['n'] if n_cl else 0) or 0
    flash('Lead deleted' + (f' (and {_cln} linked closure{"s" if _cln != 1 else ""})' if _cln else ''), 'success')
    return redirect(url_for('sales_leads_list'))


@app.route('/sales/leads/<int:lead_id>/resend-invite', methods=['POST'])
@login_required
@sales_write_required
def sales_leads_resend_invite(lead_id):
    """Resend the client registration link for a closed lead. Finds the
    invitation by mobile + product, re-syncs the counsellor to the lead's
    current owner (on the invitation and any registration created from it),
    then re-sends the email + WhatsApp."""
    user = get_user()
    role = get_sales_role(user)
    visible_ids = get_visible_sales_employee_ids(user)
    conn = get_db()
    lead = conn.execute('SELECT * FROM sales_leads WHERE id = ?', (lead_id,)).fetchone()
    if not lead:
        conn.close(); flash('Lead not found', 'error'); return redirect(url_for('sales_leads_list'))
    if lead['owner_employee_id'] not in visible_ids and role != 'admin':
        conn.close(); flash('Access denied', 'error'); return redirect(url_for('sales_leads_list'))

    ph = (lead['phone'] or '').lstrip('+').lstrip('0')
    if ph.startswith('91') and len(ph) == 12:
        ph = ph[2:]
    inv = None
    if ph and lead['product_id']:
        inv = conn.execute(
            "SELECT * FROM client_invitations WHERE client_mobile = ? AND product_id = ? "
            "AND COALESCE(status,'pending') <> 'cancelled' ORDER BY id DESC LIMIT 1",
            (ph, lead['product_id'])).fetchone()
    if not inv:
        conn.close()
        flash('No invitation exists for this lead yet — move it to a Won stage (or use Add Closed Client) to generate one.', 'warning')
        return redirect(url_for('sales_leads_list'))

    # Counsellor = the lead's current owner. Re-sync it onto the invitation and
    # any registration created from it, so the client portal + email show the
    # right counsellor even when an old invitation was reused.
    owner_id = lead['owner_employee_id']
    svc_name, cns_name = '', ''
    pr = conn.execute("SELECT name FROM products_services WHERE id = ?", (lead['product_id'],)).fetchone()
    if pr: svc_name = pr['name'] or ''
    # Combined AMC Consulting + AMC MCQ (AMC 1) enrolment: the invitation's
    # stored closure_metadata carries include_training. Honour it here so the
    # RE-SENT email lists both programs, matching the auto-invite on close.
    also_svc = ''
    try:
        import json as _json
        _meta = _json.loads(inv['closure_metadata']) if inv['closure_metadata'] else {}
        if _meta.get('include_training'):
            also_svc = 'AMC MCQ (AMC 1) — Training'
    except Exception:
        also_svc = ''
    if owner_id:
        em = conn.execute("SELECT name FROM employees WHERE id = ?", (owner_id,)).fetchone()
        if em: cns_name = em['name'] or ''
        try:
            conn.execute("UPDATE client_invitations SET invited_by = ? WHERE id = ?", (owner_id, inv['id']))
            conn.execute(
                "UPDATE client_registrations SET counsellor_id = ?, counsellor_name = ? "
                "WHERE mobile = ? AND product_id = ?", (owner_id, cns_name, ph, lead['product_id']))
            conn.commit()
        except Exception as e:
            logging.warning(f"resend-invite counsellor resync: {e}")
            try: conn.rollback()
            except Exception: pass
    conn.close()

    invite_url = f"https://goocampus.org/client/register/{inv['token']}"
    wa_ok = email_ok = False
    try:
        if inv['client_mobile']:
            wa_ok = _send_client_invite_wa(inv['client_mobile'], inv['client_name'], invite_url)
    except Exception as e:
        logging.error(f"resend-invite WA: {e}")
    try:
        if inv['client_email']:
            email_ok = _send_client_invite_email(inv['client_email'], inv['client_name'], invite_url,
                                                 service_name=svc_name, counsellor_name=cns_name,
                                                 also_service=also_svc)
    except Exception as e:
        logging.error(f"resend-invite email: {e}")
    sent = (['WhatsApp'] if wa_ok else []) + (['email'] if email_ok else [])
    if sent:
        flash(f"Invitation resent via {' + '.join(sent)} to {inv['client_name']}. Link: {invite_url}", 'success')
    else:
        flash(f"Couldn't auto-send (check WhatsApp/email setup) — share this link manually: {invite_url}", 'warning')
    return redirect(url_for('sales_leads_list'))


@app.route('/api/pg/lead', methods=['POST'])
def api_pg_lead():
    """Inbound lead from the goocampus.in public site → the sales CRM.

    Service-to-service: no user login, guarded by a shared secret in the X-PG-Key
    header (must equal env PG_API_KEY). The goocampus.in Next.js server action posts
    here so a "Book Free Counselling Call" reaches sales — a lead written anywhere
    else would skip the CRM's follow-up. Contract owned jointly; see the PG repo's
    INTEGRATION.md. Founder 2026-07-20."""
    expected = os.environ.get('PG_API_KEY') or ''
    got = request.headers.get('X-PG-Key') or ''
    if not expected or got != expected:
        return jsonify({'ok': False, 'error': 'unauthorized'}), 401
    data = request.get_json(silent=True) or {}
    name = (data.get('name') or '').strip()
    phone = (data.get('phone') or '').strip()
    email = (data.get('email') or '').strip()
    year = (data.get('neet_pg_year') or '').strip()
    speciality = (data.get('target_speciality') or '').strip()
    src_page = (data.get('source_page') or '').strip()
    if not name or not phone:
        return jsonify({'ok': False, 'error': 'name and phone are required'}), 400
    note_bits = []
    if year:
        note_bits.append(f"NEET PG {year}")
    if speciality:
        note_bits.append(f"Target speciality: {speciality}")
    if src_page:
        note_bits.append(f"From page: {src_page}")
    notes = ' · '.join(note_bits) or 'Website enquiry'
    conn = get_db()
    try:
        stage = conn.execute(
            "SELECT id FROM sales_lead_stages WHERE COALESCE(is_active,1)=1 "
            "ORDER BY sort_order, id LIMIT 1").fetchone()
        stage_id = stage['id'] if stage else None
        conn.execute(
            "INSERT INTO sales_leads (lead_name, phone, email, source, stage_id, is_hot, notes, created_at) "
            "VALUES (?, ?, ?, 'NEET PG Website (goocampus.in)', ?, 1, ?, CURRENT_TIMESTAMP)",
            (name, phone, email, stage_id, notes))
        conn.commit()
        try:
            sales_emails = _dept_emails(conn, ['Sales'])
        except Exception:
            sales_emails = []
        conn.close()
        # Alert the sales team that a website lead came in.
        if sales_emails:
            try:
                from email_utils import send_email
                send_email(sales_emails, f"New website lead — {name}",
                           f"<p>A new lead came in from goocampus.in.</p>"
                           f"<p><strong>{name}</strong><br>{phone}{(' · ' + email) if email else ''}<br>{notes}</p>"
                           f"<p>Open the Sales Leads board to action it.</p>")
            except Exception:
                pass
        return jsonify({'ok': True}), 200
    except Exception as e:
        try: conn.rollback(); conn.close()
        except Exception: pass
        logging.error("api_pg_lead: %s", e)
        return jsonify({'ok': False, 'error': 'server_error'}), 500


# ---- Product lookup API (for lead form auto-fill) ----------------------
@app.route('/sales/api/product/<int:pid>')
@login_required
def sales_product_info(pid):
    conn = get_db()
    row = conn.execute(
        "SELECT id, name, revenue_stream_id, sale_price, product_cost, COALESCE(pathway,'plab') AS pathway FROM products_services WHERE id = ?",
        (pid,)
    ).fetchone()
    if not row:
        conn.close()
        return jsonify({'error': 'not found'}), 404
    pw = row['pathway'] or 'plab'
    # Plan types for this product (drives the Plan Type cascade on the sales
    # closed-client form). Fall back to the pathway's full plan list when the
    # product has no product-specific plans.
    try:
        # Match plan types by product NAME (not pathway): a product's pathway
        # tag can lag behind where its plan types actually live (e.g. AMC / UK
        # Consulting are tagged plab but their plans sit under consulting), so
        # matching on name finds them regardless. Falls back to the product's
        # pathway list only when nothing is mapped to the name.
        plans = conn.execute(
            "SELECT value FROM lookup_options WHERE category='plan_type' "
            "AND COALESCE(product_name,'')=? "
            "AND COALESCE(is_active,true) IS NOT FALSE ORDER BY value", (row['name'],)).fetchall()
        plan_types = [r['value'] for r in plans if r['value']]
        if not plan_types:
            plans = conn.execute(
                "SELECT value FROM lookup_options WHERE category='plan_type' "
                "AND COALESCE(pathway,'plab')=? AND COALESCE(is_active,true) IS NOT FALSE "
                "ORDER BY value", (pw,)).fetchall()
            plan_types = [r['value'] for r in plans if r['value']]
    except Exception:
        plan_types = []
    conn.close()
    return jsonify({
        'id': row['id'],
        'name': row['name'],
        'stream_id': row['revenue_stream_id'],
        'sale_price': float(row['sale_price'] or 0),
        'product_cost': float(row['product_cost'] or 0),
        'margin': float((row['sale_price'] or 0) - (row['product_cost'] or 0)),
        'pathway': pw,
        'plan_types': plan_types,
    })


# ---- Closures ----------------------------------------------------------
@app.route('/sales/closures')
@login_required
@sales_crm_required
def sales_closures_list():
    user = get_user()
    role = get_sales_role(user)
    visible_ids = get_visible_sales_employee_ids(user)
    if not visible_ids:
        return render_template('sales_closures.html', user=user, closures=[], owners=[], products=[], role=role,
                    active_section='sales')
    placeholders = ','.join(['?'] * len(visible_ids))
    now = datetime.now()
    year = int(request.args.get('year') or now.year)
    month_filter = request.args.get('month')
    f_owner = request.args.get('owner')
    f_product = request.args.get('product')

    where = [f'c.employee_id IN ({placeholders})', 'EXTRACT(YEAR FROM c.close_date) = ?']
    params = list(visible_ids) + [year]
    if month_filter and month_filter.isdigit():
        where.append('EXTRACT(MONTH FROM c.close_date) = ?'); params.append(int(month_filter))
    if f_owner and f_owner.isdigit():
        where.append('c.employee_id = ?'); params.append(int(f_owner))
    if f_product and f_product.isdigit():
        where.append('c.product_id = ?'); params.append(int(f_product))

    conn = get_db()
    closures = conn.execute(
        f'''SELECT c.*, e.name AS employee_name, e.photo_url AS emp_photo,
                  ps.name AS product_name_live, p.name AS project_name
           FROM sales_closures c
           LEFT JOIN employees e ON c.employee_id = e.id
           LEFT JOIN products_services ps ON c.product_id = ps.id
           LEFT JOIN projects p ON c.project_id = p.id
           WHERE {' AND '.join(where)}
           ORDER BY c.close_date DESC, c.id DESC''',
        params
    ).fetchall()
    owners = conn.execute(
        f'SELECT id, name FROM employees WHERE id IN ({placeholders}) ORDER BY name',
        visible_ids
    ).fetchall()
    products = conn.execute(
        "SELECT id, name FROM products_services WHERE status = 'active' ORDER BY name"
    ).fetchall()
    # Aggregates
    total_revenue = sum(float(c['revenue'] or 0) for c in closures)
    total_margin = sum(float(c['margin'] or 0) for c in closures)
    total_deals = len(closures)
    # Product-wise rollup
    by_product = {}
    for c in closures:
        key = c['product_name'] or c['product_name_live'] or 'Unspecified'
        if key not in by_product:
            by_product[key] = {'name': key, 'deals': 0, 'revenue': 0.0, 'margin': 0.0}
        by_product[key]['deals'] += 1
        by_product[key]['revenue'] += float(c['revenue'] or 0)
        by_product[key]['margin'] += float(c['margin'] or 0)
    by_product = sorted(by_product.values(), key=lambda x: x['margin'], reverse=True)
    conn.close()

    closures_dicts = []
    for c in closures:
        d = dict(c)
        d['photo_src'] = d.get('emp_photo') or ''
        d['display_name'] = d.get('product_name') or d.get('product_name_live') or '—'
        closures_dicts.append(d)

    return render_template('sales_closures.html', user=user, closures=closures_dicts,
                           owners=owners, products=products,
                           total_revenue=total_revenue, total_margin=total_margin,
                           total_deals=total_deals, by_product=by_product,
                           year=year, month=month_filter,
                           f_owner=f_owner, f_product=f_product, role=role,
                    active_section='sales')


@app.route('/sales/closures/<int:cid>/edit', methods=['GET', 'POST'])
@login_required
@sales_write_required
def sales_closures_edit(cid):
    user = get_user()
    role = get_sales_role(user)
    visible_ids = get_visible_sales_employee_ids(user)
    conn = get_db()
    closure = conn.execute('SELECT * FROM sales_closures WHERE id = ?', (cid,)).fetchone()
    if not closure:
        conn.close()
        flash('Closure not found', 'error')
        return redirect(url_for('sales_closures_list'))
    if closure['employee_id'] not in visible_ids and role != 'admin':
        conn.close()
        flash('Access denied', 'error')
        return redirect(url_for('sales_closures_list'))
    if request.method == 'POST':
        # Non-admin users keep the existing owner; only admin can reassign
        if role == 'admin':
            owner = request.form.get('employee_id')
            owner_id = int(owner) if owner and owner.isdigit() else closure['employee_id']
        else:
            owner_id = closure['employee_id']
        product_id = request.form.get('product_id')
        product_id = int(product_id) if product_id and product_id.isdigit() else None
        product_name = ''
        project_id = closure['project_id']
        if product_id:
            row = conn.execute('SELECT name, project_id FROM products_services WHERE id = ?', (product_id,)).fetchone()
            if row:
                product_name = row['name']
                project_id = row['project_id']
        try:
            revenue = float(request.form.get('revenue') or 0)
        except ValueError:
            revenue = float(closure['revenue'] or 0)
        try:
            cost = float(request.form.get('cost') or 0)
        except ValueError:
            cost = float(closure['cost'] or 0)
        margin = revenue - cost
        currency = (request.form.get('currency') or closure['currency'] or 'INR').upper()
        close_date = request.form.get('close_date') or closure['close_date']
        conn.execute(
            '''UPDATE sales_closures SET
               employee_id = ?, product_id = ?, product_name = ?, project_id = ?, client_name = ?,
               revenue = ?, cost = ?, margin = ?, currency = ?, close_date = ?, notes = ?,
               updated_at = CURRENT_TIMESTAMP
               WHERE id = ?''',
            (
                owner_id, product_id, product_name, project_id,
                (request.form.get('client_name') or '').strip(),
                revenue, cost, margin, currency, close_date,
                (request.form.get('notes') or '').strip(),
                cid
            )
        )
        conn.commit()
        conn.close()
        flash('Closure updated', 'success')
        return redirect(url_for('sales_closures_list'))

    products = conn.execute(
        "SELECT id, name FROM products_services WHERE status = 'active' ORDER BY name"
    ).fetchall()
    if visible_ids:
        ph = ','.join(['?'] * len(visible_ids))
        owners = conn.execute(
            f'SELECT id, name FROM employees WHERE id IN ({ph}) ORDER BY name',
            visible_ids
        ).fetchall()
    else:
        owners = []
    conn.close()
    return render_template('sales_closure_form.html', user=user, mode='edit', closure=closure,
                           products=products, owners=owners, leads=[], role=role,
                    active_section='sales')


