@app.route('/partner/api/cities')
def partner_api_cities():
    """Return cities for a given state (no login required, for partner onboarding)."""
    conn = get_db()
    try:
        state_id = request.args.get('state_id', '').strip()
        state_name = request.args.get('state', '').strip()
        if state_id:
            rows = conn.execute("SELECT id, name FROM cities WHERE state_id = ? AND is_active = TRUE ORDER BY name", (int(state_id),)).fetchall()
        elif state_name:
            st = conn.execute("SELECT id FROM states WHERE name = ? AND is_active = TRUE", (state_name,)).fetchone()
            if st:
                rows = conn.execute("SELECT id, name FROM cities WHERE state_id = ? AND is_active = TRUE ORDER BY name", (st['id'],)).fetchall()
            else:
                rows = []
        else:
            rows = []
        return jsonify([{'id': r['id'], 'name': r['name']} for r in rows])
    except Exception as e:
        logging.error(f"partner_api_cities: {e}")
        return jsonify([])
    finally:
        conn.close()


@app.route('/partner/onboard/<token>', methods=['GET'])
def partner_onboard_form(token):
    """Partner onboarding form - company details, team members, address."""
    if not session.get('partner_register_token') or session.get('partner_register_token') != token:
        flash('Please verify your email first', 'error')
        return redirect(url_for('login'))

    conn = get_db()
    invitation = conn.execute('''
        SELECT id, name, email, token, status FROM partner_invitations WHERE token = ?
    ''', (token,)).fetchone()

    if not invitation:
        conn.close()
        flash('Invalid invitation token', 'error')
        return redirect(url_for('login'))

    products = conn.execute(
        'SELECT id, name FROM products_services WHERE status = ? ORDER BY name',
        ('active',)
    ).fetchall()
    conn.close()

    return render_template('partner_onboard.html', token=token, invitation=invitation, products=products)


@app.route('/partner/onboard/<token>', methods=['POST'])
def partner_onboard_submit(token):
    """Process partner onboarding form and create partner account."""
    is_ajax = request.headers.get('Accept', '').find('application/json') != -1 or request.headers.get('X-Requested-With') == 'XMLHttpRequest'

    if not session.get('partner_register_token') or session.get('partner_register_token') != token:
        if is_ajax:
            return jsonify({'error': 'Session expired. Please refresh the page and try again.'}), 401
        flash('Session expired. Please try again', 'error')
        return redirect(url_for('login'))

    try:
        conn = get_db()

        # Get invitation
        invitation = conn.execute('''
            SELECT id, email, name, status FROM partner_invitations WHERE token = ?
        ''', (token,)).fetchone()

        if not invitation or invitation['status'] != 'pending':
            conn.close()
            if is_ajax:
                return jsonify({'error': 'Invalid or expired invitation'}), 400
            flash('Invalid or expired invitation', 'error')
            return redirect(url_for('login'))

        # Get form data
        company_name = request.form.get('company_name', '').strip()
        contact_person = request.form.get('contact_person', '').strip()
        phone = request.form.get('phone', '').strip()
        website = request.form.get('website', '').strip()
        address = request.form.get('address', '').strip()
        city = request.form.get('city', '').strip()
        state = request.form.get('state', '').strip()
        country = request.form.get('country', 'India').strip()
        partner_type = request.form.get('partner_type', '').strip()

        password = request.form.get('password', '').strip()
        confirm_password = request.form.get('confirm_password', '').strip()

        if not company_name or not contact_person:
            conn.close()
            if is_ajax:
                return jsonify({'error': 'Required fields: company name, contact person'}), 400
            flash('Required fields: company name, contact person', 'error')
            return redirect(url_for('partner_onboard_form', token=token))

        # The mobile number must be verified by WhatsApp OTP before the account is
        # created — that number becomes the partner's password-less login. (2026-07-21)
        _phone10 = _normalise_in_mobile(phone)
        if not _phone10 or session.get('partner_onb_phone_ok') != _phone10:
            conn.close()
            if is_ajax:
                return jsonify({'error': 'Please verify your mobile number with the WhatsApp OTP first.'}), 400
            flash('Please verify your mobile number with the WhatsApp OTP first.', 'error')
            return redirect(url_for('partner_onboard_form', token=token))

        # Password is now OPTIONAL — partners log in with mobile + OTP. If they
        # chose to set one, keep the old rules (>= 6 chars, must match).
        password_hash_val = None
        if password:
            if len(password) < 6:
                conn.close()
                if is_ajax:
                    return jsonify({'error': 'Password must be at least 6 characters'}), 400
                flash('Password must be at least 6 characters', 'error')
                return redirect(url_for('partner_onboard_form', token=token))
            if password != confirm_password:
                conn.close()
                if is_ajax:
                    return jsonify({'error': 'Passwords do not match'}), 400
                flash('Passwords do not match', 'error')
                return redirect(url_for('partner_onboard_form', token=token))
            password_hash_val = hash_password(password)

        # Create partner
        cursor = conn.execute('''
            INSERT INTO partners (
                company_name, contact_person, email, phone, website, address, city, state, country,
                partner_type, status, password_hash, invitation_id, onboarding_status, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'Active', ?, ?, 'completed', CURRENT_TIMESTAMP)
        ''', (
            company_name, contact_person, invitation['email'], phone, website, address, city, state, country,
            partner_type, password_hash_val, invitation['id']
        ))

        # Get the new partner ID
        result = conn.execute("SELECT id FROM partners WHERE email = ? ORDER BY id DESC LIMIT 1", (invitation['email'],))
        row = result.fetchone()
        partner_id = row['id'] if row else None

        # Add team members if provided
        team_members = request.form.getlist('team_name[]')
        team_emails = request.form.getlist('team_email[]')
        team_designations = request.form.getlist('team_designation[]')
        team_phones = request.form.getlist('team_phone[]')

        for i, name in enumerate(team_members):
            if name.strip():
                conn.execute('''
                    INSERT INTO partner_team_members (partner_id, name, email, designation, phone, created_at)
                    VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                ''', (
                    partner_id,
                    name.strip(),
                    team_emails[i].strip() if i < len(team_emails) else '',
                    team_designations[i].strip() if i < len(team_designations) else '',
                    team_phones[i].strip() if i < len(team_phones) else ''
                ))

        # Update invitation status
        conn.execute('''
            UPDATE partner_invitations SET status = 'registered', registered_at = CURRENT_TIMESTAMP WHERE id = ?
        ''', (invitation['id'],))

        conn.commit()
        conn.close()

        # Create notification for admins in a SEPARATE transaction so it never poisons partner creation
        try:
            nconn = get_db()
            admin_row = nconn.execute("SELECT id FROM employees WHERE is_admin = 1 ORDER BY id LIMIT 1").fetchone()
            admin_id = admin_row['id'] if admin_row else 1
            nconn.execute('''
                INSERT INTO notifications (employee_id, type, title, message, created_at)
                VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)
            ''', (
                admin_id,
                'partner_registration',
                f'New Partner Registration: {company_name}',
                f'Partner {company_name} has completed onboarding. Contact: {contact_person}'
            ))
            nconn.commit()
            nconn.close()
        except Exception as e:
            logging.error(f"Failed to create partner registration notification: {e}")

        # Set partner session
        session.permanent = True
        session['user_id'] = partner_id
        session['is_partner'] = True
        session['partner_name'] = company_name
        session['partner_email'] = invitation['email']

        # Clear registration temp session
        session.pop('partner_register_token', None)
        session.pop('partner_register_email', None)
        if is_ajax:
            return jsonify({'success': True, 'message': 'Partner account created successfully', 'redirect': url_for('partner_dashboard_view')}), 200
        flash('Welcome! Your partner account has been created successfully.', 'success')
        return redirect(url_for('partner_dashboard_view'))
    except Exception as e:
        logging.error(f"partner_onboard_submit: {e}")
        conn.rollback()
        conn.close()
        if is_ajax:
            return jsonify({'error': f'Error completing onboarding: {e}'}), 500
        flash(f'Error completing onboarding: {e}', 'error')
        return redirect(url_for('partner_onboard_form', token=token))


# ─── ADMIN PARTNER LEADS ROUTES ───

@app.route('/partners/leads', methods=['GET'])
@login_required
def admin_partner_leads():
    """Admin view of all student leads from all partners."""
    conn = get_db()
    user = conn.execute('SELECT * FROM employees WHERE id = ?', (session['user_id'],)).fetchone()

    if not (user and (user['is_admin'] or has_section_permission(user, 'partners', 'leads', 'view'))):
        conn.close()
        flash('Admin access required', 'error')
        return redirect(url_for('dashboard'))

    # Get filter parameters
    partner_id = request.args.get('partner_id', '')
    status_filter = request.args.get('status', '')

    query = '''
        SELECT pl.id, pl.partner_id, pl.student_name, pl.student_email, pl.student_phone,
               pl.city, pl.state, pl.interested_products, pl.status, pl.created_at,
               p.company_name
        FROM partner_leads pl
        LEFT JOIN partners p ON pl.partner_id = p.id
        WHERE 1=1
    '''
    params = []

    if partner_id:
        query += ' AND pl.partner_id = ?'
        params.append(partner_id)

    if status_filter:
        query += ' AND pl.status = ?'
        params.append(status_filter)

    query += ' ORDER BY pl.created_at DESC'

    leads = conn.execute(query, params).fetchall()

    # Get partners for filter dropdown
    partners = conn.execute('SELECT id, company_name FROM partners ORDER BY company_name').fetchall()
    lead_statuses = get_lookup_options('lead_status')

    conn.close()

    return render_template('partner_leads_admin.html',
                         leads=leads,
                         partners=partners,
                         lead_statuses=lead_statuses,
                         selected_partner=partner_id,
                         selected_status=status_filter,
                    active_section='partners')


