def ensure_attendance_table():
    """Create attendance_logs table if it doesn't exist."""
    try:
        conn = get_db()
        conn.execute("""
            CREATE TABLE IF NOT EXISTS attendance_logs (
                id SERIAL PRIMARY KEY,
                employee_id INTEGER NOT NULL REFERENCES employees(id),
                attendance_date TEXT NOT NULL,
                shift TEXT,
                scheduled_in TEXT,
                scheduled_out TEXT,
                actual_in TEXT,
                actual_out TEXT,
                work_duration TEXT,
                overtime TEXT,
                total_duration TEXT,
                late_by TEXT,
                early_going_by TEXT,
                status TEXT,
                punch_records TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(employee_id, attendance_date)
            )
        """)
        conn.commit()
        conn.close()
        logging.info("attendance_logs table ensured.")
    except Exception as e:
        logging.error(f"ensure_attendance_table: {e}")


def ensure_package_tables():
    """Central package/services definition: per (product, plan_type) a package
    amount + the list of services included (delivered over time). service_catalogue
    is the reusable master list of service names."""
    conn = get_db()
    for ddl in (
        """CREATE TABLE IF NOT EXISTS service_catalogue (
            id SERIAL PRIMARY KEY, name TEXT NOT NULL, description TEXT, category TEXT,
            is_active INTEGER DEFAULT 1, sort_order INTEGER DEFAULT 0,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)""",
        """CREATE TABLE IF NOT EXISTS plan_packages (
            id SERIAL PRIMARY KEY, product_id INTEGER NOT NULL, plan_type TEXT NOT NULL,
            package_amount NUMERIC(14,2) DEFAULT 0, summary TEXT,
            is_active INTEGER DEFAULT 1, sort_order INTEGER DEFAULT 0,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(product_id, plan_type))""",
        """CREATE TABLE IF NOT EXISTS package_services (
            id SERIAL PRIMARY KEY,
            plan_package_id INTEGER NOT NULL REFERENCES plan_packages(id) ON DELETE CASCADE,
            service_id INTEGER, service_name TEXT NOT NULL, description TEXT,
            quantity TEXT, delivery_stage TEXT, sort_order INTEGER DEFAULT 0,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)""",
        "CREATE INDEX IF NOT EXISTS idx_plan_packages_product ON plan_packages(product_id)",
        "CREATE INDEX IF NOT EXISTS idx_package_services_plan ON package_services(plan_package_id)",
        "ALTER TABLE plan_packages ADD COLUMN IF NOT EXISTS plan_cost NUMERIC(14,2) DEFAULT 0",
        "ALTER TABLE package_services ADD COLUMN IF NOT EXISTS budget NUMERIC(14,2) DEFAULT 0",
        # Multi-currency per plan type (2026-07-14): any plan can be priced in a
        # FOREIGN currency; the client is still billed INR at the live rate + markup.
        # currency default 'INR' (rupees, unchanged); fx_markup_pct = % over the live
        # rate (AMC uses 3%); fixed_sales_revenue = optional flat INR sales revenue
        # (NULL/0 = use the normal package-cost-discount calc). Replaces amc_aud_pricing.
        "ALTER TABLE plan_packages ADD COLUMN IF NOT EXISTS currency TEXT DEFAULT 'INR'",
        "ALTER TABLE plan_packages ADD COLUMN IF NOT EXISTS fx_markup_pct NUMERIC(5,2) DEFAULT 0",
        "ALTER TABLE plan_packages ADD COLUMN IF NOT EXISTS fixed_sales_revenue NUMERIC(14,2)",
        # AUD-priced plans (AMC 1 / AMC 2). Keyed by plan_type so it works whatever
        # product they sit under. aud_amount = package in AUD; fixed_sales_revenue =
        # the flat INR credited to the sales member (NOT package-cost-discount);
        # markup_pct = added to the live AUD rate to approximate ICICI's card rate.
        """CREATE TABLE IF NOT EXISTS amc_aud_pricing (
            id SERIAL PRIMARY KEY,
            plan_type TEXT NOT NULL UNIQUE,
            aud_amount NUMERIC(12,2) DEFAULT 0,
            fixed_sales_revenue NUMERIC(12,2) DEFAULT 0,
            markup_pct NUMERIC(5,2) DEFAULT 3,
            is_active INTEGER DEFAULT 1,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)""",
    ):
        try:
            conn.execute(ddl); conn.commit()
        except Exception:
            try: conn.rollback()
            except Exception: pass
    # Seed AMC 1 / AMC 2 AUD pricing (only if absent — never overwrite edited values).
    for _p in ({'plan_type': 'AMC 1', 'aud': 1550, 'rev': 15000},
               {'plan_type': 'AMC 2', 'aud': 2000, 'rev': 20000}):
        try:
            _ex = conn.execute("SELECT id FROM amc_aud_pricing WHERE plan_type = ?", (_p['plan_type'],)).fetchone()
            if not _ex:
                conn.execute("INSERT INTO amc_aud_pricing (plan_type, aud_amount, fixed_sales_revenue, markup_pct) VALUES (?, ?, ?, 3)",
                             (_p['plan_type'], _p['aud'], _p['rev']))
                conn.commit()
        except Exception:
            try: conn.rollback()
            except Exception: pass
    # ONE-TIME migration (marker-gated): fold amc_aud_pricing into plan_packages so
    # AMC 1/AMC 2 are managed in Products & Services like every other plan. Runs once,
    # then the admin owns the values (so a later edit is never overwritten).
    try:
        conn.execute("CREATE TABLE IF NOT EXISTS _import_markers (key TEXT PRIMARY KEY, value TEXT)")
        _mk = conn.execute("SELECT value FROM _import_markers WHERE key = 'amc_currency_migrated'").fetchone()
        if not _mk:
            conn.execute(
                "UPDATE plan_packages pp SET currency = 'AUD', package_amount = aap.aud_amount, "
                "fx_markup_pct = aap.markup_pct, fixed_sales_revenue = aap.fixed_sales_revenue "
                "FROM amc_aud_pricing aap "
                "WHERE pp.plan_type = aap.plan_type AND COALESCE(aap.is_active,1) = 1 "
                "AND COALESCE(pp.currency, 'INR') = 'INR'")
            conn.execute("INSERT INTO _import_markers (key, value) VALUES ('amc_currency_migrated', 'v1') "
                         "ON CONFLICT (key) DO NOTHING")
            conn.commit()
    except Exception as _mig_e:
        logging.warning(f"amc->plan_packages currency migration: {_mig_e}")
        try: conn.rollback()
        except Exception: pass
    conn.close()


