def ensure_installment_approvals_unique():
    """Make sure installment_approvals EXISTS (it was missing on live — its
    original CREATE block never ran, so approving a payment 500'd with 'relation
    does not exist', founder 2026-07-20), then back-fill the UNIQUE(registration_id,
    inst_no): dedupe (keep the newest) before creating the index or it fails on
    existing duplicates."""
    conn = None
    try:
        conn = get_db()
        try:
            conn.execute('''CREATE TABLE IF NOT EXISTS installment_approvals (
                id SERIAL PRIMARY KEY,
                registration_id INTEGER,
                registration_number TEXT,
                inst_no INTEGER,
                base_amount NUMERIC(14,2) DEFAULT 0,
                gst_amount NUMERIC(14,2) DEFAULT 0,
                total_amount NUMERIC(14,2) DEFAULT 0,
                payment_method TEXT,
                payment_date TEXT,
                pathway TEXT,
                status TEXT DEFAULT 'pending',
                ops_payment_id INTEGER,
                reviewed_by INTEGER,
                reviewed_at TIMESTAMP,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(registration_id, inst_no)
            )''')
            conn.commit()
        except Exception:
            conn.rollback()
        try:
            conn.execute(
                "DELETE FROM installment_approvals a USING installment_approvals b "
                "WHERE a.registration_id = b.registration_id AND a.inst_no = b.inst_no AND a.id < b.id")
            conn.commit()
        except Exception:
            conn.rollback()
        try:
            conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS ux_inst_appr_reg_inst "
                         "ON installment_approvals(registration_id, inst_no)")
            conn.commit()
        except Exception:
            conn.rollback()
    except Exception as e:
        logging.warning("ensure_installment_approvals_unique: %s", e)
        try:
            if conn: conn.rollback()
        except Exception:
            pass
    finally:
        try:
            if conn: conn.close()
        except Exception:
            pass


ensure_installment_approvals_unique()


