def seed_pathway_product_plans():
    """Idempotent sync of the founder's Pathway -> Product -> Plan Type sheet into
    lookup_options (the plan-type cascade) + plan_packages. Links every plan type
    to its product + pathway and adds the new ones, so sales dropdowns are complete
    and correct. NEVER touches client records or existing package amounts."""
    #   (pathway slug used by clients/reg-numbers, product name, [plan types])
    mapping = [
        ('australia',  'AUS PGCP',           ['Australia PGCP 2023', 'Australia PGCP 2024',
                                              'Australia PGCP 2025', 'Australia PGCP 2026']),
        ('portfolio',  'Portfolio Services', ['Portfolio Plus']),
        ('consulting', 'AMC Consulting',     ['Australia CSS 2024', 'Australia CSS 2025',
                                              'Australia CSS 2026', 'Australia CSS 2026 (V2)']),
        ('consulting', 'UK Consulting',      ['UK CSS 2024', 'UK CSS 2025', 'UK CSS 2026']),
        ('consulting', 'USA Consulting',     ['USA CSS 2025', 'USA CSS 2026']),
        ('consulting', 'UAE Consulting',     ['UAE CSS 2025']),
        ('training',   'AMC MCQ',            ['AMC 1']),
        ('training',   'AMC Clinical',       ['AMC 2']),
        ('uae',        'UAE PGCP',           ['GULF PGCP 2025', 'UAE PGCP 2025', 'UAE PGCP 2026']),
        ('plab',       'UK PGCP',            ['2022 Integrated Consulting', '2022 Integrated Consulting - Dual',
                                              '2022 Premium Consulting', 'Full Spon', 'Integrated Consulting',
                                              'PGCP 2023', 'PGCP 2023 - Dual', 'PGCP 2024', 'PGCP 2025']),
    ]
    try:
        conn = get_db()
    except Exception:
        return
    linked = added = 0
    try:
        for pathway, product, plans in mapping:
            prod = conn.execute("SELECT id FROM products_services WHERE name = ? LIMIT 1", (product,)).fetchone()
            pid = prod['id'] if prod else None
            for i, pt in enumerate(plans):
                try:
                    ex = conn.execute("SELECT id FROM lookup_options WHERE category = 'plan_type' AND value = ? LIMIT 1", (pt,)).fetchone()
                    if ex:
                        conn.execute("UPDATE lookup_options SET product_name = ?, pathway = ?, is_active = TRUE "
                                     "WHERE category = 'plan_type' AND value = ?", (product, pathway, pt))
                        linked += 1
                    else:
                        conn.execute("INSERT INTO lookup_options (category, label, value, product_name, pathway, is_active, sort_order) "
                                     "VALUES ('plan_type', ?, ?, ?, ?, TRUE, ?)", (pt, pt, product, pathway, i))
                        added += 1
                    conn.commit()
                except Exception:
                    try: conn.rollback()
                    except Exception: pass
                if pid:
                    try:
                        pp = conn.execute("SELECT id FROM plan_packages WHERE product_id = ? AND plan_type = ?", (pid, pt)).fetchone()
                        if not pp:
                            conn.execute("INSERT INTO plan_packages (product_id, plan_type, package_amount, is_active, sort_order) "
                                         "VALUES (?, ?, 0, 1, ?)", (pid, pt, i))
                            conn.commit()
                    except Exception:
                        try: conn.rollback()
                        except Exception: pass
        logging.info(f"seed_pathway_product_plans: linked {linked}, added {added} plan-type mappings")
    finally:
        try: conn.close()
        except Exception: pass


seed_pathway_product_plans()


def seed_academic_field_order():
    """Order the Step-2 (Academic Details) fields to match the guided cascade:
    IMG/FMG -> college -> MBBS -> internship -> gap -> working -> speciality.
    Idempotent — re-runs each boot, only touches these known academic fields.
    'country' is disambiguated to step 2 (the FMG country of study), so the
    step-1 personal 'country' field is left untouched."""
    order = ['img_fmg', 'img_medical_college', 'fmg_medical_college', 'country',
             'mbbs_status', 'mbbs_start_date', 'mbbs_end_date',
             'internship_status', 'internship_hospital', 'internship_location',
             'internship_start_date', 'internship_end_date',
             'internship_hospital_2', 'internship_location_2',
             'internship_gap', 'gap_in_months', 'gap_reason',
             'working_status', 'working_hospital_name',
             'speciality_interest_1', 'speciality_interest_2', 'additional_info']
    conn = get_db()
    try:
        for i, fn in enumerate(order):
            try:
                if fn == 'country':
                    conn.execute("UPDATE client_form_configs SET display_order = ? "
                                 "WHERE field_name = ? AND role = 'client' AND step_number = 2",
                                 (i * 10, fn))
                else:
                    conn.execute("UPDATE client_form_configs SET display_order = ? "
                                 "WHERE field_name = ? AND role = 'client'", (i * 10, fn))
                conn.commit()
            except Exception as e:
                logging.warning(f"seed_academic_field_order {fn}: {e}")
                try: conn.rollback()
                except Exception: pass
        logging.info("seed_academic_field_order: applied academic step-2 ordering")
    finally:
        try: conn.close()
        except Exception: pass


seed_academic_field_order()


def seed_fix_state_city_fields():
    """Ensure every product's client registration form has State and City as
    proper cascade dropdowns. Older per-product configs sometimes stored these
    as plain text or with the wrong field_options, so picking a state produced
    no city list. Idempotent — safe no-op when already correct."""
    conn = get_db()
    try:
        conn.execute("UPDATE client_form_configs SET field_type = 'select', field_options = 'db:states' "
                     "WHERE field_name = 'state' AND role = 'client'")
        conn.execute("UPDATE client_form_configs SET field_type = 'select', field_options = 'db:cities' "
                     "WHERE field_name = 'city' AND role = 'client'")
        # Ops 'Current Stage' must use the PATHWAY-scoped 'current_stage' lookup
        # (like Joined Stage), NOT the PLAB-only 'plab_stage' category — otherwise
        # every pathway's ops verification showed the UK/PLAB stages.
        conn.execute("UPDATE client_form_configs SET field_type = 'select', field_options = 'db:current_stage' "
                     "WHERE field_name = 'current_stage' AND role = 'ops' "
                     "AND (field_options IN ('db:plab_stage', 'db:plab_stages') OR field_options IS NULL OR field_options = '')")
        # Data-consistency: an ACTIVE employee must have employment_status 'active'.
        # A stale non-active value made the profile edit form show an exit status,
        # so saving the profile silently deactivated them. Align the two.
        try:
            conn.execute("UPDATE employees SET employment_status = 'active' "
                         "WHERE COALESCE(is_active,0) = 1 AND COALESCE(employment_status,'') <> 'active'")
            conn.commit()
        except Exception:
            try: conn.rollback()
            except Exception: pass
        conn.commit()
        logging.info("seed_fix_state_city_fields: normalised state/city + ops current_stage + employee status")
    except Exception as e:
        logging.warning(f"seed_fix_state_city_fields: {e}")
        try: conn.rollback()
        except Exception: pass
    finally:
        try: conn.close()
        except Exception: pass


seed_fix_state_city_fields()


def seed_clean_junk_cities():
    """A bad city import left rows containing stray control characters (e.g. a
    lone U+000E), which showed as a blank first option in every state's city
    dropdown. This strips control characters everywhere they appear so real
    names survive ('Bangalore\\x0e' -> 'Bangalore'), removes rows that are pure
    junk (empty after stripping), de-dupes the resulting (state, name) pairs,
    and — most importantly — repairs the SAME junk in every client's saved city
    so no client record is left pointing at a bad value. Idempotent."""
    conn = get_db()
    try:
        # 1) Repair client-facing saved city values FIRST (keep the real name,
        #    blank only if the whole value was junk). Cities are stored by name.
        for tbl in ('client_registrations', 'plab_clients'):
            try:
                conn.execute(
                    f"UPDATE {tbl} SET city = NULLIF(BTRIM(regexp_replace(city, '[[:cntrl:]]', '', 'g')), '') "
                    f"WHERE city IS NOT NULL AND city ~ '[[:cntrl:]]'")
                conn.commit()
            except Exception as e:
                logging.warning(f"seed_clean_junk_cities {tbl}: {e}")
                try: conn.rollback()
                except Exception: pass
        # 2) Strip control chars from the cities lookup names
        try:
            conn.execute("UPDATE cities SET name = BTRIM(regexp_replace(name, '[[:cntrl:]]', '', 'g')) "
                         "WHERE name ~ '[[:cntrl:]]'")
            conn.commit()
        except Exception as e:
            logging.warning(f"seed_clean_junk_cities strip: {e}")
            try: conn.rollback()
            except Exception: pass
        # 3) Delete rows that are now empty (pure junk)
        try:
            conn.execute("DELETE FROM cities WHERE COALESCE(BTRIM(name), '') = ''")
            conn.commit()
        except Exception as e:
            logging.warning(f"seed_clean_junk_cities delete-empty: {e}")
            try: conn.rollback()
            except Exception: pass
        # 4) De-dupe identical (state_id, name) rows the strip may have created
        try:
            conn.execute("DELETE FROM cities a USING cities b "
                         "WHERE a.id > b.id AND a.state_id = b.state_id AND a.name = b.name")
            conn.commit()
        except Exception as e:
            logging.warning(f"seed_clean_junk_cities dedupe: {e}")
            try: conn.rollback()
            except Exception: pass
        logging.info("seed_clean_junk_cities: cleaned control-char city data")
    finally:
        try: conn.close()
        except Exception: pass


seed_clean_junk_cities()


