@app.route('/api/countries')
@login_required
def api_countries():
    """Return all active countries as JSON."""
    conn = get_db()
    try:
        rows = conn.execute("SELECT id, name, code, currency_code FROM countries WHERE is_active = TRUE ORDER BY name").fetchall()
        return jsonify([{'id': r['id'], 'name': r['name'], 'code': r['code'], 'currency_code': r['currency_code']} for r in rows])
    except Exception as e:
        logging.error(f"api_countries: {e}")
        return jsonify([])
    finally:
        conn.close()


@app.route('/api/states')
@login_required
def api_states():
    """Return all active states as JSON."""
    conn = get_db()
    try:
        rows = conn.execute("SELECT id, name FROM states WHERE is_active = TRUE ORDER BY sort_order, name").fetchall()
        return jsonify([{'id': r['id'], 'name': r['name']} for r in rows])
    except Exception as e:
        logging.error(f"api_states: {e}")
        return jsonify([])
