def set_welcome_email_format_v2_once():
    """Apply the founder's welcome-email format (2026-07-20): polished copy + a
    Contact Person / Designation / Contact Number table, with the counsellor row
    and product name dynamic. One-time (marker-guarded) so a later manual edit in
    /admin/email-templates is never overwritten."""
    MARKER = 'welcome_email_format_v2'
    conn = None
    try:
        conn = get_db()
        conn.execute("CREATE TABLE IF NOT EXISTS _import_markers (key TEXT PRIMARY KEY, value TEXT)")
        seen = conn.execute("SELECT value FROM _import_markers WHERE key = ?", (MARKER,)).fetchone()
        if seen and seen['value'] == 'done':
            conn.close(); return
        conn.execute(
            "UPDATE email_templates SET subject = ?, body_html = ?, updated_at = CURRENT_TIMESTAMP "
            "WHERE template_key = 'welcome_email'",
            ('Welcome to {{product_name}} — GooCampus', _WELCOME_EMAIL_V2_HTML))
        conn.execute("INSERT INTO _import_markers (key, value) VALUES (?, 'done') "
                     "ON CONFLICT(key) DO UPDATE SET value = 'done'", (MARKER,))
        conn.commit()
        logging.info("welcome_email format v2 applied")
    except Exception as e:
        logging.warning("set_welcome_email_format_v2_once: %s", e)
        try:
            if conn: conn.rollback()
        except Exception:
            pass
    finally:
        try:
            if conn: conn.close()
        except Exception:
            pass


def _sc_body(inner):
    """Wrap inner HTML in the branded email shell (navy header + logo + card)."""
    try:
        from email_utils import render_branded_email
        return render_branded_email('', inner, '')
    except Exception:
        return ('<div style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;">' + inner + '</div>')


def _sc_render(conn, key, context=None):
    """(subject, body_html) for a Standard Consulting lifecycle email from its
    EDITABLE template, or None to fall back to the built-in hardcoded email.

    Returns None when the template is missing, disabled, or empty — so every
    sender keeps working exactly as today until the founder edits/enables the
    template in /admin/email-templates. Placeholders like {{client_name}} are
    substituted from `context`. (founder 2026-07-22)"""
    try:
        row = conn.execute("SELECT * FROM email_templates WHERE template_key = ?", (key,)).fetchone()
    except Exception:
        return None
    if not row:
        return None
    tpl = dict(row)
    if not tpl.get('enabled'):
        return None
    if not (tpl.get('body_html') or '').strip():
        return None
    try:
        subject, body = _render_stage_email(tpl, context or {})
        if not (subject or '').strip() or not (body or '').strip():
            return None
        return (subject, body)
    except Exception as e:
        logging.warning("_sc_render(%s): %s", key, e)
        return None


