# ── Auto-publish scheduler (10 AM + 5 PM IST daily, FIFO) ──
# Slots: 10:00 AM IST and 5:00 PM IST — one PDF per slot, oldest first.
# On startup we catch up on any missed slots for today so deploys/restarts
# don't cause skipped publishes.

def neetpg_auto_publish():
    """Publish the next draft PDF PER TAB (each category+doc_type queues independently,
    FIFO oldest-first). So at each slot every tab rolls out one PDF in parallel, rather
    than all tabs sharing one global 1-per-slot queue."""
    try:
        conn = get_db()
        # One oldest draft per (category, doc_type) tab. Postgres DISTINCT ON keeps the
        # first row per group given the ORDER BY, i.e. the oldest upload in each tab.
        drafts = conn.execute(
            "SELECT DISTINCT ON (category, doc_type) id, title, state, category, doc_type "
            "FROM neetpg_pdfs WHERE is_published = 0 AND is_active = 1 AND auto_schedule = 1 "
            "ORDER BY category, doc_type, upload_date ASC"
        ).fetchall()
        if not drafts:
            print("[AUTO_PUBLISH] No drafts to publish", flush=True)
            conn.close()
            return
        for draft in drafts:
            conn.execute(
                "UPDATE neetpg_pdfs SET is_published = 1, published_at = CURRENT_TIMESTAMP WHERE id = ?",
                (draft['id'],)
            )
            conn.commit()
            print(f"[AUTO_PUBLISH] Published PDF id={draft['id']} tab={draft.get('category')}/{draft.get('doc_type')} title='{draft['title']}'", flush=True)
            # NOTE: no per-PDF WhatsApp blast — leads get ONE batched reminder every
            # ~2 days via neetpg_reminder_digest() (Meta frequency-caps per-recipient).
        conn.close()
    except Exception as e:
        logging.error(f"neetpg_auto_publish error: {e}")


def neetpg_catchup_publish():
    """On startup, publish drafts for any slots missed today.

    Approach: count how many 10 AM / 1 PM / 5 PM slots have passed today in IST,
    then count how many PDFs were already published today (IST date).
    If published < passed_slots, publish the difference (FIFO, max 3/day).
    Uses IST-based date comparison via AT TIME ZONE to avoid UTC mismatch.
    """
    try:
        import pytz
        ist = pytz.timezone('Asia/Kolkata')
        now_ist = datetime.now(ist)

        # How many slots have passed today?
        slots_passed = 0
        if now_ist.hour >= 10:
            slots_passed += 1
        if now_ist.hour >= 13:
            slots_passed += 1
        if now_ist.hour >= 17:
            slots_passed += 1

        if slots_passed == 0:
            logging.info("Catchup: no slots passed yet today, nothing to do")
            return

        today_ist_str = now_ist.strftime('%Y-%m-%d')
        conn = get_db()
        # Per-tab catchup: each (category, doc_type) queue is independent, so publish up to
        # (slots_passed - that-tab's-publishes-today) for EVERY tab that still has drafts.
        tabs = conn.execute(
            "SELECT DISTINCT category, doc_type FROM neetpg_pdfs "
            "WHERE is_published = 0 AND is_active = 1 AND auto_schedule = 1"
        ).fetchall()
        total = 0
        for tab in tabs:
            pub_today = conn.execute(
                "SELECT COUNT(*) as c FROM neetpg_pdfs WHERE is_published = 1 "
                "AND category = ? AND doc_type = ? "
                "AND (published_at AT TIME ZONE 'UTC' AT TIME ZONE 'Asia/Kolkata')::date = ?::date",
                (tab['category'], tab['doc_type'], today_ist_str)
            ).fetchone()['c']
            need = slots_passed - pub_today          # missed slots for THIS tab (<= 3)
            if need <= 0:
                continue
            drafts = conn.execute(
                "SELECT id, title, state FROM neetpg_pdfs WHERE is_published = 0 AND is_active = 1 "
                "AND auto_schedule = 1 AND category = ? AND doc_type = ? ORDER BY upload_date ASC LIMIT ?",
                (tab['category'], tab['doc_type'], need)
            ).fetchall()
            for draft in drafts:
                conn.execute(
                    "UPDATE neetpg_pdfs SET is_published = 1, published_at = CURRENT_TIMESTAMP WHERE id = ?",
                    (draft['id'],)
                )
                logging.info(f"Catchup-published NEET PG PDF id={draft['id']} tab={tab['category']}/{tab['doc_type']} title={draft['title']}")
                # No per-PDF blast — batched reminder handles notifications (see digest).
                total += 1
            if drafts:
                conn.commit()
        logging.info(f"Catchup: {slots_passed} slot(s) passed today; per-tab catchup-published {total}")
        conn.close()
    except Exception as e:
        logging.error(f"neetpg_catchup_publish error: {e}")


def neetpg_reminder_digest():
    """Send ONE batched WhatsApp reminder to all NEET PG leads when new PDFs have been
    published — but at most once every ~2 days (Meta frequency-caps recipients, so we
    never blast per file). Generic 'new files available' nudge, not per-file."""
    try:
        conn = get_db()
        conn.execute("CREATE TABLE IF NOT EXISTS neetpg_reminders ("
                     "id SERIAL PRIMARY KEY, sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, new_files INTEGER DEFAULT 0)")
        conn.commit()
        last = conn.execute("SELECT sent_at FROM neetpg_reminders ORDER BY id DESC LIMIT 1").fetchone()
        last_at = last['sent_at'] if last else None
        if last_at:
            gap_ok = conn.execute(
                "SELECT (CURRENT_TIMESTAMP - ?::timestamp) >= INTERVAL '2 days' AS ok", (last_at,)).fetchone()['ok']
            new_cnt = conn.execute(
                "SELECT COUNT(*) AS c FROM neetpg_pdfs WHERE is_published = 1 AND published_at > ?", (last_at,)).fetchone()['c']
        else:
            gap_ok = True
            new_cnt = conn.execute("SELECT COUNT(*) AS c FROM neetpg_pdfs WHERE is_published = 1").fetchone()['c']
        if gap_ok and new_cnt > 0:
            conn.execute("INSERT INTO neetpg_reminders (new_files) VALUES (?)", (new_cnt,))
            conn.commit()
            conn.close()
            # Reuse the college notify with a GENERIC title → one reminder, not per file.
            neetpg_wa_notify_leads("new cut-offs & documents", "")
            logging.info(f"neetpg_reminder_digest: reminder sent for {new_cnt} new file(s)")
        else:
            conn.close()
            logging.info(f"neetpg_reminder_digest: skipped (gap_ok={gap_ok}, new_files={new_cnt})")
    except Exception as e:
        logging.error(f"neetpg_reminder_digest error: {e}")


# ── Item F-2: 30-day check-in scheduler ─────────────────────────────
# Daily job: find clients onboarded ~30 working days ago and fire the
# `thirty_day_checkin` stage email (gated on the template being
# enabled in /admin/email-templates).
#
# Freshness window of FRESHNESS_DAYS guards against retroactive bulk-
# send: when an admin first enables the template, only clients due
# within the past `FRESHNESS_DAYS` calendar days will be emailed.
# Older candidates are silently marked `thirty_day_checkin_skipped=1`
# so they don't keep getting reconsidered each day.

THIRTY_DAY_CHECKIN_FRESHNESS_DAYS = 7


def process_thirty_day_checkins():
    """One pass of the 30-day check-in job. Safe to call from the
    daily APScheduler trigger OR an admin "run now" button. Never
    raises. Returns a summary dict for caller-side reporting.
    """
    summary = {'sent': 0, 'disabled': 0, 'not_due': 0,
               'skipped_late': 0, 'error': 0, 'considered': 0}
    conn = None
    try:
        from working_days import (
            add_working_days, load_holidays_set, now_ist,
        )
        from datetime import datetime as _dt
        conn = get_db()
        holidays_set = load_holidays_set(conn)
        today_ist = now_ist().date()

        rows = conn.execute("""
            SELECT id, client_id, registration_number,
                   onboarding_status, updated_at,
                   thirty_day_checkin_sent_at,
                   thirty_day_checkin_skipped
              FROM client_onboarding
             WHERE LOWER(COALESCE(onboarding_status,'')) = 'completed'
               AND thirty_day_checkin_sent_at IS NULL
               AND COALESCE(thirty_day_checkin_skipped, 0) = 0
        """).fetchall()
        summary['considered'] = len(rows)

        for r in rows:
            try:
                onboarded_str = str(r['updated_at'] or '')[:10]
                if not onboarded_str:
                    continue
                try:
                    base = _dt.strptime(onboarded_str, '%Y-%m-%d').date()
                except Exception:
                    continue
                # Compute the projected due date once -- same logic
                # the client's dashboard timeline shows.
                due = add_working_days(
                    base, 30, holidays_set, cutoff_hour=None)
                days_overdue = (today_ist - due).days
                if days_overdue < 0:
                    summary['not_due'] += 1
                    continue
                if days_overdue > THIRTY_DAY_CHECKIN_FRESHNESS_DAYS:
                    # Past the freshness window -- mark skipped so we
                    # don't keep reconsidering this row every morning.
                    try:
                        conn.execute(
                            "UPDATE client_onboarding "
                            "  SET thirty_day_checkin_skipped = 1 "
                            "WHERE id = ?",
                            (r['id'],))
                        conn.commit()
                    except Exception: pass
                    summary['skipped_late'] += 1
                    continue

                client_row = conn.execute(
                    "SELECT * FROM plab_clients WHERE id = ?",
                    (r['client_id'],)
                ).fetchone()
                if not client_row:
                    continue
                ctx = _stage_email_context_from_client(dict(client_row))
                result = _send_stage_email(
                    conn, 'thirty_day_checkin', r['client_id'], ctx)

                if result['status'] == 'sent':
                    conn.execute(
                        "UPDATE client_onboarding "
                        "  SET thirty_day_checkin_sent_at = CURRENT_TIMESTAMP "
                        "WHERE id = ?", (r['id'],))
                    conn.commit()
                    summary['sent'] += 1
                elif result['status'] == 'disabled':
                    # Don't mark sent: when admin enables the
                    # template, the row remains a candidate on
                    # tomorrow's run (still within freshness).
                    summary['disabled'] += 1
                else:
                    summary['error'] += 1
            except Exception as e:
                logging.error(
                    f"thirty_day_checkin row {r.get('id')}: {e}")
                summary['error'] += 1
        logging.info(
            f"thirty_day_checkin job: considered={summary['considered']}, "
            f"sent={summary['sent']}, disabled={summary['disabled']}, "
            f"not_due={summary['not_due']}, "
            f"skipped_late={summary['skipped_late']}, "
            f"errors={summary['error']}")
    except Exception as e:
        logging.error(f"process_thirty_day_checkins fatal: {e}")
    finally:
        try:
            if conn is not None: conn.close()
        except Exception: pass
    return summary


@app.route('/admin/email-templates/run-checkin-job-now', methods=['POST'])
@login_required
def admin_run_thirty_day_checkin_job():
    """Admin-triggered immediate run of the 30-day check-in job.
    Useful for testing after enabling the template -- no need to
    wait for tomorrow's 9 AM IST cron."""
    user = get_user()
    if not (user and user['is_admin']):
        flash('Admin access required', 'error')
        return redirect(url_for('dashboard'))
    summary = process_thirty_day_checkins()
    flash(
        f"Check-in job: considered {summary['considered']}, "
        f"sent {summary['sent']}, disabled {summary['disabled']}, "
        f"not due {summary['not_due']}, "
        f"skipped (past freshness) {summary['skipped_late']}, "
        f"errors {summary['error']}",
        'success' if summary['sent'] else 'info'
    )
    return redirect(url_for('admin_email_templates_list'))


def start_neetpg_scheduler():
    """Start background scheduler for auto-publishing PDFs at 10 AM, 1 PM and 5 PM IST.

    Also runs the daily 30-day check-in job (Item F-2) and a one-
    time catchup to handle any slots missed due to app restarts.
    """
    try:
        from apscheduler.schedulers.background import BackgroundScheduler
        from apscheduler.triggers.cron import CronTrigger
        import pytz
        ist = pytz.timezone('Asia/Kolkata')
        scheduler = BackgroundScheduler()
        # 10:00 AM IST daily
        scheduler.add_job(neetpg_auto_publish, CronTrigger(hour=10, minute=0, timezone=ist), id='neetpg_publish_morning')
        # 1:00 PM IST daily
        scheduler.add_job(neetpg_auto_publish, CronTrigger(hour=13, minute=0, timezone=ist), id='neetpg_publish_afternoon')
        # 5:00 PM IST daily
        scheduler.add_job(neetpg_auto_publish, CronTrigger(hour=17, minute=0, timezone=ist), id='neetpg_publish_evening')
        # Batched "new files available" WhatsApp reminder — checked daily at 6:30 PM IST,
        # but self-gated to fire at most once every ~2 days and only when new PDFs exist.
        scheduler.add_job(neetpg_reminder_digest, CronTrigger(hour=18, minute=30, timezone=ist), id='neetpg_reminder_digest')
        # Item F-2: 30-day check-in -- 09:00 AM IST daily. Cheap
        # query (uses thirty_day_checkin_sent_at IS NULL filter), so
        # safe to run unconditionally even if the template is
        # disabled (helper short-circuits with status='disabled').
        scheduler.add_job(
            process_thirty_day_checkins,
            CronTrigger(hour=9, minute=0, timezone=ist),
            id='thirty_day_checkin_daily',
        )
        scheduler.start()
        logging.info(
            "Schedulers started: NEET PG auto-publish (10am+1pm+5pm IST), "
            "30-day check-in (9am IST)")
        # Run catchup for missed slots after restarts/deploys
        neetpg_catchup_publish()
    except ImportError:
        logging.warning("APScheduler not installed. Auto-publish disabled. pip install APScheduler pytz")
    except Exception as e:
        logging.error(f"Scheduler start failed: {e}")


# Start scheduler on app boot (only in production, not in reloader child)
if os.environ.get('WERKZEUG_RUN_MAIN') != 'true' or os.environ.get('DATABASE_URL'):
    start_neetpg_scheduler()


