@app.route('/whatsapp')
@admin_required
def wa_dashboard():
    conn = get_db()
    try:
        # Campaign stats
        total_campaigns = conn.execute("SELECT COUNT(*) AS cnt FROM wa_campaigns").fetchone()['cnt']
        active_campaigns = conn.execute("SELECT COUNT(*) AS cnt FROM wa_campaigns WHERE status='sending'").fetchone()['cnt']
        total_contacts = conn.execute("SELECT COUNT(*) AS cnt FROM wa_contacts WHERE opted_in=1").fetchone()['cnt']
        total_messages = conn.execute("SELECT COUNT(*) AS cnt FROM wa_messages").fetchone()['cnt']
        delivered = conn.execute("SELECT COUNT(*) AS cnt FROM wa_messages WHERE status='delivered' OR status='read'").fetchone()['cnt']
        read_count = conn.execute("SELECT COUNT(*) AS cnt FROM wa_messages WHERE status='read'").fetchone()['cnt']
        failed = conn.execute("SELECT COUNT(*) AS cnt FROM wa_messages WHERE status='failed'").fetchone()['cnt']
        delivery_rate = round((delivered / total_messages * 100), 1) if total_messages > 0 else 0
        read_rate = round((read_count / total_messages * 100), 1) if total_messages > 0 else 0

        # Recent campaigns
        recent_campaigns = conn.execute("""
            SELECT c.*, e.first_name || ' ' || COALESCE(e.last_name,'') as created_by_name
            FROM wa_campaigns c
            LEFT JOIN employees e ON c.created_by = e.id
            ORDER BY c.created_at DESC LIMIT 10
        """).fetchall()

        # Recent messages
        recent_messages = conn.execute("""
            SELECT m.*, wc.name as contact_name, wc.phone as contact_phone
            FROM wa_messages m
            LEFT JOIN wa_contacts wc ON m.contact_id = wc.id
            ORDER BY m.created_at DESC LIMIT 20
        """).fetchall()
    except Exception as e:
        logging.error(f"wa_dashboard error: {e}")
        conn.close()
        return render_template('wa_dashboard.html',
            active_section='whatsapp',
            total_campaigns=0, active_campaigns=0, total_contacts=0,
            total_messages=0, delivered=0, read_count=0, failed=0,
            delivery_rate=0, read_rate=0, recent_campaigns=[], recent_messages=[]
        )

    conn.close()
    return render_template('wa_dashboard.html',
        active_section='whatsapp',
        total_campaigns=total_campaigns,
        active_campaigns=active_campaigns,
        total_contacts=total_contacts,
        total_messages=total_messages,
        delivered=delivered,
        read_count=read_count,
        failed=failed,
        delivery_rate=delivery_rate,
        read_rate=read_rate,
        recent_campaigns=recent_campaigns,
        recent_messages=recent_messages
    )


@app.route('/whatsapp/contacts')
@admin_required
def wa_contacts_list():
    conn = get_db()
    search = request.args.get('search', '').strip()
    source_filter = request.args.get('source', '')
    page = int(request.args.get('page', 1))
    per_page = 50

    sql = "SELECT * FROM wa_contacts WHERE 1=1"
    count_sql = "SELECT COUNT(*) AS cnt FROM wa_contacts WHERE 1=1"
    params = []

    if search:
        sql += " AND (phone LIKE ? OR name LIKE ? OR email LIKE ?)"
        count_sql += " AND (phone LIKE ? OR name LIKE ? OR email LIKE ?)"
        s = f"%{search}%"
        params.extend([s, s, s])
    if source_filter:
        sql += " AND source = ?"
        count_sql += " AND source = ?"
        params.append(source_filter)

    total = conn.execute(count_sql, params).fetchone()['cnt']
    total_pages = max(1, -(-total // per_page))
    sql += " ORDER BY created_at DESC LIMIT ? OFFSET ?"
    contacts = conn.execute(sql, params + [per_page, (page - 1) * per_page]).fetchall()

    # Source options
    sources = conn.execute("SELECT DISTINCT source FROM wa_contacts WHERE source IS NOT NULL ORDER BY source").fetchall()

    return render_template('wa_contacts.html',
        active_section='whatsapp',
        contacts=contacts,
        total=total,
        page=page,
        total_pages=total_pages,
        search=search,
        source_filter=source_filter,
        sources=[s['source'] for s in sources]
    )


@app.route('/whatsapp/contacts/sync', methods=['POST'])
@admin_required
def wa_contacts_sync():
    """Sync contacts from NEET PG leads and PLAB clients into wa_contacts."""
    conn = get_db()
    synced = 0

    # Sync from NEET PG leads
    try:
        leads = conn.execute("SELECT phone, name, email FROM neetpg_leads WHERE phone IS NOT NULL AND phone != ''").fetchall()
        for lead in leads:
            phone = lead['phone'].strip().replace(' ', '').replace('-', '')
            if not phone.startswith('+') and not phone.startswith('91'):
                phone = '91' + phone
            existing = conn.execute("SELECT id FROM wa_contacts WHERE phone = ?", (phone,)).fetchone()
            if not existing:
                conn.execute("""INSERT INTO wa_contacts (phone, name, email, source, opted_in)
                    VALUES (?, ?, ?, 'neetpg_lead', 1)""",
                    (phone, lead['name'], lead['email']))
                synced += 1
    except Exception as e:
        logging.error(f"wa_contacts_sync neetpg: {e}")

    # Sync from PLAB clients
    try:
        clients = conn.execute("""SELECT phone_number, first_name, last_name, email, id
            FROM plab_clients WHERE phone_number IS NOT NULL AND phone_number != ''""").fetchall()
        for c in clients:
            phone = c['phone_number'].strip().replace(' ', '').replace('-', '')
            if not phone.startswith('+') and not phone.startswith('91'):
                phone = '91' + phone
            name = f"{c['first_name'] or ''} {c['last_name'] or ''}".strip()
            existing = conn.execute("SELECT id FROM wa_contacts WHERE phone = ?", (phone,)).fetchone()
            if not existing:
                conn.execute("""INSERT INTO wa_contacts (phone, name, email, source, source_id, opted_in)
                    VALUES (?, ?, ?, 'plab_client', ?, 1)""",
                    (phone, name, c['email'], c['id']))
                synced += 1
    except Exception as e:
        logging.error(f"wa_contacts_sync plab: {e}")

    conn.commit()
    flash(f'Synced {synced} new contacts', 'success')
    return redirect('/whatsapp/contacts')


@app.route('/whatsapp/contacts/import', methods=['POST'])
@admin_required
def wa_contacts_import():
    """Import contacts from CSV/Excel file. Expects columns: phone (required), name, email, tags."""
    import io
    file = request.files.get('file')
    if not file or not file.filename:
        flash('Please select a file to upload', 'error')
        return redirect('/whatsapp/contacts')

    filename = file.filename.lower()
    try:
        if filename.endswith('.csv'):
            import csv
            stream = io.StringIO(file.read().decode('utf-8-sig'))
            reader = csv.DictReader(stream)
            rows = list(reader)
        elif filename.endswith(('.xlsx', '.xls')):
            import openpyxl
            wb = openpyxl.load_workbook(io.BytesIO(file.read()), read_only=True, data_only=True)
            ws = wb.active
            headers_row = [str(c.value or '').strip().lower() for c in next(ws.iter_rows(min_row=1, max_row=1))]
            rows = []
            for row in ws.iter_rows(min_row=2, values_only=True):
                row_dict = {}
                for i, val in enumerate(row):
                    if i < len(headers_row):
                        row_dict[headers_row[i]] = str(val).strip() if val else ''
                rows.append(row_dict)
            wb.close()
        else:
            flash('Unsupported file format. Use CSV or XLSX.', 'error')
            return redirect('/whatsapp/contacts')
    except Exception as e:
        logging.error(f"wa_contacts_import parse: {e}")
        flash(f'Error reading file: {str(e)}', 'error')
        return redirect('/whatsapp/contacts')

    # Normalise header names
    def find_col(row, candidates):
        for c in candidates:
            if c in row:
                return row[c]
        return ''

    conn = get_db()
    imported = 0
    skipped = 0
    for row in rows:
        norm = {k.strip().lower().replace(' ', '_'): v for k, v in row.items()}
        phone_raw = find_col(norm, ['phone', 'phone_number', 'mobile', 'whatsapp', 'number', 'contact'])
        if not phone_raw:
            skipped += 1
            continue
        phone = phone_raw.strip().replace(' ', '').replace('-', '').replace('+', '')
        if phone.startswith('0'):
            phone = '91' + phone[1:]
        if not phone.startswith('91') and len(phone) == 10:
            phone = '91' + phone
        if len(phone) < 10:
            skipped += 1
            continue

        name = find_col(norm, ['name', 'full_name', 'contact_name', 'doctor_name']) or None
        email = find_col(norm, ['email', 'email_address']) or None
        tags = find_col(norm, ['tags', 'tag', 'label']) or None

        existing = conn.execute("SELECT id FROM wa_contacts WHERE phone = ?", (phone,)).fetchone()
        if existing:
            if name or email:
                updates = []
                params = []
                if name:
                    updates.append("name = COALESCE(NULLIF(name,''), ?)")
                    params.append(name)
                if email:
                    updates.append("email = COALESCE(NULLIF(email,''), ?)")
                    params.append(email)
                if tags:
                    updates.append("tags = COALESCE(tags || ',' || ?, ?)")
                    params.extend([tags, tags])
                params.append(existing['id'])
                conn.execute(f"UPDATE wa_contacts SET {', '.join(updates)} WHERE id = ?", params)
            skipped += 1
            continue

        conn.execute("""INSERT INTO wa_contacts (phone, name, email, source, tags, opted_in)
            VALUES (?, ?, ?, 'csv_import', ?, 1)""",
            (phone, name, email, tags))
        imported += 1

    conn.commit()

    # Create named contact list if list_name provided
    list_name = request.form.get('list_name', '').strip()
    if list_name and imported > 0:
        conn.execute("INSERT INTO wa_contact_lists (name, description, created_by) VALUES (?, ?, ?)",
            (list_name, f'Imported {imported} contacts from {file.filename}', session.get('user_id')))
        conn.commit()
        # Get list id
        new_list = conn.execute("SELECT id FROM wa_contact_lists WHERE name=? ORDER BY created_at DESC LIMIT 1",
            (list_name,)).fetchone()
        if new_list:
            # Link all contacts from this import (by source=csv_import, most recent)
            recent_contacts = conn.execute(
                "SELECT id FROM wa_contacts WHERE source='csv_import' ORDER BY created_at DESC LIMIT ?",
                (imported,)).fetchall()
            for rc in recent_contacts:
                conn.execute("INSERT INTO wa_contact_list_members (list_id, contact_id) VALUES (?, ?)",
                    (new_list['id'], rc['id']))
            conn.commit()
        flash(f'Imported {imported} contacts into list "{list_name}", {skipped} skipped', 'success')
    else:
        flash(f'Imported {imported} new contacts, {skipped} skipped (duplicate/invalid)', 'success')
    return redirect('/whatsapp/contacts')


