@app.route('/whatsapp/chat/<int:contact_id>/send', methods=['POST'])
@admin_required
def wa_chat_send(contact_id):
    conn = get_db()
    contact = conn.execute("SELECT * FROM wa_contacts WHERE id=?", (contact_id,)).fetchone()
    if not contact:
        return jsonify(success=False, error='Contact not found'), 404

    text = request.form.get('message', '').strip()
    if not text:
        return jsonify(success=False, error='Message is empty'), 400

    INFOBIP_KEY = os.environ.get('INFOBIP_API_KEY', '')
    INFOBIP_BASE = os.environ.get('INFOBIP_BASE_URL', '')
    sender = "15558246314"
    phone = contact['phone']
    if not phone.startswith('+'):
        phone = '+' + phone

    try:
        payload = {
            "from": sender,
            "to": phone,
            "content": {"text": text}
        }
        resp = requests.post(
            f"https://{INFOBIP_BASE}/whatsapp/1/message/text",
            json=payload,
            headers={"Authorization": f"App {INFOBIP_KEY}", "Content-Type": "application/json"},
            timeout=15
        )
        resp_data = resp.json()
        msg_id = None
        msg_status = 'sent'
        if resp.status_code < 300:
            if 'messages' in resp_data and resp_data['messages']:
                msg_id = resp_data['messages'][0].get('messageId')
        else:
            msg_status = 'failed'

        conn.execute("""INSERT INTO wa_messages
            (contact_id, direction, message_type, content, status, infobip_message_id,
             error_text, sent_at)
            VALUES (?, 'outbound', 'text', ?, ?, ?, ?, CURRENT_TIMESTAMP)""",
            (contact_id, text, msg_status, msg_id,
             str(resp_data) if msg_status == 'failed' else None))
        conn.execute("UPDATE wa_contacts SET last_message_at=CURRENT_TIMESTAMP WHERE id=?", (contact_id,))
        conn.commit()

        return jsonify(success=True, status=msg_status)
    except Exception as e:
        logging.error(f"wa_chat_send: {e}")
        return jsonify(success=False, error=str(e)), 500


@app.route('/whatsapp/test-send', methods=['POST'])
def wa_test_send():
    """Test endpoint to send a WhatsApp message directly via Infobip."""
    data = request.get_json(silent=True) or {}
    phone = data.get('phone', '')
    text = data.get('text', '')
    if not phone or not text:
        return jsonify(success=False, error='phone and text required'), 400

    INFOBIP_KEY = os.environ.get('INFOBIP_API_KEY', '')
    INFOBIP_BASE = os.environ.get('INFOBIP_BASE_URL', '')
    sender = "15558246314"
    if not phone.startswith('+'):
        phone = '+' + phone

    try:
        payload = {"from": sender, "to": phone, "content": {"text": text}}
        resp = requests.post(
            f"https://{INFOBIP_BASE}/whatsapp/1/message/text",
            json=payload,
            headers={"Authorization": f"App {INFOBIP_KEY}", "Content-Type": "application/json"},
            timeout=15
        )
        return jsonify(success=resp.status_code < 300, status_code=resp.status_code, response=resp.json())
    except Exception as e:
        return jsonify(success=False, error=str(e)), 500


@app.route('/whatsapp/quick-send', methods=['GET', 'POST'])
@admin_required
def wa_quick_send():
    """Send WhatsApp template message to multiple numbers, GC team, or a contact list."""
    conn = get_db()

    if request.method == 'POST':
        audience_type = request.form.get('audience_type', 'manual')
        template_id = request.form.get('template_id')
        placeholder_1 = request.form.get('placeholder_1', '').strip()

        tpl = conn.execute("SELECT * FROM wa_templates WHERE id=?", (template_id,)).fetchone()
        if not tpl:
            flash('Template not found', 'error')
            return redirect('/whatsapp/quick-send')

        # Collect phone numbers based on audience type
        phone_list = []  # list of (phone, name)

        if audience_type == 'manual':
            phone_raw = request.form.get('phone', '').strip()
            if not phone_raw:
                flash('Enter at least one phone number', 'error')
                return redirect('/whatsapp/quick-send')
            for p in phone_raw.replace('\n', ',').split(','):
                p = p.strip().replace(' ', '').replace('-', '').replace('+', '')
                if not p:
                    continue
                if p.startswith('0'):
                    p = '91' + p[1:]
                if not p.startswith('91') and len(p) == 10:
                    p = '91' + p
                if len(p) >= 10:
                    phone_list.append((p, None))

        elif audience_type == 'gc_team':
            team_ids = request.form.getlist('team_members')
            if team_ids:
                for tid in team_ids:
                    emp = conn.execute("SELECT name, phone FROM employees WHERE id=? AND is_active=1", (tid,)).fetchone()
                    if emp and emp['phone']:
                        phone = emp['phone'].strip().replace(' ', '').replace('-', '').replace('+', '')
                        if phone.startswith('0'):
                            phone = '91' + phone[1:]
                        if not phone.startswith('91') and len(phone) == 10:
                            phone = '91' + phone
                        if len(phone) >= 10:
                            phone_list.append((phone, emp['name']))

        elif audience_type == 'contact_list':
            list_id = request.form.get('contact_list_id')
            if list_id:
                members = conn.execute("""SELECT wc.phone, wc.name FROM wa_contact_list_members wlm
                    JOIN wa_contacts wc ON wlm.contact_id = wc.id
                    WHERE wlm.list_id = ?""", (list_id,)).fetchall()
                for m in members:
                    if m['phone']:
                        phone_list.append((m['phone'], m['name']))

        if not phone_list:
            flash('No valid phone numbers found', 'error')
            return redirect('/whatsapp/quick-send')

        import re as re_mod
        body_text = tpl.get('body_text') or ''
        ph_count = len(re_mod.findall(r'\{\{\d+\}\}', body_text))

        INFOBIP_KEY = os.environ.get('INFOBIP_API_KEY', '')
        INFOBIP_BASE = os.environ.get('INFOBIP_BASE_URL', '')
        # Send from the template's own approved sender (some templates live on a
        # different WhatsApp number); fall back to the default GooCampus sender.
        sender = (tpl.get('sender') or '').strip() or "15558246314"
        sent = 0
        failed = 0

        for phone, contact_name in phone_list:
            phone_with_plus = '+' + phone
            placeholders = []
            if ph_count > 0:
                placeholders = [placeholder_1 or contact_name or 'Doctor']
                for i in range(1, ph_count):
                    extra = request.form.get(f'placeholder_{i+1}', '').strip()
                    placeholders.append(extra)

            payload = {
                "messages": [{
                    "from": sender,
                    "to": phone_with_plus,
                    "content": {
                        "templateName": tpl['name'],
                        "templateData": {"body": {"placeholders": placeholders}},
                        "language": tpl['language'] or 'en'
                    }
                }]
            }

            try:
                resp = requests.post(
                    f"https://{INFOBIP_BASE}/whatsapp/1/message/template",
                    json=payload,
                    headers={"Authorization": f"App {INFOBIP_KEY}", "Content-Type": "application/json"},
                    timeout=15
                )
                resp_data = resp.json()
                msg_id = None
                if resp.status_code < 300:
                    if 'messages' in resp_data and resp_data['messages']:
                        msg_id = resp_data['messages'][0].get('messageId')

                    existing = conn.execute("SELECT id FROM wa_contacts WHERE phone=?", (phone,)).fetchone()
                    if not existing:
                        conn.execute("INSERT INTO wa_contacts (phone, name, source, opted_in) VALUES (?, ?, 'quick_send', 1)",
                            (phone, contact_name or placeholder_1 or None))
                        conn.commit()
                        existing = conn.execute("SELECT id FROM wa_contacts WHERE phone=?", (phone,)).fetchone()

                    conn.execute("""INSERT INTO wa_messages
                        (contact_id, direction, message_type, template_name, status, infobip_message_id, sent_at)
                        VALUES (?, 'outbound', 'template', ?, 'sent', ?, CURRENT_TIMESTAMP)""",
                        (existing['id'], tpl['name'], msg_id))
                    conn.execute("UPDATE wa_contacts SET last_message_at=CURRENT_TIMESTAMP WHERE id=?", (existing['id'],))
                    sent += 1
                else:
                    failed += 1
            except Exception as e:
                logging.error(f"wa_quick_send to {phone}: {e}")
                failed += 1

        conn.commit()
        flash(f'Sent to {sent} number{"s" if sent != 1 else ""}, {failed} failed (template: {tpl["name"]})', 'success')
        return redirect('/whatsapp/quick-send')

    templates = conn.execute("SELECT * FROM wa_templates WHERE status='APPROVED' ORDER BY name").fetchall()
    team_members = conn.execute("SELECT id, name, phone, department FROM employees WHERE is_active=1 ORDER BY name").fetchall()
    contact_lists = conn.execute("""SELECT cl.id, cl.name, cl.description, cl.created_at,
        COUNT(clm.id) as member_count
        FROM wa_contact_lists cl LEFT JOIN wa_contact_list_members clm ON cl.id = clm.list_id
        GROUP BY cl.id, cl.name, cl.description, cl.created_at ORDER BY cl.created_at DESC""").fetchall()
    return render_template('wa_quick_send.html',
        active_section='whatsapp',
        templates=templates,
        team_members=team_members,
        contact_lists=contact_lists
    )


@app.route('/whatsapp/debug')
def wa_debug():
    """Debug endpoint to check WA table status and Infobip account."""
    INFOBIP_KEY = os.environ.get('INFOBIP_API_KEY', '')
    INFOBIP_BASE = os.environ.get('INFOBIP_BASE_URL', '')
    headers = {"Authorization": f"App {INFOBIP_KEY}", "Content-Type": "application/json"}

    conn = get_db()
    results = {'tables': {}}
    for table in ['wa_contacts', 'wa_templates', 'wa_campaigns', 'wa_messages']:
        try:
            row = conn.execute(f"SELECT COUNT(*) AS cnt FROM {table}").fetchone()
            results['tables'][table] = row['cnt']
        except Exception as e:
            results['tables'][table] = f"ERROR: {str(e)}"
    conn.close()

    # Check Infobip senders
    try:
        resp = requests.get(f"https://{INFOBIP_BASE}/whatsapp/1/senders", headers=headers, timeout=10)
        results['senders'] = resp.json()
    except Exception as e:
        results['senders'] = str(e)

    # Check message log for last message
    msg_id = request.args.get('msg_id', '')
    if msg_id:
        try:
            resp = requests.get(f"https://{INFOBIP_BASE}/whatsapp/1/message/{msg_id}/status", headers=headers, timeout=10)
            results['message_status'] = resp.json()
        except Exception as e:
            results['message_status'] = str(e)

    results['infobip_base'] = INFOBIP_BASE
    results['api_key_set'] = bool(INFOBIP_KEY)

    return jsonify(results)


@app.route('/whatsapp/webhook', methods=['POST'])
def wa_webhook():
    """Infobip delivery report and incoming message webhook."""
    data = request.get_json(silent=True) or {}
    results = data.get('results', [])
    conn = get_db()

    for r in results:
        msg_id = r.get('messageId')
        if not msg_id:
            continue

        # Delivery report
        status_obj = r.get('status', {})
        group_name = status_obj.get('groupName', '').upper()

        if group_name == 'DELIVERED':
            conn.execute("""UPDATE wa_messages SET status='delivered', delivered_at=CURRENT_TIMESTAMP
                WHERE infobip_message_id=?""", (msg_id,))
            # Update campaign delivered count
            msg = conn.execute("SELECT campaign_id FROM wa_messages WHERE infobip_message_id=?", (msg_id,)).fetchone()
            if msg and msg['campaign_id']:
                conn.execute("UPDATE wa_campaigns SET delivered_count = delivered_count + 1 WHERE id=?", (msg['campaign_id'],))
        elif group_name == 'SEEN':
            conn.execute("""UPDATE wa_messages SET status='read', read_at=CURRENT_TIMESTAMP
                WHERE infobip_message_id=?""", (msg_id,))
            msg = conn.execute("SELECT campaign_id FROM wa_messages WHERE infobip_message_id=?", (msg_id,)).fetchone()
            if msg and msg['campaign_id']:
                conn.execute("UPDATE wa_campaigns SET read_count = read_count + 1 WHERE id=?", (msg['campaign_id'],))

        # Incoming message
        if r.get('direction') == 'INBOUND' or r.get('from'):
            from_phone = r.get('from', '')
            text = ''
            if r.get('message', {}).get('text'):
                text = r['message']['text']
            elif r.get('content', {}).get('text'):
                text = r['content']['text']

            if from_phone:
                contact = conn.execute("SELECT id FROM wa_contacts WHERE phone=?", (from_phone,)).fetchone()
                if not contact:
                    conn.execute("INSERT INTO wa_contacts (phone, source, opted_in) VALUES (?, 'inbound', 1)", (from_phone,))
                    conn.commit()
                    contact = conn.execute("SELECT id FROM wa_contacts WHERE phone=?", (from_phone,)).fetchone()
                if contact:
                    conn.execute("""INSERT INTO wa_messages
                        (contact_id, direction, message_type, content, status, infobip_message_id, sent_at)
                        VALUES (?, 'inbound', 'text', ?, 'received', ?, CURRENT_TIMESTAMP)""",
                        (contact['id'], text, msg_id))
                    conn.execute("UPDATE wa_contacts SET last_message_at=CURRENT_TIMESTAMP WHERE id=?", (contact['id'],))

    conn.commit()
    return jsonify(ok=True), 200


